import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum HealthGoal {
  WeightLoss = 'Weight Loss',
  MuscleGain = 'Muscle Gain',
  HeartHealth = 'Heart Health',
  Energy = 'Energy',
  BalancedLifestyle = 'Balanced Lifestyle'
}

export enum Cuisine {
  Indian = 'Indian',
  Mediterranean = 'Mediterranean',
  Asian = 'Asian',
  MiddleEastern = 'Middle Eastern',
  Western = 'Western',
  Mixed = 'Mixed'
}

export enum MealFrequency {
  ThreeMeals = 'Breakfast + Lunch + Dinner',
  ThreePlusSnacks = '3 Meals + Snacks',
  IntermittentFasting = 'Intermittent Fasting',
  Custom = 'Custom'
}

export enum DietPreference {
  Vegetarian = 'Vegetarian',
  Vegan = 'Vegan',
  Eggetarian = 'Eggetarian',
  NonVegetarian = 'Non-Vegetarian',
  Keto = 'Keto',
  Balanced = 'Balanced'
}

export interface UserProfile {
  healthGoal: HealthGoal;
  cuisine: Cuisine;
  mealFrequency: MealFrequency;
  dietPreference: DietPreference;
  allergies: string[];
  challenges: string[];
}

export interface MealPlan {
  id: string;
  name: string;
  duration: string;
  calories: number;
  description: string;
}

export interface Meal {
  id: string;
  type: 'Breakfast' | 'Lunch' | 'Snack' | 'Dinner';
  name: string;
  calories: number;
  isLogged: boolean;
  protein: number;
  carbs: number;
  fat: number;
}

export interface MealAlternative {
  name: string;
  calories: number;
  protein: number;
  carbs: number;
  fat: number;
  timingTip: string;
  synergyTip: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { Meal, MealAlternative, UserProfile } from "../types";

const API_KEY = process.env.API_KEY;

export const generateMealAlternatives = async (
  meal: Meal,
  profile: UserProfile
): Promise<MealAlternative[]> => {
  if (!API_KEY) return [];

  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const prompt = `As a high-end nutrition AI for GOQii NutriForge, suggest 3 alternative meals for a ${profile.dietPreference} user with a goal of ${profile.healthGoal}. 
  The original meal is ${meal.name} (${meal.calories} kcal). 
  The user prefers ${profile.cuisine} cuisine and has these allergies: ${profile.allergies.join(', ') || 'none'}.
  Provide calorie/macro breakdowns, a nutrient timing tip, and a food synergy tip for each.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              calories: { type: Type.NUMBER },
              protein: { type: Type.NUMBER },
              carbs: { type: Type.NUMBER },
              fat: { type: Type.NUMBER },
              timingTip: { type: Type.STRING },
              synergyTip: { type: Type.STRING },
            },
            required: ["name", "calories", "protein", "carbs", "fat", "timingTip", "synergyTip"]
          }
        },
      },
    });

    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Failed to generate alternatives", error);
    return [];
  }
};

import React from 'react';

export const Button: React.FC<{
  onClick?: () => void;
  children: React.ReactNode;
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
  className?: string;
  disabled?: boolean;
}> = ({ onClick, children, variant = 'primary', className = '', disabled }) => {
  const baseStyles = "px-6 py-3 rounded-2xl font-semibold transition-all duration-200 flex items-center justify-center gap-2 disabled:opacity-50 active:scale-95";
  const variants = {
    primary: "bg-green-500 text-white shadow-lg shadow-green-200 hover:bg-green-600",
    secondary: "bg-slate-800 text-white hover:bg-slate-900",
    outline: "border-2 border-green-500 text-green-600 hover:bg-green-50",
    ghost: "text-slate-500 hover:bg-slate-100",
  };

  return (
    <button onClick={onClick} className={`${baseStyles} ${variants[variant]} ${className}`} disabled={disabled}>
      {children}
    </button>
  );
};

export const Card: React.FC<{
  children: React.ReactNode;
  className?: string;
  onClick?: () => void;
}> = ({ children, className = '', onClick }) => (
  <div 
    onClick={onClick}
    className={`bg-white rounded-3xl p-6 shadow-sm border border-slate-100 transition-all ${onClick ? 'cursor-pointer hover:shadow-md hover:border-green-100' : ''} ${className}`}
  >
    {children}
  </div>
);

export const ProgressBar: React.FC<{
  progress: number;
  color?: string;
  height?: string;
  label?: string;
  target?: string;
}> = ({ progress, color = 'bg-green-500', height = 'h-2', label, target }) => (
  <div className="w-full space-y-1">
    {(label || target) && (
      <div className="flex justify-between text-sm font-medium text-slate-600">
        <span>{label}</span>
        <span>{target}</span>
      </div>
    )}
    <div className={`w-full bg-slate-100 rounded-full overflow-hidden ${height}`}>
      <div 
        className={`${color} h-full transition-all duration-700 ease-out`}
        style={{ width: `${Math.min(progress, 100)}%` }}
      />
    </div>
  </div>
);

import React, { useState, useEffect } from 'react';
import { UserProfile, HealthGoal, Cuisine, MealFrequency, DietPreference, MealPlan, Meal } from './types';
import Onboarding from './views/Onboarding';
import PlanSelection from './views/PlanSelection';
import Dashboard from './views/Dashboard';
import FreeMode from './views/FreeMode';

type View = 'onboarding' | 'plan-selection' | 'dashboard' | 'free-mode';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('onboarding');
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [selectedPlan, setSelectedPlan] = useState<MealPlan | null>(null);

  const handleOnboardingComplete = (data: UserProfile) => {
    setProfile(data);
    setCurrentView('plan-selection');
  };

  const handlePlanSelect = (plan: MealPlan | null) => {
    if (plan) {
      setSelectedPlan(plan);
      setCurrentView('dashboard');
    } else {
      setCurrentView('free-mode');
    }
  };

  return (
    <div className="min-h-screen max-w-md mx-auto bg-slate-50 relative overflow-hidden flex flex-col">
      {currentView === 'onboarding' && (
        <Onboarding onComplete={handleOnboardingComplete} />
      )}
      {currentView === 'plan-selection' && (
        <PlanSelection onSelect={handlePlanSelect} />
      )}
      {currentView === 'dashboard' && profile && selectedPlan && (
        <Dashboard 
          profile={profile} 
          plan={selectedPlan} 
          onExit={() => setCurrentView('plan-selection')}
        />
      )}
      {currentView === 'free-mode' && (
        <FreeMode onBack={() => setCurrentView('plan-selection')} />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { UserProfile, HealthGoal, Cuisine, MealFrequency, DietPreference } from '../types';
import { Button, Card, ProgressBar } from '../components/UI';

interface OnboardingProps {
  onComplete: (data: UserProfile) => void;
}

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState<UserProfile>({
    healthGoal: HealthGoal.WeightLoss,
    cuisine: Cuisine.Indian,
    mealFrequency: MealFrequency.ThreePlusSnacks,
    dietPreference: DietPreference.Balanced,
    allergies: [],
    challenges: [],
  });

  const totalSteps = 8;

  const next = () => {
    if (step < totalSteps - 1) {
      setStep(s => s + 1);
    } else {
      setLoading(true);
      setTimeout(() => {
        onComplete(formData);
      }, 3000);
    }
  };

  const toggleItem = (list: string[], item: string, key: keyof UserProfile) => {
    const newList = list.includes(item) 
      ? list.filter(i => i !== item) 
      : [...list, item];
    setFormData(prev => ({ ...prev, [key]: newList }));
  };

  const renderStep = () => {
    switch (step) {
      case 0:
        return (
          <div className="space-y-6 text-center py-10">
            <div className="w-24 h-24 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
              <svg className="w-12 h-12 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
              </svg>
            </div>
            <h1 className="text-3xl font-bold text-slate-900 leading-tight px-4">Your Personal Nutrition Intelligence</h1>
            <p className="text-slate-500 text-lg px-8">Let's design a way of eating that works for your life.</p>
            <Button onClick={next} className="w-full mt-10">Start Journey</Button>
          </div>
        );

      case 1:
        return (
          <div className="space-y-4">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">What's your primary health goal?</h2>
            {Object.values(HealthGoal).map(goal => (
              <Card 
                key={goal} 
                onClick={() => { setFormData({...formData, healthGoal: goal}); next(); }}
                className={formData.healthGoal === goal ? 'border-green-500 bg-green-50' : ''}
              >
                <div className="flex justify-between items-center">
                  <span className="font-semibold text-slate-700">{goal}</span>
                  {formData.healthGoal === goal && <span className="text-green-500">✓</span>}
                </div>
              </Card>
            ))}
          </div>
        );

      case 2:
        return (
          <div className="space-y-4">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">Cuisine Preference</h2>
            <div className="grid grid-cols-2 gap-3">
              {Object.values(Cuisine).map(c => (
                <Card 
                  key={c} 
                  onClick={() => { setFormData({...formData, cuisine: c}); next(); }}
                  className={`${formData.cuisine === c ? 'border-green-500 bg-green-50' : ''} py-4 text-center`}
                >
                  <span className="font-medium text-slate-700">{c}</span>
                </Card>
              ))}
            </div>
          </div>
        );

      case 3:
        return (
          <div className="space-y-4">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">Meals Per Day</h2>
            {Object.values(MealFrequency).map(f => (
              <Card 
                key={f} 
                onClick={() => { setFormData({...formData, mealFrequency: f}); next(); }}
                className={formData.mealFrequency === f ? 'border-green-500 bg-green-50' : ''}
              >
                <span className="font-medium text-slate-700">{f}</span>
              </Card>
            ))}
          </div>
        );

      case 4:
        return (
          <div className="space-y-4">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">Dietary Preference</h2>
            {Object.values(DietPreference).map(d => (
              <Card 
                key={d} 
                onClick={() => { setFormData({...formData, dietPreference: d}); next(); }}
                className={formData.dietPreference === d ? 'border-green-500 bg-green-50' : ''}
              >
                <span className="font-medium text-slate-700">{d}</span>
              </Card>
            ))}
          </div>
        );

      case 5:
        return (
          <div className="space-y-4">
            <h2 className="text-2xl font-bold text-slate-800 mb-2">Allergies & Restrictions</h2>
            <p className="text-slate-500 text-sm mb-4">Select all that apply.</p>
            <div className="grid grid-cols-2 gap-3">
              {['Nuts', 'Dairy', 'Gluten', 'Seafood', 'Eggs', 'None'].map(a => (
                <Card 
                  key={a} 
                  onClick={() => toggleItem(formData.allergies, a, 'allergies')}
                  className={`${formData.allergies.includes(a) ? 'border-green-500 bg-green-50' : ''} py-3 text-center`}
                >
                  <span className="text-sm font-medium">{a}</span>
                </Card>
              ))}
            </div>
            <Button onClick={next} className="w-full mt-6">Continue</Button>
          </div>
        );

      case 6:
        return (
          <div className="space-y-4">
            <h2 className="text-2xl font-bold text-slate-800 mb-2">Challenging Foods?</h2>
            <p className="text-slate-500 text-sm mb-4">Areas where you struggle most.</p>
            <div className="space-y-3">
              {['Sugar', 'Fried Foods', 'Late-night Snacking', 'Portions', 'Emotional Eating'].map(c => (
                <Card 
                  key={c} 
                  onClick={() => toggleItem(formData.challenges, c, 'challenges')}
                  className={`${formData.challenges.includes(c) ? 'border-green-500 bg-green-50' : ''}`}
                >
                  <span className="font-medium">{c}</span>
                </Card>
              ))}
            </div>
            <Button onClick={next} className="w-full mt-6">Build My Plan</Button>
          </div>
        );

      case 7:
        return (
          <div className="flex flex-col items-center justify-center space-y-8 py-20">
            <div className="relative w-32 h-32">
              <div className="absolute inset-0 border-4 border-green-100 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-green-500 rounded-full border-t-transparent animate-spin"></div>
            </div>
            <div className="text-center space-y-2">
              <h2 className="text-2xl font-bold text-slate-800 animate-pulse">NutriForge is Thinking...</h2>
              <p className="text-slate-500">Building your personalised nutrition plan...</p>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="flex-1 flex flex-col p-6 animate-in fade-in duration-500">
      {step > 0 && step < totalSteps - 1 && (
        <div className="mb-8">
          <ProgressBar progress={(step / (totalSteps - 1)) * 100} height="h-1" />
        </div>
      )}
      <div className="flex-1 overflow-y-auto">
        {renderStep()}
      </div>
    </div>
  );
};

export default Onboarding;

