import React, { useState, useEffect } from 'react';
import { UserProfile, MealPlan, Meal, MealAlternative } from '../types';
import { Card, ProgressBar, Button } from '../components/UI';
import { generateMealAlternatives } from '../services/geminiService';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  onExit: () => void;
}

const INITIAL_MEALS: Meal[] = [
  { id: '1', type: 'Breakfast', name: 'Avocado Toast & Boiled Egg', calories: 350, isLogged: false, protein: 15, carbs: 30, fat: 20 },
  { id: '2', type: 'Lunch', name: 'Grilled Chicken Quinoa Bowl', calories: 450, isLogged: true, protein: 35, carbs: 40, fat: 12 },
  { id: '3', type: 'Snack', name: 'Greek Yogurt with Berries', calories: 200, isLogged: false, protein: 12, carbs: 20, fat: 5 },
  { id: '4', type: 'Dinner', name: 'Steamed Fish with Greens', calories: 300, isLogged: false, protein: 25, carbs: 10, fat: 15 },
];

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, onExit }) => {
  const [meals, setMeals] = useState<Meal[]>(INITIAL_MEALS);
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [alternatives, setAlternatives] = useState<MealAlternative[]>([]);
  const [loadingAlts, setLoadingAlts] = useState(false);
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);

  const totalConsumed = meals.reduce((sum, m) => m.isLogged ? sum + m.calories : sum, 0);
  const targetCals = plan.calories;

  const handleLog = (mealId: string) => {
    setMeals(prev => prev.map(m => m.id === mealId ? { ...m, isLogged: !m.isLogged } : m));
    setShowLogModal(null);
  };

  const openAlternative = async (meal: Meal) => {
    setSelectedMealForAlt(meal);
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setAlternatives(alts);
    setLoadingAlts(false);
  };

  const applyAlternative = (alt: MealAlternative) => {
    if (!selectedMealForAlt) return;
    setMeals(prev => prev.map(m => m.id === selectedMealForAlt.id ? {
      ...m,
      name: alt.name,
      calories: alt.calories,
      protein: alt.protein,
      carbs: alt.carbs,
      fat: alt.fat,
      isLogged: false
    } : m));
    setSelectedMealForAlt(null);
  };

  return (
    <div className="flex-1 flex flex-col bg-slate-50 overflow-hidden relative">
      {/* Header */}
      <div className="p-6 bg-white border-b border-slate-100 flex justify-between items-center">
        <div>
          <h2 className="text-xl font-bold text-slate-800">NutriForge</h2>
          <span className="text-xs text-green-600 font-semibold">{plan.name}</span>
        </div>
        <button onClick={onExit} className="p-2 text-slate-400 hover:text-slate-600">
           <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
        </button>
      </div>

      {/* Calendar Strip */}
      <div className="px-6 py-4 flex gap-4 overflow-x-auto no-scrollbar bg-white shadow-sm mb-4">
        {['M', 'T', 'W', 'T', 'F', 'S', 'S'].map((day, i) => (
          <div key={i} className={`flex-shrink-0 w-10 h-14 rounded-2xl flex flex-col items-center justify-center gap-1 ${i === 2 ? 'bg-green-500 text-white shadow-lg shadow-green-100' : 'text-slate-400'}`}>
            <span className="text-xs font-bold">{day}</span>
            <span className="text-sm font-black">{12 + i}</span>
          </div>
        ))}
      </div>

      {/* Stats Area */}
      <div className="px-6 space-y-4 mb-6">
        <Card className="bg-gradient-to-br from-slate-800 to-slate-900 text-white border-none shadow-xl">
          <ProgressBar 
            progress={(totalConsumed / targetCals) * 100} 
            color="bg-green-400"
            label="Calories"
            target={`${totalConsumed} / ${targetCals} kcal`}
          />
          <div className="grid grid-cols-3 gap-4 mt-6">
            <div className="space-y-1">
              <span className="text-[10px] text-slate-400 font-bold uppercase">Carbs</span>
              <ProgressBar progress={60} color="bg-orange-400" height="h-1" />
              <p className="text-xs font-bold">150 / 220g</p>
            </div>
            <div className="space-y-1">
              <span className="text-[10px] text-slate-400 font-bold uppercase">Protein</span>
              <ProgressBar progress={85} color="bg-blue-400" height="h-1" />
              <p className="text-xs font-bold">85 / 100g</p>
            </div>
            <div className="space-y-1">
              <span className="text-[10px] text-slate-400 font-bold uppercase">Fat</span>
              <ProgressBar progress={40} color="bg-pink-400" height="h-1" />
              <p className="text-xs font-bold">45 / 70g</p>
            </div>
          </div>
        </Card>
      </div>

      {/* Meal List */}
      <div className="flex-1 overflow-y-auto px-6 pb-10 space-y-4">
        {meals.map(meal => (
          <Card key={meal.id} className="p-4 border-l-4 border-l-green-500">
            <div className="flex justify-between items-start mb-3">
              <div>
                <span className="text-[10px] font-bold text-green-600 uppercase tracking-widest">{meal.type}</span>
                <h4 className="font-bold text-slate-800">{meal.name}</h4>
                <span className="text-sm text-slate-500">{meal.calories} kcal</span>
              </div>
              <div className={`w-6 h-6 rounded-full flex items-center justify-center ${meal.isLogged ? 'bg-green-500 text-white' : 'border-2 border-slate-200'}`}>
                {meal.isLogged && <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>}
              </div>
            </div>
            <div className="flex gap-2">
              <Button 
                variant={meal.isLogged ? 'ghost' : 'outline'} 
                className="py-1.5 px-3 text-xs rounded-lg flex-1"
                onClick={() => setShowLogModal(meal)}
              >
                {meal.isLogged ? 'View' : 'Log'}
              </Button>
              <Button 
                variant="ghost" 
                className="py-1.5 px-3 text-xs rounded-lg flex-1 bg-slate-50 border border-slate-100"
                onClick={() => openAlternative(meal)}
              >
                Alternative
              </Button>
            </div>
          </Card>
        ))}
      </div>

      {/* Alternative Modal */}
      {selectedMealForAlt && (
        <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex flex-col justify-end">
          <div className="bg-white rounded-t-[40px] p-8 max-h-[85%] overflow-y-auto animate-in slide-in-from-bottom duration-300">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-800">Smart Alternatives</h3>
              <button onClick={() => setSelectedMealForAlt(null)} className="p-2 bg-slate-100 rounded-full">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>

            {loadingAlts ? (
              <div className="py-20 text-center">
                <div className="w-12 h-12 border-4 border-green-500 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
                <p className="text-slate-500">Consulting Nutrition AI...</p>
              </div>
            ) : (
              <div className="space-y-6">
                {alternatives.map((alt, i) => (
                  <Card key={i} className="bg-green-50 border-green-100" onClick={() => applyAlternative(alt)}>
                    <div className="flex justify-between mb-2">
                      <h4 className="font-bold text-slate-800">{alt.name}</h4>
                      <span className="text-sm font-bold text-green-700">{alt.calories} kcal</span>
                    </div>
                    <div className="flex gap-4 text-[10px] font-bold text-slate-500 uppercase mb-3">
                      <span>P: {alt.protein}g</span>
                      <span>C: {alt.carbs}g</span>
                      <span>F: {alt.fat}g</span>
                    </div>
                    <div className="space-y-2">
                      <div className="flex gap-2 items-start">
                        <span className="bg-green-200 text-green-800 text-[9px] px-1.5 rounded uppercase font-bold mt-1">Timing</span>
                        <p className="text-xs text-slate-600 italic">"{alt.timingTip}"</p>
                      </div>
                      <div className="flex gap-2 items-start">
                        <span className="bg-blue-200 text-blue-800 text-[9px] px-1.5 rounded uppercase font-bold mt-1">Synergy</span>
                        <p className="text-xs text-slate-600 italic">"{alt.synergyTip}"</p>
                      </div>
                    </div>
                  </Card>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Log Modal */}
      {showLogModal && (
        <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex flex-col justify-end">
          <div className="bg-white rounded-t-[40px] p-8 animate-in slide-in-from-bottom duration-300">
             <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-800">Log {showLogModal.type}</h3>
              <button onClick={() => setShowLogModal(null)} className="p-2 bg-slate-100 rounded-full">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            <Card className="mb-6">
              <h4 className="font-bold mb-1">{showLogModal.name}</h4>
              <p className="text-sm text-slate-500 mb-4">{showLogModal.calories} kcal per serving</p>
              <div className="space-y-4">
                <label className="text-sm font-semibold text-slate-600 block">Portion Size</label>
                <div className="flex gap-2">
                  {['0.5x', '1x', '1.5x', '2x'].map(p => (
                    <button key={p} className={`flex-1 py-2 rounded-xl text-xs font-bold ${p === '1x' ? 'bg-green-500 text-white' : 'bg-slate-100 text-slate-500'}`}>{p}</button>
                  ))}
                </div>
              </div>
            </Card>
            <div className="space-y-4">
               <textarea 
                className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 text-sm focus:outline-none focus:ring-2 focus:ring-green-500" 
                placeholder="Add notes (e.g., added extra spinach)..."
                rows={3}
               />
               <Button className="w-full" onClick={() => handleLog(showLogModal.id)}>Save & Log</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

