import React, { useState, useEffect } from 'react';
import { UserProfile, MealPlan, Meal, MealAlternative, GamificationState, ActivityData } from '../types';
import { Card, ProgressBar, Button, BadgeItem } from '../components/UI';
import { generateMealAlternatives } from '../services/geminiService';
import { fetchWearableData, getBadgeDefinitions } from '../services/activityService';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  onExit: () => void;
}

const INITIAL_MEALS: Meal[] = [
  { id: '1', type: 'Breakfast', name: 'Avocado Toast & Boiled Egg', calories: 350, isLogged: false, protein: 15, carbs: 30, fat: 20 },
  { id: '2', type: 'Lunch', name: 'Grilled Chicken Quinoa Bowl', calories: 450, isLogged: true, protein: 35, carbs: 40, fat: 12 },
  { id: '3', type: 'Snack', name: 'Greek Yogurt with Berries', calories: 200, isLogged: false, protein: 12, carbs: 20, fat: 5 },
  { id: '4', type: 'Dinner', name: 'Steamed Fish with Greens', calories: 300, isLogged: false, protein: 25, carbs: 10, fat: 15 },
];

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, onExit }) => {
  const [meals, setMeals] = useState<Meal[]>(INITIAL_MEALS);
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [alternatives, setAlternatives] = useState<MealAlternative[]>([]);
  const [loadingAlts, setLoadingAlts] = useState(false);
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);

  // Gamification & Activity State
  const [gamification, setGamification] = useState<GamificationState>({
    points: 1240,
    streak: 4,
    badges: [{ id: 'sync', name: 'Sync King', icon: '⌚', description: 'Connected a wearable device' }]
  });
  const [activity, setActivity] = useState<ActivityData | null>(null);
  const [pointsAnimation, setPointsAnimation] = useState(false);

  useEffect(() => {
    const syncData = async () => {
      const data = await fetchWearableData();
      setActivity(data);
    };
    syncData();
  }, []);

  const totalConsumed = meals.reduce((sum, m) => m.isLogged ? sum + m.calories : sum, 0);
  const activityBonus = activity ? Math.round(activity.caloriesBurned * 0.8) : 0;
  const targetCals = plan.calories + activityBonus;

  const handleLog = (mealId: string) => {
    setMeals(prev => prev.map(m => m.id === mealId ? { ...m, isLogged: !m.isLogged } : m));
    setShowLogModal(null);

    // Gamification Reward
    setGamification(prev => ({ ...prev, points: prev.points + 20 }));
    setPointsAnimation(true);
    setTimeout(() => setPointsAnimation(false), 2000);
  };

  const openAlternative = async (meal: Meal) => {
    setSelectedMealForAlt(meal);
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setAlternatives(alts);
    setLoadingAlts(false);
  };

  const applyAlternative = (alt: MealAlternative) => {
    if (!selectedMealForAlt) return;
    setMeals(prev => prev.map(m => m.id === selectedMealForAlt.id ? {
      ...m,
      name: alt.name,
      calories: alt.calories,
      protein: alt.protein,
      carbs: alt.carbs,
      fat: alt.fat,
      isLogged: false
    } : m));
    setSelectedMealForAlt(null);
  };

  return (
    <div className="flex-1 flex flex-col bg-slate-50 overflow-hidden relative">
      {/* Header */}
      <div className="p-6 bg-white border-b border-slate-100 flex justify-between items-center z-10">
        <div className="flex flex-col">
          <h2 className="text-xl font-bold text-slate-800">NutriForge</h2>
          <div className="flex items-center gap-2">
            <span className="text-xs text-green-600 font-semibold">{plan.name}</span>
            <div className="w-1 h-1 bg-slate-300 rounded-full"></div>
            <div className="flex items-center gap-1 text-orange-500 font-bold text-xs">
              <span>🔥</span> {gamification.streak} Day Streak
            </div>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end">
            <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Forge Points</span>
            <div className="flex items-center gap-1">
              <span className="font-black text-slate-800">{gamification.points}</span>
              {pointsAnimation && <span className="absolute text-green-500 font-bold animate-bounce text-sm">+20</span>}
            </div>
          </div>
          <button onClick={onExit} className="p-2 text-slate-400 hover:text-slate-600">
             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pb-20">
        {/* Calendar Strip */}
        <div className="px-6 py-4 flex gap-4 overflow-x-auto no-scrollbar bg-white shadow-sm mb-4">
          {['M', 'T', 'W', 'T', 'F', 'S', 'S'].map((day, i) => (
            <div key={i} className={`flex-shrink-0 w-10 h-14 rounded-2xl flex flex-col items-center justify-center gap-1 ${i === 2 ? 'bg-green-500 text-white shadow-lg shadow-green-100' : 'text-slate-400'}`}>
              <span className="text-xs font-bold">{day}</span>
              <span className="text-sm font-black">{12 + i}</span>
            </div>
          ))}
        </div>

        {/* Dynamic Activity Card */}
        {activity && (
          <div className="px-6 mb-4">
            <Card className="bg-indigo-50 border-indigo-100 py-3 px-4">
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-indigo-500 rounded-full flex items-center justify-center text-white shadow-lg shadow-indigo-200">
                    <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z"></path></svg>
                  </div>
                  <div>
                    <h4 className="text-sm font-bold text-slate-800">Wearable Synced</h4>
                    <p className="text-[10px] text-slate-500 font-medium">Last sync: {activity.lastSynced}</p>
                  </div>
                </div>
                <div className="text-right">
                  <span className="text-sm font-black text-indigo-600">+{activity.caloriesBurned} kcal</span>
                  <p className="text-[10px] text-slate-400 font-bold uppercase">{activity.steps} Steps</p>
                </div>
              </div>
            </Card>
          </div>
        )}

        {/* Stats Area */}
        <div className="px-6 space-y-4 mb-6">
          <Card className="bg-gradient-to-br from-slate-800 to-slate-900 text-white border-none shadow-xl relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-green-400/10 rounded-full -mr-16 -mt-16 blur-3xl"></div>
            <ProgressBar 
              progress={(totalConsumed / targetCals) * 100} 
              secondaryProgress={(totalConsumed / plan.calories) * 100}
              color="bg-green-400"
              label="Daily Calories"
              target={`${totalConsumed} / ${targetCals} kcal`}
            />
            <p className="text-[10px] text-slate-400 mt-2 italic">*Target adjusted by +{activityBonus} kcal based on activity</p>

            <div className="grid grid-cols-3 gap-4 mt-6">
              <div className="space-y-1">
                <span className="text-[10px] text-slate-400 font-bold uppercase">Carbs</span>
                <ProgressBar progress={60} color="bg-orange-400" height="h-1" />
                <p className="text-xs font-bold">150 / 220g</p>
              </div>
              <div className="space-y-1">
                <span className="text-[10px] text-slate-400 font-bold uppercase">Protein</span>
                <ProgressBar progress={85} color="bg-blue-400" height="h-1" />
                <p className="text-xs font-bold">85 / 100g</p>
              </div>
              <div className="space-y-1">
                <span className="text-[10px] text-slate-400 font-bold uppercase">Fat</span>
                <ProgressBar progress={40} color="bg-pink-400" height="h-1" />
                <p className="text-xs font-bold">45 / 70g</p>
              </div>
            </div>
          </Card>
        </div>

        {/* Badges Carousel */}
        <div className="px-6 mb-6">
          <div className="flex justify-between items-center mb-3">
            <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest">Achievements</h3>
            <span className="text-xs text-green-600 font-bold">View All</span>
          </div>
          <div className="flex gap-6 bg-white p-4 rounded-3xl border border-slate-100 shadow-sm overflow-x-auto no-scrollbar">
            {getBadgeDefinitions().map(badge => (
              <BadgeItem 
                key={badge.id} 
                icon={badge.icon} 
                name={badge.name} 
                earned={gamification.badges.some(b => b.id === badge.id)} 
              />
            ))}
          </div>
        </div>

        {/* Meal List */}
        <div className="px-6 space-y-4">
          <div className="flex justify-between items-center mb-1">
            <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest">Today's Meals</h3>
          </div>
          {meals.map(meal => (
            <Card key={meal.id} className={`p-4 border-l-4 ${meal.isLogged ? 'border-l-green-500 bg-white' : 'border-l-slate-200 bg-slate-50/50'}`}>
              <div className="flex justify-between items-start mb-3">
                <div>
                  <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{meal.type}</span>
                  <h4 className="font-bold text-slate-800">{meal.name}</h4>
                  <span className="text-sm text-slate-500">{meal.calories} kcal</span>
                </div>
                <div className={`w-6 h-6 rounded-full flex items-center justify-center transition-all ${meal.isLogged ? 'bg-green-500 text-white scale-110 shadow-lg shadow-green-100' : 'border-2 border-slate-200'}`}>
                  {meal.isLogged && <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>}
                </div>
              </div>
              <div className="flex gap-2">
                <Button 
                  variant={meal.isLogged ? 'ghost' : 'outline'} 
                  className="py-1.5 px-3 text-xs rounded-xl flex-1 h-9"
                  onClick={() => setShowLogModal(meal)}
                >
                  {meal.isLogged ? 'Edit Entry' : 'Log Meal'}
                </Button>
                <Button 
                  variant="ghost" 
                  className="py-1.5 px-3 text-xs rounded-xl flex-1 bg-white border border-slate-100 h-9"
                  onClick={() => openAlternative(meal)}
                >
                  Swap Item
                </Button>
              </div>
            </Card>
          ))}
        </div>
      </div>

      {/* Alternative Modal */}
      {selectedMealForAlt && (
        <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex flex-col justify-end">
          <div className="bg-white rounded-t-[40px] p-8 max-h-[85%] overflow-y-auto animate-in slide-in-from-bottom duration-500">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-800">Forge AI Alternatives</h3>
              <button onClick={() => setSelectedMealForAlt(null)} className="p-2 bg-slate-100 rounded-full">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>

            {loadingAlts ? (
              <div className="py-20 text-center">
                <div className="w-16 h-16 border-4 border-green-500 border-t-transparent rounded-full animate-spin mx-auto mb-6"></div>
                <p className="text-slate-500 font-medium">Scanning metabolic profile...</p>
              </div>
            ) : (
              <div className="space-y-6 pb-10">
                {alternatives.map((alt, i) => (
                  <Card key={i} className="bg-green-50/50 border-green-100 hover:scale-[1.02] active:scale-95" onClick={() => applyAlternative(alt)}>
                    <div className="flex justify-between mb-2">
                      <h4 className="font-bold text-slate-800">{alt.name}</h4>
                      <span className="text-sm font-bold text-green-700">{alt.calories} kcal</span>
                    </div>
                    <div className="flex gap-4 text-[10px] font-bold text-slate-500 uppercase mb-3">
                      <span className="bg-white px-2 py-0.5 rounded shadow-sm">P: {alt.protein}g</span>
                      <span className="bg-white px-2 py-0.5 rounded shadow-sm">C: {alt.carbs}g</span>
                      <span className="bg-white px-2 py-0.5 rounded shadow-sm">F: {alt.fat}g</span>
                    </div>
                    <div className="space-y-2 border-t border-green-100 pt-3 mt-2">
                      <div className="flex gap-2 items-start">
                        <span className="bg-green-500 text-white text-[9px] px-1.5 py-0.5 rounded uppercase font-black mt-0.5 tracking-tighter">Timing</span>
                        <p className="text-xs text-slate-700 leading-tight">"{alt.timingTip}"</p>
                      </div>
                      <div className="flex gap-2 items-start">
                        <span className="bg-blue-500 text-white text-[9px] px-1.5 py-0.5 rounded uppercase font-black mt-0.5 tracking-tighter">Synergy</span>
                        <p className="text-xs text-slate-700 leading-tight">"{alt.synergyTip}"</p>
                      </div>
                    </div>
                  </Card>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Log Modal */}
      {showLogModal && (
        <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex flex-col justify-end">
          <div className="bg-white rounded-t-[40px] p-8 animate-in slide-in-from-bottom duration-500">
             <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-800">Log {showLogModal.type}</h3>
              <button onClick={() => setShowLogModal(null)} className="p-2 bg-slate-100 rounded-full">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            <Card className="mb-6 bg-slate-50">
              <h4 className="font-bold mb-1 text-slate-800">{showLogModal.name}</h4>
              <p className="text-sm text-slate-500 mb-4">{showLogModal.calories} kcal per serving</p>
              <div className="space-y-4">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest block">Adjust Portion</label>
                <div className="flex gap-2">
                  {['0.5x', '1x', '1.5x', '2x'].map(p => (
                    <button key={p} className={`flex-1 py-3 rounded-2xl text-xs font-black ${p === '1x' ? 'bg-green-500 text-white shadow-lg shadow-green-100' : 'bg-white border border-slate-200 text-slate-500'}`}>{p}</button>
                  ))}
                </div>
              </div>
            </Card>
            <div className="space-y-4">
               <textarea 
                className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 text-sm focus:outline-none focus:ring-2 focus:ring-green-500" 
                placeholder="How was the meal? Any swaps?"
                rows={3}
               />
               <Button className="w-full h-14" onClick={() => handleLog(showLogModal.id)}>
                 Confirm Log (+20 Points)
               </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { UserProfile, HealthGoal, Cuisine, MealFrequency, DietPreference } from '../types';
import { Button, Card, ProgressBar } from '../components/UI';

interface OnboardingProps {
  onComplete: (data: UserProfile) => void;
}

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(0);
  const [formData, setFormData] = useState<UserProfile>({
    healthGoal: HealthGoal.WeightLoss,
    cuisine: Cuisine.Indian,
    mealFrequency: MealFrequency.ThreePlusSnacks,
    dietPreference: DietPreference.Balanced,
    allergies: [],
    challenges: [],
  });

  const totalSteps = 8; // 0 to 7

  // Automatically trigger completion when the loading step (7) is reached
  useEffect(() => {
    if (step === 7) {
      const timer = setTimeout(() => {
        onComplete(formData);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [step, formData, onComplete]);

  const next = () => {
    if (step < totalSteps - 1) {
      setStep(s => s + 1);
    }
  };

  const toggleItem = (list: string[], item: string, key: keyof UserProfile) => {
    const newList = list.includes(item) 
      ? list.filter(i => i !== item) 
      : [...list, item];
    setFormData(prev => ({ ...prev, [key]: newList }));
  };

  const renderStep = () => {
    switch (step) {
      case 0:
        return (
          <div className="space-y-6 text-center py-10">
            <div className="w-24 h-24 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
              <svg className="w-12 h-12 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
              </svg>
            </div>
            <h1 className="text-3xl font-bold text-slate-900 leading-tight px-4">Your Personal Nutrition Intelligence</h1>
            <p className="text-slate-500 text-lg px-8">Let's design a way of eating that works for your life.</p>
            <Button onClick={next} className="w-full mt-10">Start Journey</Button>
          </div>
        );

      case 1:
        return (
          <div className="space-y-4">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">What's your primary health goal?</h2>
            {Object.values(HealthGoal).map(goal => (
              <Card 
                key={goal} 
                onClick={() => { setFormData({...formData, healthGoal: goal}); next(); }}
                className={formData.healthGoal === goal ? 'border-green-500 bg-green-50' : ''}
              >
                <div className="flex justify-between items-center">
                  <span className="font-semibold text-slate-700">{goal}</span>
                  {formData.healthGoal === goal && <span className="text-green-500">✓</span>}
                </div>
              </Card>
            ))}
          </div>
        );

      case 2:
        return (
          <div className="space-y-4">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">Cuisine Preference</h2>
            <div className="grid grid-cols-2 gap-3">
              {Object.values(Cuisine).map(c => (
                <Card 
                  key={c} 
                  onClick={() => { setFormData({...formData, cuisine: c}); next(); }}
                  className={`${formData.cuisine === c ? 'border-green-500 bg-green-50' : ''} py-4 text-center`}
                >
                  <span className="font-medium text-slate-700">{c}</span>
                </Card>
              ))}
            </div>
          </div>
        );

      case 3:
        return (
          <div className="space-y-4">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">Meals Per Day</h2>
            {Object.values(MealFrequency).map(f => (
              <Card 
                key={f} 
                onClick={() => { setFormData({...formData, mealFrequency: f}); next(); }}
                className={formData.mealFrequency === f ? 'border-green-500 bg-green-50' : ''}
              >
                <span className="font-medium text-slate-700">{f}</span>
              </Card>
            ))}
          </div>
        );

      case 4:
        return (
          <div className="space-y-4">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">Dietary Preference</h2>
            {Object.values(DietPreference).map(d => (
              <Card 
                key={d} 
                onClick={() => { setFormData({...formData, dietPreference: d}); next(); }}
                className={formData.dietPreference === d ? 'border-green-500 bg-green-50' : ''}
              >
                <span className="font-medium text-slate-700">{d}</span>
              </Card>
            ))}
          </div>
        );

      case 5:
        return (
          <div className="space-y-4">
            <h2 className="text-2xl font-bold text-slate-800 mb-2">Allergies & Restrictions</h2>
            <p className="text-slate-500 text-sm mb-4">Select all that apply.</p>
            <div className="grid grid-cols-2 gap-3">
              {['Nuts', 'Dairy', 'Gluten', 'Seafood', 'Eggs', 'None'].map(a => (
                <Card 
                  key={a} 
                  onClick={() => toggleItem(formData.allergies, a, 'allergies')}
                  className={`${formData.allergies.includes(a) ? 'border-green-500 bg-green-50' : ''} py-3 text-center`}
                >
                  <span className="text-sm font-medium">{a}</span>
                </Card>
              ))}
            </div>
            <Button onClick={next} className="w-full mt-6">Continue</Button>
          </div>
        );

      case 6:
        return (
          <div className="space-y-4">
            <h2 className="text-2xl font-bold text-slate-800 mb-2">Challenging Foods?</h2>
            <p className="text-slate-500 text-sm mb-4">Areas where you struggle most.</p>
            <div className="space-y-3">
              {['Sugar', 'Fried Foods', 'Late-night Snacking', 'Portions', 'Emotional Eating'].map(c => (
                <Card 
                  key={c} 
                  onClick={() => toggleItem(formData.challenges, c, 'challenges')}
                  className={`${formData.challenges.includes(c) ? 'border-green-500 bg-green-50' : ''}`}
                >
                  <span className="font-medium">{c}</span>
                </Card>
              ))}
            </div>
            <Button onClick={next} className="w-full mt-6">Build My Plan</Button>
          </div>
        );

      case 7:
        return (
          <div className="flex flex-col items-center justify-center space-y-8 py-20">
            <div className="relative w-32 h-32">
              <div className="absolute inset-0 border-4 border-green-100 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-green-500 rounded-full border-t-transparent animate-spin"></div>
            </div>
            <div className="text-center space-y-2">
              <h2 className="text-2xl font-bold text-slate-800 animate-pulse">NutriForge is Thinking...</h2>
              <p className="text-slate-500">Building your personalised nutrition plan...</p>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="flex-1 flex flex-col p-6 animate-in fade-in duration-500">
      {step > 0 && step < totalSteps - 1 && (
        <div className="mb-8">
          <ProgressBar progress={(step / (totalSteps - 1)) * 100} height="h-1" />
        </div>
      )}
      <div className="flex-1 overflow-y-auto">
        {renderStep()}
      </div>
    </div>
  );
};

export default Onboarding;

import React, { useState, useEffect } from 'react';
import { UserProfile, MealPlan, Meal, MealAlternative, GamificationState, ActivityData } from '../types';
import { Card, ProgressBar, Button, BadgeItem } from '../components/UI';
import { generateMealAlternatives } from '../services/geminiService';
import { fetchWearableData, getBadgeDefinitions } from '../services/activityService';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  onExit: () => void;
}

const INITIAL_MEALS: Meal[] = [
  { id: '1', type: 'Breakfast', name: 'Avocado Toast & Boiled Egg', calories: 350, isLogged: false, protein: 15, carbs: 30, fat: 20 },
  { id: '2', type: 'Lunch', name: 'Grilled Chicken Quinoa Bowl', calories: 450, isLogged: true, protein: 35, carbs: 40, fat: 12 },
  { id: '3', type: 'Snack', name: 'Greek Yogurt with Berries', calories: 200, isLogged: false, protein: 12, carbs: 20, fat: 5 },
  { id: '4', type: 'Dinner', name: 'Steamed Fish with Greens', calories: 300, isLogged: false, protein: 25, carbs: 10, fat: 15 },
];

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, onExit }) => {
  const [meals, setMeals] = useState<Meal[]>(INITIAL_MEALS);
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [alternatives, setAlternatives] = useState<MealAlternative[]>([]);
  const [loadingAlts, setLoadingAlts] = useState(false);
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);

  // Gamification & Activity State
  const [gamification, setGamification] = useState<GamificationState>({
    points: 1240,
    streak: 4,
    badges: [{ id: 'sync', name: 'Sync King', icon: '⌚', description: 'Connected a wearable device' }]
  });
  const [activity, setActivity] = useState<ActivityData | null>(null);
  const [pointsAnimation, setPointsAnimation] = useState(false);

  useEffect(() => {
    const syncData = async () => {
      const data = await fetchWearableData();
      setActivity(data);
    };
    syncData();
  }, []);

  const totalConsumed = meals.reduce((sum, m) => m.isLogged ? sum + m.calories : sum, 0);
  const activityBonus = activity ? Math.round(activity.caloriesBurned * 0.8) : 0;
  const targetCals = plan.calories + activityBonus;

  const handleLog = (mealId: string) => {
    setMeals(prev => prev.map(m => m.id === mealId ? { ...m, isLogged: !m.isLogged } : m));
    setShowLogModal(null);

    // Gamification Reward
    setGamification(prev => ({ ...prev, points: prev.points + 20 }));
    setPointsAnimation(true);
    setTimeout(() => setPointsAnimation(false), 2000);
  };

  const openAlternative = async (meal: Meal) => {
    setSelectedMealForAlt(meal);
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setAlternatives(alts);
    setLoadingAlts(false);
  };

  const applyAlternative = (alt: MealAlternative) => {
    if (!selectedMealForAlt) return;
    setMeals(prev => prev.map(m => m.id === selectedMealForAlt.id ? {
      ...m,
      name: alt.name,
      calories: alt.calories,
      protein: alt.protein,
      carbs: alt.carbs,
      fat: alt.fat,
      isLogged: false
    } : m));
    setSelectedMealForAlt(null);
  };

  return (
    <div className="flex-1 flex flex-col bg-slate-50 overflow-hidden relative">
      {/* Header */}
      <div className="p-6 bg-white border-b border-slate-100 flex justify-between items-center z-10">
        <div className="flex flex-col">
          <h2 className="text-xl font-bold text-slate-800">NutriForge</h2>
          <div className="flex items-center gap-2">
            <span className="text-xs text-green-600 font-semibold">{plan.name}</span>
            <div className="w-1 h-1 bg-slate-300 rounded-full"></div>
            <div className="flex items-center gap-1 text-orange-500 font-bold text-xs">
              <span>🔥</span> {gamification.streak} Day Streak
            </div>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end">
            <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Forge Points</span>
            <div className="flex items-center gap-1">
              <span className="font-black text-slate-800">{gamification.points}</span>
              {pointsAnimation && <span className="absolute text-green-500 font-bold animate-bounce text-sm">+20</span>}
            </div>
          </div>
          <button onClick={onExit} className="p-2 text-slate-400 hover:text-slate-600">
             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pb-20">
        {/* Calendar Strip */}
        <div className="px-6 py-4 flex gap-4 overflow-x-auto no-scrollbar bg-white shadow-sm mb-4">
          {['M', 'T', 'W', 'T', 'F', 'S', 'S'].map((day, i) => (
            <div key={i} className={`flex-shrink-0 w-10 h-14 rounded-2xl flex flex-col items-center justify-center gap-1 ${i === 2 ? 'bg-green-500 text-white shadow-lg shadow-green-100' : 'text-slate-400'}`}>
              <span className="text-xs font-bold">{day}</span>
              <span className="text-sm font-black">{12 + i}</span>
            </div>
          ))}
        </div>

        {/* Dynamic Activity Card */}
        {activity && (
          <div className="px-6 mb-4">
            <Card className="bg-white border-slate-200 py-3 px-4">
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-slate-800 rounded-full flex items-center justify-center text-white shadow-sm">
                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z"></path></svg>
                  </div>
                  <div>
                    <h4 className="text-xs font-bold text-slate-800">Wearable Synced</h4>
                    <p className="text-[9px] text-slate-400 font-medium">Synced at {activity.lastSynced}</p>
                  </div>
                </div>
                <div className="text-right">
                  <span className="text-sm font-black text-slate-900">+{activity.caloriesBurned} kcal</span>
                  <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tight">{activity.steps} Steps</p>
                </div>
              </div>
            </Card>
          </div>
        )}

        {/* Stats Area (Light Grey Scale) */}
        <div className="px-6 space-y-4 mb-6">
          <Card className="bg-slate-50 border-slate-200 shadow-sm relative overflow-hidden group">
            <div className="flex justify-between items-end mb-4">
              <div className="space-y-0.5">
                <span className="text-[10px] text-slate-500 font-black uppercase tracking-widest">Daily Target</span>
                <div className="flex items-baseline gap-1">
                  <span className="text-3xl font-black text-slate-900 tracking-tighter">{totalConsumed}</span>
                  <span className="text-sm text-slate-400 font-bold">/ {targetCals} kcal</span>
                </div>
              </div>
              <div className="w-12 h-12 rounded-full border-4 border-slate-100 flex items-center justify-center">
                <span className="text-[10px] font-black text-slate-800">{Math.round((totalConsumed/targetCals)*100)}%</span>
              </div>
            </div>

            <ProgressBar 
              progress={(totalConsumed / targetCals) * 100} 
              secondaryProgress={(totalConsumed / plan.calories) * 100}
              color="bg-slate-800"
              secondaryColor="bg-slate-300"
              height="h-3"
            />

            <p className="text-[10px] text-slate-400 mt-3 font-medium italic">*Plan: {plan.calories} + Activity: {activityBonus} kcal</p>

            <div className="grid grid-cols-3 gap-6 mt-6 pt-6 border-t border-slate-200">
              <div className="space-y-2">
                <div className="flex justify-between items-center">
                  <span className="text-[9px] text-slate-400 font-black uppercase">Carbs</span>
                  <span className="text-[10px] font-bold text-slate-700">150g</span>
                </div>
                <ProgressBar progress={60} color="bg-slate-400" height="h-1" />
              </div>
              <div className="space-y-2">
                <div className="flex justify-between items-center">
                  <span className="text-[9px] text-slate-400 font-black uppercase">Protein</span>
                  <span className="text-[10px] font-bold text-slate-700">85g</span>
                </div>
                <ProgressBar progress={85} color="bg-slate-600" height="h-1" />
              </div>
              <div className="space-y-2">
                <div className="flex justify-between items-center">
                  <span className="text-[9px] text-slate-400 font-black uppercase">Fat</span>
                  <span className="text-[10px] font-bold text-slate-700">45g</span>
                </div>
                <ProgressBar progress={40} color="bg-slate-300" height="h-1" />
              </div>
            </div>
          </Card>
        </div>

        {/* Badges Carousel */}
        <div className="px-6 mb-6">
          <div className="flex justify-between items-center mb-3">
            <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest">Achievements</h3>
            <span className="text-xs text-green-600 font-bold">View All</span>
          </div>
          <div className="flex gap-6 bg-white p-4 rounded-3xl border border-slate-100 shadow-sm overflow-x-auto no-scrollbar">
            {getBadgeDefinitions().map(badge => (
              <BadgeItem 
                key={badge.id} 
                icon={badge.icon} 
                name={badge.name} 
                earned={gamification.badges.some(b => b.id === badge.id)} 
              />
            ))}
          </div>
        </div>

        {/* Meal List */}
        <div className="px-6 space-y-4">
          <div className="flex justify-between items-center mb-1">
            <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest">Today's Meals</h3>
          </div>
          {meals.map(meal => (
            <Card key={meal.id} className={`p-4 border-l-4 ${meal.isLogged ? 'border-l-green-500 bg-white' : 'border-l-slate-200 bg-slate-50/50'}`}>
              <div className="flex justify-between items-start mb-3">
                <div>
                  <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{meal.type}</span>
                  <h4 className="font-bold text-slate-800">{meal.name}</h4>
                  <span className="text-sm text-slate-500">{meal.calories} kcal</span>
                </div>
                <div className={`w-6 h-6 rounded-full flex items-center justify-center transition-all ${meal.isLogged ? 'bg-green-500 text-white scale-110 shadow-lg shadow-green-100' : 'border-2 border-slate-200'}`}>
                  {meal.isLogged && <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>}
                </div>
              </div>
              <div className="flex gap-2">
                <Button 
                  variant={meal.isLogged ? 'ghost' : 'outline'} 
                  className="py-1.5 px-3 text-xs rounded-xl flex-1 h-9"
                  onClick={() => setShowLogModal(meal)}
                >
                  {meal.isLogged ? 'Edit Entry' : 'Log Meal'}
                </Button>
                <Button 
                  variant="ghost" 
                  className="py-1.5 px-3 text-xs rounded-xl flex-1 bg-white border border-slate-100 h-9"
                  onClick={() => openAlternative(meal)}
                >
                  Swap Item
                </Button>
              </div>
            </Card>
          ))}
        </div>
      </div>

      {/* Alternative Modal */}
      {selectedMealForAlt && (
        <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex flex-col justify-end">
          <div className="bg-white rounded-t-[40px] p-8 max-h-[85%] overflow-y-auto animate-in slide-in-from-bottom duration-500">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-800">Forge AI Alternatives</h3>
              <button onClick={() => setSelectedMealForAlt(null)} className="p-2 bg-slate-100 rounded-full">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>

            {loadingAlts ? (
              <div className="py-20 text-center">
                <div className="w-16 h-16 border-4 border-green-500 border-t-transparent rounded-full animate-spin mx-auto mb-6"></div>
                <p className="text-slate-500 font-medium">Scanning metabolic profile...</p>
              </div>
            ) : (
              <div className="space-y-6 pb-10">
                {alternatives.map((alt, i) => (
                  <Card key={i} className="bg-green-50/50 border-green-100 hover:scale-[1.02] active:scale-95" onClick={() => applyAlternative(alt)}>
                    <div className="flex justify-between mb-2">
                      <h4 className="font-bold text-slate-800">{alt.name}</h4>
                      <span className="text-sm font-bold text-green-700">{alt.calories} kcal</span>
                    </div>
                    <div className="flex gap-4 text-[10px] font-bold text-slate-500 uppercase mb-3">
                      <span className="bg-white px-2 py-0.5 rounded shadow-sm">P: {alt.protein}g</span>
                      <span className="bg-white px-2 py-0.5 rounded shadow-sm">C: {alt.carbs}g</span>
                      <span className="bg-white px-2 py-0.5 rounded shadow-sm">F: {alt.fat}g</span>
                    </div>
                    <div className="space-y-2 border-t border-green-100 pt-3 mt-2">
                      <div className="flex gap-2 items-start">
                        <span className="bg-green-500 text-white text-[9px] px-1.5 py-0.5 rounded uppercase font-black mt-0.5 tracking-tighter">Timing</span>
                        <p className="text-xs text-slate-700 leading-tight">"{alt.timingTip}"</p>
                      </div>
                      <div className="flex gap-2 items-start">
                        <span className="bg-blue-500 text-white text-[9px] px-1.5 py-0.5 rounded uppercase font-black mt-0.5 tracking-tighter">Synergy</span>
                        <p className="text-xs text-slate-700 leading-tight">"{alt.synergyTip}"</p>
                      </div>
                    </div>
                  </Card>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Log Modal */}
      {showLogModal && (
        <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex flex-col justify-end">
          <div className="bg-white rounded-t-[40px] p-8 animate-in slide-in-from-bottom duration-500">
             <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-800">Log {showLogModal.type}</h3>
              <button onClick={() => setShowLogModal(null)} className="p-2 bg-slate-100 rounded-full">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            <Card className="mb-6 bg-slate-50">
              <h4 className="font-bold mb-1 text-slate-800">{showLogModal.name}</h4>
              <p className="text-sm text-slate-500 mb-4">{showLogModal.calories} kcal per serving</p>
              <div className="space-y-4">
                <label className="text-xs font-black text-slate-400 uppercase tracking-widest block">Adjust Portion</label>
                <div className="flex gap-2">
                  {['0.5x', '1x', '1.5x', '2x'].map(p => (
                    <button key={p} className={`flex-1 py-3 rounded-2xl text-xs font-black ${p === '1x' ? 'bg-green-500 text-white shadow-lg shadow-green-100' : 'bg-white border border-slate-200 text-slate-500'}`}>{p}</button>
                  ))}
                </div>
              </div>
            </Card>
            <div className="space-y-4">
               <textarea 
                className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 text-sm focus:outline-none focus:ring-2 focus:ring-green-500" 
                placeholder="How was the meal? Any swaps?"
                rows={3}
               />
               <Button className="w-full h-14" onClick={() => handleLog(showLogModal.id)}>
                 Confirm Log (+20 Points)
               </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { UserProfile, HealthGoal, Cuisine, MealFrequency, DietPreference, MealPlan, Meal } from './types';
import Onboarding from './views/Onboarding';
import PlanSelection from './views/PlanSelection';
import Dashboard from './views/Dashboard';
import FreeMode from './views/FreeMode';

type View = 'onboarding' | 'plan-selection' | 'dashboard' | 'free-mode' | 'insights';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('onboarding');
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [selectedPlan, setSelectedPlan] = useState<MealPlan | null>(null);
  const [time, setTime] = useState(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));

  useEffect(() => {
    const timer = setInterval(() => {
      setTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    }, 10000);
    return () => clearInterval(timer);
  }, []);

  const handleOnboardingComplete = (data: UserProfile) => {
    setProfile(data);
    setCurrentView('plan-selection');
  };

  const handlePlanSelect = (plan: MealPlan | null) => {
    if (plan) {
      setSelectedPlan(plan);
      setCurrentView('dashboard');
    } else {
      setCurrentView('free-mode');
    }
  };

  const isMainApp = ['dashboard', 'free-mode', 'insights'].includes(currentView);

  return (
    <div className="min-h-screen bg-slate-200 flex items-center justify-center p-0 sm:p-4">
