        {/* Mobile Status Bar */}
        <div className="h-10 flex justify-between items-center px-8 shrink-0 z-50 bg-white/80 backdrop-blur-sm">
          <span className="text-xs font-bold text-slate-800">{time}</span>
          <div className="flex gap-1.5 items-center">
            <svg className="w-4 h-4 text-slate-800" fill="currentColor" viewBox="0 0 20 20"><path d="M2 11a1 1 0 011-1h2a1 1 0 011 1v5a1 1 0 01-1 1H3a1 1 0 01-1-1v-5zm6-4a1 1 0 011-1h2a1 1 0 011 1v9a1 1 0 01-1 1H9a1 1 0 01-1-1V7zm6-4a1 1 0 011-1h2a1 1 0 011 1v13a1 1 0 01-1 1h-2a1 1 0 01-1-1V3z"></path></svg>
            <div className="w-5 h-2.5 border border-slate-800 rounded-sm relative">
              <div className="absolute left-0.5 top-0.5 bottom-0.5 right-1 bg-slate-800 rounded-px"></div>
