import React, { useState, useEffect } from 'react';
import { UserProfile, MealPlan, Meal, MealAlternative, GamificationState, ActivityData } from '../types';
import { Card, ProgressBar, Button, BadgeItem } from '../components/UI';
import { generateMealAlternatives } from '../services/geminiService';
import { fetchWearableData, getBadgeDefinitions } from '../services/activityService';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  onExit: () => void;
}

const INITIAL_MEALS: Meal[] = [
  { id: '1', type: 'Breakfast', name: 'Avocado Toast & Boiled Egg', calories: 350, isLogged: false, protein: 15, carbs: 30, fat: 20 },
  { id: '2', type: 'Lunch', name: 'Grilled Chicken Quinoa Bowl', calories: 450, isLogged: true, protein: 35, carbs: 40, fat: 12 },
  { id: '3', type: 'Snack', name: 'Greek Yogurt with Berries', calories: 200, isLogged: false, protein: 12, carbs: 20, fat: 5 },
  { id: '4', type: 'Dinner', name: 'Steamed Fish with Greens', calories: 300, isLogged: false, protein: 25, carbs: 10, fat: 15 },
];

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, onExit }) => {
  const [meals, setMeals] = useState<Meal[]>(INITIAL_MEALS);
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [alternatives, setAlternatives] = useState<MealAlternative[]>([]);
  const [loadingAlts, setLoadingAlts] = useState(false);
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);

  // Gamification & Activity State
  const [gamification, setGamification] = useState<GamificationState>({
    points: 1240,
    streak: 4,
    badges: [{ id: 'sync', name: 'Sync King', icon: '⌚', description: 'Connected a wearable device' }]
  });
  const [activity, setActivity] = useState<ActivityData | null>(null);
  const [pointsAnimation, setPointsAnimation] = useState(false);

  useEffect(() => {
    const syncData = async () => {
      const data = await fetchWearableData();
      setActivity(data);
    };
    syncData();
  }, []);

  const totalConsumed = meals.reduce((sum, m) => m.isLogged ? sum + m.calories : sum, 0);
  const activityBonus = activity ? Math.round(activity.caloriesBurned * 0.8) : 0;
  const targetCals = plan.calories + activityBonus;

  const handleLog = (mealId: string) => {
    setMeals(prev => prev.map(m => m.id === mealId ? { ...m, isLogged: !m.isLogged } : m));
    setShowLogModal(null);

    // Gamification Reward
    setGamification(prev => ({ ...prev, points: prev.points + 20 }));
    setPointsAnimation(true);
    setTimeout(() => setPointsAnimation(false), 2000);
  };

  const openAlternative = async (meal: Meal) => {
    setSelectedMealForAlt(meal);
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setAlternatives(alts);
    setLoadingAlts(false);
  };

  const applyAlternative = (alt: MealAlternative) => {
    if (!selectedMealForAlt) return;
    setMeals(prev => prev.map(m => m.id === selectedMealForAlt.id ? {
      ...m,
      name: alt.name,
      calories: alt.calories,
      protein: alt.protein,
      carbs: alt.carbs,
      fat: alt.fat,
      isLogged: false
    } : m));
    setSelectedMealForAlt(null);
  };

  return (
    <div className="flex-1 flex flex-col bg-slate-50 overflow-hidden relative">
      {/* Header */}
      <div className="p-6 pt-2 bg-white border-b border-slate-100 flex justify-between items-center z-10">
        <div className="flex flex-col">
          <h2 className="text-xl font-bold text-slate-800 tracking-tight">NutriForge</h2>
          <div className="flex items-center gap-2">
            <span className="text-[10px] text-green-600 font-black uppercase tracking-widest">{plan.name}</span>
            <div className="w-1 h-1 bg-slate-300 rounded-full"></div>
            <div className="flex items-center gap-1 text-orange-500 font-bold text-[10px]">
              <span>🔥</span> {gamification.streak} Day Streak
            </div>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end">
            <span className="text-[9px] text-slate-400 font-black uppercase tracking-wider">Forge Points</span>
            <div className="flex items-center gap-1">
              <span className="font-black text-slate-800">{gamification.points}</span>
              {pointsAnimation && <span className="absolute text-green-500 font-bold animate-bounce text-sm">+20</span>}
            </div>
          </div>
          <button onClick={onExit} className="p-2 text-slate-400 hover:text-slate-600">
             <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pb-32">
        {/* Calendar Strip */}
        <div className="px-6 py-4 flex gap-4 overflow-x-auto no-scrollbar bg-white shadow-sm mb-4">
          {['M', 'T', 'W', 'T', 'F', 'S', 'S'].map((day, i) => (
            <div key={i} className={`flex-shrink-0 w-10 h-14 rounded-2xl flex flex-col items-center justify-center gap-1 ${i === 2 ? 'bg-green-500 text-white shadow-lg shadow-green-100' : 'text-slate-400'}`}>
              <span className="text-[10px] font-black">{day}</span>
              <span className="text-sm font-black">{12 + i}</span>
            </div>
          ))}
        </div>

        {/* Dynamic Activity Card */}
        {activity && (
          <div className="px-6 mb-4">
            <Card className="bg-white border-slate-200 py-3 px-4">
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-slate-800 rounded-full flex items-center justify-center text-white shadow-sm">
                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z"></path></svg>
                  </div>
                  <div>
                    <h4 className="text-[10px] font-black text-slate-800 uppercase tracking-tighter">Wearable Synced</h4>
                    <p className="text-[9px] text-slate-400 font-medium">{activity.lastSynced}</p>
                  </div>
                </div>
                <div className="text-right">
