              <path d="M12 16c-1.657 0-3-1.343-3-3s1.343-3 3-3 3 1.343 3 3-1.343 3-3 3z" />
            </svg>
          )},
          { type: DietPreference.OpenToAll, label: 'Open to all foods', icon: (
            <svg viewBox="0 0 24 24" className="w-12 h-12" fill="none" stroke="currentColor" strokeWidth="1.2">
              <circle cx="12" cy="12" r="9" />
              <circle cx="12" cy="12" r="6" />
              <path d="M19 12h-2M5 12h2M12 19v-2M12 5v2" />
              <path d="M8 8l1.5 1.5M14.5 14.5L16 16M16 8l-1.5 1.5M9.5 14.5L8 16" />
            </svg>
          )},
        ];

        return (
          <div className="flex flex-col h-full bg-white animate-in fade-in duration-500">
            <div className="px-6 pt-16 text-center space-y-4 mb-14">
              <h2 className="text-[32px] font-black text-[#2D2D2D] leading-[1.1] tracking-tight">
                What Kind of<br />Diet Do You Prefer?
              </h2>
              <p className="text-slate-500 text-lg font-medium max-w-[280px] mx-auto leading-relaxed">
                This helps us personalise meal plans and food recommendations for you.
              </p>
            </div>

            <div className="px-6 flex-1 max-w-sm mx-auto w-full">
              {/* Row 1: 3 Items */}
              <div className="grid grid-cols-3 gap-3 mb-4">
                {diets.slice(0, 3).map((diet) => (
                  <button
                    key={diet.label}
                    onClick={() => { setFormData({...formData, dietPreference: diet.type}); next(); }}
                    className={`flex flex-col items-center justify-between pt-8 pb-5 px-2 rounded-[32px] border transition-all duration-300 aspect-[0.85/1] group active:scale-95 ${
                      formData.dietPreference === diet.type 
                        ? 'border-[#39C101] bg-[#F7FFF2] shadow-sm' 
                        : 'border-[#EAEAEA] bg-white hover:border-slate-200'
                    }`}
                  >
                    <div className={`transition-colors ${formData.dietPreference === diet.type ? 'text-[#39C101]' : 'text-slate-400 group-hover:text-slate-600'}`}>
                      {diet.icon}
                    </div>
                    <span className={`text-[12px] font-bold text-center leading-tight tracking-tight ${formData.dietPreference === diet.type ? 'text-slate-900' : 'text-slate-500'}`}>
                      {diet.label}
                    </span>
                  </button>
                ))}
              </div>

              {/* Row 2: 2 Items */}
              <div className="grid grid-cols-2 gap-3 max-w-[220px] mx-auto">
                {diets.slice(3, 5).map((diet) => (
                  <button
                    key={diet.label}
                    onClick={() => { setFormData({...formData, dietPreference: diet.type}); next(); }}
                    className={`flex flex-col items-center justify-between pt-8 pb-5 px-2 rounded-[32px] border transition-all duration-300 aspect-[0.85/1] group active:scale-95 ${
                      formData.dietPreference === diet.type 
                        ? 'border-[#39C101] bg-[#F7FFF2] shadow-sm' 
                        : 'border-[#EAEAEA] bg-white hover:border-slate-200'
                    }`}
                  >
                    <div className={`transition-colors ${formData.dietPreference === diet.type ? 'text-[#39C101]' : 'text-slate-400 group-hover:text-slate-600'}`}>
                      {diet.icon}
                    </div>
                    <span className={`text-[12px] font-bold text-center leading-tight tracking-tight ${formData.dietPreference === diet.type ? 'text-slate-900' : 'text-slate-500'}`}>
                      {diet.label}
                    </span>
                  </button>
                ))}
              </div>
            </div>

            <div className="pb-16 text-center mt-8">
              <span className="text-[13px] font-bold text-slate-400">
                Tap to select any one
              </span>
            </div>
          </div>
        );

      case 5:
        const allergyOptions = [
          { id: 'Nuts', label: 'Nuts', icon: <svg viewBox="0 0 24 24" className="w-10 h-10" fill="none" stroke="currentColor" strokeWidth="1.5"><path d="M12 18a6 6 0 100-12 6 6 0 000 12zM8 12h8M12 8v8" /></svg> },
          { id: 'Dairy', label: 'Dairy', icon: <svg viewBox="0 0 24 24" className="w-10 h-10" fill="none" stroke="currentColor" strokeWidth="1.5"><path d="M7 2h10l1 2v14l-1 2H7l-1-2V4l1-2zM7 6h10" /></svg> },
          { id: 'Gluten', label: 'Gluten', icon: <svg viewBox="0 0 24 24" className="w-10 h-10" fill="none" stroke="currentColor" strokeWidth="1.5"><path d="M12 2L8 6l4 4 4-4-4-4zm0 20l-4-4 4-4 4 4-4 4z" /></svg> },
          { id: 'Seafood', label: 'Seafood', icon: <svg viewBox="0 0 24 24" className="w-10 h-10" fill="none" stroke="currentColor" strokeWidth="1.5"><path d="M22 12s-4-4-10-4-10 4-10 4 4 4 10 4 10-4 10-4z" /></svg> },
          { id: 'Eggs', label: 'Eggs', icon: <svg viewBox="0 0 24 24" className="w-10 h-10" fill="none" stroke="currentColor" strokeWidth="1.5"><path d="M12 21a7 7 0 100-14 7 7 0 000 14zM12 17a3 3 0 100-6 3 3 0 000 6z" /></svg> },
          { id: 'None', label: 'No Allergies', icon: <svg viewBox="0 0 24 24" className="w-10 h-10" fill="none" stroke="currentColor" strokeWidth="1.5"><circle cx="12" cy="12" r="9" /><path d="M9 12l2 2 4-4" /></svg> },
        ];

        return (
          <div className="flex flex-col h-full bg-white animate-in slide-in-from-right duration-500">
            <div className="px-6 pt-16 text-center space-y-4 mb-12">
              <h2 className="text-[32px] font-black text-[#2D2D2D] leading-[1.1] tracking-tight">
                Any Allergies or<br />Restrictions?
              </h2>
              <p className="text-slate-500 text-lg font-medium max-w-[280px] mx-auto leading-relaxed">
                We'll filter out foods that don't sit well with your body.
              </p>
            </div>

            <div className="px-6 flex-1 max-w-sm mx-auto w-full">
              <div className="grid grid-cols-3 gap-3">
                {allergyOptions.map((opt) => (
                  <button
                    key={opt.id}
                    onClick={() => toggleItem(formData.allergies, opt.id, 'allergies')}
                    className={`flex flex-col items-center justify-between pt-8 pb-5 px-2 rounded-[32px] border transition-all duration-300 aspect-[0.85/1] group active:scale-95 ${
                      formData.allergies.includes(opt.id) 
                        ? 'border-[#39C101] bg-[#F7FFF2]' 
                        : 'border-[#EAEAEA] bg-white hover:border-slate-200 shadow-sm'
                    }`}
                  >
                    <div className={`transition-colors ${formData.allergies.includes(opt.id) ? 'text-[#39C101]' : 'text-slate-400 group-hover:text-slate-600'}`}>
                      {opt.icon}
                    </div>
                    <span className={`text-[12px] font-bold text-center leading-tight tracking-tight ${formData.allergies.includes(opt.id) ? 'text-slate-900' : 'text-slate-500'}`}>
                      {opt.label}
                    </span>
                  </button>
                ))}
              </div>
            </div>

            <div className="px-8 pb-16">
              <button 
                disabled={formData.allergies.length === 0}
                onClick={next}
                className="w-full bg-[#39C101] disabled:bg-slate-200 disabled:text-slate-400 text-white font-bold py-5 rounded-full shadow-lg transition-all active:scale-95 text-lg"
              >
                Continue
              </button>
            </div>
          </div>
        );

      case 6:
        return (
          <div className="space-y-4 pt-4">
            <h2 className="text-2xl font-bold text-slate-800 mb-2">Challenging Foods?</h2>
            <p className="text-slate-500 text-sm mb-4">Areas where you struggle most.</p>
            <div className="space-y-3">
              {['Sugar', 'Fried Foods', 'Late-night Snacking', 'Portions', 'Emotional Eating'].map(c => (
                <Card 
                  key={c} 
                  onClick={() => toggleItem(formData.challenges, c, 'challenges')}
                  className={`${formData.challenges.includes(c) ? 'border-green-500 bg-green-50' : ''}`}
                >
                  <span className="font-bold text-slate-700">{c}</span>
                </Card>
              ))}
            </div>
            <Button onClick={next} className="w-full mt-6 h-14 rounded-full">Build My Plan</Button>
          </div>
        );

      case 7:
        return (
          <div className="flex flex-col items-center justify-center space-y-8 py-20 px-8 text-center bg-white h-full">
            <div className="relative w-32 h-32">
              <div className="absolute inset-0 border-4 border-slate-100 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-[#39C101] rounded-full border-t-transparent animate-spin"></div>
            </div>
            <div className="space-y-3">
              <h2 className="text-2xl font-black text-slate-900 animate-pulse tracking-tight">NutriForge is Thinking...</h2>
              <p className="text-slate-500 font-medium">Synthesizing metabolic data and crafting your metabolic blueprint...</p>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="flex-1 flex flex-col relative overflow-hidden bg-white">
      {step > 0 && step < totalSteps - 1 && step !== 4 && step !== 5 && (
        <div className="px-6 pt-6 z-20">
          <ProgressBar progress={(step / (totalSteps - 2)) * 100} height="h-1.5" color="bg-[#39C101]" />
        </div>
      )}
      <div className={`flex-1 flex flex-col ${step === 0 || step === 4 || step === 5 ? '' : 'p-6'} overflow-y-auto z-10`}>
        {renderStep()}
      </div>
    </div>
  );
};

export default Onboarding;

import React from 'react';

export const Button: React.FC<{
  onClick?: () => void;
  children: React.ReactNode;
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
  className?: string;
  disabled?: boolean;
}> = ({ onClick, children, variant = 'primary', className = '', disabled }) => {
  const baseStyles = "px-6 py-3 rounded-2xl font-semibold transition-all duration-200 flex items-center justify-center gap-2 disabled:opacity-50 active:scale-95";
  const variants = {
    primary: "bg-green-500 text-white shadow-lg shadow-green-200 hover:bg-green-600",
    secondary: "bg-slate-800 text-white hover:bg-slate-900",
    outline: "border-2 border-green-500 text-green-600 hover:bg-green-50",
    ghost: "text-slate-500 hover:bg-slate-100",
  };

  return (
    <button onClick={onClick} className={`${baseStyles} ${variants[variant]} ${className}`} disabled={disabled}>
      {children}
    </button>
  );
};

export const BackButton: React.FC<{ onClick: () => void; className?: string }> = ({ onClick, className = '' }) => (
  <button 
    onClick={onClick} 
    className={`p-2 hover:bg-slate-100 rounded-full transition-colors flex items-center justify-center ${className}`}
    aria-label="Go back"
  >
    <svg className="w-6 h-6 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" />
    </svg>
  </button>
);

export const Card: React.FC<{
  children: React.ReactNode;
  className?: string;
  onClick?: () => void;
}> = ({ children, className = '', onClick }) => (
  <div 
    onClick={onClick}
    className={`bg-white rounded-3xl p-6 shadow-sm border border-slate-100 transition-all ${onClick ? 'cursor-pointer hover:shadow-md hover:border-green-100' : ''} ${className}`}
  >
    {children}
  </div>
);

export const ProgressBar: React.FC<{
  progress: number;
  color?: string;
  height?: string;
  label?: string;
  target?: string;
  secondaryProgress?: number;
  secondaryColor?: string;
}> = ({ progress, color = 'bg-green-500', height = 'h-2', label, target, secondaryProgress, secondaryColor = 'bg-blue-400' }) => (
  <div className="w-full space-y-1">
    {(label || target) && (
      <div className="flex justify-between text-sm font-medium text-slate-600">
        <span>{label}</span>
        <span>{target}</span>
      </div>
    )}
    <div className={`w-full bg-slate-100 rounded-full overflow-hidden relative ${height}`}>
      {secondaryProgress !== undefined && (
        <div 
          className={`${secondaryColor} h-full absolute top-0 left-0 transition-all duration-700 ease-out opacity-30`}
          style={{ width: `${Math.min(secondaryProgress, 100)}%` }}
        />
      )}
      <div 
        className={`${color} h-full relative transition-all duration-700 ease-out shadow-sm`}
        style={{ width: `${Math.min(progress, 100)}%` }}
      />
    </div>
  </div>
);

export const BadgeItem: React.FC<{ icon: string; name: string; earned: boolean }> = ({ icon, name, earned }) => (
  <div className={`flex flex-col items-center gap-1 ${earned ? 'opacity-100' : 'opacity-30 grayscale'}`}>
    <div className="w-12 h-12 bg-slate-100 rounded-2xl flex items-center justify-center text-2xl shadow-inner">
      {icon}
    </div>
    <span className="text-[10px] font-bold text-slate-600 text-center">{name}</span>
  </div>
);

import React, { useState, useEffect } from 'react';
import { UserProfile, HealthGoal, Cuisine, MealFrequency, DietPreference } from '../types';
import { Button, Card, ProgressBar, BackButton } from '../components/UI';

interface OnboardingProps {
  onComplete: (data: UserProfile) => void;
}

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(0);
  const [formData, setFormData] = useState<UserProfile>({
    healthGoal: HealthGoal.WeightLoss,
    cuisine: Cuisine.Indian,
    mealFrequency: MealFrequency.ThreePlusSnacks,
    dietPreference: DietPreference.Vegetarian,
    allergies: [],
    challenges: [],
  });

  const totalSteps = 8;

  useEffect(() => {
    if (step === 7) {
      const timer = setTimeout(() => {
        onComplete(formData);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [step, formData, onComplete]);

  const next = () => {
    if (step < totalSteps - 1) {
      setStep(s => s + 1);
    }
  };

  const back = () => {
    if (step > 0) {
      setStep(s => s - 1);
    }
  };

  const toggleItem = (list: string[], item: string, key: keyof UserProfile) => {
    let newList: string[];
    if (item === 'None') {
      newList = ['None'];
    } else {
      newList = list.filter(i => i !== 'None');
      newList = newList.includes(item) 
        ? newList.filter(i => i !== item) 
        : [...newList, item];
    }
    setFormData(prev => ({ ...prev, [key]: newList }));
  };

  const renderStep = () => {
    switch (step) {
      case 0:
        return (
          <div className="absolute inset-0 flex flex-col justify-end overflow-hidden">
            <div className="absolute inset-0 z-0">
              <img 
                src="https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&q=80&w=1000" 
                alt="Healthy Food" 
                className="w-full h-full object-cover scale-105 animate-pulse-slow"
                style={{ animationDuration: '8s' }}
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent"></div>
            </div>
            <div className="relative z-10 p-8 pb-16 text-center space-y-6 animate-in slide-in-from-bottom-8 duration-1000">
              <div className="space-y-3">
                <h1 className="text-4xl font-black text-white leading-[1.1] tracking-tight">
                  Nutrition That Understands Your Body
                </h1>
                <p className="text-slate-200 text-lg font-medium px-4 opacity-90">
                  Powered by food science, genetics & lifestyle data
                </p>
              </div>
              <div className="pt-4">
                <button 
                  onClick={next} 
                  className="w-full bg-[#39C101] hover:bg-[#32aa01] text-white font-bold py-5 px-8 rounded-full shadow-2xl transition-all active:scale-95 text-lg flex items-center justify-center gap-2"
                >
                  Personalise My Nutrition
                </button>
              </div>
            </div>
          </div>
        );

      case 1:
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2" />
            <h2 className="text-2xl font-bold text-slate-800 mb-6">What's your primary health goal?</h2>
            {Object.values(HealthGoal).map(goal => (
              <Card 
                key={goal} 
                onClick={() => { setFormData({...formData, healthGoal: goal}); next(); }}
                className={formData.healthGoal === goal ? 'border-green-500 bg-green-50' : ''}
              >
                <div className="flex justify-between items-center">
                  <span className="font-semibold text-slate-700">{goal}</span>
                  {formData.healthGoal === goal && <span className="text-green-500 font-bold text-lg">✓</span>}
                </div>
              </Card>
            ))}
          </div>
        );

      case 2:
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2" />
            <h2 className="text-2xl font-bold text-slate-800 mb-6">Cuisine Preference</h2>
            <div className="grid grid-cols-2 gap-3">
              {Object.values(Cuisine).map(c => (
                <Card 
                  key={c} 
                  onClick={() => { setFormData({...formData, cuisine: c}); next(); }}
                  className={`${formData.cuisine === c ? 'border-green-500 bg-green-50' : ''} py-5 text-center`}
                >
                  <span className="font-bold text-slate-700">{c}</span>
                </Card>
              ))}
            </div>
          </div>
        );

      case 3:
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2" />
            <h2 className="text-2xl font-bold text-slate-800 mb-6">Meals Per Day</h2>
            {Object.values(MealFrequency).map(f => (
              <Card 
                key={f} 
                onClick={() => { setFormData({...formData, mealFrequency: f}); next(); }}
                className={formData.mealFrequency === f ? 'border-green-500 bg-green-50' : ''}
              >
                <span className="font-bold text-slate-700">{f}</span>
              </Card>
            ))}
          </div>
        );

      case 4:
        const diets = [
          { type: DietPreference.Vegetarian, label: 'Vegetarian', icon: (
            <svg viewBox="0 0 24 24" className="w-12 h-12" fill="none" stroke="currentColor" strokeWidth="1.2">
              <path d="M18.5 3.5c-2 0-3.5 1.5-3.5 1.5S13.5 3.5 11.5 3.5 8 5 8 5s1.5 1.5 1.5 3.5" />
              <path d="M9.5 8.5L3.5 21s3 1 5.5-2.5 4.5-5.5 4.5-5.5l6-9.5-1-1-9 6z" />
            </svg>
          )},
          { type: DietPreference.NonVegetarian, label: 'Non-vegetarian', icon: (
            <svg viewBox="0 0 24 24" className="w-12 h-12" fill="none" stroke="currentColor" strokeWidth="1.2">
              <path d="M14 6c1.5 0 3 1.5 3 4s-1 4-3 4-3-1.5-3-4 1.5-4 3-4zM17 10s4 1 4 4-2 6-5 6h-1l1-3-3-1" />
              <path d="M4 14c0 3 4 3 8 3s8 0 8-3-4-3-8-3-8 0-8 3z" />
              <circle cx="16" cy="14" r="1" />
            </svg>
          )},
          { type: DietPreference.Vegan, label: 'Vegan', icon: (
            <svg viewBox="0 0 24 24" className="w-12 h-12" fill="none" stroke="currentColor" strokeWidth="1.2">
              <path d="M12 21c-4.418 0-8-3.582-8-8 0-5 8-11 8-11s8 6 8 11c0 4.418-3.582 8-8 8z" />
              <path d="M12 21V10M12 14c-2 0-3-1-3-1M12 16c2 0 3-1 3-1" />
            </svg>
          )},
          { type: DietPreference.Eggetarian, label: 'Eggetarian', icon: (
            <svg viewBox="0 0 24 24" className="w-12 h-12" fill="none" stroke="currentColor" strokeWidth="1.2">
              <path d="M12 20c-3.314 0-6-3.134-6-7s2.686-7 6-7 6 3.134 6 7-2.686 7-6 7z" />
              <path d="M12 16c-1.657 0-3-1.343-3-3s1.343-3 3-3 3 1.343 3 3-1.343 3-3 3z" />
            </svg>
          )},
          { type: DietPreference.OpenToAll, label: 'Open to all foods', icon: (
            <svg viewBox="0 0 24 24" className="w-12 h-12" fill="none" stroke="currentColor" strokeWidth="1.2">
              <circle cx="12" cy="12" r="9" />
              <circle cx="12" cy="12" r="6" />
              <path d="M19 12h-2M5 12h2M12 19v-2M12 5v2" />
