              </button>
            </div>
            <Card className="mb-6 bg-slate-50">
              <h4 className="font-bold mb-1 text-slate-800">{showLogModal.name}</h4>
              <p className="text-xs text-slate-500 mb-4">{showLogModal.calories} kcal per serving</p>
              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Adjust Portion</label>
