            <div className="space-y-4">
              {[
                { type: DietPreference.Vegetarian, label: 'Vegetarian' },
                { type: DietPreference.NonVegetarian, label: 'Non-vegetarian' },
                { type: DietPreference.Vegan, label: 'Vegan' },
