                    <span className="font-semibold text-slate-700">{diet.label}</span>
                    {formData.dietPreference === diet.type && <span className="text-green-500 font-bold text-lg">✓</span>}
                  </div>
                </Card>
              ))}
            </div>
          </div>
        );

      case 5:
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2" />
            <h2 className="text-2xl font-bold text-slate-800 mb-6">Any Allergies or Restrictions?</h2>
            <div className="space-y-3">
              {['Nuts', 'Dairy', 'Gluten', 'Seafood', 'Eggs', 'None'].map((opt) => (
                <Card 
                  key={opt} 
                  onClick={() => toggleItem(formData.allergies, opt, 'allergies')}
                  className={formData.allergies.includes(opt) ? 'border-green-500 bg-green-50' : ''}
                >
                  <div className="flex justify-between items-center">
                    <span className="font-semibold text-slate-700">{opt}</span>
                    {formData.allergies.includes(opt) && <span className="text-green-500 font-bold text-lg">✓</span>}
                  </div>
                </Card>
              ))}
            </div>
            <div className="pt-4">
              <Button 
                disabled={formData.allergies.length === 0}
                onClick={next}
                className="w-full h-14 rounded-full"
              >
                Continue
              </Button>
            </div>
          </div>
        );

      case 6:
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2" />
