import { GoogleGenAI, Type } from "@google/genai";
import { Meal, MealAlternative, UserProfile, Recipe } from "../types";

const API_KEY = process.env.API_KEY;

export const generateMealAlternatives = async (
  meal: Meal,
  profile: UserProfile
): Promise<MealAlternative[]> => {
  if (!API_KEY) return [];

  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const prompt = `As a high-end nutrition AI for GOQii NutriForge, suggest 3 alternative meals for a ${profile.dietPreference} user with a goal of ${profile.healthGoal}. 
  The original meal is ${meal.name} (${meal.calories} kcal). 
  The user prefers ${profile.cuisine} cuisine and has these allergies: ${profile.allergies.join(', ') || 'none'}.
  Provide calorie/macro breakdowns, a nutrient timing tip, and a food synergy tip for each.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              calories: { type: Type.NUMBER },
              protein: { type: Type.NUMBER },
              carbs: { type: Type.NUMBER },
              fat: { type: Type.NUMBER },
              timingTip: { type: Type.STRING },
              synergyTip: { type: Type.STRING },
            },
            required: ["name", "calories", "protein", "carbs", "fat", "timingTip", "synergyTip"]
          }
        },
      },
    });

    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Failed to generate alternatives", error);
    return [];
  }
};

export const generateRecipe = async (
  mealName: string,
  profile: UserProfile
): Promise<Recipe | null> => {
  if (!API_KEY) return null;

  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const prompt = `Provide a healthy recipe for ${mealName} suitable for a ${profile.dietPreference} diet.
  Cuisine style: ${profile.cuisine}. 
  Avoid these allergens: ${profile.allergies.join(', ') || 'none'}.
  Format as JSON with ingredients list, step-by-step instructions, prep time, and cook time.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
            instructions: { type: Type.ARRAY, items: { type: Type.STRING } },
            prepTime: { type: Type.STRING },
            cookTime: { type: Type.STRING },
          },
          required: ["ingredients", "instructions", "prepTime", "cookTime"]
        },
      },
    });

    return JSON.parse(response.text || "null");
  } catch (error) {
    console.error("Failed to generate recipe", error);
    return null;
  }
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { UserProfile, MealPlan, Meal, MealAlternative, GamificationState, ActivityData, Recipe } from '../types';
import { Card, ProgressBar, Button, BadgeItem, BackButton } from '../components/UI';
import { generateMealAlternatives, generateRecipe } from '../services/geminiService';
import { fetchWearableData, getBadgeDefinitions } from '../services/activityService';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  meals: Meal[];
  setMeals: React.Dispatch<React.SetStateAction<Meal[]>>;
  onExit: () => void;
  onViewInsights: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, meals, setMeals, onExit, onViewInsights }) => {
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [selectedMealForRecipe, setSelectedMealForRecipe] = useState<Meal | null>(null);
  const [recipeData, setRecipeData] = useState<Recipe | null>(null);
  const [loadingRecipe, setLoadingRecipe] = useState(false);
  const [alternatives, setAlternatives] = useState<MealAlternative[]>([]);
  const [loadingAlts, setLoadingAlts] = useState(false);
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Gamification & Activity State
  const [gamification, setGamification] = useState<GamificationState>({
    points: 1240,
    streak: 4,
    badges: [{ id: 'sync', name: 'Sync King', icon: '⌚', description: 'Connected a wearable device' }]
  });
  const [activity, setActivity] = useState<ActivityData | null>(null);
  const [pointsAnimation, setPointsAnimation] = useState(false);

  // Live Calendar Logic
  const weekDays = useMemo(() => {
    const today = new Date();
    const days = [];
    const start = new Date(today);
    start.setDate(today.getDate() - 3);

    for (let i = 0; i < 7; i++) {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      days.push({
        label: d.toLocaleDateString('en-US', { weekday: 'narrow' }),
        date: d.getDate(),
        isToday: d.toDateString() === today.toDateString(),
      });
    }
    return days;
  }, []);

  useEffect(() => {
    const syncData = async () => {
      const data = await fetchWearableData();
      setActivity(data);
    };
    syncData();
  }, []);

  const totalConsumed = meals.reduce((sum, m) => m.isLogged ? sum + m.calories : sum, 0);
  const activityBonus = activity ? Math.round(activity.caloriesBurned * 0.8) : 0;
  const targetCals = plan.calories + activityBonus;

  const handleLog = (mealId: string) => {
    setMeals(prev => prev.map(m => m.id === mealId ? { ...m, isLogged: !m.isLogged, photoUri: tempPhoto || m.photoUri } : m));
    setShowLogModal(null);
    setTempPhoto(null);

    // Gamification Reward
    setGamification(prev => ({ ...prev, points: prev.points + 20 }));
    setPointsAnimation(true);
    setTimeout(() => setPointsAnimation(false), 2000);
  };

  const openAlternative = async (meal: Meal) => {
    setSelectedMealForAlt(meal);
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setAlternatives(alts);
    setLoadingAlts(false);
  };

  const openRecipe = async (meal: Meal) => {
    setSelectedMealForRecipe(meal);
    setLoadingRecipe(true);
    const recipe = await generateRecipe(meal.name, profile);
    setRecipeData(recipe);
    setLoadingRecipe(false);
  };

  const applyAlternative = (alt: MealAlternative) => {
    if (!selectedMealForAlt) return;
    setMeals(prev => prev.map(m => m.id === selectedMealForAlt.id ? {
      ...m,
      name: alt.name,
      calories: alt.calories,
      protein: alt.protein,
      carbs: alt.carbs,
      fat: alt.fat,
      isLogged: false,
      photoUri: undefined
    } : m));
    setSelectedMealForAlt(null);
  };

  const handlePhotoCapture = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setTempPhoto(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-slate-50 overflow-hidden relative">
      {/* Header */}
      <div className="p-6 pt-2 bg-white border-b border-slate-100 flex justify-between items-center z-10">
        <div className="flex items-center gap-2">
          <BackButton onClick={onExit} className="-ml-2" />
          <div className="flex flex-col">
            <h2 className="text-xl font-bold text-slate-800 tracking-tight">NutriForge</h2>
            <div className="flex items-center gap-2">
              <span className="text-[10px] text-green-600 font-black uppercase tracking-widest">{plan.name}</span>
              <div className="w-1 h-1 bg-slate-300 rounded-full"></div>
              <div className="flex items-center gap-1 text-orange-500 font-bold text-[10px]">
                <span>🔥</span> {gamification.streak} Day Streak
              </div>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end">
            <span className="text-[9px] text-slate-400 font-black uppercase tracking-wider">Forge Points</span>
            <div className="flex items-center gap-1">
              <span className="font-black text-slate-800">{gamification.points}</span>
              {pointsAnimation && <span className="absolute text-green-500 font-bold animate-bounce text-sm">+20</span>}
            </div>
          </div>
          <button className="p-2 text-slate-400 hover:text-slate-600">
             <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pb-32">
        {/* Calendar Strip */}
        <div className="px-6 py-4 flex gap-4 overflow-x-auto no-scrollbar bg-white shadow-sm mb-4">
          {weekDays.map((day, i) => (
            <div key={i} className={`flex-shrink-0 w-10 h-14 rounded-2xl flex flex-col items-center justify-center gap-1 ${day.isToday ? 'bg-green-500 text-white shadow-lg shadow-green-100' : 'text-slate-400'}`}>
              <span className="text-[10px] font-black">{day.label}</span>
              <span className="text-sm font-black">{day.date}</span>
            </div>
          ))}
        </div>

        {/* Dynamic Activity Card */}
        {activity && (
          <div className="px-6 mb-4">
            <Card className="bg-white border-slate-200 py-3 px-4">
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-slate-800 rounded-full flex items-center justify-center text-white shadow-sm">
                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z"></path></svg>
                  </div>
                  <div>
                    <h4 className="text-[10px] font-black text-slate-800 uppercase tracking-tighter">Wearable Synced</h4>
                    <p className="text-[9px] text-slate-400 font-medium">{activity.lastSynced}</p>
                  </div>
                </div>
                <div className="text-right">
                  <span className="text-sm font-black text-slate-900">+{activity.caloriesBurned} kcal</span>
                  <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tight">{activity.steps} Steps</p>
                </div>
              </div>
            </Card>
          </div>
        )}

        {/* Stats Area (Light Grey Scale) */}
        <div className="px-6 space-y-4 mb-6">
          <Card 
            onClick={onViewInsights}
            className="bg-slate-50 border-slate-200 shadow-sm relative overflow-hidden group hover:border-green-300 transition-colors"
          >
            <div className="flex justify-between items-end mb-4">
              <div className="space-y-0.5">
                <div className="flex items-center gap-1">
                  <span className="text-[9px] text-slate-400 font-black uppercase tracking-widest">Daily Energy</span>
                  <svg className="w-3 h-3 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7"></path></svg>
                </div>
                <div className="flex items-baseline gap-1">
                  <span className="text-3xl font-black text-slate-900 tracking-tighter">{totalConsumed}</span>
                  <span className="text-sm text-slate-400 font-bold">/ {targetCals} kcal</span>
                </div>
              </div>
              <div className="w-12 h-12 rounded-full border-4 border-slate-200 flex items-center justify-center">
                <span className="text-[10px] font-black text-slate-800">{Math.round((totalConsumed/targetCals)*100)}%</span>
              </div>
            </div>

            <ProgressBar 
              progress={(totalConsumed / targetCals) * 100} 
              secondaryProgress={(totalConsumed / plan.calories) * 100}
              color="bg-slate-800"
              secondaryColor="bg-slate-300"
              height="h-3"
            />

            <p className="text-[10px] text-slate-400 mt-3 font-medium italic">*Tap to view detailed macro forge</p>
          </Card>
        </div>

        {/* Meal List */}
        <div className="px-6 space-y-4">
          <div className="flex justify-between items-center mb-1">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-none">Today's Meals</h3>
          </div>
          {meals.map(meal => (
            <Card key={meal.id} className={`p-4 border-l-4 ${meal.isLogged ? 'border-l-green-500 bg-white shadow-md' : 'border-l-slate-200 bg-slate-50/50'}`}>
              <div className="flex gap-4">
                {meal.photoUri && (
                  <div className="w-20 h-20 rounded-2xl overflow-hidden shadow-inner shrink-0 border border-slate-100">
                    <img src={meal.photoUri} alt="Meal" className="w-full h-full object-cover" />
                  </div>
                )}
                <div className="flex-1">
                  <div className="flex justify-between items-start mb-2">
                    <div onClick={onViewInsights} className="cursor-pointer">
                      <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{meal.type}</span>
                      <h4 className="font-bold text-slate-800 text-sm leading-tight">{meal.name}</h4>
                      <span className="text-xs text-slate-500 font-medium">{meal.calories} kcal</span>
                    </div>
                    <div 
                      onClick={() => setShowLogModal(meal)}
                      className={`w-6 h-6 rounded-full cursor-pointer flex items-center justify-center transition-all ${meal.isLogged ? 'bg-green-500 text-white scale-110 shadow-lg shadow-green-100' : 'border-2 border-slate-200'}`}
                    >
                      {meal.isLogged && <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>}
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <Button 
                      variant={meal.isLogged ? 'ghost' : 'outline'} 
                      className="py-1 px-3 text-[9px] rounded-xl flex-1 h-7 bg-white/50 border-slate-100"
                      onClick={() => openRecipe(meal)}
                    >
                      Recipe AI
                    </Button>
                    <Button 
                      variant="ghost" 
                      className="py-1 px-3 text-[9px] rounded-xl flex-1 bg-white border border-slate-100 h-7"
                      onClick={() => openAlternative(meal)}
                    >
                      Swap AI
                    </Button>
                  </div>
                </div>
              </div>
            </Card>
          ))}
        </div>
      </div>

      {/* Recipe Modal */}
      {selectedMealForRecipe && (
        <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex flex-col justify-end">
          <div className="bg-white rounded-t-[40px] p-8 max-h-[85%] overflow-y-auto animate-in slide-in-from-bottom duration-500">
            <div className="flex justify-between items-center mb-6">
              <div>
                <h3 className="text-xl font-bold text-slate-800">{selectedMealForRecipe.name}</h3>
                <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">NutriForge Recipe</p>
              </div>
              <button onClick={() => { setSelectedMealForRecipe(null); setRecipeData(null); }} className="p-2 bg-slate-100 rounded-full">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>

            {loadingRecipe ? (
              <div className="py-20 text-center">
                <div className="w-16 h-16 border-4 border-green-500 border-t-transparent rounded-full animate-spin mx-auto mb-6"></div>
                <p className="text-slate-500 font-medium">Forging the culinary blueprint...</p>
              </div>
            ) : recipeData ? (
              <div className="space-y-8 pb-10">
                <div className="flex gap-6">
                  <div className="flex flex-col">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Prep</span>
                    <span className="font-bold text-slate-800">{recipeData.prepTime}</span>
                  </div>
                  <div className="flex flex-col">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Cook</span>
                    <span className="font-bold text-slate-800">{recipeData.cookTime}</span>
                  </div>
                </div>

                <div className="space-y-3">
                  <h4 className="text-sm font-black text-slate-800 uppercase tracking-widest border-b border-slate-100 pb-2">Ingredients</h4>
                  <ul className="space-y-2">
                    {recipeData.ingredients.map((ing, i) => (
                      <li key={i} className="flex items-center gap-3 text-sm text-slate-600 font-medium">
                        <div className="w-1.5 h-1.5 bg-green-500 rounded-full"></div>
                        {ing}
                      </li>
                    ))}
                  </ul>
                </div>

                <div className="space-y-4">
                  <h4 className="text-sm font-black text-slate-800 uppercase tracking-widest border-b border-slate-100 pb-2">Instructions</h4>
                  <ol className="space-y-4">
                    {recipeData.instructions.map((step, i) => (
                      <li key={i} className="flex gap-4">
                        <span className="flex-shrink-0 w-6 h-6 bg-slate-100 text-slate-800 rounded-full flex items-center justify-center text-[10px] font-black">{i + 1}</span>
                        <p className="text-sm text-slate-600 leading-relaxed">{step}</p>
                      </li>
                    ))}
                  </ol>
                </div>

                <Button className="w-full h-14" onClick={() => { setShowLogModal(selectedMealForRecipe); setSelectedMealForRecipe(null); setRecipeData(null); }}>
                  Ready to Log Meal
                </Button>
              </div>
            ) : null}
          </div>
        </div>
      )}

      {/* Alternative Modal */}
      {selectedMealForAlt && (
        <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex flex-col justify-end">
          <div className="bg-white rounded-t-[40px] p-8 max-h-[85%] overflow-y-auto animate-in slide-in-from-bottom duration-500">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-800">Forge AI Swaps</h3>
              <button onClick={() => setSelectedMealForAlt(null)} className="p-2 bg-slate-100 rounded-full">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>

            {loadingAlts ? (
              <div className="py-20 text-center">
                <div className="w-16 h-16 border-4 border-green-500 border-t-transparent rounded-full animate-spin mx-auto mb-6"></div>
                <p className="text-slate-500 font-medium">Scanning metabolic profile...</p>
              </div>
            ) : (
              <div className="space-y-6 pb-10">
                {alternatives.map((alt, i) => (
                  <Card key={i} className="bg-green-50/50 border-green-100 hover:scale-[1.02] active:scale-95" onClick={() => applyAlternative(alt)}>
                    <div className="flex justify-between mb-2">
                      <h4 className="font-bold text-slate-800">{alt.name}</h4>
                      <span className="text-sm font-bold text-green-700">{alt.calories} kcal</span>
                    </div>
                    <div className="flex gap-4 text-[9px] font-black text-slate-400 uppercase mb-3">
                      <span>P: {alt.protein}g</span>
                      <span>C: {alt.carbs}g</span>
                      <span>F: {alt.fat}g</span>
                    </div>
                  </Card>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Log Modal with Photo Upload */}
      {showLogModal && (
        <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md z-[120] flex flex-col justify-end">
          <div className="bg-white rounded-t-[40px] p-8 animate-in slide-in-from-bottom duration-500">
             <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-800">Log {showLogModal.type}</h3>
              <button onClick={() => { setShowLogModal(null); setTempPhoto(null); }} className="p-2 bg-slate-100 rounded-full">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>

            <div className="mb-6 flex flex-col items-center">
               <div className="w-full aspect-video bg-slate-100 rounded-[32px] border-2 border-dashed border-slate-200 relative overflow-hidden group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                 {tempPhoto ? (
                   <img src={tempPhoto} alt="Captured" className="w-full h-full object-cover" />
                 ) : (
                   <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-400">
                     <svg className="w-12 h-12 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                     <span className="text-[10px] font-black uppercase tracking-widest">Tap to Snap or Upload Meal Photo</span>
                   </div>
                 )}
                 <input 
                   type="file" 
                   ref={fileInputRef} 
                   className="hidden" 
                   accept="image/*" 
                   capture="environment"
                   onChange={handlePhotoCapture}
                 />
               </div>
            </div>

            <Card className="mb-6 bg-slate-50 border-none">
              <h4 className="font-bold mb-1 text-slate-800 text-center">{showLogModal.name}</h4>
              <p className="text-xs text-slate-500 mb-4 text-center">{showLogModal.calories} kcal per serving</p>
            </Card>

            <div className="space-y-4">
               <Button className="w-full h-14" onClick={() => handleLog(showLogModal.id)}>
                 {showLogModal.isLogged ? 'Update Log' : 'Confirm & Log (+20 Points)'}
               </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { UserProfile, MealPlan, Meal, MealAlternative, GamificationState, ActivityData, Recipe } from '../types';
import { Card, ProgressBar, Button, BadgeItem, BackButton } from '../components/UI';
import { generateMealAlternatives, generateRecipe } from '../services/geminiService';
import { fetchWearableData, getBadgeDefinitions } from '../services/activityService';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  meals: Meal[];
  setMeals: React.Dispatch<React.SetStateAction<Meal[]>>;
  onExit: () => void;
  onViewInsights: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, meals, setMeals, onExit, onViewInsights }) => {
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [selectedMealForRecipe, setSelectedMealForRecipe] = useState<Meal | null>(null);
  const [recipeData, setRecipeData] = useState<Recipe | null>(null);
  const [loadingRecipe, setLoadingRecipe] = useState(false);
  const [alternatives, setAlternatives] = useState<MealAlternative[]>([]);
  const [loadingAlts, setLoadingAlts] = useState(false);
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Gamification & Activity State
  const [gamification, setGamification] = useState<GamificationState>({
    points: 1240,
    streak: 4,
    badges: [{ id: 'sync', name: 'Sync King', icon: '⌚', description: 'Connected a wearable device' }]
  });
  const [activity, setActivity] = useState<ActivityData | null>(null);
  const [pointsAnimation, setPointsAnimation] = useState(false);

  // Live Calendar Logic
  const weekDays = useMemo(() => {
    const today = new Date();
    const days = [];
    const start = new Date(today);
    start.setDate(today.getDate() - 3);

    for (let i = 0; i < 7; i++) {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      days.push({
        label: d.toLocaleDateString('en-US', { weekday: 'narrow' }),
        date: d.getDate(),
        isToday: d.toDateString() === today.toDateString(),
      });
    }
    return days;
  }, []);

  useEffect(() => {
    const syncData = async () => {
      const data = await fetchWearableData();
      setActivity(data);
    };
    syncData();
  }, []);

  const totalConsumed = meals.reduce((sum, m) => m.isLogged ? sum + m.calories : sum, 0);
  const activityBonus = activity ? Math.round(activity.caloriesBurned * 0.8) : 0;
  const targetCals = plan.calories + activityBonus;

  const handleLog = (mealId: string) => {
    setMeals(prev => prev.map(m => m.id === mealId ? { ...m, isLogged: !m.isLogged, photoUri: tempPhoto || m.photoUri } : m));
    setShowLogModal(null);
    setTempPhoto(null);

    // Gamification Reward
    setGamification(prev => ({ ...prev, points: prev.points + 20 }));
    setPointsAnimation(true);
    setTimeout(() => setPointsAnimation(false), 2000);
  };

  const openAlternative = async (meal: Meal) => {
    setSelectedMealForAlt(meal);
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setAlternatives(alts);
    setLoadingAlts(false);
  };

  const openRecipe = async (meal: Meal) => {
    setSelectedMealForRecipe(meal);
    setLoadingRecipe(true);
    const recipe = await generateRecipe(meal.name, profile);
    setRecipeData(recipe);
    setLoadingRecipe(false);
  };

  const applyAlternative = (alt: MealAlternative) => {
    if (!selectedMealForAlt) return;
    setMeals(prev => prev.map(m => m.id === selectedMealForAlt.id ? {
      ...m,
      name: alt.name,
      calories: alt.calories,
      protein: alt.protein,
      carbs: alt.carbs,
      fat: alt.fat,
      isLogged: false,
      photoUri: undefined
    } : m));
    setSelectedMealForAlt(null);
  };

  const handlePhotoCapture = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setTempPhoto(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-slate-50 overflow-hidden relative">
      {/* Header */}
      <div className="p-6 pt-2 bg-white border-b border-slate-100 flex justify-between items-center z-10">
        <div className="flex items-center gap-2">
          <BackButton onClick={onExit} className="-ml-2" />
          <div className="flex flex-col">
            <h2 className="text-xl font-bold text-slate-800 tracking-tight">NutriForge</h2>
            <div className="flex items-center gap-2">
              <span className="text-[10px] text-green-600 font-black uppercase tracking-widest">{plan.name}</span>
              <div className="w-1 h-1 bg-slate-300 rounded-full"></div>
              <div className="flex items-center gap-1 text-orange-500 font-bold text-[10px]">
                <span>🔥</span> {gamification.streak} Day Streak
              </div>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end">
            <span className="text-[9px] text-slate-400 font-black uppercase tracking-wider">Forge Points</span>
            <div className="flex items-center gap-1">
              <span className="font-black text-slate-800">{gamification.points}</span>
              {pointsAnimation && <span className="absolute text-green-500 font-bold animate-bounce text-sm">+20</span>}
            </div>
          </div>
          <button className="p-2 text-slate-400 hover:text-slate-600">
             <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pb-32">
        {/* Calendar Strip */}
        <div className="px-6 py-4 flex gap-4 overflow-x-auto no-scrollbar bg-white shadow-sm mb-4">
