                      <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">{meal.calories} kcal</span>
                    </div>
                    <div 
                      onClick={() => setShowLogModal(meal)}
                      className={`w-6 h-6 rounded-full cursor-pointer flex items-center justify-center transition-all ${meal.isLogged ? 'bg-green-500 text-white scale-110 shadow-lg shadow-green-100 dark:shadow-green-900/40' : 'border-2 border-slate-200 dark:border-slate-600'}`}
                    >
                      {meal.isLogged && <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>}
                    </div>
                  </div>
                  <div className="flex gap-1.5">
                    <Button 
                      variant="outline" 
