  const [recipeData, setRecipeData] = useState<Recipe | null>(null);
  const [loadingRecipe, setLoadingRecipe] = useState(false);
  const [alternatives, setAlternatives] = useState<MealAlternative[]>([]);
  const [loadingAlts, setLoadingAlts] = useState(false);
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Gamification & Activity State
  const [gamification, setGamification] = useState<GamificationState>({
    points: 1240,
    streak: 4,
    badges: [{ id: 'sync', name: 'Sync King', icon: '⌚', description: 'Connected a wearable device' }]
  });
  const [activity, setActivity] = useState<ActivityData | null>(null);
  const [pointsAnimation, setPointsAnimation] = useState(false);

  // Live Calendar Logic
  const weekDays = useMemo(() => {
    const today = new Date();
    const days = [];
    const start = new Date(today);
    start.setDate(today.getDate() - 3);

    for (let i = 0; i < 7; i++) {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      days.push({
        label: d.toLocaleDateString('en-US', { weekday: 'narrow' }),
        date: d.getDate(),
        isToday: d.toDateString() === today.toDateString(),
      });
    }
    return days;
  }, []);

  useEffect(() => {
    const syncData = async () => {
      const data = await fetchWearableData();
      setActivity(data);
    };
    syncData();
  }, []);

  const totalConsumed = meals.reduce((sum, m) => m.isLogged ? sum + m.calories : sum, 0);
  const activityBonus = activity ? Math.round(activity.caloriesBurned * 0.8) : 0;
  const targetCals = plan.calories + activityBonus;

  const handleLog = (mealId: string, forceLogged?: boolean) => {
    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: forceLogged !== undefined ? forceLogged : !m.isLogged, 
      photoUri: tempPhoto || m.photoUri 
    } : m));
    setShowLogModal(null);
    setTempPhoto(null);

    // Gamification Reward only if newly logged
    const wasLogged = meals.find(m => m.id === mealId)?.isLogged;
    if (!wasLogged || forceLogged) {
      setGamification(prev => ({ ...prev, points: prev.points + 20 }));
      setPointsAnimation(true);
      setTimeout(() => setPointsAnimation(false), 2000);
    }
  };

  const openAlternative = async (meal: Meal) => {
    setSelectedMealForAlt(meal);
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setAlternatives(alts);
    setLoadingAlts(false);
  };

  const openRecipe = async (meal: Meal) => {
    setSelectedMealForRecipe(meal);
    setLoadingRecipe(true);
    const recipe = await generateRecipe(meal.name, profile);
    setRecipeData(recipe);
    setLoadingRecipe(false);
  };

  const applyAlternative = (alt: MealAlternative) => {
    if (!selectedMealForAlt) return;
    setMeals(prev => prev.map(m => m.id === selectedMealForAlt.id ? {
      ...m,
      name: alt.name,
      calories: alt.calories,
      protein: alt.protein,
      carbs: alt.carbs,
      fat: alt.fat,
      isLogged: false,
      photoUri: undefined
    } : m));
    setSelectedMealForAlt(null);
  };

  const handlePhotoCapture = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setTempPhoto(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-slate-50 dark:bg-slate-900 overflow-hidden relative transition-colors duration-500">
      {/* Header */}
      <div className="p-6 pt-2 bg-white dark:bg-slate-800 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center z-10 transition-colors">
        <div className="flex items-center gap-2">
          <BackButton onClick={onExit} className="-ml-2 dark:text-slate-100" />
          <div className="flex flex-col">
            <h2 className="text-xl font-bold text-slate-800 dark:text-slate-100 tracking-tight">NutriForge</h2>
            <div className="flex items-center gap-2">
              <span className="text-[10px] text-green-600 dark:text-green-400 font-black uppercase tracking-widest">{plan.name}</span>
              <div className="w-1 h-1 bg-slate-300 dark:bg-slate-600 rounded-full"></div>
              <div className="flex items-center gap-1 text-orange-500 font-bold text-[10px]">
                <span>🔥</span> {gamification.streak} Day Streak
              </div>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end">
            <span className="text-[9px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-wider">Forge Points</span>
            <div className="flex items-center gap-1">
              <span className="font-black text-slate-800 dark:text-slate-100">{gamification.points}</span>
              {pointsAnimation && <span className="absolute text-green-500 font-bold animate-bounce text-sm">+20</span>}
            </div>
          </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pb-32 no-scrollbar">
        {/* Calendar Strip */}
        <div className="px-6 py-4 flex gap-4 overflow-x-auto no-scrollbar bg-white dark:bg-slate-800 shadow-sm mb-4 transition-colors">
          {weekDays.map((day, i) => (
            <div key={i} className={`flex-shrink-0 w-10 h-14 rounded-2xl flex flex-col items-center justify-center gap-1 ${day.isToday ? 'bg-green-500 text-white shadow-lg shadow-green-100 dark:shadow-green-900/20' : 'text-slate-400 dark:text-slate-500'}`}>
              <span className="text-[10px] font-black">{day.label}</span>
              <span className="text-sm font-black">{day.date}</span>
            </div>
          ))}
        </div>

        {/* Dynamic Activity Card */}
        {activity && (
          <div className="px-6 mb-4">
            <Card className="bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 py-3 px-4">
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-slate-800 dark:bg-slate-100 rounded-full flex items-center justify-center text-white dark:text-slate-900 shadow-sm">
                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z"></path></svg>
                  </div>
                  <div>
                    <h4 className="text-[10px] font-black text-slate-800 dark:text-slate-100 uppercase tracking-tighter">Wearable Synced</h4>
                    <p className="text-[9px] text-slate-400 dark:text-slate-500 font-medium">{activity.lastSynced}</p>
                  </div>
                </div>
                <div className="text-right">
                  <span className="text-sm font-black text-slate-900 dark:text-slate-100">+{activity.caloriesBurned} kcal</span>
                  <p className="text-[9px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-tight">{activity.steps} Steps</p>
                </div>
              </div>
            </Card>
          </div>
        )}

        {/* Stats Area */}
        <div className="px-6 space-y-4 mb-6">
          <Card 
            onClick={onViewInsights}
            className="bg-slate-50 dark:bg-slate-800 border-slate-200 dark:border-slate-700 shadow-sm relative overflow-hidden group hover:border-green-300 dark:hover:border-green-800 transition-colors"
          >
            <div className="flex justify-between items-end mb-4">
              <div className="space-y-0.5">
                <div className="flex items-center gap-1">
                  <span className="text-[9px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-widest">Daily Energy</span>
                  <svg className="w-3 h-3 text-slate-300 dark:text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7"></path></svg>
                </div>
                <div className="flex items-baseline gap-1">
                  <span className="text-3xl font-black text-slate-900 dark:text-slate-100 tracking-tighter">{totalConsumed}</span>
                  <span className="text-sm text-slate-400 dark:text-slate-500 font-bold">/ {targetCals} kcal</span>
                </div>
              </div>
              <div className="w-12 h-12 rounded-full border-4 border-slate-200 dark:border-slate-700 flex items-center justify-center">
                <span className="text-[10px] font-black text-slate-800 dark:text-slate-100">{Math.round((totalConsumed/targetCals)*100)}%</span>
              </div>
            </div>

            <ProgressBar 
              progress={(totalConsumed / targetCals) * 100} 
              secondaryProgress={(totalConsumed / plan.calories) * 100}
              color="bg-slate-800 dark:bg-slate-100"
              secondaryColor="bg-slate-300 dark:bg-slate-600"
              height="h-3"
            />

            <p className="text-[10px] text-slate-400 dark:text-slate-500 mt-3 font-medium italic">*Tap to view detailed macro forge</p>
          </Card>
        </div>

        {/* Meal List */}
        <div className="px-6 space-y-4">
          <div className="flex justify-between items-center mb-1">
            <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest leading-none">Today's Meals</h3>
          </div>
          {meals.map(meal => (
            <Card key={meal.id} className={`p-4 border-l-4 dark:border-slate-700 ${meal.isLogged ? 'border-l-green-500 bg-white dark:bg-slate-800 shadow-md' : 'border-l-slate-200 dark:border-l-slate-600 bg-slate-50/50 dark:bg-slate-800/50'}`}>
              <div className="flex gap-4">
                {meal.photoUri && (
                  <div className="w-20 h-20 rounded-2xl overflow-hidden shadow-inner shrink-0 border border-slate-100 dark:border-slate-700">
                    <img src={meal.photoUri} alt="Meal" className="w-full h-full object-cover" />
                  </div>
                )}
                <div className="flex-1">
                  <div className="flex justify-between items-start mb-2">
                    <div onClick={onViewInsights} className="cursor-pointer">
                      <span className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest">{meal.type}</span>
                      <h4 className="font-bold text-slate-800 dark:text-slate-100 text-sm leading-tight">{meal.name}</h4>
                      <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">{meal.calories} kcal</span>
                    </div>
                    <div 
                      onClick={() => setShowLogModal(meal)}
                      className={`w-6 h-6 rounded-full cursor-pointer flex items-center justify-center transition-all ${meal.isLogged ? 'bg-green-500 text-white scale-110 shadow-lg shadow-green-100 dark:shadow-green-900/40' : 'border-2 border-slate-200 dark:border-slate-600'}`}
                    >
                      {meal.isLogged && <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>}
                    </div>
                  </div>
                  <div className="flex gap-1.5">
                    <Button 
                      variant="outline" 
                      className="py-1 px-2 text-[9px] rounded-xl flex-1 h-7 bg-white/50 dark:bg-slate-700/50 border-slate-100 dark:border-slate-600"
                      onClick={() => openRecipe(meal)}
                    >
                      Recipe
                    </Button>
                    <Button 
                      variant="outline" 
                      className="py-1 px-2 text-[9px] rounded-xl flex-1 bg-white/50 dark:bg-slate-700/50 border border-slate-100 dark:border-slate-600"
                      onClick={() => openAlternative(meal)}
                    >
                      Swap
                    </Button>
                    <Button 
                      variant={meal.isLogged ? 'ghost' : 'primary'} 
                      className={`py-1 px-2 text-[9px] rounded-xl flex-1 h-7 ${meal.isLogged ? 'text-green-600 dark:text-green-400 font-black' : ''}`}
                      onClick={() => setShowLogModal(meal)}
                    >
                      {meal.isLogged ? 'Logged' : 'Log'}
                    </Button>
                  </div>
                </div>
              </div>
            </Card>
          ))}
        </div>
      </div>

      {/* Recipe Modal */}
      {selectedMealForRecipe && (
        <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex flex-col justify-end">
          <div className="bg-white dark:bg-slate-800 rounded-t-[40px] p-8 max-h-[85%] overflow-y-auto animate-in slide-in-from-bottom duration-500">
            <div className="flex justify-between items-center mb-6">
              <div>
                <h3 className="text-xl font-bold text-slate-800 dark:text-slate-100">{selectedMealForRecipe.name}</h3>
                <p className="text-xs text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest">NutriForge Recipe AI</p>
              </div>
              <button onClick={() => { setSelectedMealForRecipe(null); setRecipeData(null); }} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full">
                <svg className="w-5 h-5 text-slate-500 dark:text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>

            {loadingRecipe ? (
              <div className="py-20 text-center">
                <div className="w-16 h-16 border-4 border-green-500 border-t-transparent rounded-full animate-spin mx-auto mb-6"></div>
                <p className="text-slate-500 dark:text-slate-400 font-medium">Forging culinary blueprint...</p>
              </div>
            ) : recipeData ? (
              <div className="space-y-8 pb-10">
                <div className="flex gap-6">
                  <div className="flex flex-col">
                    <span className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Prep</span>
                    <span className="font-bold text-slate-800 dark:text-slate-100">{recipeData.prepTime}</span>
                  </div>
                  <div className="flex flex-col">
                    <span className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Cook</span>
                    <span className="font-bold text-slate-800 dark:text-slate-100">{recipeData.cookTime}</span>
                  </div>
                </div>
                <div className="space-y-3">
                  <h4 className="text-sm font-black text-slate-800 dark:text-slate-100 uppercase tracking-widest border-b border-slate-100 dark:border-slate-700 pb-2">Ingredients</h4>
                  <ul className="space-y-2">
                    {recipeData.ingredients.map((ing, i) => (
                      <li key={i} className="flex items-center gap-3 text-sm text-slate-600 dark:text-slate-400 font-medium">
                        <div className="w-1.5 h-1.5 bg-green-500 rounded-full"></div>
                        {ing}
                      </li>
                    ))}
                  </ul>
                </div>
                <div className="space-y-4">
                  <h4 className="text-sm font-black text-slate-800 dark:text-slate-100 uppercase tracking-widest border-b border-slate-100 dark:border-slate-700 pb-2">Instructions</h4>
                  <ol className="space-y-4">
                    {recipeData.instructions.map((step, i) => (
                      <li key={i} className="flex gap-4">
                        <span className="flex-shrink-0 w-6 h-6 bg-slate-100 dark:bg-slate-700 text-slate-800 dark:text-slate-100 rounded-full flex items-center justify-center text-[10px] font-black">{i + 1}</span>
                        <p className="text-sm text-slate-600 dark:text-slate-400 leading-relaxed">{step}</p>
                      </li>
                    ))}
                  </ol>
                </div>
                <Button className="w-full h-14" onClick={() => { setShowLogModal(selectedMealForRecipe); setSelectedMealForRecipe(null); setRecipeData(null); }}>
                  Ready to Log Meal
                </Button>
              </div>
            ) : null}
          </div>
        </div>
      )}

      {/* Alternative Modal */}
      {selectedMealForAlt && (
        <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex flex-col justify-end">
          <div className="bg-white dark:bg-slate-800 rounded-t-[40px] p-8 max-h-[85%] overflow-y-auto animate-in slide-in-from-bottom duration-500">
            <div className="flex justify-between items-center mb-6">
              <div>
                <h3 className="text-xl font-bold text-slate-800 dark:text-slate-100">Forge AI Swaps</h3>
                <p className="text-xs text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest">Optimized Metabolic Alternatives</p>
              </div>
              <button onClick={() => setSelectedMealForAlt(null)} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full">
                <svg className="w-5 h-5 text-slate-500 dark:text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>

            {loadingAlts ? (
              <div className="py-20 text-center">
                <div className="w-16 h-16 border-4 border-green-500 border-t-transparent rounded-full animate-spin mx-auto mb-6"></div>
                <p className="text-slate-500 dark:text-slate-400 font-medium">Scanning metabolic profile...</p>
              </div>
            ) : (
              <div className="space-y-6 pb-10">
                {alternatives.map((alt, i) => (
                  <Card key={i} className="bg-green-50/50 dark:bg-green-900/10 border-green-100 dark:border-green-900/30 hover:scale-[1.02] active:scale-95" onClick={() => applyAlternative(alt)}>
                    <div className="flex justify-between mb-2">
                      <h4 className="font-bold text-slate-800 dark:text-slate-100">{alt.name}</h4>
                      <span className="text-sm font-bold text-green-700 dark:text-green-400">{alt.calories} kcal</span>
                    </div>
                    <div className="flex gap-4 text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase mb-3">
                      <span>P: {alt.protein}g</span>
                      <span>C: {alt.carbs}g</span>
                      <span>F: {alt.fat}g</span>
                    </div>
                    <p className="text-[11px] text-slate-600 dark:text-slate-400 italic">"{alt.timingTip}"</p>
                  </Card>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Log Modal with Photo Upload */}
      {showLogModal && (
        <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md z-[120] flex flex-col justify-end">
          <div className="bg-white dark:bg-slate-800 rounded-t-[40px] p-8 animate-in slide-in-from-bottom duration-500">
             <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-800 dark:text-slate-100">Log {showLogModal.type}</h3>
              <button onClick={() => { setShowLogModal(null); setTempPhoto(null); }} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full">
                <svg className="w-5 h-5 text-slate-500 dark:text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>

            <div className="mb-6 flex flex-col items-center">
               <div className="w-full aspect-video bg-slate-100 dark:bg-slate-700 rounded-[32px] border-2 border-dashed border-slate-200 dark:border-slate-600 relative overflow-hidden group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                 {tempPhoto ? (
                   <img src={tempPhoto} alt="Captured" className="w-full h-full object-cover" />
                 ) : (
                   <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-400 dark:text-slate-500">
                     <svg className="w-12 h-12 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                     <span className="text-[10px] font-black uppercase tracking-widest">Tap to Snap or Upload Meal Photo</span>
                   </div>
                 )}
                 <input 
                   type="file" 
                   ref={fileInputRef} 
                   className="hidden" 
                   accept="image/*" 
                   capture="environment"
                   onChange={handlePhotoCapture}
                 />
               </div>
            </div>

            <Card className="mb-6 bg-slate-50 dark:bg-slate-700 border-none">
              <h4 className="font-bold mb-1 text-slate-800 dark:text-slate-100 text-center">{showLogModal.name}</h4>
              <p className="text-xs text-slate-500 dark:text-slate-400 mb-4 text-center">{showLogModal.calories} kcal per serving</p>
            </Card>

            <div className="space-y-4">
               <Button className="w-full h-14" onClick={() => handleLog(showLogModal.id, true)}>
                 {showLogModal.isLogged ? 'Update Log' : 'Confirm & Log (+20 Points)'}
               </Button>
               {showLogModal.isLogged && (
                 <Button variant="ghost" className="w-full text-red-500" onClick={() => handleLog(showLogModal.id, false)}>
                   Delete Entry
                 </Button>
               )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { UserProfile, MealPlan, Meal, MealAlternative, GamificationState, ActivityData, Recipe } from '../types';
import { Card, ProgressBar, Button, BadgeItem, BackButton } from '../components/UI';
import { generateMealAlternatives, generateRecipe } from '../services/geminiService';
import { fetchWearableData, getBadgeDefinitions } from '../services/activityService';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  meals: Meal[];
  setMeals: React.Dispatch<React.SetStateAction<Meal[]>>;
  onExit: () => void;
  onViewInsights: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, meals, setMeals, onExit, onViewInsights }) => {
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [selectedMealForRecipe, setSelectedMealForRecipe] = useState<Meal | null>(null);
  const [recipeData, setRecipeData] = useState<Recipe | null>(null);
  const [loadingRecipe, setLoadingRecipe] = useState(false);
  const [alternatives, setAlternatives] = useState<MealAlternative[]>([]);
  const [loadingAlts, setLoadingAlts] = useState(false);
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Gamification & Activity State
  const [gamification, setGamification] = useState<GamificationState>({
    points: 1240,
    streak: 4,
    badges: [{ id: 'sync', name: 'Sync King', icon: '⌚', description: 'Connected a wearable device' }]
  });
  const [activity, setActivity] = useState<ActivityData | null>(null);
  const [pointsAnimation, setPointsAnimation] = useState(false);

  // Live Calendar Logic
  const weekDays = useMemo(() => {
    const today = new Date();
    const days = [];
    const start = new Date(today);
    start.setDate(today.getDate() - 3);

    for (let i = 0; i < 7; i++) {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      days.push({
        label: d.toLocaleDateString('en-US', { weekday: 'narrow' }),
        date: d.getDate(),
        isToday: d.toDateString() === today.toDateString(),
      });
    }
    return days;
  }, []);

  useEffect(() => {
    const syncData = async () => {
      const data = await fetchWearableData();
      setActivity(data);
    };
    syncData();
  }, []);

  const totalConsumed = meals.reduce((sum, m) => m.isLogged ? sum + m.calories : sum, 0);
  const activityBonus = activity ? Math.round(activity.caloriesBurned * 0.8) : 0;
  const targetCals = plan.calories + activityBonus;

  const handleLog = (mealId: string, forceLogged?: boolean) => {
    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: forceLogged !== undefined ? forceLogged : !m.isLogged, 
      photoUri: tempPhoto || m.photoUri 
    } : m));
    setShowLogModal(null);
    setTempPhoto(null);

    // Gamification Reward only if newly logged
    const wasLogged = meals.find(m => m.id === mealId)?.isLogged;
    if (!wasLogged || forceLogged) {
      setGamification(prev => ({ ...prev, points: prev.points + 20 }));
      setPointsAnimation(true);
      setTimeout(() => setPointsAnimation(false), 2000);
    }
  };

  const openAlternative = async (meal: Meal) => {
    setSelectedMealForAlt(meal);
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setAlternatives(alts);
    setLoadingAlts(false);
  };

  const openRecipe = async (meal: Meal) => {
    setSelectedMealForRecipe(meal);
    setLoadingRecipe(true);
    const recipe = await generateRecipe(meal.name, profile);
    setRecipeData(recipe);
    setLoadingRecipe(false);
  };

  const applyAlternative = (alt: MealAlternative) => {
    if (!selectedMealForAlt) return;
    setMeals(prev => prev.map(m => m.id === selectedMealForAlt.id ? {
      ...m,
      name: alt.name,
      calories: alt.calories,
      protein: alt.protein,
      carbs: alt.carbs,
      fat: alt.fat,
      isLogged: false,
      photoUri: undefined
    } : m));
    setSelectedMealForAlt(null);
  };

  const handlePhotoCapture = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setTempPhoto(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-slate-50 dark:bg-slate-900 overflow-hidden relative transition-colors duration-500">
      {/* Header */}
      <div className="p-6 pt-2 bg-white dark:bg-slate-800 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center z-10 transition-colors">
        <div className="flex items-center gap-2">
          <BackButton onClick={onExit} className="-ml-2 dark:text-slate-100" />
          <div className="flex flex-col">
            <h2 className="text-xl font-bold text-slate-800 dark:text-slate-100 tracking-tight">NutriForge</h2>
            <div className="flex items-center gap-2">
              <span className="text-[10px] text-green-600 dark:text-green-400 font-black uppercase tracking-widest">{plan.name}</span>
              <div className="w-1 h-1 bg-slate-300 dark:bg-slate-600 rounded-full"></div>
              <div className="flex items-center gap-1 text-orange-500 font-bold text-[10px]">
                <span>🔥</span> {gamification.streak} Day Streak
              </div>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end">
            <span className="text-[9px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-wider">Forge Points</span>
            <div className="flex items-center gap-1">
              <span className="font-black text-slate-800 dark:text-slate-100">{gamification.points}</span>
              {pointsAnimation && <span className="absolute text-green-500 font-bold animate-bounce text-sm">+20</span>}
            </div>
          </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pb-32 no-scrollbar">
        {/* Calendar Strip */}
        <div className="px-6 py-4 flex gap-4 overflow-x-auto no-scrollbar bg-white dark:bg-slate-800 shadow-sm mb-4 transition-colors">
          {weekDays.map((day, i) => (
            <div key={i} className={`flex-shrink-0 w-10 h-14 rounded-2xl flex flex-col items-center justify-center gap-1 ${day.isToday ? 'bg-green-500 text-white shadow-lg shadow-green-100 dark:shadow-green-900/20' : 'text-slate-400 dark:text-slate-500'}`}>
              <span className="text-[10px] font-black">{day.label}</span>
              <span className="text-sm font-black">{day.date}</span>
            </div>
          ))}
        </div>

        {/* Dynamic Activity Card */}
        {activity && (
          <div className="px-6 mb-4">
            <Card className="bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 py-3 px-4">
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-slate-800 dark:bg-slate-100 rounded-full flex items-center justify-center text-white dark:text-slate-900 shadow-sm">
                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z"></path></svg>
                  </div>
                  <div>
                    <h4 className="text-[10px] font-black text-slate-800 dark:text-slate-100 uppercase tracking-tighter">Wearable Synced</h4>
                    <p className="text-[9px] text-slate-400 dark:text-slate-500 font-medium">{activity.lastSynced}</p>
                  </div>
                </div>
                <div className="text-right">
                  <span className="text-sm font-black text-slate-900 dark:text-slate-100">+{activity.caloriesBurned} kcal</span>
                  <p className="text-[9px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-tight">{activity.steps} Steps</p>
                </div>
              </div>
            </Card>
          </div>
        )}

        {/* Stats Area */}
        <div className="px-6 space-y-4 mb-6">
          <Card 
            onClick={onViewInsights}
            className="bg-slate-50 dark:bg-slate-800 border-slate-200 dark:border-slate-700 shadow-sm relative overflow-hidden group hover:border-green-300 dark:hover:border-green-800 transition-colors"
          >
            <div className="flex justify-between items-end mb-4">
              <div className="space-y-0.5">
                <div className="flex items-center gap-1">
                  <span className="text-[9px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-widest">Daily Energy</span>
                  <svg className="w-3 h-3 text-slate-300 dark:text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7"></path></svg>
                </div>
                <div className="flex items-baseline gap-1">
                  <span className="text-3xl font-black text-slate-900 dark:text-slate-100 tracking-tighter">{totalConsumed}</span>
                  <span className="text-sm text-slate-400 dark:text-slate-500 font-bold">/ {targetCals} kcal</span>
                </div>
              </div>
              <div className="w-12 h-12 rounded-full border-4 border-slate-200 dark:border-slate-700 flex items-center justify-center">
                <span className="text-[10px] font-black text-slate-800 dark:text-slate-100">{Math.round((totalConsumed/targetCals)*100)}%</span>
              </div>
            </div>

            <ProgressBar 
              progress={(totalConsumed / targetCals) * 100} 
              secondaryProgress={(totalConsumed / plan.calories) * 100}
              color="bg-slate-800 dark:bg-slate-100"
              secondaryColor="bg-slate-300 dark:bg-slate-600"
              height="h-3"
            />

            <p className="text-[10px] text-slate-400 dark:text-slate-500 mt-3 font-medium italic">*Tap to view detailed macro forge</p>
          </Card>
        </div>

        {/* Meal List */}
        <div className="px-6 space-y-4">
          <div className="flex justify-between items-center mb-1">
            <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest leading-none">Today's Meals</h3>
          </div>
          {meals.map(meal => (
            <Card key={meal.id} className={`p-4 border-l-4 dark:border-slate-700 ${meal.isLogged ? 'border-l-green-500 bg-white dark:bg-slate-800 shadow-md' : 'border-l-slate-200 dark:border-l-slate-600 bg-slate-50/50 dark:bg-slate-800/50'}`}>
              <div className="flex gap-4">
                {meal.photoUri && (
                  <div className="w-20 h-20 rounded-2xl overflow-hidden shadow-inner shrink-0 border border-slate-100 dark:border-slate-700">
                    <img src={meal.photoUri} alt="Meal" className="w-full h-full object-cover" />
                  </div>
                )}
                <div className="flex-1">
                  <div className="flex justify-between items-start mb-2">
                    <div onClick={onViewInsights} className="cursor-pointer">
                      <span className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest">{meal.type}</span>
                      <h4 className="font-bold text-slate-800 dark:text-slate-100 text-sm leading-tight">{meal.name}</h4>
                      <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">{meal.calories} kcal</span>
                    </div>
                    <div 
                      onClick={() => setShowLogModal(meal)}
                      className={`w-6 h-6 rounded-full cursor-pointer flex items-center justify-center transition-all ${meal.isLogged ? 'bg-green-500 text-white scale-110 shadow-lg shadow-green-100 dark:shadow-green-900/40' : 'border-2 border-slate-200 dark:border-slate-600'}`}
                    >
                      {meal.isLogged && <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>}
                    </div>
                  </div>
                  <div className="flex gap-1.5">
                    <Button 
                      variant="outline" 
                      className="py-1 px-2 text-[9px] rounded-xl flex-1 h-7 bg-white/50 dark:bg-slate-700/50 border-slate-100 dark:border-slate-600"
                      onClick={() => openRecipe(meal)}
                    >
                      Recipe
                    </Button>
                    <Button 
                      variant="outline" 
                      className="py-1 px-2 text-[9px] rounded-xl flex-1 bg-white/50 dark:bg-slate-700/50 border border-slate-100 dark:border-slate-600"
                      onClick={() => openAlternative(meal)}
                    >
                      Swap
                    </Button>
                    <Button 
                      variant={meal.isLogged ? 'ghost' : 'primary'} 
                      className={`py-1 px-2 text-[9px] rounded-xl flex-1 h-7 ${meal.isLogged ? 'text-green-600 dark:text-green-400 font-black' : ''}`}
                      onClick={() => setShowLogModal(meal)}
                    >
                      {meal.isLogged ? 'Logged' : 'Log'}
                    </Button>
                  </div>
                </div>
              </div>
            </Card>
          ))}
        </div>
      </div>

      {/* Recipe Modal */}
      {selectedMealForRecipe && (
        <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex flex-col justify-end">
          <div className="bg-white dark:bg-slate-800 rounded-t-[40px] p-8 max-h-[85%] overflow-y-auto animate-in slide-in-from-bottom duration-500">
            <div className="flex justify-between items-center mb-6">
              <div>
                <h3 className="text-xl font-bold text-slate-800 dark:text-slate-100">{selectedMealForRecipe.name}</h3>
                <p className="text-xs text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest">NutriForge Recipe AI</p>
              </div>
              <button onClick={() => { setSelectedMealForRecipe(null); setRecipeData(null); }} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full">
                <svg className="w-5 h-5 text-slate-500 dark:text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>

            {loadingRecipe ? (
              <div className="py-20 text-center">
                <div className="w-16 h-16 border-4 border-green-500 border-t-transparent rounded-full animate-spin mx-auto mb-6"></div>
                <p className="text-slate-500 dark:text-slate-400 font-medium">Forging culinary blueprint...</p>
              </div>
            ) : recipeData ? (
              <div className="space-y-8 pb-10">
                <div className="flex gap-6">
                  <div className="flex flex-col">
                    <span className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Prep</span>
                    <span className="font-bold text-slate-800 dark:text-slate-100">{recipeData.prepTime}</span>
                  </div>
                  <div className="flex flex-col">
                    <span className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Cook</span>
                    <span className="font-bold text-slate-800 dark:text-slate-100">{recipeData.cookTime}</span>
                  </div>
                </div>
                <div className="space-y-3">
                  <h4 className="text-sm font-black text-slate-800 dark:text-slate-100 uppercase tracking-widest border-b border-slate-100 dark:border-slate-700 pb-2">Ingredients</h4>
                  <ul className="space-y-2">
                    {recipeData.ingredients.map((ing, i) => (
                      <li key={i} className="flex items-center gap-3 text-sm text-slate-600 dark:text-slate-400 font-medium">
                        <div className="w-1.5 h-1.5 bg-green-500 rounded-full"></div>
                        {ing}
                      </li>
                    ))}
                  </ul>
                </div>
                <div className="space-y-4">
                  <h4 className="text-sm font-black text-slate-800 dark:text-slate-100 uppercase tracking-widest border-b border-slate-100 dark:border-slate-700 pb-2">Instructions</h4>
                  <ol className="space-y-4">
                    {recipeData.instructions.map((step, i) => (
                      <li key={i} className="flex gap-4">
                        <span className="flex-shrink-0 w-6 h-6 bg-slate-100 dark:bg-slate-700 text-slate-800 dark:text-slate-100 rounded-full flex items-center justify-center text-[10px] font-black">{i + 1}</span>
                        <p className="text-sm text-slate-600 dark:text-slate-400 leading-relaxed">{step}</p>
                      </li>
                    ))}
                  </ol>
                </div>
                <Button className="w-full h-14" onClick={() => { setShowLogModal(selectedMealForRecipe); setSelectedMealForRecipe(null); setRecipeData(null); }}>
                  Ready to Log Meal
                </Button>
              </div>
            ) : null}
          </div>
        </div>
      )}

      {/* Alternative Modal */}
      {selectedMealForAlt && (
        <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex flex-col justify-end">
          <div className="bg-white dark:bg-slate-800 rounded-t-[40px] p-8 max-h-[85%] overflow-y-auto animate-in slide-in-from-bottom duration-500">
            <div className="flex justify-between items-center mb-6">
              <div>
                <h3 className="text-xl font-bold text-slate-800 dark:text-slate-100">Forge AI Swaps</h3>
                <p className="text-xs text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest">Optimized Metabolic Alternatives</p>
              </div>
              <button onClick={() => setSelectedMealForAlt(null)} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full">
                <svg className="w-5 h-5 text-slate-500 dark:text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>

            {loadingAlts ? (
              <div className="py-20 text-center">
                <div className="w-16 h-16 border-4 border-green-500 border-t-transparent rounded-full animate-spin mx-auto mb-6"></div>
                <p className="text-slate-500 dark:text-slate-400 font-medium">Scanning metabolic profile...</p>
              </div>
            ) : (
              <div className="space-y-6 pb-10">
                {alternatives.map((alt, i) => (
                  <Card key={i} className="bg-green-50/50 dark:bg-green-900/10 border-green-100 dark:border-green-900/30 hover:scale-[1.02] active:scale-95" onClick={() => applyAlternative(alt)}>
                    <div className="flex justify-between mb-2">
                      <h4 className="font-bold text-slate-800 dark:text-slate-100">{alt.name}</h4>
                      <span className="text-sm font-bold text-green-700 dark:text-green-400">{alt.calories} kcal</span>
                    </div>
                    <div className="flex gap-4 text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase mb-3">
                      <span>P: {alt.protein}g</span>
                      <span>C: {alt.carbs}g</span>
                      <span>F: {alt.fat}g</span>
                    </div>
                    <p className="text-[11px] text-slate-600 dark:text-slate-400 italic">"{alt.timingTip}"</p>
                  </Card>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Log Modal with Photo Upload */}
      {showLogModal && (
        <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md z-[120] flex flex-col justify-end">
          <div className="bg-white dark:bg-slate-800 rounded-t-[40px] p-8 max-h-[90%] overflow-y-auto animate-in slide-in-from-bottom duration-500 no-scrollbar">
             <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-800 dark:text-slate-100">Log {showLogModal.type}</h3>
              <button onClick={() => { setShowLogModal(null); setTempPhoto(null); }} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full">
                <svg className="w-5 h-5 text-slate-500 dark:text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>

            <div className="mb-6 flex flex-col items-center">
               <div className="w-full aspect-video bg-slate-100 dark:bg-slate-700 rounded-[32px] border-2 border-dashed border-slate-200 dark:border-slate-600 relative overflow-hidden group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                 {tempPhoto ? (
                   <img src={tempPhoto} alt="Captured" className="w-full h-full object-cover" />
                 ) : (
                   <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-400 dark:text-slate-500">
                     <svg className="w-12 h-12 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                     <span className="text-[10px] font-black uppercase tracking-widest">Tap to Snap or Upload Meal Photo</span>
                   </div>
                 )}
                 <input 
                   type="file" 
                   ref={fileInputRef} 
                   className="hidden" 
                   accept="image/*" 
                   capture="environment"
                   onChange={handlePhotoCapture}
                 />
               </div>
            </div>

            <Card className="mb-6 bg-slate-50 dark:bg-slate-700 border-none">
              <h4 className="font-bold mb-1 text-slate-800 dark:text-slate-100 text-center">{showLogModal.name}</h4>
              <p className="text-xs text-slate-500 dark:text-slate-400 mb-4 text-center">{showLogModal.calories} kcal per serving</p>
            </Card>

            {/* AI Nutrition Insight */}
            <div className="mb-8 p-5 bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-indigo-900/20 dark:to-blue-900/20 rounded-[28px] border border-blue-100 dark:border-blue-900/30 relative overflow-hidden group">
               <div className="absolute top-0 right-0 p-3 opacity-20 group-hover:opacity-40 transition-opacity">
                  <svg className="w-8 h-8 text-blue-500" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2L14.4 9.6H22L15.8 14.1L18.2 21.7L12 17.2L5.8 21.7L8.2 14.1L2 9.6H9.6L12 2Z"/></svg>
               </div>
               <div className="relative z-10 flex items-start gap-4">
                  <div className="w-10 h-10 bg-blue-500 text-white rounded-full flex items-center justify-center flex-shrink-0 shadow-lg shadow-blue-200 dark:shadow-blue-900/40">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M13 10V3L4 14h7v7l9-11h-7z"/></svg>
                  </div>
                  <div className="space-y-1">
                    <h5 className="text-[10px] font-black text-blue-600 dark:text-blue-400 uppercase tracking-widest">NutriForge AI Insight</h5>
                    <p className="text-[13px] font-bold text-slate-700 dark:text-slate-200 leading-snug">
                      You are low in protein. We have added Greek yogurt to your afternoon snack to hit the target.
                    </p>
                  </div>
               </div>
            </div>

            <div className="space-y-4 pb-4">
               <Button className="w-full h-14" onClick={() => handleLog(showLogModal.id, true)}>
                 {showLogModal.isLogged ? 'Update Log' : 'Confirm & Log (+20 Points)'}
               </Button>
               {showLogModal.isLogged && (
                 <Button variant="ghost" className="w-full text-red-500" onClick={() => handleLog(showLogModal.id, false)}>
                   Delete Entry
                 </Button>
               )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { UserProfile, MealPlan, Meal, MealAlternative, GamificationState, ActivityData, Recipe } from '../types';
import { Card, ProgressBar, Button, BackButton } from '../components/UI';
import { generateMealAlternatives, generateRecipe } from '../services/geminiService';
import { fetchWearableData } from '../services/activityService';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  meals: Meal[];
  setMeals: React.Dispatch<React.SetStateAction<Meal[]>>;
  onExit: () => void;
  onViewInsights: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, meals, setMeals, onExit, onViewInsights }) => {
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [selectedMealForRecipe, setSelectedMealForRecipe] = useState<Meal | null>(null);
  const [recipeData, setRecipeData] = useState<Recipe | null>(null);
  const [loadingRecipe, setLoadingRecipe] = useState(false);
  const [alternatives, setAlternatives] = useState<MealAlternative[]>([]);
  const [loadingAlts, setLoadingAlts] = useState(false);
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [activity, setActivity] = useState<ActivityData | null>(null);
  const [gamification, setGamification] = useState<GamificationState>({
    points: 1240,
    streak: 4,
    badges: []
  });

  useEffect(() => {
    fetchWearableData().then(setActivity);
  }, []);

  const totalMacros = meals.reduce((acc, m) => m.isLogged ? {
    cals: acc.cals + m.calories,
    pro: acc.pro + m.protein,
    carb: acc.carb + m.carbs,
    fat: acc.fat + m.fat
  } : acc, { cals: 0, pro: 0, carb: 0, fat: 0 });

  const targetCals = plan.calories + (activity ? Math.round(activity.caloriesBurned * 0.8) : 0);
  const calProgress = Math.min((totalMacros.cals / targetCals) * 100, 100);

  const handleLog = (mealId: string, forceLogged?: boolean) => {
    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: forceLogged !== undefined ? forceLogged : !m.isLogged, 
      photoUri: tempPhoto || m.photoUri 
    } : m));
    setShowLogModal(null);
    setTempPhoto(null);
  };

  const openAlternative = async (meal: Meal) => {
    setSelectedMealForAlt(meal);
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setAlternatives(alts);
    setLoadingAlts(false);
  };

  const openRecipe = async (meal: Meal) => {
    setSelectedMealForRecipe(meal);
    setLoadingRecipe(true);
    const recipe = await generateRecipe(meal.name, profile);
    setRecipeData(recipe);
    setLoadingRecipe(false);
  };

  const applyAlternative = (alt: MealAlternative) => {
    if (!selectedMealForAlt) return;
    setMeals(prev => prev.map(m => m.id === selectedMealForAlt.id ? {
      ...m,
      name: alt.name,
      calories: alt.calories,
      protein: alt.protein,
      carbs: alt.carbs,
      fat: alt.fat,
      isLogged: false,
      photoUri: undefined
    } : m));
    setSelectedMealForAlt(null);
  };

  return (
    <div className="flex-1 flex flex-col bg-white dark:bg-slate-950 overflow-y-auto no-scrollbar transition-colors duration-500 pb-24">

      {/* 1. TOP HEADER */}
      <div className="p-6 pt-4 flex justify-between items-start">
        <div className="space-y-0.5">
          <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 tracking-tight">Hello, Champion!</h2>
          <p className="text-[11px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest">{new Date().toDateString()}</p>
          <p className="text-xs text-slate-500 dark:text-slate-400">Your personalised nutrition plan for today</p>
        </div>
        <div className="flex items-center gap-2">
           <div className="w-10 h-10 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center border border-slate-200 dark:border-slate-700">
             <span className="text-lg">🥗</span>
           </div>
        </div>
      </div>

      {/* 2. NUTRITION TARGETS SNAPSHOT */}
      <div className="px-6 mb-8">
        <Card onClick={onViewInsights} className="bg-slate-50 dark:bg-slate-900 border-none relative overflow-hidden p-6 shadow-sm hover:shadow-md transition-shadow">
          <div className="flex items-center gap-6">
            {/* Calorie Ring */}
            <div className="relative w-24 h-24 shrink-0">
              <svg className="w-full h-full -rotate-90">
                <circle cx="48" cy="48" r="40" fill="transparent" stroke="currentColor" strokeWidth="8" className="text-slate-200 dark:text-slate-800" />
                <circle cx="48" cy="48" r="40" fill="transparent" stroke="currentColor" strokeWidth="8" strokeDasharray={`${2 * Math.PI * 40}`} strokeDashoffset={`${2 * Math.PI * 40 * (1 - calProgress / 100)}`} strokeLinecap="round" className="text-green-500 transition-all duration-1000" />
              </svg>
              <div className="absolute inset-0 flex flex-col items-center justify-center text-center">
                <span className="text-lg font-black text-slate-900 dark:text-slate-100 leading-none">{totalMacros.cals}</span>
                <span className="text-[8px] font-black text-slate-400 uppercase">kcal</span>
              </div>
            </div>
            {/* Macro Bars */}
            <div className="flex-1 space-y-3">
              <div className="space-y-1">
                <div className="flex justify-between text-[9px] font-black uppercase text-slate-500">
                  <span>Protein</span>
                  <span>{totalMacros.pro}g / 120g</span>
                </div>
                <div className="h-1.5 w-full bg-slate-200 dark:bg-slate-800 rounded-full overflow-hidden">
                  <div className="h-full bg-indigo-500 transition-all" style={{ width: `${Math.min((totalMacros.pro/120)*100, 100)}%` }}></div>
                </div>
              </div>
              <div className="space-y-1">
                <div className="flex justify-between text-[9px] font-black uppercase text-slate-500">
                  <span>Carbs</span>
                  <span>{totalMacros.carb}g / 200g</span>
                </div>
                <div className="h-1.5 w-full bg-slate-200 dark:bg-slate-800 rounded-full overflow-hidden">
                  <div className="h-full bg-blue-400 transition-all" style={{ width: `${Math.min((totalMacros.carb/200)*100, 100)}%` }}></div>
                </div>
              </div>
              <div className="space-y-1">
                <div className="flex justify-between text-[9px] font-black uppercase text-slate-500">
                  <span>Fats</span>
                  <span>{totalMacros.fat}g / 60g</span>
                </div>
                <div className="h-1.5 w-full bg-slate-200 dark:bg-slate-800 rounded-full overflow-hidden">
                  <div className="h-full bg-yellow-500 transition-all" style={{ width: `${Math.min((totalMacros.fat/60)*100, 100)}%` }}></div>
                </div>
              </div>
            </div>
          </div>
          <p className="text-center text-[10px] font-bold text-green-600 dark:text-green-400 mt-4 uppercase tracking-widest cursor-pointer">View Detailed Forge Metrics →</p>
        </Card>
      </div>

      {/* 3. TODAY’S MEALS */}
      <div className="px-6 space-y-4 mb-8">
        <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest px-1">Daily Fuel Log</h3>
        {meals.map(meal => (
          <Card key={meal.id} className={`p-4 transition-all duration-300 ${meal.isLogged ? 'bg-green-50/30 dark:bg-green-950/10 border-green-100 dark:border-green-900/30' : 'bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800'}`}>
            <div className="flex gap-4">
              <div className="w-16 h-16 rounded-2xl bg-slate-100 dark:bg-slate-800 overflow-hidden shrink-0">
                 <img src={meal.photoUri || `https://picsum.photos/200/200?random=${meal.id}`} className="w-full h-full object-cover" />
              </div>
              <div className="flex-1">
                <div className="flex justify-between items-start">
                  <div>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-wider">{meal.type}</span>
                    <h4 className="font-bold text-slate-800 dark:text-slate-100 text-sm">{meal.name}</h4>
                    <span className="text-xs text-slate-500">{meal.calories} kcal</span>
                  </div>
                  <div className={`w-5 h-5 rounded-full flex items-center justify-center ${meal.isLogged ? 'bg-green-500 text-white' : 'border border-slate-200'}`}>
                    {meal.isLogged && <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"/></svg>}
                  </div>
                </div>
                <div className="flex gap-2 mt-3">
                   <Button variant="outline" className="h-7 py-0 px-3 text-[10px] rounded-lg" onClick={() => openRecipe(meal)}>Recipe</Button>
                   <Button variant="outline" className="h-7 py-0 px-3 text-[10px] rounded-lg" onClick={() => openAlternative(meal)}>Swap</Button>
                   <Button variant={meal.isLogged ? 'ghost' : 'primary'} className="h-7 py-0 px-3 text-[10px] rounded-lg" onClick={() => setShowLogModal(meal)}>
                     {meal.isLogged ? 'Logged' : 'Log'}
                   </Button>
                </div>
              </div>
            </div>
          </Card>
        ))}
      </div>

      {/* 4. TRENDING NUTRITION PLANS */}
      <div className="mb-8">
        <div className="px-6 flex justify-between items-center mb-4">
           <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Trending Master Plans</h3>
           <span className="text-[10px] font-black text-green-600 uppercase">View All</span>
        </div>
        <div className="flex gap-4 overflow-x-auto no-scrollbar px-6">
          {[
            { name: 'Fat Loss Reset', days: '7 Days', color: 'bg-orange-500' },
            { name: 'Muscle Builder', days: '14 Days', color: 'bg-indigo-600' },
            { name: 'Indian Detox', days: '5 Days', color: 'bg-emerald-500' },
          ].map((p, i) => (
            <div key={i} className={`flex-shrink-0 w-40 h-28 ${p.color} rounded-[28px] p-4 text-white flex flex-col justify-between shadow-lg`}>
               <div>
                 <h4 className="font-bold text-sm leading-tight">{p.name}</h4>
                 <p className="text-[10px] opacity-80 font-medium">{p.days}</p>
               </div>
               <div className="w-6 h-6 rounded-full bg-white/20 flex items-center justify-center self-end">
                 <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7"/></svg>
               </div>
            </div>
          ))}
        </div>
      </div>

      {/* 6. QUICK ACTIONS STRIP */}
      <div className="px-6 grid grid-cols-4 gap-4 mb-10">
        {[
          { icon: '📅', label: 'Planner' },
          { icon: '🛒', label: 'Grocery' },
          { icon: '🎯', label: 'Targets' },
          { icon: '⏳', label: 'History' },
        ].map((action, i) => (
          <div key={i} className="flex flex-col items-center gap-2">
            <div className="w-14 h-14 bg-slate-50 dark:bg-slate-900 rounded-[22px] flex items-center justify-center text-xl shadow-sm border border-slate-100 dark:border-slate-800">
              {action.icon}
            </div>
            <span className="text-[10px] font-bold text-slate-500 uppercase">{action.label}</span>
          </div>
        ))}
      </div>

      {/* 8. SMART AI TIPS (Bottom Insight) */}
      <div className="px-6 mb-10">
        <div className="bg-blue-600 rounded-[32px] p-6 text-white shadow-xl relative overflow-hidden group">
           <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:scale-125 transition-transform">
             <svg className="w-16 h-16" fill="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z"/></svg>
           </div>
           <h5 className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-80">NutriForge AI Advice</h5>
           <p className="font-bold text-sm leading-snug">"You are low in protein today. We recommend adding Greek yogurt to your afternoon snack to hit your target!"</p>
        </div>
      </div>

      {/* 9. BLOGS & WELLNESS */}
      <div className="mb-20">
        <div className="px-6 flex justify-between items-center mb-4">
           <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">From GOQii Desk</h3>
           <span className="text-[10px] font-black text-green-600 uppercase">Read More</span>
        </div>
        <div className="space-y-4 px-6">
           <div className="flex gap-4 items-center">
             <div className="w-20 h-20 rounded-2xl bg-slate-100 shrink-0 overflow-hidden">
                <img src="https://picsum.photos/200/200?random=10" className="w-full h-full object-cover" />
             </div>
             <div>
                <h4 className="font-bold text-sm dark:text-slate-100">Superfoods for Metabolism</h4>
                <p className="text-xs text-slate-400">4 min read • By Dr. Sarah</p>
             </div>
           </div>
        </div>
      </div>

      {/* Modals from previous logic (Recipe, Alt, Log) - keeping them functional */}
      {selectedMealForRecipe && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex flex-col justify-end">
          <div className="bg-white dark:bg-slate-800 rounded-t-[40px] p-8 max-h-[85%] overflow-y-auto">
             {/* ... (Existing Recipe Modal Content) ... */}
             <div className="flex justify-between items-center mb-6">
               <h3 className="text-xl font-bold dark:text-white">Recipe AI</h3>
               <button onClick={() => setSelectedMealForRecipe(null)} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full">✕</button>
             </div>
             {loadingRecipe ? <div className="py-20 text-center animate-pulse">Forging...</div> : recipeData && (
               <div className="space-y-4 text-slate-700 dark:text-slate-300">
                 <h4 className="font-bold">Instructions</h4>
                 <ul className="list-disc pl-5">
                   {recipeData.instructions.map((s, i) => <li key={i}>{s}</li>)}
                 </ul>
                 <Button className="w-full" onClick={() => { setShowLogModal(selectedMealForRecipe); setSelectedMealForRecipe(null); }}>Log this Meal</Button>
               </div>
             )}
          </div>
        </div>
      )}

      {selectedMealForAlt && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex flex-col justify-end">
          <div className="bg-white dark:bg-slate-800 rounded-t-[40px] p-8 max-h-[85%] overflow-y-auto">
             <div className="flex justify-between items-center mb-6">
               <h3 className="text-xl font-bold dark:text-white">AI Swaps</h3>
               <button onClick={() => setSelectedMealForAlt(null)} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full">✕</button>
             </div>
             {loadingAlts ? <div className="py-20 text-center animate-pulse">Scanning...</div> : (
               <div className="space-y-4">
                 {alternatives.map((alt, i) => (
                   <Card key={i} onClick={() => applyAlternative(alt)} className="hover:border-green-500">
                     <h4 className="font-bold dark:text-white">{alt.name}</h4>
                     <p className="text-xs text-slate-500">{alt.calories} kcal • {alt.protein}g Protein</p>
                   </Card>
                 ))}
               </div>
             )}
          </div>
        </div>
      )}

      {showLogModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex flex-col justify-end">
          <div className="bg-white dark:bg-slate-800 rounded-t-[40px] p-8">
             <div className="flex justify-between items-center mb-6">
               <h3 className="text-xl font-bold dark:text-white">Log {showLogModal.type}</h3>
               <button onClick={() => setShowLogModal(null)} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full">✕</button>
             </div>
             <div className="w-full h-40 bg-slate-100 dark:bg-slate-700 rounded-3xl mb-6 flex items-center justify-center border-2 border-dashed" onClick={() => fileInputRef.current?.click()}>
               {tempPhoto ? <img src={tempPhoto} className="w-full h-full object-cover rounded-3xl" /> : <span className="text-xs text-slate-400">Capture Meal Photo</span>}
               <input type="file" ref={fileInputRef} hidden capture="environment" onChange={handlePhotoCapture} />
             </div>
             <Button className="w-full h-14" onClick={() => handleLog(showLogModal.id, true)}>Confirm Log</Button>
          </div>
        </div>
      )}

    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { UserProfile, HealthGoal, Cuisine, MealFrequency, DietPreference, MealPlan, Meal } from './types';
import Onboarding from './views/Onboarding';
import PlanSelection from './views/PlanSelection';
import Dashboard from './views/Dashboard';
import FreeMode from './views/FreeMode';
import Insights from './views/Insights';
import Settings from './views/Settings';

type View = 'onboarding' | 'plan-selection' | 'dashboard' | 'free-mode' | 'insights' | 'settings';

const INITIAL_MEALS: Meal[] = [
  { id: '1', type: 'Breakfast', name: 'Avocado Toast & Boiled Egg', calories: 350, isLogged: false, protein: 15, carbs: 30, fat: 20 },
  { id: '2', type: 'Lunch', name: 'Grilled Chicken Quinoa Bowl', calories: 450, isLogged: true, protein: 35, carbs: 40, fat: 12 },
  { id: '3', type: 'Snack', name: 'Greek Yogurt with Berries', calories: 200, isLogged: false, protein: 12, carbs: 20, fat: 5 },
  { id: '4', type: 'Dinner', name: 'Steamed Fish with Greens', calories: 300, isLogged: false, protein: 25, carbs: 10, fat: 15 },
];

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('onboarding');
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [selectedPlan, setSelectedPlan] = useState<MealPlan | null>(null);
  const [meals, setMeals] = useState<Meal[]>(INITIAL_MEALS);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [time, setTime] = useState(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));

  useEffect(() => {
    const timer = setInterval(() => {
      setTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    }, 10000);
    return () => clearInterval(timer);
  }, []);

  const handleOnboardingComplete = (data: UserProfile) => {
    setProfile(data);
    setCurrentView('plan-selection');
  };

  const handlePlanSelect = (plan: MealPlan | null) => {
    if (plan) {
      setSelectedPlan(plan);
      setCurrentView('dashboard');
    } else {
      setCurrentView('free-mode');
    }
  };

  const isMainApp = ['dashboard', 'free-mode', 'insights', 'settings'].includes(currentView);

  return (
    <div className={`min-h-screen ${isDarkMode ? 'bg-slate-950' : 'bg-slate-200'} flex items-center justify-center p-0 sm:p-4 transition-colors duration-500`}>
      <div className={`${isDarkMode ? 'dark' : ''} w-full max-w-md h-[100vh] sm:h-[844px] relative overflow-hidden flex flex-col sm:rounded-[48px] sm:shadow-2xl border-[8px] border-slate-900 shadow-inner`}>
        <div className="w-full h-full bg-slate-50 dark:bg-slate-900 flex flex-col transition-colors duration-500">

          {/* Mobile Status Bar */}
          <div className="h-10 flex justify-between items-center px-8 shrink-0 z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-sm">
            <span className="text-xs font-bold text-slate-800 dark:text-slate-100">{time}</span>
            <div className="flex gap-1.5 items-center">
              <svg className="w-4 h-4 text-slate-800 dark:text-slate-100" fill="currentColor" viewBox="0 0 20 20"><path d="M2 11a1 1 0 011-1h2a1 1 0 011 1v5a1 1 0 01-1 1H3a1 1 0 01-1-1v-5zm6-4a1 1 0 011-1h2a1 1 0 011 1v9a1 1 0 01-1 1H9a1 1 0 01-1-1V7zm6-4a1 1 0 011-1h2a1 1 0 011 1v13a1 1 0 01-1 1h-2a1 1 0 01-1-1V3z"></path></svg>
              <div className="w-5 h-2.5 border border-slate-800 dark:border-slate-100 rounded-sm relative">
                <div className="absolute left-0.5 top-0.5 bottom-0.5 right-1 bg-slate-800 dark:bg-slate-100 rounded-px"></div>
              </div>
            </div>
          </div>

          {/* View Container */}
          <div className="flex-1 flex flex-col overflow-hidden relative">
            {currentView === 'onboarding' && (
              <Onboarding onComplete={handleOnboardingComplete} />
            )}
            {currentView === 'plan-selection' && (
              <PlanSelection onSelect={handlePlanSelect} onBack={() => setCurrentView('onboarding')} />
            )}
            {currentView === 'dashboard' && profile && selectedPlan && (
              <Dashboard 
                profile={profile} 
                plan={selectedPlan} 
                meals={meals}
                setMeals={setMeals}
                onExit={() => setCurrentView('plan-selection')}
                onViewInsights={() => setCurrentView('insights')}
              />
            )}
            {currentView === 'free-mode' && (
              <FreeMode onBack={() => setCurrentView('plan-selection')} currentPlan={selectedPlan} />
            )}
            {currentView === 'insights' && profile && (
              <Insights 
                onBack={() => setCurrentView('dashboard')} 
                meals={meals}
                targetCalories={selectedPlan?.calories || 2000}
              />
            )}
            {currentView === 'settings' && (
              <Settings 
                onBack={() => setCurrentView('dashboard')}
                isDarkMode={isDarkMode}
                onToggleDarkMode={() => setIsDarkMode(!isDarkMode)}
              />
            )}
          </div>

          {/* Mobile Navigation Bar */}
          {isMainApp && (
            <div className="absolute bottom-0 left-0 right-0 h-20 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-t border-slate-100 dark:border-slate-800 flex items-center justify-around px-4 pb-2 z-50">
              <button 
                onClick={() => setCurrentView('dashboard')}
                className={`flex flex-col items-center gap-1 transition-all ${currentView === 'dashboard' ? 'text-green-600' : 'text-slate-400 dark:text-slate-500'}`}
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"></path></svg>
                <span className="text-[10px] font-bold">Home</span>
              </button>
              <button 
                onClick={() => setCurrentView('free-mode')}
                className={`flex flex-col items-center gap-1 transition-all ${currentView === 'free-mode' ? 'text-green-600' : 'text-slate-400 dark:text-slate-500'}`}
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
                <span className="text-[10px] font-bold">Explore</span>
              </button>
              <button 
                onClick={() => setCurrentView('insights')} 
                className={`flex flex-col items-center gap-1 transition-all ${currentView === 'insights' ? 'text-green-600' : 'text-slate-400 dark:text-slate-500'}`}
              >
