              {Object.values(Cuisine).map(c => (
                <Card 
                  key={c} 
                  onClick={() => { setFormData({...formData, cuisine: c}); next(); }}
                  className={`transition-all border-2 ${formData.cuisine === c ? 'border-green-500 bg-green-50 dark:bg-green-950/20' : 'border-slate-100 dark:border-slate-800'} py-6 text-center flex flex-col items-center gap-3`}
                >
                  <span className="text-3xl">{cuisineIcons[c]}</span>
                  <span className="font-bold text-slate-700 dark:text-slate-200 text-sm">{c}</span>
                </Card>
              ))}
            </div>
          </div>
        );

      case 4:
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2 dark:text-slate-300" />
            <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 mb-6 tracking-tight">Meals Per Day</h2>
            <div className="space-y-3">
              {Object.values(MealFrequency).map(f => (
                <Card 
                  key={f} 
                  onClick={() => { setFormData({...formData, mealFrequency: f}); next(); }}
                  className={`transition-all border-2 ${formData.mealFrequency === f ? 'border-green-500 bg-green-50 dark:bg-green-950/20' : 'border-slate-100 dark:border-slate-800'}`}
                >
                  <span className="font-bold text-slate-700 dark:text-slate-200">{f}</span>
                </Card>
              ))}
            </div>
          </div>
        );

      case 5:
        const dietIcons: Record<string, string> = {
          [DietPreference.Vegetarian]: '🥦',
          [DietPreference.Vegan]: '🌿',
          [DietPreference.Eggetarian]: '🥚',
          [DietPreference.NonVegetarian]: '🍗',
          [DietPreference.OpenToAll]: '🥘',
          [DietPreference.Keto]: '🥓',
          [DietPreference.Balanced]: '⚖️',
        };
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2 dark:text-slate-300" />
            <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 mb-6 tracking-tight">Dietary Preference</h2>
            <div className="space-y-3">
              {Object.values(DietPreference).map((type) => (
                <Card 
                  key={type} 
                  onClick={() => { setFormData({...formData, dietPreference: type}); next(); }}
                  className={`transition-all border-2 ${formData.dietPreference === type ? 'border-green-500 bg-green-50 dark:bg-green-950/20' : 'border-slate-100 dark:border-slate-800'}`}
                >
                  <div className="flex items-center gap-4">
                    <span className="text-2xl">{dietIcons[type]}</span>
                    <span className="font-bold text-slate-700 dark:text-slate-200 flex-1">{type}</span>
                    {formData.dietPreference === type && <div className="w-2 h-2 rounded-full bg-green-500"></div>}
                  </div>
                </Card>
              ))}
            </div>
          </div>
        );

      case 6:
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2 dark:text-slate-300" />
            <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 mb-2 tracking-tight">Any Allergies?</h2>
            <p className="text-slate-500 dark:text-slate-400 text-sm mb-4">We'll exclude these from your recipes.</p>
            <div className="grid grid-cols-2 gap-3">
              {['Nuts', 'Dairy', 'Gluten', 'Seafood', 'Eggs', 'None'].map((opt) => (
                <Card 
                  key={opt} 
                  onClick={() => toggleItem(formData.allergies, opt, 'allergies')}
                  className={`transition-all border-2 ${formData.allergies.includes(opt) ? 'border-green-500 bg-green-50 dark:bg-green-950/20' : 'border-slate-100 dark:border-slate-800'} py-4 text-center`}
                >
                  <span className="font-bold text-slate-700 dark:text-slate-200 text-sm">{opt}</span>
                </Card>
              ))}
            </div>
            <div className="pt-4">
              <Button 
                disabled={formData.allergies.length === 0}
                onClick={next}
                className="w-full h-14 rounded-full shadow-lg"
              >
                Continue
              </Button>
            </div>
          </div>
        );

      case 7:
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2 dark:text-slate-300" />
            <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 mb-2 tracking-tight">Challenging Foods?</h2>
            <p className="text-slate-500 dark:text-slate-400 text-sm mb-4">Areas where you struggle most.</p>
            <div className="space-y-3">
              {['Sugar', 'Fried Foods', 'Late-night Snacking', 'Portions', 'Emotional Eating'].map(c => (
                <Card 
                  key={c} 
                  onClick={() => toggleItem(formData.challenges, c, 'challenges')}
                  className={`transition-all border-2 ${formData.challenges.includes(c) ? 'border-green-500 bg-green-50 dark:bg-green-950/20' : 'border-slate-100 dark:border-slate-800'}`}
                >
                  <span className="font-bold text-slate-700 dark:text-slate-200">{c}</span>
                </Card>
              ))}
            </div>
            <Button onClick={next} className="w-full mt-6 h-14 rounded-full shadow-lg">Build My Plan</Button>
          </div>
        );

      case 8:
        return (
          <div className="flex flex-col items-center justify-center space-y-8 py-20 px-8 text-center h-full">
            <div className="relative w-32 h-32">
              <div className="absolute inset-0 border-4 border-slate-100 dark:border-slate-800 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-[#39C101] rounded-full border-t-transparent animate-spin"></div>
            </div>
            <div className="space-y-3">
              <h2 className="text-2xl font-black text-slate-900 dark:text-slate-100 animate-pulse tracking-tight">NutriForge is Thinking...</h2>
              <p className="text-slate-500 dark:text-slate-400 font-medium">Synthesizing metabolic data and crafting your metabolic blueprint in {formData.language}...</p>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="flex-1 flex flex-col relative overflow-hidden bg-white dark:bg-slate-900 transition-colors duration-500">
      {step > 0 && step < totalSteps - 1 && (
        <div className="px-6 pt-6 z-20">
          <ProgressBar progress={(step / (totalSteps - 2)) * 100} height="h-1.5" color="bg-[#39C101]" />
        </div>
      )}
      <div className={`flex-1 flex flex-col p-6 overflow-y-auto z-10 no-scrollbar`}>
        {renderStep()}
      </div>
    </div>
  );
};

export default Onboarding;

import React, { useState, useEffect } from 'react';
import { UserProfile, HealthGoal, Cuisine, MealFrequency, DietPreference, MealPlan, Meal } from './types';
import Onboarding from './views/Onboarding';
import PlanSelection from './views/PlanSelection';
import Dashboard from './views/Dashboard';
import FreeMode from './views/FreeMode';
import Insights from './views/Insights';
import Settings from './views/Settings';
import { Language, translations } from './i18n';

type View = 'onboarding' | 'plan-selection' | 'dashboard' | 'free-mode' | 'insights' | 'settings';

const INITIAL_MEALS: Meal[] = [
  { id: '1', type: 'Breakfast', name: 'Avocado Toast & Boiled Egg', calories: 350, isLogged: false, protein: 15, carbs: 30, fat: 20 },
  { id: '2', type: 'Lunch', name: 'Grilled Chicken Quinoa Bowl', calories: 450, isLogged: true, protein: 35, carbs: 40, fat: 12 },
  { id: '3', type: 'Snack', name: 'Greek Yogurt with Berries', calories: 200, isLogged: false, protein: 12, carbs: 20, fat: 5 },
  { id: '4', type: 'Dinner', name: 'Steamed Fish with Greens', calories: 300, isLogged: false, protein: 25, carbs: 10, fat: 15 },
];

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('onboarding');
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [selectedPlan, setSelectedPlan] = useState<MealPlan | null>(null);
  const [meals, setMeals] = useState<Meal[]>(INITIAL_MEALS);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [language, setLanguage] = useState<Language>('English');
  const [time, setTime] = useState(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));

  useEffect(() => {
    const timer = setInterval(() => {
      setTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    }, 10000);
    return () => clearInterval(timer);
  }, []);

  const t = (key: string) => translations[language]?.[key] || key;

  const handleOnboardingComplete = (data: UserProfile) => {
    setProfile(data);
    setLanguage(data.language as Language);
    setCurrentView('plan-selection');
  };

  const handlePlanSelect = (plan: MealPlan | null) => {
    if (plan) {
      setSelectedPlan(plan);
      setCurrentView('dashboard');
    } else {
      setCurrentView('free-mode');
    }
  };

  const handleUpdateLanguage = (newLang: Language) => {
    setLanguage(newLang);
    if (profile) {
      setProfile({ ...profile, language: newLang });
    }
  };

  const isMainApp = ['dashboard', 'free-mode', 'insights', 'settings'].includes(currentView);

  return (
    <div className={`min-h-screen ${isDarkMode ? 'bg-slate-950' : 'bg-slate-200'} flex items-center justify-center p-0 sm:p-4 transition-colors duration-500`}>
      <div className={`${isDarkMode ? 'dark' : ''} w-full max-w-md h-[100vh] sm:h-[844px] relative overflow-hidden flex flex-col sm:rounded-[48px] sm:shadow-2xl border-[8px] border-slate-900 shadow-inner`}>
        <div className="w-full h-full bg-slate-50 dark:bg-slate-900 flex flex-col transition-colors duration-500">

          <div className="h-10 flex justify-between items-center px-8 shrink-0 z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-sm">
            <span className="text-xs font-bold text-slate-800 dark:text-slate-100">{time}</span>
            <div className="flex gap-1.5 items-center">
              <svg className="w-4 h-4 text-slate-800 dark:text-slate-100" fill="currentColor" viewBox="0 0 20 20"><path d="M2 11a1 1 0 011-1h2a1 1 0 011 1v5a1 1 0 01-1 1H3a1 1 0 01-1-1v-5zm6-4a1 1 0 011-1h2a1 1 0 011 1v9a1 1 0 01-1 1H9a1 1 0 01-1-1V7zm6-4a1 1 0 011-1h2a1 1 0 011 1v13a1 1 0 01-1 1h-2a1 1 0 01-1-1V3z"></path></svg>
              <div className="w-5 h-2.5 border border-slate-800 dark:border-slate-100 rounded-sm relative">
                <div className="absolute left-0.5 top-0.5 bottom-0.5 right-1 bg-slate-800 dark:bg-slate-100 rounded-px"></div>
              </div>
            </div>
          </div>

          <div className="flex-1 flex flex-col overflow-hidden relative">
            {currentView === 'onboarding' && (
              <Onboarding onComplete={handleOnboardingComplete} />
            )}
            {currentView === 'plan-selection' && (
              <PlanSelection onSelect={handlePlanSelect} onBack={() => setCurrentView('onboarding')} t={t} />
            )}
            {currentView === 'dashboard' && profile && selectedPlan && (
              <Dashboard 
                profile={profile} 
                plan={selectedPlan} 
                meals={meals}
                setMeals={setMeals}
                onExit={() => setCurrentView('plan-selection')}
                onViewInsights={() => setCurrentView('insights')}
                t={t}
              />
            )}
            {currentView === 'free-mode' && (
              <FreeMode onBack={() => setCurrentView('plan-selection')} currentPlan={selectedPlan} t={t} />
            )}
            {currentView === 'insights' && profile && (
              <Insights 
                onBack={() => setCurrentView('dashboard')} 
                meals={meals}
                targetCalories={selectedPlan?.calories || 2000}
                t={t}
              />
            )}
            {currentView === 'settings' && (
              <Settings 
                onBack={() => setCurrentView('dashboard')}
                isDarkMode={isDarkMode}
                onToggleDarkMode={() => setIsDarkMode(!isDarkMode)}
                language={language}
                onUpdateLanguage={handleUpdateLanguage}
                t={t}
              />
            )}
          </div>

          {isMainApp && (
            <div className="absolute bottom-0 left-0 right-0 h-20 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-t border-slate-100 dark:border-slate-800 flex items-center justify-around px-4 pb-2 z-50">
              <button 
                onClick={() => setCurrentView('dashboard')}
                className={`flex flex-col items-center gap-1 transition-all ${currentView === 'dashboard' ? 'text-green-600' : 'text-slate-400 dark:text-slate-500'}`}
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"></path></svg>
                <span className="text-[10px] font-bold">{t('home')}</span>
              </button>
              <button 
                onClick={() => setCurrentView('free-mode')}
                className={`flex flex-col items-center gap-1 transition-all ${currentView === 'free-mode' ? 'text-green-600' : 'text-slate-400 dark:text-slate-500'}`}
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
                <span className="text-[10px] font-bold">{t('explore')}</span>
              </button>
              <button 
                onClick={() => setCurrentView('insights')} 
                className={`flex flex-col items-center gap-1 transition-all ${currentView === 'insights' ? 'text-green-600' : 'text-slate-400 dark:text-slate-500'}`}
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"></path></svg>
                <span className="text-[10px] font-bold">{t('insights')}</span>
              </button>
              <button 
                onClick={() => setCurrentView('settings')} 
                className={`flex flex-col items-center gap-1 transition-all ${currentView === 'settings' ? 'text-green-600' : 'text-slate-400 dark:text-slate-500'}`}
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                <span className="text-[10px] font-bold">{t('settings')}</span>
              </button>
            </div>
          )}

          <div className="absolute top-0 left-1/2 -translate-x-1/2 w-32 h-6 bg-slate-900 rounded-b-2xl z-[60] hidden sm:block"></div>
        </div>
      </div>
