export default App;

import React, { useState, useEffect } from 'react';
import { UserProfile, HealthGoal, Cuisine, MealFrequency, DietPreference } from '../types';
import { Button, Card, ProgressBar, BackButton } from '../components/UI';
import { translations, Language } from '../i18n';

interface OnboardingProps {
  onComplete: (data: UserProfile) => void;
}

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(0);
  const [formData, setFormData] = useState<UserProfile>({
    language: 'English',
    healthGoal: HealthGoal.WeightLoss,
    cuisine: Cuisine.Indian,
    mealFrequency: MealFrequency.ThreePlusSnacks,
    dietPreference: DietPreference.Vegetarian,
    allergies: [],
    challenges: [],
  });

  const totalSteps = 9;

  useEffect(() => {
    if (step === 8) {
      const timer = setTimeout(() => {
        onComplete(formData);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [step, formData, onComplete]);

  const t = (key: string) => translations[formData.language as Language]?.[key] || key;

  const next = () => {
    if (step < totalSteps - 1) {
      setStep(s => s + 1);
    }
  };

  const back = () => {
    if (step > 0) {
      setStep(s => s - 1);
    }
  };

  const toggleItem = (list: string[], item: string, key: keyof UserProfile) => {
    let newList: string[];
    if (item === 'None') {
      newList = ['None'];
    } else {
      newList = list.filter(i => i !== 'None');
      newList = newList.includes(item) 
        ? newList.filter(i => i !== item) 
        : [...newList, item];
    }
    setFormData(prev => ({ ...prev, [key]: newList }));
  };

  const renderStep = () => {
    switch (step) {
      case 0:
        return (
          <div className="absolute inset-0 flex flex-col justify-end overflow-hidden">
            <div className="absolute inset-0 z-0">
              <img 
                src="https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&q=80&w=1000" 
                alt="Healthy Food" 
                className="w-full h-full object-cover scale-105 animate-pulse-slow"
                style={{ animationDuration: '8s' }}
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent"></div>
            </div>
            <div className="relative z-10 p-8 pb-16 text-center space-y-6 animate-in slide-in-from-bottom-8 duration-1000">
              <div className="space-y-3">
                <h1 className="text-4xl font-black text-white leading-[1.1] tracking-tight">
                  {t('onboardingTitle')}
                </h1>
                <p className="text-slate-200 text-lg font-medium px-4 opacity-90">
                  {t('onboardingSub')}
                </p>
              </div>
              <div className="pt-4">
                <button 
                  onClick={next} 
                  className="w-full bg-[#39C101] hover:bg-[#32aa01] text-white font-bold py-5 px-8 rounded-full shadow-2xl transition-all active:scale-95 text-lg flex items-center justify-center gap-2"
                >
                  {t('personaliseButton')}
                </button>
              </div>
            </div>
          </div>
        );

      case 1:
        const languages = [
          { name: 'English', native: 'English', icon: '🇺🇸' },
          { name: 'Hindi', native: 'हिन्दी', icon: '🇮🇳' },
          { name: 'Chinese', native: '中文', icon: '🇨🇳' },
          { name: 'Arabic', native: 'العربية', icon: '🇦🇪' },
        ];
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2 dark:text-slate-300" />
            <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 mb-6 tracking-tight">{t('selectLanguage')}</h2>
            <div className="grid grid-cols-1 gap-3">
              {languages.map(lang => (
                <Card 
                  key={lang.name} 
                  onClick={() => { setFormData({...formData, language: lang.name}); next(); }}
                  className={`transition-all border-2 ${formData.language === lang.name ? 'border-green-500 bg-green-50 dark:bg-green-950/20' : 'border-slate-100 dark:border-slate-800'}`}
                >
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 rounded-xl bg-slate-100 dark:bg-slate-700 flex items-center justify-center text-xl">
                      {lang.icon}
                    </div>
                    <div className="flex-1">
                      <span className="font-bold text-slate-800 dark:text-slate-100 block">{lang.name}</span>
                      <span className="text-xs text-slate-400 dark:text-slate-500 font-medium">{lang.native}</span>
                    </div>
                  </div>
                </Card>
              ))}
            </div>
          </div>
        );

      case 2:
        const goalIcons: Record<string, string> = {
          [HealthGoal.WeightLoss]: '⚖️',
          [HealthGoal.MuscleGain]: '💪',
          [HealthGoal.HeartHealth]: '❤️',
          [HealthGoal.Energy]: '⚡',
          [HealthGoal.BalancedLifestyle]: '🧘',
        };
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2 dark:text-slate-300" />
            <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 mb-6 tracking-tight">{t('healthGoalQuestion')}</h2>
            <div className="space-y-3">
              {Object.values(HealthGoal).map(goal => (
                <Card 
                  key={goal} 
                  onClick={() => { setFormData({...formData, healthGoal: goal}); next(); }}
                  className={`transition-all border-2 ${formData.healthGoal === goal ? 'border-green-500 bg-green-50 dark:bg-green-950/20' : 'border-slate-100 dark:border-slate-800'}`}
                >
                  <div className="flex items-center gap-4">
                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-2xl ${formData.healthGoal === goal ? 'bg-green-100 dark:bg-green-900/40' : 'bg-slate-100 dark:bg-slate-800'}`}>
                      {goalIcons[goal]}
                    </div>
                    <div className="flex-1">
                      <span className="font-bold text-slate-700 dark:text-slate-200 block">{goal}</span>
                    </div>
                    {formData.healthGoal === goal && (
                      <div className="w-6 h-6 bg-green-500 rounded-full flex items-center justify-center">
                        <svg className="w-4 h-4 text-white" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>
                      </div>
                    )}
                  </div>
                </Card>
              ))}
            </div>
          </div>
        );

      case 3:
        const cuisineIcons: Record<string, string> = {
          [Cuisine.Indian]: '🍛',
          [Cuisine.Mediterranean]: '🥗',
          [Cuisine.Asian]: '🥢',
          [Cuisine.MiddleEastern]: '🥙',
          [Cuisine.Western]: '🍔',
          [Cuisine.Mixed]: '🍱',
        };
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2 dark:text-slate-300" />
