        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2 dark:text-slate-300" />
            <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 mb-6 tracking-tight">{t('mealsPerDay')}</h2>
