      </div>

      <div className="px-6 space-y-4 mb-8">
        <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">{t('dailyFuelLog')}</h3>
        {meals.map(meal => (
          <Card key={meal.id} className={`p-4 transition-all duration-300 ${meal.isLogged ? 'bg-green-50/20 dark:bg-green-950/10 border-green-100' : 'bg-white dark:bg-slate-900'}`}>
            <div className="flex justify-between items-start mb-3">
              <div>
                <span className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">{meal.type}</span>
                <h4 className="font-bold text-slate-800 dark:text-slate-100 text-sm">{meal.name}</h4>
                <span className="text-xs text-slate-500 dark:text-slate-400">{meal.calories} kcal</span>
              </div>
              <div 
                onClick={() => setShowLogModal(meal)}
                className={`w-6 h-6 rounded-full cursor-pointer flex items-center justify-center transition-all ${meal.isLogged ? 'bg-green-500 text-white' : 'border-2 border-slate-200'}`}
              >
                {meal.isLogged ? '✓' : ''}
              </div>
            </div>
            <div className="flex gap-2">
              <Button variant="outline" className="h-7 text-[9px] px-3 py-0 flex-1" onClick={() => openRecipe(meal)}>{t('recipe')}</Button>
              <Button variant="outline" className="h-7 text-[9px] px-3 py-0 flex-1" onClick={() => openAlternative(meal)}>{t('swap')}</Button>
              <Button variant={meal.isLogged ? 'ghost' : 'primary'} className="h-7 text-[9px] px-3 py-0 flex-1" onClick={() => setShowLogModal(meal)}>
                {meal.isLogged ? t('logged') : t('log')}
              </Button>
            </div>
          </Card>
        ))}
      </div>

      <div className="px-6 mb-10">
        <div className="bg-blue-600 rounded-[32px] p-6 text-white shadow-xl relative overflow-hidden group">
           <h5 className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-80">{t('aiAdvice')}</h5>
           <p className="font-bold text-sm leading-snug">"You are low in protein today. We recommend adding Greek yogurt to your afternoon snack to hit your target!"</p>
        </div>
      </div>

      {showLogModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex flex-col justify-end">
          <div className="bg-white dark:bg-slate-800 rounded-t-[40px] p-8">
             <div className="flex justify-between items-center mb-6">
               <h3 className="text-xl font-bold dark:text-white">{t('log')} {showLogModal.type}</h3>
               <button onClick={() => setShowLogModal(null)} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full">✕</button>
             </div>
             <div className="w-full h-40 bg-slate-100 dark:bg-slate-700 rounded-3xl mb-6 flex items-center justify-center border-2 border-dashed" onClick={() => fileInputRef.current?.click()}>
               {tempPhoto ? <img src={tempPhoto} className="w-full h-full object-cover rounded-3xl" /> : <span className="text-xs text-slate-400">Capture Meal Photo</span>}
               <input type="file" ref={fileInputRef} hidden capture="environment" onChange={handlePhotoCapture} />
             </div>
             <Button className="w-full h-14" onClick={() => handleLog(showLogModal.id, true)}>{t('confirmLog')}</Button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { UserProfile, HealthGoal, Cuisine, MealFrequency, DietPreference, MealPlan, Meal } from './types';
import Onboarding from './views/Onboarding';
import PlanSelection from './views/PlanSelection';
import Dashboard from './views/Dashboard';
import FreeMode from './views/FreeMode';
import Insights from './views/Insights';
import Settings from './views/Settings';
import { Language, translations } from './i18n';

type View = 'onboarding' | 'plan-selection' | 'dashboard' | 'free-mode' | 'insights' | 'settings';

const INITIAL_MEALS: Meal[] = [
  { id: '1', type: 'Breakfast', name: 'Avocado Toast & Boiled Egg', calories: 350, isLogged: false, protein: 15, carbs: 30, fat: 20 },
  { id: '2', type: 'Lunch', name: 'Grilled Chicken Quinoa Bowl', calories: 450, isLogged: true, protein: 35, carbs: 40, fat: 12 },
  { id: '3', type: 'Snack', name: 'Greek Yogurt with Berries', calories: 200, isLogged: false, protein: 12, carbs: 20, fat: 5 },
  { id: '4', type: 'Dinner', name: 'Steamed Fish with Greens', calories: 300, isLogged: false, protein: 25, carbs: 10, fat: 15 },
];

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('onboarding');
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [selectedPlan, setSelectedPlan] = useState<MealPlan | null>(null);
  const [meals, setMeals] = useState<Meal[]>(INITIAL_MEALS);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [language, setLanguage] = useState<Language>('English');
  const [time, setTime] = useState(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));

  useEffect(() => {
    const timer = setInterval(() => {
      setTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    }, 10000);
    return () => clearInterval(timer);
  }, []);

  const t = (key: string) => translations[language]?.[key] || key;
  const isRTL = language === 'Arabic';

  const handleOnboardingComplete = (data: UserProfile) => {
    setProfile(data);
    setLanguage(data.language as Language);
    setCurrentView('plan-selection');
  };

  const handlePlanSelect = (plan: MealPlan | null) => {
    if (plan) {
      setSelectedPlan(plan);
      setCurrentView('dashboard');
    } else {
      setCurrentView('free-mode');
    }
  };

  const handleUpdateLanguage = (newLang: Language) => {
    setLanguage(newLang);
    if (profile) setProfile({ ...profile, language: newLang });
    // Show a small native alert as requested for "Language updated successfully"
    // Using a subtle delay to avoid blocking UI immediately
    setTimeout(() => {
      console.log("Language updated successfully.");
    }, 100);
  };

  const isMainApp = ['dashboard', 'free-mode', 'insights', 'settings'].includes(currentView);

  return (
    <div className={`min-h-screen ${isDarkMode ? 'bg-slate-950' : 'bg-slate-200'} flex items-center justify-center p-0 sm:p-4 transition-colors duration-500`} dir={isRTL ? 'rtl' : 'ltr'}>
      <div className={`${isDarkMode ? 'dark' : ''} w-full max-w-md h-[100vh] sm:h-[844px] relative overflow-hidden flex flex-col sm:rounded-[48px] sm:shadow-2xl border-[8px] border-slate-900 shadow-inner`}>
        <div className="w-full h-full bg-slate-50 dark:bg-slate-900 flex flex-col transition-colors duration-500">

          <div className={`h-10 flex ${isRTL ? 'flex-row-reverse' : 'flex-row'} justify-between items-center px-8 shrink-0 z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-sm`}>
            <span className="text-xs font-bold text-slate-800 dark:text-slate-100">{time}</span>
            <div className={`flex gap-1.5 items-center ${isRTL ? 'flex-row-reverse' : ''}`}>
              <svg className="w-4 h-4 text-slate-800 dark:text-slate-100" fill="currentColor" viewBox="0 0 20 20"><path d="M2 11a1 1 0 011-1h2a1 1 0 011 1v5a1 1 0 01-1 1H3a1 1 0 01-1-1v-5zm6-4a1 1 0 011-1h2a1 1 0 011 1v9a1 1 0 01-1 1H9a1 1 0 01-1-1V7zm6-4a1 1 0 011-1h2a1 1 0 011 1v13a1 1 0 01-1 1h-2a1 1 0 01-1-1V3z"></path></svg>
              <div className="w-5 h-2.5 border border-slate-800 dark:border-slate-100 rounded-sm relative">
                <div className={`absolute top-0.5 bottom-0.5 bg-slate-800 dark:bg-slate-100 rounded-px ${isRTL ? 'left-1 right-0.5' : 'left-0.5 right-1'}`}></div>
              </div>
            </div>
          </div>

          <div className="flex-1 flex flex-col overflow-hidden relative">
            {currentView === 'onboarding' && (
              <Onboarding onComplete={handleOnboardingComplete} />
            )}
            {currentView === 'plan-selection' && (
              <PlanSelection onSelect={handlePlanSelect} onBack={() => setCurrentView('onboarding')} t={t} />
            )}
            {currentView === 'dashboard' && profile && selectedPlan && (
              <Dashboard 
                profile={profile} 
                plan={selectedPlan} 
                meals={meals}
                setMeals={setMeals}
                onExit={() => setCurrentView('plan-selection')}
                onViewInsights={() => setCurrentView('insights')}
                t={t}
              />
            )}
            {currentView === 'free-mode' && (
              <FreeMode onBack={() => setCurrentView('plan-selection')} t={t} />
            )}
            {currentView === 'insights' && profile && (
              <Insights 
                onBack={() => setCurrentView('dashboard')} 
                meals={meals}
                targetCalories={selectedPlan?.calories || 2000}
                t={t}
              />
            )}
            {currentView === 'settings' && (
              <Settings 
                onBack={() => setCurrentView('dashboard')}
                isDarkMode={isDarkMode}
                onToggleDarkMode={() => setIsDarkMode(!isDarkMode)}
                language={language}
                onUpdateLanguage={handleUpdateLanguage}
                t={t}
              />
            )}
          </div>

          {isMainApp && (
            <div className={`absolute bottom-0 left-0 right-0 h-20 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-t border-slate-100 dark:border-slate-800 flex ${isRTL ? 'flex-row-reverse' : 'flex-row'} items-center justify-around px-4 pb-2 z-50`}>
              <button 
                onClick={() => setCurrentView('dashboard')}
                className={`flex flex-col items-center gap-1 transition-all ${currentView === 'dashboard' ? 'text-green-600' : 'text-slate-400 dark:text-slate-500'}`}
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"></path></svg>
                <span className="text-[10px] font-bold">{t('home')}</span>
              </button>
              <button 
                onClick={() => setCurrentView('free-mode')}
                className={`flex flex-col items-center gap-1 transition-all ${currentView === 'free-mode' ? 'text-green-600' : 'text-slate-400 dark:text-slate-500'}`}
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
                <span className="text-[10px] font-bold">{t('explore')}</span>
              </button>
              <button 
                onClick={() => setCurrentView('insights')} 
                className={`flex flex-col items-center gap-1 transition-all ${currentView === 'insights' ? 'text-green-600' : 'text-slate-400 dark:text-slate-500'}`}
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"></path></svg>
                <span className="text-[10px] font-bold">{t('insights')}</span>
              </button>
              <button 
                onClick={() => setCurrentView('settings')} 
                className={`flex flex-col items-center gap-1 transition-all ${currentView === 'settings' ? 'text-green-600' : 'text-slate-400 dark:text-slate-500'}`}
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                <span className="text-[10px] font-bold">{t('settings')}</span>
              </button>
            </div>
          )}

          <div className="absolute top-0 left-1/2 -translate-x-1/2 w-32 h-6 bg-slate-900 rounded-b-2xl z-[60] hidden sm:block"></div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { UserProfile, HealthGoal, Cuisine, MealFrequency, DietPreference } from '../types';
import { Button, Card, ProgressBar, BackButton } from '../components/UI';
import { Language, translations } from '../i18n';

interface OnboardingProps {
  onComplete: (data: UserProfile) => void;
}

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(0);
  const [formData, setFormData] = useState<UserProfile>({
    language: 'English',
    healthGoal: HealthGoal.WeightLoss,
    cuisine: Cuisine.Indian,
    mealFrequency: MealFrequency.ThreePlusSnacks,
    dietPreference: DietPreference.Vegetarian,
    allergies: [],
    challenges: [],
  });

  const totalSteps = 9;

  useEffect(() => {
    if (step === 8) {
      const timer = setTimeout(() => {
        onComplete(formData);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [step, formData, onComplete]);

  const t = (key: string) => translations[formData.language as Language]?.[key] || key;
  const isRTL = formData.language === 'Arabic';

  const next = () => {
    if (step < totalSteps - 1) {
      setStep(s => s + 1);
    }
  };

  const back = () => {
    if (step > 0) {
      setStep(s => s - 1);
    }
  };

  const toggleItem = (list: string[], item: string, key: keyof UserProfile) => {
    let newList: string[];
    if (item === 'None') {
      newList = ['None'];
    } else {
      newList = list.filter(i => i !== 'None');
      newList = newList.includes(item) 
        ? newList.filter(i => i !== item) 
        : [...newList, item];
    }
    setFormData(prev => ({ ...prev, [key]: newList }));
  };

  const renderStep = () => {
    switch (step) {
      case 0:
        return (
          <div className="absolute inset-0 flex flex-col justify-end overflow-hidden">
            <div className="absolute inset-0 z-0">
              <img 
                src="https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&q=80&w=1000" 
                alt="Healthy Food" 
                className="w-full h-full object-cover scale-105 animate-pulse-slow"
                style={{ animationDuration: '8s' }}
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent"></div>
            </div>
            <div className="relative z-10 p-8 pb-16 text-center space-y-6 animate-in slide-in-from-bottom-8 duration-1000">
              <div className="space-y-3">
                <h1 className="text-4xl font-black text-white leading-[1.1] tracking-tight">
                  {t('onboardingTitle')}
                </h1>
                <p className="text-slate-200 text-lg font-medium px-4 opacity-90">
                  {t('onboardingSub')}
                </p>
              </div>
              <div className="pt-4">
                <button 
                  onClick={next} 
                  className="w-full bg-[#39C101] hover:bg-[#32aa01] text-white font-bold py-5 px-8 rounded-full shadow-2xl transition-all active:scale-95 text-lg flex items-center justify-center gap-2"
                >
                  {t('personaliseButton')}
                </button>
              </div>
            </div>
          </div>
        );

      case 1:
        const languages = [
          { name: 'English', native: 'English', icon: '🇺🇸' },
          { name: 'Hindi', native: 'हिन्दी', icon: '🇮🇳' },
          { name: 'Chinese', native: '中文', icon: '🇨🇳' },
          { name: 'Arabic', native: 'العربية', icon: '🇦🇪' },
        ];
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className={`mb-2 ${isRTL ? '-mr-2' : '-ml-2'} dark:text-slate-300`} />
            <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 mb-6 tracking-tight">{t('selectLanguage')}</h2>
            <div className="grid grid-cols-1 gap-3">
              {languages.map(lang => (
                <Card 
                  key={lang.name} 
                  onClick={() => { setFormData({...formData, language: lang.name}); next(); }}
                  className={`transition-all border-2 ${formData.language === lang.name ? 'border-green-500 bg-green-50 dark:bg-green-950/20' : 'border-slate-100 dark:border-slate-800'}`}
                >
                  <div className={`flex items-center gap-4 ${isRTL ? 'flex-row-reverse' : ''}`}>
                    <div className="w-10 h-10 rounded-xl bg-slate-100 dark:bg-slate-700 flex items-center justify-center text-xl">
                      {lang.icon}
                    </div>
                    <div className={`flex-1 ${isRTL ? 'text-right' : 'text-left'}`}>
                      <span className="font-bold text-slate-800 dark:text-slate-100 block">{lang.name}</span>
                      <span className="text-xs text-slate-400 dark:text-slate-500 font-medium">{lang.native}</span>
                    </div>
                  </div>
                </Card>
              ))}
            </div>
          </div>
        );

      case 2:
        const goalIcons: Record<string, string> = {
          [HealthGoal.WeightLoss]: '⚖️',
          [HealthGoal.MuscleGain]: '💪',
          [HealthGoal.HeartHealth]: '❤️',
          [HealthGoal.Energy]: '⚡',
          [HealthGoal.BalancedLifestyle]: '🧘',
        };
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className={`mb-2 ${isRTL ? '-mr-2' : '-ml-2'} dark:text-slate-300`} />
            <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 mb-6 tracking-tight">{t('healthGoalQuestion')}</h2>
            <div className="space-y-3">
              {Object.values(HealthGoal).map(goal => (
                <Card 
                  key={goal} 
                  onClick={() => { setFormData({...formData, healthGoal: goal}); next(); }}
                  className={`transition-all border-2 ${formData.healthGoal === goal ? 'border-green-500 bg-green-50 dark:bg-green-950/20' : 'border-slate-100 dark:border-slate-800'}`}
                >
                  <div className={`flex items-center gap-4 ${isRTL ? 'flex-row-reverse' : ''}`}>
                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-2xl ${formData.healthGoal === goal ? 'bg-green-100 dark:bg-green-900/40' : 'bg-slate-100 dark:bg-slate-800'}`}>
                      {goalIcons[goal]}
                    </div>
                    <div className={`flex-1 ${isRTL ? 'text-right' : 'text-left'}`}>
                      <span className="font-bold text-slate-700 dark:text-slate-200 block">{goal}</span>
                    </div>
                  </div>
                </Card>
              ))}
            </div>
          </div>
        );

      case 3:
        const cuisineIcons: Record<string, string> = {
          [Cuisine.Indian]: '🍛',
          [Cuisine.Mediterranean]: '🥗',
          [Cuisine.Asian]: '🥢',
          [Cuisine.MiddleEastern]: '🥙',
          [Cuisine.Western]: '🍔',
          [Cuisine.Mixed]: '🍱',
        };
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className={`mb-2 ${isRTL ? '-mr-2' : '-ml-2'} dark:text-slate-300`} />
            <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 mb-6 tracking-tight">{t('cuisineQuestion')}</h2>
            <div className="grid grid-cols-2 gap-3">
              {Object.values(Cuisine).map(c => (
                <Card 
                  key={c} 
                  onClick={() => { setFormData({...formData, cuisine: c}); next(); }}
                  className={`transition-all border-2 ${formData.cuisine === c ? 'border-green-500 bg-green-50 dark:bg-green-950/20' : 'border-slate-100 dark:border-slate-800'} py-6 text-center flex flex-col items-center gap-3`}
                >
                  <span className="text-3xl">{cuisineIcons[c]}</span>
                  <span className="font-bold text-slate-700 dark:text-slate-200 text-sm">{c}</span>
                </Card>
              ))}
            </div>
          </div>
        );

      case 4:
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className={`mb-2 ${isRTL ? '-mr-2' : '-ml-2'} dark:text-slate-300`} />
            <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 mb-6 tracking-tight">{t('mealsPerDay')}</h2>
            <div className="space-y-3">
              {Object.values(MealFrequency).map(f => (
                <Card 
                  key={f} 
                  onClick={() => { setFormData({...formData, mealFrequency: f}); next(); }}
                  className={`transition-all border-2 ${formData.mealFrequency === f ? 'border-green-500 bg-green-50 dark:bg-green-950/20' : 'border-slate-100 dark:border-slate-800'}`}
                >
                  <span className={`font-bold text-slate-700 dark:text-slate-200 block ${isRTL ? 'text-right' : 'text-left'}`}>{f}</span>
                </Card>
              ))}
            </div>
          </div>
        );

      case 5:
        const dietIcons: Record<string, string> = {
          [DietPreference.Vegetarian]: '🥦',
          [DietPreference.Vegan]: '🌿',
          [DietPreference.Eggetarian]: '🥚',
          [DietPreference.NonVegetarian]: '🍗',
          [DietPreference.OpenToAll]: '🥘',
          [DietPreference.Keto]: '🥓',
          [DietPreference.Balanced]: '⚖️',
        };
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className={`mb-2 ${isRTL ? '-mr-2' : '-ml-2'} dark:text-slate-300`} />
            <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 mb-6 tracking-tight">{t('dietaryPreference')}</h2>
            <div className="space-y-3">
              {Object.values(DietPreference).map((type) => (
                <Card 
                  key={type} 
                  onClick={() => { setFormData({...formData, dietPreference: type}); next(); }}
                  className={`transition-all border-2 ${formData.dietPreference === type ? 'border-green-500 bg-green-50 dark:bg-green-950/20' : 'border-slate-100 dark:border-slate-800'}`}
                >
                  <div className={`flex items-center gap-4 ${isRTL ? 'flex-row-reverse' : ''}`}>
                    <span className="text-2xl">{dietIcons[type]}</span>
                    <span className={`font-bold text-slate-700 dark:text-slate-200 flex-1 ${isRTL ? 'text-right' : 'text-left'}`}>{type}</span>
                  </div>
                </Card>
              ))}
            </div>
          </div>
        );

      case 6:
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className={`mb-2 ${isRTL ? '-mr-2' : '-ml-2'} dark:text-slate-300`} />
            <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 mb-2 tracking-tight">{t('allergiesQuestion')}</h2>
            <p className={`text-slate-500 dark:text-slate-400 text-sm mb-4 ${isRTL ? 'text-right' : 'text-left'}`}>We'll exclude these from your recipes.</p>
            <div className="grid grid-cols-2 gap-3">
              {['Nuts', 'Dairy', 'Gluten', 'Seafood', 'Eggs', 'None'].map((opt) => (
                <Card 
                  key={opt} 
                  onClick={() => toggleItem(formData.allergies, opt, 'allergies')}
                  className={`transition-all border-2 ${formData.allergies.includes(opt) ? 'border-green-500 bg-green-50 dark:bg-green-950/20' : 'border-slate-100 dark:border-slate-800'} py-4 text-center`}
                >
                  <span className="font-bold text-slate-700 dark:text-slate-200 text-sm">{opt}</span>
                </Card>
              ))}
            </div>
            <div className="pt-4">
              <Button onClick={next} className="w-full h-14 rounded-full shadow-lg">Continue</Button>
            </div>
          </div>
        );

      case 7:
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className={`mb-2 ${isRTL ? '-mr-2' : '-ml-2'} dark:text-slate-300`} />
            <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 mb-2 tracking-tight">{t('challengesQuestion')}</h2>
            <p className={`text-slate-500 dark:text-slate-400 text-sm mb-4 ${isRTL ? 'text-right' : 'text-left'}`}>Areas where you struggle most.</p>
            <div className="space-y-3">
              {['Sugar', 'Fried Foods', 'Late-night Snacking', 'Portions', 'Emotional Eating'].map(c => (
                <Card 
                  key={c} 
                  onClick={() => toggleItem(formData.challenges, c, 'challenges')}
                  className={`transition-all border-2 ${formData.challenges.includes(c) ? 'border-green-500 bg-green-50 dark:bg-green-950/20' : 'border-slate-100 dark:border-slate-800'}`}
                >
                  <span className={`font-bold text-slate-700 dark:text-slate-200 block ${isRTL ? 'text-right' : 'text-left'}`}>{c}</span>
                </Card>
              ))}
            </div>
            <Button onClick={next} className="w-full mt-6 h-14 rounded-full shadow-lg">Build My Plan</Button>
          </div>
        );

      case 8:
        return (
          <div className="flex flex-col items-center justify-center space-y-8 py-20 px-8 text-center h-full">
            <div className="relative w-32 h-32">
              <div className="absolute inset-0 border-4 border-slate-100 dark:border-slate-800 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-[#39C101] rounded-full border-t-transparent animate-spin"></div>
            </div>
            <div className="space-y-3">
              <h2 className="text-2xl font-black text-slate-900 dark:text-slate-100 animate-pulse tracking-tight">{t('thinking')}</h2>
              <p className="text-slate-500 dark:text-slate-400 font-medium">{t('blueprint')}</p>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="flex-1 flex flex-col relative overflow-hidden bg-white dark:bg-slate-900 transition-colors duration-500">
      {step > 0 && step < totalSteps - 1 && (
        <div className="px-6 pt-6 z-20">
          <ProgressBar progress={(step / (totalSteps - 2)) * 100} height="h-1.5" color="bg-[#39C101]" />
        </div>
      )}
      <div className={`flex-1 flex flex-col p-6 overflow-y-auto z-10 no-scrollbar`}>
        {renderStep()}
      </div>
    </div>
  );
};

