          <p className="text-xs text-slate-500 dark:text-slate-400">{t('subGreeting')}</p>
        </div>
        <div className="flex items-center gap-2">
           <div className={`flex flex-col ${isRTL ? 'items-start' : 'items-end'}`}>
              <span className="text-[9px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-wider">{t('forgePoints')}</span>
              <span className="font-black text-slate-800 dark:text-slate-100">{gamification.points}</span>
           </div>
        </div>
      </div>

      <div className="px-6 mb-6">
        <Card onClick={onViewInsights} className="bg-slate-800 dark:bg-slate-900 border-none text-white p-6 shadow-xl relative overflow-hidden">
          <div className={`flex ${isRTL ? 'flex-row-reverse' : 'flex-row'} justify-between items-end mb-4`}>
             <div className={`space-y-1 ${isRTL ? 'text-right' : 'text-left'}`}>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{t('calories')}</span>
                <div className={`flex items-baseline gap-1 ${isRTL ? 'flex-row-reverse' : 'flex-row'}`}>
                   <span className="text-4xl font-black">{totalConsumed}</span>
                   <span className="text-sm opacity-60">/ {targetCals} kcal</span>
                </div>
             </div>
             <div className={isRTL ? 'text-left' : 'text-right'}>
                <span className="text-orange-500 text-sm font-bold">🔥 {gamification.streak} {t('streak')}</span>
             </div>
          </div>
          <ProgressBar progress={(totalConsumed/targetCals)*100} color="bg-green-500" height="h-2" />
