              <Button variant={meal.isLogged ? 'ghost' : 'primary'} className="h-7 text-[9px] px-3 py-0 flex-1" onClick={() => setShowLogModal(meal)}>
                {meal.isLogged ? t('logged') : t('log')}
              </Button>
            </div>
