import React from 'react';
import { BackButton, ProgressBar, Card } from '../components/UI';
import { Meal } from '../types';

interface InsightsProps {
  onBack: () => void;
  meals: Meal[];
  targetCalories: number;
  t: (key: string) => string;
}

const Insights: React.FC<InsightsProps> = ({ onBack, meals, targetCalories, t }) => {
  const loggedMeals = meals.filter(m => m.isLogged);

  const totalMacros = loggedMeals.reduce((acc, meal) => ({
    calories: acc.calories + meal.calories,
    protein: acc.protein + meal.protein,
    carbs: acc.carbs + meal.carbs,
    fat: acc.fat + meal.fat,
  }), { calories: 0, protein: 0, carbs: 0, fat: 0 });

  const totalGrams = totalMacros.protein + totalMacros.carbs + totalMacros.fat || 1;
  const pPct = Math.round((totalMacros.protein / totalGrams) * 100);
  const cPct = Math.round((totalMacros.carbs / totalGrams) * 100);
  const fPct = 100 - pPct - cPct;

  // Mock targets based on user settings
  const targets = {
    calories: targetCalories,
    carbs: 313,
    fat: 319,
    protein: 313,
    fiber: 30,
  };

  return (
    <div className="flex-1 flex flex-col bg-white dark:bg-slate-950 overflow-y-auto pb-24 no-scrollbar transition-colors">
      <div className="p-6 pt-2 flex items-center gap-4 border-b border-slate-50 dark:border-slate-800 sticky top-0 bg-white/90 dark:bg-slate-900/90 backdrop-blur-md z-20">
        <BackButton onClick={onBack} className="-ml-2" />
        <h1 className="text-xl font-bold text-slate-800 dark:text-white tracking-tight">{t('dailyInsights')}</h1>
      </div>

      <div className="p-6 space-y-8">
        {/* Pie Chart Simulation */}
        <div className="flex flex-col items-center">
          <div className="relative w-48 h-48 rounded-full border-[12px] border-white dark:border-slate-800 shadow-xl overflow-hidden flex items-center justify-center bg-slate-50 dark:bg-slate-900">
             <div 
               className="absolute inset-0"
               style={{
                 background: `conic-gradient(
                   #8c71d6 0% ${pPct}%, 
                   #f5b61a ${pPct}% ${pPct + fPct}%, 
                   #26b1b5 ${pPct + fPct}% 100%
                 )`
               }}
             />
             <div className="absolute inset-0 flex items-center justify-center">
               <div className="w-32 h-32 bg-white dark:bg-slate-800 rounded-full flex flex-col items-center justify-center shadow-inner">
                 <span className="text-xs font-black text-slate-400 uppercase">{t('macros')}</span>
                 <span className="text-xl font-black text-slate-800 dark:text-white">{totalMacros.calories}</span>
               </div>
             </div>

             {/* Labels Overlay */}
             <div className="absolute top-6 right-6 text-[10px] font-black text-white drop-shadow-sm text-center">
               {t('protein')}<br/>{pPct}%
             </div>
             <div className="absolute bottom-10 right-10 text-[10px] font-black text-white drop-shadow-sm text-center">
               {t('fat')}<br/>{fPct}%
             </div>
             <div className="absolute top-1/2 left-8 -translate-y-1/2 text-[10px] font-black text-white drop-shadow-sm text-center">
               {t('carbs')}<br/>{cPct}%
             </div>
          </div>
        </div>

        {/* Nutrition Targets Section */}
        <section className="space-y-6">
          <h3 className="text-sm font-bold text-slate-500 border-b border-slate-100 dark:border-slate-800 pb-2">{t('nutritionTargets')}</h3>

          <div className="grid grid-cols-3 text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">
            <span>{t('nutrient')}</span>
            <span className="text-center">{t('todayIntake')}</span>
            <span className="text-right">{t('targets')}</span>
          </div>

          <div className="space-y-5">
            <NutrientRow label={t('calories')} current={totalMacros.calories} target={targets.calories} unit="" color="bg-orange-500" />
            <NutrientRow label={t('carbs')} current={totalMacros.carbs} target={targets.carbs} unit="g" color="bg-[#26b1b5]" />
            <NutrientRow label={t('fat')} current={totalMacros.fat} target={targets.fat} unit="g" color="bg-[#f5b61a]" />
            <NutrientRow label={t('protein')} current={totalMacros.protein} target={targets.protein} unit="g" color="bg-[#8c71d6]" />
            <NutrientRow label={t('fiber')} current={18} target={targets.fiber} unit="g" color="bg-cyan-400" />
          </div>
        </section>

        {/* List Breakdown */}
        <section className="space-y-3 pt-4">
          <DetailRow label={t('netCarbs')} value="213g" />
          <DetailRow label={t('sodium')} value="864mg" />
          <DetailRow label={t('potassium')} value="3957mg" />
          <div className="border-t border-slate-100 dark:border-slate-800 border-dashed my-2"></div>
          <DetailRow label={t('cholesterol')} value="162mg" />
        </section>

        {/* Sugar Section */}
        <section className="space-y-4 pt-4">
          <div className="flex justify-between items-center text-xs font-bold text-slate-500 border-b border-slate-100 dark:border-slate-800 pb-2">
