            <BackButton onClick={back} className={`mb-2 ${isRTL ? '-mr-2' : '-ml-2'} dark:text-slate-300`} />
            <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 mb-2 tracking-tight">{t('allergiesQuestion')}</h2>
            <p className={`text-slate-500 dark:text-slate-400 text-sm mb-4 ${isRTL ? 'text-right' : 'text-left'}`}>We'll exclude these from your recipes.</p>
            <div className="grid grid-cols-2 gap-3">
              {['Nuts', 'Dairy', 'Gluten', 'Seafood', 'Eggs', 'None'].map((opt) => (
                <Card 
                  key={opt} 
                  onClick={() => toggleItem(formData.allergies, opt, 'allergies')}
                  className={`transition-all border-2 ${formData.allergies.includes(opt) ? 'border-green-500 bg-green-50 dark:bg-green-950/20' : 'border-slate-100 dark:border-slate-800'} py-4 text-center`}
                >
                  <span className="font-bold text-slate-700 dark:text-slate-200 text-sm">{opt}</span>
                </Card>
              ))}
            </div>
            <div className="pt-4">
              <Button onClick={next} className="w-full h-14 rounded-full shadow-lg">Continue</Button>
            </div>
          </div>
        );

      case 7:
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className={`mb-2 ${isRTL ? '-mr-2' : '-ml-2'} dark:text-slate-300`} />
            <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 mb-2 tracking-tight">{t('challengesQuestion')}</h2>
            <p className={`text-slate-500 dark:text-slate-400 text-sm mb-4 ${isRTL ? 'text-right' : 'text-left'}`}>Areas where you struggle most.</p>
            <div className="space-y-3">
              {['Sugar', 'Fried Foods', 'Late-night Snacking', 'Portions', 'Emotional Eating'].map(c => (
                <Card 
                  key={c} 
                  onClick={() => toggleItem(formData.challenges, c, 'challenges')}
                  className={`transition-all border-2 ${formData.challenges.includes(c) ? 'border-green-500 bg-green-50 dark:bg-green-950/20' : 'border-slate-100 dark:border-slate-800'}`}
                >
                  <span className={`font-bold text-slate-700 dark:text-slate-200 block ${isRTL ? 'text-right' : 'text-left'}`}>{c}</span>
                </Card>
              ))}
            </div>
            <Button onClick={next} className="w-full mt-6 h-14 rounded-full shadow-lg">Build My Plan</Button>
          </div>
        );

      case 8:
        return (
          <div className="flex flex-col items-center justify-center space-y-8 py-20 px-8 text-center h-full">
            <div className="relative w-32 h-32">
              <div className="absolute inset-0 border-4 border-slate-100 dark:border-slate-800 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-[#39C101] rounded-full border-t-transparent animate-spin"></div>
            </div>
            <div className="space-y-3">
              <h2 className="text-2xl font-black text-slate-900 dark:text-slate-100 animate-pulse tracking-tight">{t('thinking')}</h2>
              <p className="text-slate-500 dark:text-slate-400 font-medium">{t('blueprint')}</p>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="flex-1 flex flex-col relative overflow-hidden bg-white dark:bg-slate-900 transition-colors duration-500">
      {step > 0 && step < totalSteps - 1 && (
        <div className="px-6 pt-6 z-20">
          <ProgressBar progress={(step / (totalSteps - 2)) * 100} height="h-1.5" color="bg-[#39C101]" />
        </div>
      )}
      <div className={`flex-1 flex flex-col p-6 overflow-y-auto z-10 no-scrollbar`}>
        {renderStep()}
      </div>
    </div>
  );
};

export default Onboarding;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { UserProfile, MealPlan, Meal, MealAlternative, GamificationState, ActivityData, Recipe } from '../types';
import { Card, ProgressBar, Button, BackButton } from '../components/UI';
import { generateMealAlternatives, generateRecipe } from '../services/geminiService';
import { fetchWearableData } from '../services/activityService';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  meals: Meal[];
  setMeals: React.Dispatch<React.SetStateAction<Meal[]>>;
  onExit: () => void;
  onViewInsights: () => void;
  t: (key: string) => string;
}

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, meals, setMeals, onExit, onViewInsights, t }) => {
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [selectedMealForRecipe, setSelectedMealForRecipe] = useState<Meal | null>(null);
  const [recipeData, setRecipeData] = useState<Recipe | null>(null);
  const [loadingRecipe, setLoadingRecipe] = useState(false);
  const [alternatives, setAlternatives] = useState<MealAlternative[]>([]);
  const [loadingAlts, setLoadingAlts] = useState(false);
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [gamification, setGamification] = useState<GamificationState>({
    points: 1240,
    streak: 4,
    badges: []
  });
