               </div>
             )}
          </div>
        </div>
      )}

      {selectedMealForAlt && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex flex-col justify-end">
          <div className={`bg-white dark:bg-slate-800 rounded-t-[40px] p-8 max-h-[85%] overflow-y-auto ${isRTL ? 'text-right' : 'text-left'}`}>
             <div className={`flex justify-between items-center mb-6 ${isRTL ? 'flex-row-reverse' : ''}`}>
               <h3 className="text-xl font-bold dark:text-white">AI Swaps</h3>
               <button onClick={() => setSelectedMealForAlt(null)} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full transition-colors dark:text-white">✕</button>
