             {loadingAlts ? <div className="py-20 text-center animate-pulse dark:text-slate-300">Scanning...</div> : (
               <div className="space-y-4">
                 {alternatives.map((alt, i) => (
                   <Card key={i} onClick={() => applyAlternative(alt)} className="hover:border-green-500 dark:bg-slate-900 dark:border-slate-800 transition-colors">
                     <h4 className="font-bold dark:text-white">{alt.name}</h4>
                     <p className="text-xs text-slate-500 dark:text-slate-400">{alt.calories} kcal • {alt.protein}g {t('protein')}</p>
                   </Card>
                 ))}
               </div>
             )}
          </div>
        </div>
      )}

      {showLogModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex flex-col justify-end">
          <div className={`bg-white dark:bg-slate-800 rounded-t-[40px] p-8 ${isRTL ? 'text-right' : 'text-left'}`}>
             <div className={`flex justify-between items-center mb-6 ${isRTL ? 'flex-row-reverse' : ''}`}>
               <h3 className="text-xl font-bold dark:text-white">{t('log')} {showLogModal.type}</h3>
               <button onClick={() => setShowLogModal(null)} className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full transition-colors dark:text-white">✕</button>
             </div>
             <div className="w-full h-40 bg-slate-100 dark:bg-slate-700 rounded-3xl mb-6 flex items-center justify-center border-2 border-dashed border-slate-300 dark:border-slate-600" onClick={() => fileInputRef.current?.click()}>
               {tempPhoto ? <img src={tempPhoto} className="w-full h-full object-cover rounded-3xl" /> : <span className="text-xs text-slate-400 dark:text-slate-500 uppercase font-black">Capture Meal Photo</span>}
               <input type="file" ref={fileInputRef} hidden capture="environment" onChange={handlePhotoCapture} />
             </div>
             <Button className="w-full h-14" onClick={() => handleLog(showLogModal.id, true)}>{t('confirmLog')}</Button>
          </div>
        </div>
      )}

    </div>
  );

  function applyAlternative(alt: MealAlternative) {
    if (!selectedMealForAlt) return;
    setMeals(prev => prev.map(m => m.id === selectedMealForAlt.id ? {
      ...m,
      name: alt.name,
      calories: alt.calories,
      protein: alt.protein,
      carbs: alt.carbs,
      fat: alt.fat,
      isLogged: false,
      photoUri: undefined
    } : m));
    setSelectedMealForAlt(null);
  }
};

export default Dashboard;

import React from 'react';
import { Card, BackButton } from '../components/UI';
import { Language } from '../i18n';

interface SettingsProps {
  onBack: () => void;
  isDarkMode: boolean;
  onToggleDarkMode: () => void;
  language: Language;
  onUpdateLanguage: (lang: Language) => void;
  t: (key: string) => string;
}

const Settings: React.FC<SettingsProps> = ({ onBack, isDarkMode, onToggleDarkMode, language, onUpdateLanguage, t }) => {
  const languages: { name: Language; icon: string }[] = [
    { name: 'English', icon: '🇺🇸' },
    { name: 'Hindi', icon: '🇮🇳' },
    { name: 'Chinese', icon: '🇨🇳' },
    { name: 'Arabic', icon: '🇦🇪' },
