                      variant={meal.isLogged ? 'ghost' : 'primary'} 
                      className={`py-1 px-2 text-[9px] rounded-xl flex-1 h-7 ${meal.isLogged ? 'text-green-600 dark:text-green-400 font-black' : ''}`}
                      onClick={() => setShowLogModal(meal)}
                    >
                      {meal.isLogged ? 'Logged' : 'Log'}
                    </Button>
                  </div>
                </div>
              </div>
            </Card>
          ))}
        </div>
