interface PlanSelectionProps {
  onSelect: (plan: MealPlan | null) => void;
  onBack: () => void;
}

const PlanSelection: React.FC<PlanSelectionProps> = ({ onSelect, onBack }) => {
  const [plans, setPlans] = useState<MealPlan[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadPlans = async () => {
      setLoading(true);
      const result = await fetchApiMealPlans({
        limit: 10,
        country: 'IN', // Consistent with region
        status: 'published'
      });

      if (result && result.data) {
        const mappedPlans: MealPlan[] = result.data.map((apiPlan: ApiMealPlan) => ({
          id: apiPlan.id,
          name: apiPlan.name,
          duration: `${apiPlan.duration_days} Days`,
          calories: apiPlan.daily_calories,
          description: apiPlan.description,
          image_url: apiPlan.image_url
        }));
        setPlans(mappedPlans);
      }
      setLoading(false);
    };

    loadPlans();
  }, []);

  return (
    <div className="flex-1 flex flex-col p-6 overflow-y-auto bg-slate-50 dark:bg-slate-900 transition-colors">
      <div className="flex items-center gap-2 mb-4 mt-2">
        <BackButton onClick={onBack} className="-ml-2 dark:text-slate-300" />
        <h1 className="text-2xl font-bold text-slate-800 dark:text-white tracking-tight">Nutrition Plans</h1>
      </div>

      <div className="space-y-4 mb-8">
        {loading ? (
          // Loading Skeleton
          [1, 2, 3, 4].map(i => (
            <div key={i} className="bg-white dark:bg-slate-800 rounded-3xl h-32 animate-pulse border border-slate-100 dark:border-slate-700"></div>
          ))
        ) : plans.length > 0 ? (
          plans.map(plan => (
            <Card key={plan.id} onClick={() => onSelect(plan)} className="relative overflow-hidden">
              <div className="flex justify-between items-start mb-2">
                <div>
                  <h3 className="text-lg font-bold text-slate-800 dark:text-white">{plan.name}</h3>
                  <span className="text-xs font-semibold text-slate-400 uppercase tracking-wider">{plan.duration}</span>
                </div>
                <div className="bg-green-100 dark:bg-green-900/40 text-green-700 dark:text-green-400 px-3 py-1 rounded-full text-sm font-bold">
                  {plan.calories} kcal/day
                </div>
              </div>
              <p className="text-slate-500 dark:text-slate-400 text-sm leading-relaxed">{plan.description}</p>
              {plan.image_url && (
                <div className="absolute right-[-20px] bottom-[-20px] opacity-10">
                   <img src={plan.image_url} alt="" className="w-24 h-24 object-cover rounded-full" />
                </div>
              )}
            </Card>
          ))
        ) : (
          <div className="text-center py-10">
            <p className="text-slate-500 dark:text-slate-400">No meal plans available at the moment.</p>
          </div>
        )}
      </div>

      <div className="mt-auto space-y-4 text-center">
        <Button variant="ghost" onClick={() => onSelect(null)} className="w-full">I'll Choose Later</Button>
        <p className="text-slate-400 dark:text-slate-500 text-xs px-4">Browse recipes freely — activate a plan anytime.</p>
      </div>
    </div>
  );
