            <div className="flex items-center gap-6">
              <div className="relative w-24 h-24 flex-shrink-0">
                <svg className="w-full h-full -rotate-90">
                  <circle cx="48" cy="48" r="40" fill="transparent" stroke="currentColor" strokeWidth="8" className="text-slate-200 dark:text-slate-700" />
                  <circle 
                    cx="48" cy="48" r="40" fill="transparent" stroke="currentColor" strokeWidth="8" 
                    strokeDasharray={`${2 * Math.PI * 40}`} 
                    strokeDashoffset={`${2 * Math.PI * 40 * (1 - (isNaN(progressPercent) ? 0 : progressPercent) / 100)}`} 
                    strokeLinecap="round" className="text-green-500" 
                  />
                </svg>
                <div className="absolute inset-0 flex flex-col items-center justify-center text-center">
                  <span className="text-lg font-black text-slate-900 dark:text-slate-100 leading-none">{totalConsumed}</span>
                  <span className="text-[8px] font-black text-slate-400 dark:text-slate-500 uppercase">Calories</span>
                </div>
              </div>
              <div className="flex-1 space-y-3">
                <div className="space-y-1">
                  <div className="flex justify-between text-[9px] font-black uppercase text-slate-500 dark:text-slate-400">
                    <span>Protein</span>
                    <span>{totalMacros.pro}g / 120g</span>
                  </div>
                  <div className="h-1.5 w-full bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                    <div className="h-full bg-indigo-500" style={{ width: `${Math.min((totalMacros.pro / 120) * 100, 100)}%` }}></div>
