import { RecipeApiResponse } from "../types";

const API_ENDPOINT = "https://tlgvwgaggtpxpxcptnzk.supabase.co/functions/v1/api-recipes";
const CLIENT_ID = "pk_96fkwJVY7CQOznUyIIWZguX1TtImAqnV";
const CLIENT_SECRET = "sk_4LCHoWSrM588XeYKEOiW0MDEUYN3fgbWF7BXe2gCDGH3rsgF";

export interface FetchRecipeParams {
  limit?: number;
  offset?: number;
  search?: string;
  status?: string;
  country?: string;
  locale?: string;
  difficulty?: number;
}

export const fetchApiRecipes = async (params: FetchRecipeParams = {}): Promise<RecipeApiResponse | null> => {
  try {
    const queryParams = new URLSearchParams();

    if (params.limit) queryParams.append("limit", params.limit.toString());
    if (params.offset) queryParams.append("offset", params.offset.toString());
    if (params.search) queryParams.append("search", params.search);
    if (params.status) queryParams.append("status", params.status);
    if (params.country) queryParams.append("country", params.country);
    if (params.locale) queryParams.append("locale", params.locale);
    if (params.difficulty) queryParams.append("difficulty", params.difficulty.toString());

    // Default include_tags to true for UI details
    queryParams.append("include_tags", "true");

    const response = await fetch(`${API_ENDPOINT}?${queryParams.toString()}`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        'x-client-id': CLIENT_ID,
        'x-client-secret': CLIENT_SECRET
      }
    });

    if (!response.ok) {
      throw new Error(`Recipe API responded with status: ${response.status}`);
    }

