import React, { useMemo, useState, useEffect } from 'react';
import { UserProfile, MealPlan, Meal, ApiRecipe, ApiMealPlan } from '../types';
import { Card, BackButton, Button } from '../components/UI';
import { fetchApiRecipes } from '../services/recipeService';
import { fetchApiMealPlans } from '../services/mealPlanService';

interface ExploreHubProps {
  profile: UserProfile;
  plan: MealPlan;
  meals: Meal[];
  onBack: () => void;
  onSelectPlan: () => void;
}

const ExploreHub: React.FC<ExploreHubProps> = ({ profile, plan, meals, onBack, onSelectPlan }) => {
  const [apiRecipes, setApiRecipes] = useState<ApiRecipe[]>([]);
  const [loadingRecipes, setLoadingRecipes] = useState(true);
  const [apiMealPlans, setApiMealPlans] = useState<ApiMealPlan[]>([]);
  const [loadingMealPlans, setLoadingMealPlans] = useState(true);

  // Map language to locale codes
  const localeMap: Record<string, string> = {
    'English': 'en',
    'Hindi': 'hi',
    'Chinese': 'zh',
    'Arabic': 'ar'
  };

  useEffect(() => {
    const loadData = async () => {
      setLoadingRecipes(true);
      setLoadingMealPlans(true);

      const locale = localeMap[profile.language] || 'en';

      // Fetch Recipes
      const recipesResult = await fetchApiRecipes({
        limit: 10,
        country: 'IN',
        locale: locale
      });

      if (recipesResult && recipesResult.data) {
        setApiRecipes(recipesResult.data);
      }
      setLoadingRecipes(false);

      // Fetch Meal Plans
      const mealPlansResult = await fetchApiMealPlans({
        limit: 5,
        country: 'IN',
        status: 'published'
      });

      if (mealPlansResult && mealPlansResult.data) {
        setApiMealPlans(mealPlansResult.data);
      }
      setLoadingMealPlans(false);
    };

    loadData();
  }, [profile.language]);

  const totalConsumed = meals.reduce((sum, m) => m.isLogged ? sum + m.calories : sum, 0);
  const targetCals = plan.calories;
  const progressPercent = Math.round((totalConsumed / targetCals) * 100);

  const totalMacros = meals.reduce((acc, m) => m.isLogged ? {
    pro: acc.pro + m.protein,
    carb: acc.carb + m.carbs,
    fat: acc.fat + m.fat
  } : acc, { pro: 0, carb: 0, fat: 0 });

  const getPlanColor = (index: number) => {
    const colors = ['bg-orange-500', 'bg-indigo-600', 'bg-emerald-500', 'bg-rose-500', 'bg-amber-500'];
    return colors[index % colors.length];
  };

  const weekDays = useMemo(() => {
    const today = new Date();
    const days = [];
    for (let i = -3; i <= 3; i++) {
      const d = new Date(today);
      d.setDate(today.getDate() + i);
      days.push({
        label: d.toLocaleDateString('en-US', { weekday: 'narrow' }),
        date: d.getDate(),
        isToday: i === 0,
      });
    }
    return days;
  }, []);

