              </div>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end">
            <span className="text-[9px] text-slate-400 dark:text-slate-500 font-black uppercase tracking-wider">Forge Points</span>
            <div className="flex items-center gap-1">
              <span className="font-black text-slate-800 dark:text-slate-100">{gamification.points}</span>
              {pointsAnimation && <span className="absolute text-green-500 font-bold animate-bounce text-sm">+20</span>}
            </div>
          </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pb-32 no-scrollbar">
        {/* Calendar Strip */}
        <div className="px-6 py-4 flex gap-4 overflow-x-auto no-scrollbar bg-white dark:bg-slate-800 shadow-sm mb-4 transition-colors">
