                  <p className="text-[9px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-tight">{activity.steps} Steps</p>
                </div>
              </div>
            </Card>
          </div>
        )}

        {/* Improved Stats Area with Round Graph */}
        <div className="px-6 space-y-4 mb-6">
          <Card 
            onClick={onViewInsights}
