import { MealPlanApiResponse, ApiMealPlan } from "../types";

const API_ENDPOINT = "https://tlgvwgaggtpxpxcptnzk.supabase.co/functions/v1/api-meal-plans";
const CLIENT_ID = "pk_96fkwJVY7CQOznUyIIWZguX1TtImAqnV";
const CLIENT_SECRET = "sk_4LCHoWSrM588XeYKEOiW0MDEUYN3fgbWF7BXe2gCDGH3rsgF";

export interface FetchMealPlanParams {
  limit?: number;
  offset?: number;
  health_goal?: string;
  status?: string;
  country?: string;
  tags?: string;
  include_tags?: boolean;
  include_recipes?: boolean;
}

export const fetchApiMealPlans = async (params: FetchMealPlanParams = {}): Promise<MealPlanApiResponse | null> => {
  try {
    const queryParams = new URLSearchParams();

    if (params.limit) queryParams.append("limit", params.limit.toString());
    if (params.offset) queryParams.append("offset", params.offset.toString());
    if (params.health_goal) queryParams.append("health_goal", params.health_goal);
    if (params.status) queryParams.append("status", params.status);
    if (params.country) queryParams.append("country", params.country);
    if (params.tags) queryParams.append("tags", params.tags);

    const response = await fetch(`${API_ENDPOINT}?${queryParams.toString()}`, {
      method: 'GET',
      mode: 'cors',
      headers: {
        'Content-Type': 'application/json',
        'x-client-id': CLIENT_ID,
        'x-secret-id': CLIENT_SECRET,
        'Accept': 'application/json'
      }
    });

    if (!response.ok) {
      console.error(`Meal Plan API Error: ${response.status} ${response.statusText}`);
      return null;
    }

    const json = await response.json();
    return json as MealPlanApiResponse;
  } catch (error) {
    console.error("Critical error fetching meal plans from API:", error);
    return null;
  }
};

export const fetchApiMealPlanById = async (id: string): Promise<ApiMealPlan | null> => {
  try {
    const response = await fetch(`${API_ENDPOINT}?id=${id}`, {
      method: 'GET',
      mode: 'cors',
      headers: {
        'Content-Type': 'application/json',
        'x-client-id': CLIENT_ID,
        'x-secret-id': CLIENT_SECRET,
        'Accept': 'application/json'
      }
    });

    if (!response.ok) {
      console.error(`Meal Plan Detail API Error: ${response.status}`);
      return null;
    }

    const json = await response.json();
    // The endpoint with ?id= typically returns the plan in the data array or directly
    // Based on common Supabase edge function patterns, it's likely { data: [plan] }
    if (json.data && Array.isArray(json.data) && json.data.length > 0) {
      return json.data[0];
    }
    return json as ApiMealPlan; // Fallback if it returns the object directly
  } catch (error) {
    console.error("Critical error fetching specific meal plan:", error);
    return null;
  }
};

