              <svg className="w-4 h-4 text-slate-800 dark:text-slate-100" fill="currentColor" viewBox="0 0 20 20"><path d="M2 11a1 1 0 011-1h2a1 1 0 011 1v5a1 1 0 01-1 1H3a1 1 0 01-1-1v-5zm6-4a1 1 0 011-1h2a1 1 0 011 1v9a1 1 0 01-1 1H9a1 1 0 01-1-1V7zm6-4a1 1 0 011-1h2a1 1 0 011 1v13a1 1 0 01-1 1h-2a1 1 0 01-1-1V3z"></path></svg>
              <div className="w-5 h-2.5 border border-slate-800 dark:border-slate-100 rounded-sm relative">
                <div className="absolute left-0.5 top-0.5 bottom-0.5 right-1 bg-slate-800 dark:bg-slate-100 rounded-px"></div>
              </div>
            </div>
          </div>

          <div className="flex-1 flex flex-col overflow-hidden relative">
            {isForging && (
              <div className="absolute inset-0 bg-white dark:bg-slate-900 z-[100] flex flex-col items-center justify-center p-12 text-center animate-in fade-in duration-500">
                <div className="relative w-32 h-32 mb-8">
                  <div className="absolute inset-0 border-4 border-green-500/10 rounded-full"></div>
                  <div className="absolute inset-0 border-4 border-[#39C101] rounded-full border-t-transparent animate-spin"></div>
                  <div className="absolute inset-4 bg-[#39C101]/5 rounded-full flex items-center justify-center animate-pulse">
                    <svg className="w-10 h-10 text-[#39C101]" fill="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z"/></svg>
                  </div>
                </div>
                <h2 className="text-2xl font-black text-slate-900 dark:text-white mb-2 tracking-tight uppercase">Forging Your Blueprint</h2>
                <p className="text-slate-400 text-xs font-bold max-w-xs leading-relaxed italic">
                  "Analyzing real-time nutritional profiles and metabolic synergies..."
                </p>
              </div>
            )}

            {currentView === 'onboarding' && (
              <Onboarding onComplete={handleOnboardingComplete} />
            )}
            {currentView === 'plan-selection' && (
              <PlanSelection 
                onSelect={handlePlanSelect} 
                onBack={() => setCurrentView('onboarding')} 
                profile={profile}
              />
            )}
            {currentView === 'dashboard' && profile && selectedPlan && (
              <Dashboard 
                profile={profile} 
                plan={selectedPlan} 
                meals={meals}
                setMeals={setMeals}
                onExit={() => setCurrentView('plan-selection')}
                onViewInsights={() => setCurrentView('insights')}
                onExplore={() => setCurrentView('explore-hub')}
              />
            )}
            {currentView === 'explore-hub' && profile && selectedPlan && (
              <ExploreHub 
                profile={profile}
                plan={selectedPlan}
                meals={meals}
                onBack={() => setCurrentView('dashboard')}
                onSelectPlan={() => setCurrentView('plan-selection')}
              />
            )}
            {currentView === 'free-mode' && (
              <FreeMode onBack={() => setCurrentView('plan-selection')} />
            )}
            {currentView === 'insights' && profile && (
              <Insights 
                onBack={() => setCurrentView('dashboard')} 
                meals={meals}
                targetCalories={selectedPlan?.calories || 2000}
              />
            )}
            {currentView === 'settings' && (
              <Settings 
                onBack={() => setCurrentView('dashboard')}
                isDarkMode={isDarkMode}
                onToggleDarkMode={() => setIsDarkMode(!isDarkMode)}
              />
            )}
          </div>

          {isMainApp && (
            <div className="absolute bottom-0 left-0 right-0 h-20 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-t border-slate-100 dark:border-slate-800 flex items-center justify-around px-4 pb-2 z-50">
              <button onClick={() => setCurrentView('dashboard')} className={`flex flex-col items-center gap-1 transition-all ${['dashboard', 'explore-hub'].includes(currentView) ? 'text-[#39C101]' : 'text-slate-400'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"></path></svg>
                <span className="text-[10px] font-bold">Home</span>
              </button>
              <button onClick={() => setCurrentView('free-mode')} className={`flex flex-col items-center gap-1 transition-all ${currentView === 'free-mode' ? 'text-[#39C101]' : 'text-slate-400'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
                <span className="text-[10px] font-bold">Explore</span>
              </button>
              <button onClick={() => setCurrentView('insights')} className={`flex flex-col items-center gap-1 transition-all ${currentView === 'insights' ? 'text-[#39C101]' : 'text-slate-400'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"></path></svg>
                <span className="text-[10px] font-bold">Insights</span>
              </button>
              <button onClick={() => setCurrentView('settings')} className={`flex flex-col items-center gap-1 transition-all ${currentView === 'settings' ? 'text-[#39C101]' : 'text-slate-400'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                <span className="text-[10px] font-bold">Settings</span>
              </button>
            </div>
          )}

          <div className="absolute top-0 left-1/2 -translate-x-1/2 w-32 h-6 bg-slate-900 rounded-b-2xl z-[60] hidden sm:block"></div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { UserProfile, MealPlan, Meal, MealAlternative, GamificationState, ActivityData, Recipe } from '../types';
import { Card, ProgressBar, Button, BackButton } from '../components/UI';
import { generateMealAlternatives, generateRecipe } from '../services/geminiService';
import { fetchWearableData } from '../services/activityService';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  meals: Meal[];
  setMeals: React.Dispatch<React.SetStateAction<Meal[]>>;
  onExit: () => void;
  onViewInsights: () => void;
  onExplore: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, meals, setMeals, onExit, onViewInsights, onExplore }) => {
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [selectedMealForRecipe, setSelectedMealForRecipe] = useState<Meal | null>(null);
  const [recipeData, setRecipeData] = useState<Recipe | null>(null);
  const [loadingRecipe, setLoadingRecipe] = useState(false);
  const [alternatives, setAlternatives] = useState<MealAlternative[]>([]);
  const [loadingAlts, setLoadingAlts] = useState(false);
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [gamification, setGamification] = useState<GamificationState>({
    points: 1240,
    streak: 4,
    badges: [{ id: 'sync', name: 'Sync King', icon: '⌚', description: 'Connected a wearable device' }]
  });
  const [activity, setActivity] = useState<ActivityData | null>(null);

  const weekDays = useMemo(() => {
    const today = new Date();
    const days = [];
    const start = new Date(today);
    start.setDate(today.getDate() - 3);

    for (let i = 0; i < 7; i++) {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      days.push({
        label: d.toLocaleDateString('en-US', { weekday: 'narrow' }),
        date: d.getDate(),
        isToday: d.toDateString() === today.toDateString(),
      });
    }
    return days;
  }, []);

  useEffect(() => {
    const syncData = async () => {
      const data = await fetchWearableData();
      setActivity(data);
    };
    syncData();
  }, []);

  const totalConsumed = meals.reduce((sum, m) => m.isLogged ? sum + m.calories : sum, 0);
  const activityBonus = activity ? Math.round(activity.caloriesBurned * 0.8) : 0;
  const targetCals = plan.calories + activityBonus;
  const progressPercent = targetCals > 0 ? Math.round((totalConsumed / targetCals) * 100) : 0;

  const handleLog = (mealId: string, forceLogged?: boolean) => {
    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: forceLogged !== undefined ? forceLogged : !m.isLogged, 
      photoUri: tempPhoto || m.photoUri 
    } : m));
    setShowLogModal(null);
    setTempPhoto(null);
  };

  const openAlternative = async (meal: Meal) => {
    setSelectedMealForAlt(meal);
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setAlternatives(alts);
    setLoadingAlts(false);
  };

  const openRecipe = async (meal: Meal) => {
    setSelectedMealForRecipe(meal);
    setLoadingRecipe(true);
    const recipe = await generateRecipe(meal.name, profile);
    setRecipeData(recipe);
    setLoadingRecipe(false);
  };

  const handlePhotoCapture = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setTempPhoto(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-[#F9FBFC] dark:bg-slate-900 overflow-hidden relative transition-colors duration-500">
      {/* Dynamic Header */}
      <div className="p-6 pt-2 bg-white dark:bg-slate-800 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center z-10">
        <div className="flex items-center gap-2">
          <BackButton onClick={onExit} className="-ml-2 dark:text-slate-100" />
          <div className="flex flex-col">
            <h2 className="text-xl font-bold text-slate-800 dark:text-slate-100 tracking-tight">NutriForge</h2>
            <div className="flex items-center gap-2">
              <span className="text-[10px] text-green-600 dark:text-green-400 font-black uppercase tracking-widest">{plan.name}</span>
              <div className="w-1 h-1 bg-slate-300 dark:bg-slate-600 rounded-full"></div>
              <div className="flex items-center gap-1 text-orange-500 font-bold text-[10px]">
                <span>🔥</span> {gamification.streak} Day Streak
              </div>
            </div>
          </div>
        </div>
        <div className="flex flex-col items-end">
          <span className="text-[9px] text-[#A5B3C1] font-black uppercase tracking-wider">Forge Points</span>
          <span className="font-black text-xl text-slate-800 dark:text-slate-100 leading-none">{gamification.points}</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pb-32 no-scrollbar">
        {/* Calendar Strip */}
        <div className="px-6 py-4 flex gap-4 overflow-x-auto no-scrollbar bg-white dark:bg-slate-800 shadow-sm transition-colors border-b border-slate-50 dark:border-slate-700">
          {weekDays.map((day, i) => (
            <div key={i} className={`flex-shrink-0 w-11 h-16 rounded-2xl flex flex-col items-center justify-center gap-1 ${day.isToday ? 'bg-[#39C101] text-white shadow-lg shadow-[#39C101]/30' : 'text-[#A5B3C1]'}`}>
              <span className="text-[10px] font-black uppercase">{day.label}</span>
              <span className="text-base font-black">{day.date}</span>
            </div>
          ))}
        </div>

        {/* Activity Sync Card */}
        {activity && (
          <div className="px-6 py-4">
            <Card className="bg-white dark:bg-slate-800 border-slate-100 py-4 px-6">
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-slate-800 rounded-full flex items-center justify-center text-white">
                    <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z"></path></svg>
                  </div>
                  <div>
                    <h4 className="text-[10px] font-black text-slate-800 dark:text-slate-100 uppercase tracking-widest">Wearable Synced</h4>
                    <p className="text-[10px] text-[#A5B3C1] font-bold uppercase">{activity.lastSynced}</p>
                  </div>
                </div>
                <div className="text-right">
                  <span className="text-base font-black text-slate-900 dark:text-slate-100">+{activity.caloriesBurned} kcal</span>
                  <p className="text-[10px] text-[#A5B3C1] font-black uppercase">{activity.steps} STEPS</p>
                </div>
              </div>
            </Card>
          </div>
        )}

        {/* Daily Energy Card */}
        <div className="px-6 pb-6">
          <Card 
            onClick={onViewInsights}
            className="bg-white dark:bg-slate-800 border-slate-100 shadow-sm relative overflow-hidden p-6"
          >
            <div className="flex justify-between items-start mb-6">
              <div className="space-y-1">
                <div className="flex items-center gap-1 group cursor-pointer">
                  <span className="text-[11px] text-[#A5B3C1] font-black uppercase tracking-widest">Daily Energy</span>
                  <svg className="w-3 h-3 text-[#A5B3C1] group-hover:translate-x-0.5 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7"></path></svg>
                </div>
                <div className="flex items-baseline gap-1.5">
                  <span className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">{totalConsumed}</span>
                  <span className="text-sm text-[#A5B3C1] font-bold">/ {targetCals} kcal</span>
                </div>
              </div>
              <div className="w-14 h-14 rounded-full border-4 border-slate-100 dark:border-slate-700 flex items-center justify-center relative">
                <svg className="w-full h-full absolute inset-0 -rotate-90">
                  <circle cx="28" cy="28" r="24" fill="transparent" stroke="currentColor" strokeWidth="4" className="text-slate-100 dark:text-slate-700"/>
                  <circle cx="28" cy="28" r="24" fill="transparent" stroke="currentColor" strokeWidth="4" className="text-[#39C101]" strokeDasharray="150" strokeDashoffset={150 - (150 * (progressPercent / 100))} strokeLinecap="round"/>
                </svg>
                <span className="text-[11px] font-black text-slate-900 dark:text-white">{progressPercent}%</span>
              </div>
            </div>

            <ProgressBar progress={progressPercent} color="bg-slate-800 dark:bg-slate-100" height="h-3" />
            <p className="text-[10px] text-[#A5B3C1] mt-4 font-bold italic tracking-tight">*Tap to view detailed macro forge</p>
          </Card>
        </div>

        {/* Explore Button */}
        <div className="px-6 mb-8">
          <button 
            onClick={onExplore}
            className="w-full bg-[#39C101] hover:bg-[#32aa01] text-white p-6 rounded-[32px] flex items-center justify-between shadow-xl shadow-[#39C101]/20 transition-all active:scale-95 group overflow-hidden"
          >
            <div className="text-left z-10">
              <span className="block text-[10px] font-black uppercase tracking-widest opacity-90 mb-1">Discover New</span>
              <span className="block font-black text-2xl leading-none tracking-tight">Explore Now</span>
            </div>
            <div className="w-12 h-12 bg-white/20 rounded-full flex items-center justify-center group-hover:translate-x-1 transition-transform z-10">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7" /></svg>
            </div>
            <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-12 -mt-12 group-hover:scale-110 transition-transform"></div>
          </button>
        </div>

        {/* Today's Meals Section */}
        <div className="px-6 space-y-6">
          <h3 className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-[0.15em] mb-4">Today's Meals</h3>

          {meals.length === 0 && (
            <div className="py-16 text-center bg-white dark:bg-slate-800 rounded-[32px] border-2 border-dashed border-slate-100 dark:border-slate-700">
               <p className="text-[#A5B3C1] text-xs font-black uppercase tracking-widest">Forging Daily Blueprint...</p>
            </div>
          )}

          {meals.map(meal => (
            <div key={meal.id} className="bg-white dark:bg-slate-800 rounded-[32px] p-6 shadow-sm border border-slate-50 dark:border-slate-700 relative group">
              <div className={`absolute top-6 right-6 w-7 h-7 rounded-full border-2 flex items-center justify-center transition-all ${meal.isLogged ? 'bg-[#39C101] border-[#39C101] shadow-lg shadow-[#39C101]/20' : 'border-slate-100 dark:border-slate-700'}`}>
                {meal.isLogged && <svg className="w-4 h-4 text-white" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>}
              </div>

              <div className="flex flex-col gap-1 mb-6 pr-8">
                <span className="text-[10px] font-black text-[#A5B3C1] uppercase tracking-widest">{meal.type}</span>
                <h4 className="text-lg font-black text-slate-800 dark:text-white leading-tight tracking-tight line-clamp-2">{meal.name}</h4>
                <span className="text-xs font-bold text-[#A5B3C1]">{meal.calories} kcal</span>
              </div>

              <div className="flex gap-3">
                <button onClick={() => openRecipe(meal)} className="flex-1 py-3 px-4 rounded-full border-2 border-[#E9EEF2] dark:border-slate-700 text-[11px] font-black text-[#39C101] uppercase tracking-widest hover:bg-slate-50 transition-all active:scale-95">Recipe</button>
                <button onClick={() => openAlternative(meal)} className="flex-1 py-3 px-4 rounded-full border-2 border-[#E9EEF2] dark:border-slate-700 text-[11px] font-black text-[#39C101] uppercase tracking-widest hover:bg-slate-50 transition-all active:scale-95">Swap</button>
                <button 
                  onClick={() => setShowLogModal(meal)}
                  className={`flex-1 py-3 px-4 rounded-full text-[11px] font-black uppercase tracking-widest transition-all active:scale-95 ${meal.isLogged ? 'bg-slate-400 text-white shadow-none' : 'bg-[#39C101] text-white shadow-lg shadow-[#39C101]/20 hover:bg-[#32aa01]'}`}
                >
                  {meal.isLogged ? 'Logged' : 'Log'}
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Modals are kept the same for functional completeness but refined for typography */}
      {selectedMealForRecipe && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-[110] flex flex-col justify-end">
          <div className="bg-white dark:bg-slate-900 rounded-t-[40px] p-8 max-h-[85%] overflow-y-auto animate-in slide-in-from-bottom duration-500 no-scrollbar">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-black text-slate-800 dark:text-white">{selectedMealForRecipe.name}</h3>
              <button onClick={() => { setSelectedMealForRecipe(null); setRecipeData(null); }} className="p-2 bg-slate-100 dark:bg-slate-800 rounded-full">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            {loadingRecipe ? (
              <div className="py-20 text-center"><div className="w-12 h-12 border-4 border-[#39C101] border-t-transparent rounded-full animate-spin mx-auto mb-4"></div><p className="text-[10px] font-black text-[#A5B3C1] uppercase">Decrypting Blueprint...</p></div>
            ) : recipeData ? (
              <div className="space-y-8 pb-10">
                <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl"><span className="text-[9px] font-black text-[#A5B3C1] uppercase block">Prep</span><span className="font-black text-slate-800 dark:text-white">{recipeData.prepTime}</span></div>
                  <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl"><span className="text-[9px] font-black text-[#A5B3C1] uppercase block">Cook</span><span className="font-black text-slate-800 dark:text-white">{recipeData.cookTime}</span></div>
                </div>
                <div className="space-y-4">
                  <h4 className="text-xs font-black text-slate-900 dark:text-white uppercase tracking-widest border-l-4 border-[#39C101] pl-3">Ingredients</h4>
                  <ul className="space-y-2">{recipeData.ingredients.map((ing, i) => <li key={i} className="text-sm text-slate-600 dark:text-slate-400 font-bold">• {ing}</li>)}</ul>
                </div>
                <Button className="w-full h-16 rounded-full" onClick={() => { setShowLogModal(selectedMealForRecipe); setSelectedMealForRecipe(null); }}>Ready to Log</Button>
              </div>
            ) : null}
          </div>
        </div>
      )}

      {showLogModal && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-[120] flex flex-col justify-end">
          <div className="bg-white dark:bg-slate-900 rounded-t-[40px] p-8 max-h-[90%] overflow-y-auto animate-in slide-in-from-bottom duration-500 no-scrollbar">
             <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-black text-slate-800 dark:text-white">Log {showLogModal.type}</h3>
              <button onClick={() => { setShowLogModal(null); setTempPhoto(null); }} className="p-2 bg-slate-100 dark:bg-slate-800 rounded-full"><svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12"></path></svg></button>
            </div>
            <div className="mb-6 flex flex-col items-center">
               <div className="w-full aspect-video bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-dashed border-slate-100 dark:border-slate-700 relative overflow-hidden flex items-center justify-center cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                 {tempPhoto ? <img src={tempPhoto} className="w-full h-full object-cover" /> : <div className="text-center space-y-2 text-[#A5B3C1]"><svg className="w-12 h-12 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" strokeWidth="1.5"/><path d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" strokeWidth="1.5"/></svg><span className="text-[10px] font-black uppercase tracking-widest block">Snap or Upload Photo</span></div>}
                 <input type="file" ref={fileInputRef} className="hidden" accept="image/*" capture="environment" onChange={handlePhotoCapture}/>
               </div>
            </div>
            <Button className="w-full h-16 rounded-full text-white shadow-xl shadow-[#39C101]/20 mb-4" onClick={() => handleLog(showLogModal.id, true)}>{showLogModal.isLogged ? 'Update Log' : 'Confirm & Log'}</Button>
            {showLogModal.isLogged && <button className="w-full py-2 text-red-500 text-xs font-black uppercase tracking-widest" onClick={() => handleLog(showLogModal.id, false)}>Delete Entry</button>}
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { UserProfile, HealthGoal, Cuisine, MealFrequency, DietPreference, MealPlan, Meal, ApiMealPlan } from './types';
import Onboarding from './views/Onboarding';
import PlanSelection from './views/PlanSelection';
import Dashboard from './views/Dashboard';
import FreeMode from './views/FreeMode';
import Insights from './views/Insights';
import Settings from './views/Settings';
import ExploreHub from './views/ExploreHub';
import { generateDailyMeals } from './services/geminiService';
import { fetchApiMealPlanById } from './services/mealPlanService';

type View = 'onboarding' | 'plan-selection' | 'dashboard' | 'free-mode' | 'insights' | 'settings' | 'explore-hub';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('onboarding');
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [selectedPlan, setSelectedPlan] = useState<MealPlan | null>(null);
  const [meals, setMeals] = useState<Meal[]>([]);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isForging, setIsForging] = useState(false);
  const [time, setTime] = useState(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));

  useEffect(() => {
    const timer = setInterval(() => {
      setTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    }, 10000);
    return () => clearInterval(timer);
  }, []);

  const handleOnboardingComplete = (data: UserProfile) => {
    setProfile(data);
    setCurrentView('plan-selection');
  };

  const handlePlanSelect = async (plan: MealPlan | null) => {
    if (plan && profile) {
      setIsForging(true);

      try {
        // 1. Fetch deep data for the selected plan using its API ID
        const apiPlanDetail: ApiMealPlan | null = await fetchApiMealPlanById(plan.id);

        const enrichedPlan: MealPlan = apiPlanDetail ? {
          id: apiPlanDetail.id,
          name: apiPlanDetail.name,
          duration: `${apiPlanDetail.duration_days} Days`,
          calories: apiPlanDetail.daily_calories,
          description: apiPlanDetail.description,
          image_url: apiPlanDetail.image_url
        } : plan;

        setSelectedPlan(enrichedPlan);

        // 2. Generate meals based strictly on the selected plan's calories and user profile
        const forgedMeals = await generateDailyMeals(enrichedPlan, profile);

        if (forgedMeals && forgedMeals.length > 0) {
          setMeals(forgedMeals);
        } else {
          setMeals([]);
        }
      } catch (err) {
        console.error("Critical error fetching or forging meal plan:", err);
        setSelectedPlan(plan);
        setMeals([]);
      } finally {
        setIsForging(false);
        setCurrentView('dashboard');
      }
    } else {
      setCurrentView('free-mode');
    }
  };

  const isMainApp = ['dashboard', 'free-mode', 'insights', 'settings', 'explore-hub'].includes(currentView);

  return (
    <div className={`min-h-screen ${isDarkMode ? 'bg-slate-950' : 'bg-slate-200'} flex items-center justify-center p-0 sm:p-4 transition-colors duration-500`}>
      <div className={`${isDarkMode ? 'dark' : ''} w-full max-w-md h-[100vh] sm:h-[844px] relative overflow-hidden flex flex-col sm:rounded-[48px] sm:shadow-2xl border-[8px] border-slate-900 shadow-inner shadow-black/20`}>
        <div className="w-full h-full bg-[#F9FBFC] dark:bg-slate-950 flex flex-col transition-colors duration-500">

          <div className="h-10 flex justify-between items-center px-8 shrink-0 z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-sm">
            <span className="text-xs font-bold text-slate-800 dark:text-slate-100">{time}</span>
            <div className="flex gap-1.5 items-center">
              <svg className="w-4 h-4 text-slate-800 dark:text-slate-100" fill="currentColor" viewBox="0 0 20 20"><path d="M2 11a1 1 0 011-1h2a1 1 0 011 1v5a1 1 0 01-1 1H3a1 1 0 01-1-1v-5zm6-4a1 1 0 011-1h2a1 1 0 011 1v9a1 1 0 01-1 1H9a1 1 0 01-1-1V7zm6-4a1 1 0 011-1h2a1 1 0 011 1v13a1 1 0 01-1 1h-2a1 1 0 01-1-1V3z"></path></svg>
              <div className="w-5 h-2.5 border border-slate-800 dark:border-slate-100 rounded-sm relative">
                <div className="absolute left-0.5 top-0.5 bottom-0.5 right-1 bg-slate-800 dark:bg-slate-100 rounded-px"></div>
              </div>
            </div>
          </div>

          <div className="flex-1 flex flex-col overflow-hidden relative">
            {isForging && (
              <div className="absolute inset-0 bg-white/95 dark:bg-slate-900/95 z-[100] flex flex-col items-center justify-center p-12 text-center animate-in fade-in duration-500">
                <div className="relative w-32 h-32 mb-8">
                  <div className="absolute inset-0 border-4 border-slate-100 dark:border-slate-800 rounded-full"></div>
                  <div className="absolute inset-0 border-4 border-[#39C101] rounded-full border-t-transparent animate-spin"></div>
                  <div className="absolute inset-4 bg-[#39C101]/5 rounded-full flex items-center justify-center animate-pulse">
                    <svg className="w-10 h-10 text-[#39C101]" fill="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z"/></svg>
                  </div>
                </div>
                <h2 className="text-2xl font-black text-slate-900 dark:text-white mb-2 tracking-tight uppercase">Forging Daily Blueprint</h2>
                <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest max-w-xs leading-relaxed italic">
                  Syncing with Global Nutrition Database...
                </p>
              </div>
            )}

            {currentView === 'onboarding' && (
              <Onboarding onComplete={handleOnboardingComplete} />
            )}
            {currentView === 'plan-selection' && (
              <PlanSelection 
                onSelect={handlePlanSelect} 
                onBack={() => setCurrentView('onboarding')} 
                profile={profile}
              />
            )}
            {currentView === 'dashboard' && profile && selectedPlan && (
              <Dashboard 
                profile={profile} 
                plan={selectedPlan} 
                meals={meals}
                setMeals={setMeals}
                onExit={() => setCurrentView('plan-selection')}
                onViewInsights={() => setCurrentView('insights')}
                onExplore={() => setCurrentView('explore-hub')}
              />
            )}
            {currentView === 'explore-hub' && profile && selectedPlan && (
              <ExploreHub 
                profile={profile}
                plan={selectedPlan}
                meals={meals}
                onBack={() => setCurrentView('dashboard')}
                onSelectPlan={() => setCurrentView('plan-selection')}
              />
            )}
            {currentView === 'free-mode' && (
              <FreeMode onBack={() => setCurrentView('plan-selection')} />
            )}
            {currentView === 'insights' && profile && (
              <Insights 
                onBack={() => setCurrentView('dashboard')} 
                meals={meals}
                targetCalories={selectedPlan?.calories || 2000}
              />
            )}
            {currentView === 'settings' && (
              <Settings 
                onBack={() => setCurrentView('dashboard')}
                isDarkMode={isDarkMode}
                onToggleDarkMode={() => setIsDarkMode(!isDarkMode)}
              />
            )}
          </div>

          {isMainApp && (
            <div className="absolute bottom-0 left-0 right-0 h-20 bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl border-t border-slate-100 dark:border-slate-800 flex items-center justify-around px-4 pb-2 z-50">
              <button onClick={() => setCurrentView('dashboard')} className={`flex flex-col items-center gap-1 transition-all ${['dashboard', 'explore-hub'].includes(currentView) ? 'text-[#39C101]' : 'text-slate-400 dark:text-slate-500'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"></path></svg>
                <span className="text-[10px] font-black uppercase tracking-tighter">Home</span>
              </button>
              <button onClick={() => setCurrentView('free-mode')} className={`flex flex-col items-center gap-1 transition-all ${currentView === 'free-mode' ? 'text-[#39C101]' : 'text-slate-400 dark:text-slate-500'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
                <span className="text-[10px] font-black uppercase tracking-tighter">Forge</span>
              </button>
              <button onClick={() => setCurrentView('insights')} className={`flex flex-col items-center gap-1 transition-all ${currentView === 'insights' ? 'text-[#39C101]' : 'text-slate-400 dark:text-slate-500'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"></path></svg>
                <span className="text-[10px] font-black uppercase tracking-tighter">Insights</span>
              </button>
              <button onClick={() => setCurrentView('settings')} className={`flex flex-col items-center gap-1 transition-all ${currentView === 'settings' ? 'text-[#39C101]' : 'text-slate-400 dark:text-slate-500'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                <span className="text-[10px] font-black uppercase tracking-tighter">Profile</span>
              </button>
            </div>
          )}

          <div className="absolute top-0 left-1/2 -translate-x-1/2 w-32 h-6 bg-slate-900 rounded-b-2xl z-[60] hidden sm:block"></div>
        </div>
      </div>
    </div>
  );
};

