          <button 
            onClick={onExplore}
            className="w-full bg-[#39C101] hover:bg-[#32aa01] text-white p-7 rounded-[32px] flex items-center justify-between shadow-2xl shadow-[#39C101]/20 active:scale-[0.98] transition-all group relative overflow-hidden"
