              <span className="block text-[11px] font-black uppercase tracking-[0.2em] opacity-80 mb-1.5">Discover New</span>
              <span className="block font-black text-3xl leading-none tracking-tight">Explore Now</span>
            </div>
            <div className="w-14 h-14 bg-white/20 rounded-full flex items-center justify-center group-hover:translate-x-1.5 transition-transform relative z-10">
              <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3.5" d="M9 5l7 7-7 7" /></svg>
            </div>
            <div className="absolute top-0 right-0 w-40 h-40 bg-white/10 rounded-full -mr-16 -mt-16 group-hover:scale-110 transition-transform"></div>
          </button>
        </div>

        {/* Meal List Section - Zero Hardcoded Data */}
        <div className="px-6 space-y-6">
          <h3 className="text-[12px] font-black text-[#A5B3C1] uppercase tracking-[0.2em] mb-4 pl-1">Today's Meals</h3>

          {meals.length === 0 && (
            <div className="py-20 text-center bg-white dark:bg-slate-800 rounded-[32px] border-2 border-dashed border-slate-100 dark:border-slate-700 shadow-sm">
               <div className="w-12 h-12 border-4 border-[#39C101] border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
               <p className="text-[#A5B3C1] text-[10px] font-black uppercase tracking-[0.2em]">Forging Culinary Intelligence...</p>
            </div>
          )}

          {meals.map(meal => (
            <div key={meal.id} className="bg-white dark:bg-slate-800 rounded-[40px] p-7 shadow-sm border border-slate-50 dark:border-slate-700 relative group overflow-hidden transition-all hover:shadow-xl hover:shadow-slate-200/50">
              {/* Checkmark indicator matching user screenshot position */}
              <div className={`absolute top-7 right-7 w-8 h-8 rounded-full border-2 flex items-center justify-center transition-all ${meal.isLogged ? 'bg-[#39C101] border-[#39C101] shadow-xl shadow-[#39C101]/30' : 'border-slate-100 dark:border-slate-700 hover:border-[#39C101]/30'}`}>
                {meal.isLogged && <svg className="w-5 h-5 text-white" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>}
              </div>

              <div className="flex flex-col gap-1.5 mb-8 pr-10">
                <span className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-[0.2em]">{meal.type}</span>
                <h4 className="text-xl font-black text-slate-900 dark:text-white leading-tight tracking-tight">{meal.name}</h4>
                <span className="text-xs font-bold text-[#A5B3C1]">{meal.calories} kcal</span>
              </div>

              <div className="flex gap-4">
                <button onClick={() => openRecipe(meal)} className="flex-1 py-4 px-4 rounded-[20px] border-2 border-[#E9EEF2] dark:border-slate-700 text-[12px] font-black text-[#39C101] uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-all active:scale-95 shadow-sm bg-white dark:bg-slate-800">Recipe</button>
                <button onClick={() => openAlternative(meal)} className="flex-1 py-4 px-4 rounded-[20px] border-2 border-[#E9EEF2] dark:border-slate-700 text-[12px] font-black text-[#39C101] uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-all active:scale-95 shadow-sm bg-white dark:bg-slate-800">Swap</button>
                <button 
                  onClick={() => setShowLogModal(meal)}
                  className={`flex-1 py-4 px-4 rounded-[20px] text-[12px] font-black uppercase tracking-widest transition-all active:scale-95 shadow-xl ${meal.isLogged ? 'bg-slate-200 text-slate-500 shadow-none' : 'bg-[#39C101] text-white shadow-[#39C101]/25 hover:bg-[#32aa01]'}`}
                >
                  {meal.isLogged ? 'Logged' : 'Log'}
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Logic for Detailed Recipe View (AI Powered) */}
      {selectedMealForRecipe && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[110] flex flex-col justify-end">
          <div className="bg-white dark:bg-slate-900 rounded-t-[48px] p-10 max-h-[85%] overflow-y-auto animate-in slide-in-from-bottom duration-500 no-scrollbar shadow-2xl">
            <div className="flex justify-between items-start mb-8">
              <div className="pr-12">
                <h3 className="text-2xl font-black text-slate-900 dark:text-white leading-tight tracking-tight mb-1">{selectedMealForRecipe.name}</h3>
                <p className="text-[10px] text-[#A5B3C1] font-black uppercase tracking-[0.2em]">Metabolic Prep Guide</p>
              </div>
              <button onClick={() => { setSelectedMealForRecipe(null); setRecipeData(null); }} className="p-3 bg-slate-50 dark:bg-slate-800 rounded-full hover:bg-slate-100 transition-colors">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            {loadingRecipe ? (
              <div className="py-24 text-center">
                <div className="w-14 h-14 border-[5px] border-[#39C101] border-t-transparent rounded-full animate-spin mx-auto mb-6"></div>
                <p className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-[0.25em]">Forging culinary blueprint...</p>
              </div>
            ) : recipeData ? (
              <div className="space-y-10 pb-12">
                <div className="grid grid-cols-2 gap-6">
                  <div className="p-5 bg-slate-50 dark:bg-slate-800 rounded-3xl border border-slate-100 dark:border-slate-700/50"><span className="text-[10px] font-black text-[#A5B3C1] uppercase tracking-widest block mb-2">Prep Time</span><span className="text-lg font-black text-slate-800 dark:text-white">{recipeData.prepTime}</span></div>
                  <div className="p-5 bg-slate-50 dark:bg-slate-800 rounded-3xl border border-slate-100 dark:border-slate-700/50"><span className="text-[10px] font-black text-[#A5B3C1] uppercase tracking-widest block mb-2">Cook Time</span><span className="text-lg font-black text-slate-800 dark:text-white">{recipeData.cookTime}</span></div>
                </div>
                <div className="space-y-4">
                  <h4 className="text-[12px] font-black text-slate-900 dark:text-white uppercase tracking-widest border-l-[6px] border-[#39C101] pl-4">Metabolic Components</h4>
                  <ul className="grid grid-cols-1 gap-3">{recipeDetail ? null : recipeData.ingredients.map((ing, i) => <li key={i} className="text-[13px] text-slate-600 dark:text-slate-400 font-bold bg-slate-50/50 dark:bg-slate-800/40 p-3 rounded-2xl flex items-center gap-3"><div className="w-1.5 h-1.5 bg-[#39C101] rounded-full"></div>{ing}</li>)}</ul>
                </div>
                <div className="space-y-6">
                  <h4 className="text-[12px] font-black text-slate-900 dark:text-white uppercase tracking-widest border-l-[6px] border-[#39C101] pl-4">Preparation Guide</h4>
                  <div className="space-y-6">{recipeData.instructions.map((step, i) => <div key={i} className="flex gap-5"><span className="flex-shrink-0 w-8 h-8 bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-white rounded-[14px] flex items-center justify-center text-[12px] font-black shadow-sm">{i + 1}</span><p className="text-[14px] text-slate-600 dark:text-slate-400 font-bold leading-relaxed">{step}</p></div>)}</div>
                </div>
                <Button className="w-full h-16 rounded-[24px] text-white shadow-2xl shadow-[#39C101]/30" onClick={() => { setShowLogModal(selectedMealForRecipe); setSelectedMealForRecipe(null); }}>Commit to Meal Plan</Button>
              </div>
            ) : null}
          </div>
        </div>
      )}

      {/* Log Meal Interface */}
      {showLogModal && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-[120] flex flex-col justify-end">
          <div className="bg-white dark:bg-slate-900 rounded-t-[48px] p-10 max-h-[90%] overflow-y-auto animate-in slide-in-from-bottom duration-500 no-scrollbar shadow-2xl">
             <div className="flex justify-between items-center mb-10">
              <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight leading-none">Log {showLogModal.type}</h3>
              <button onClick={() => { setShowLogModal(null); setTempPhoto(null); }} className="p-3 bg-slate-50 dark:bg-slate-800 rounded-full hover:bg-slate-100 transition-colors">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            <div className="mb-8 flex flex-col items-center">
               <div className="w-full aspect-square max-w-[280px] bg-slate-50 dark:bg-slate-800 rounded-[48px] border-4 border-dashed border-slate-100 dark:border-slate-700 relative overflow-hidden flex items-center justify-center cursor-pointer group hover:border-[#39C101]/50 transition-all" onClick={() => fileInputRef.current?.click()}>
                 {tempPhoto ? <img src={tempPhoto} className="w-full h-full object-cover" /> : <div className="text-center space-y-4 text-[#A5B3C1] group-hover:scale-110 transition-transform duration-500"><svg className="w-16 h-16 mx-auto opacity-50" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" strokeWidth="1.5"/><path d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" strokeWidth="1.5"/></svg><span className="text-[11px] font-black uppercase tracking-[0.3em] block px-4 opacity-80 leading-relaxed">Forge Visual Proof</span></div>}
                 <input type="file" ref={fileInputRef} className="hidden" accept="image/*" capture="environment" onChange={handlePhotoCapture}/>
               </div>
            </div>
            <div className="mb-10 text-center space-y-1">
               <h4 className="text-lg font-black text-slate-800 dark:text-white leading-tight">{showLogModal.name}</h4>
               <p className="text-[12px] text-[#A5B3C1] font-bold tracking-tight">{showLogModal.calories} kcal Blueprint Target</p>
            </div>
            <Button className="w-full h-20 rounded-[32px] text-lg font-black text-white shadow-2xl shadow-[#39C101]/40 mb-6 bg-[#39C101] hover:bg-[#32aa01]" onClick={() => handleLog(showLogModal.id, true)}>
              {showLogModal.isLogged ? 'Update Log' : 'Confirm Entry'}
            </Button>
            {showLogModal.isLogged && <button className="w-full py-4 text-red-500 text-[11px] font-black uppercase tracking-[0.3em] opacity-80 hover:opacity-100 transition-opacity" onClick={() => handleLog(showLogModal.id, false)}>Clear Metabolic Entry</button>}
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { UserProfile, MealPlan, Meal, MealAlternative, GamificationState, ActivityData, Recipe } from '../types';
import { Card, ProgressBar, Button, BackButton } from '../components/UI';
import { generateMealAlternatives, generateRecipe } from '../services/geminiService';
import { fetchWearableData } from '../services/activityService';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  meals: Meal[];
  setMeals: React.Dispatch<React.SetStateAction<Meal[]>>;
  onExit: () => void;
  onViewInsights: () => void;
  onExplore: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, meals, setMeals, onExit, onViewInsights, onExplore }) => {
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [selectedMealForRecipe, setSelectedMealForRecipe] = useState<Meal | null>(null);
  const [recipeData, setRecipeData] = useState<Recipe | null>(null);
  const [loadingRecipe, setLoadingRecipe] = useState(false);
  const [alternatives, setAlternatives] = useState<MealAlternative[]>([]);
  const [loadingAlts, setLoadingAlts] = useState(false);
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [gamification] = useState<GamificationState>({
    points: 1240,
    streak: 4,
    badges: [{ id: 'sync', name: 'Sync King', icon: '⌚', description: 'Connected a wearable device' }]
  });
  const [activity, setActivity] = useState<ActivityData | null>(null);

  const weekDays = useMemo(() => {
    const today = new Date();
    const days = [];
    const start = new Date(today);
    start.setDate(today.getDate() - 3);

    for (let i = 0; i < 7; i++) {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      days.push({
        label: d.toLocaleDateString('en-US', { weekday: 'narrow' }),
        date: d.getDate(),
        isToday: d.toDateString() === today.toDateString(),
      });
    }
    return days;
  }, []);

  useEffect(() => {
    const syncData = async () => {
      const data = await fetchWearableData();
      setActivity(data);
    };
    syncData();
  }, []);

  const totalConsumed = meals.reduce((sum, m) => m.isLogged ? sum + m.calories : sum, 0);
  const activityBonus = activity ? Math.round(activity.caloriesBurned * 0.8) : 0;
  const targetCals = plan.calories + activityBonus;
  const progressPercent = targetCals > 0 ? Math.round((totalConsumed / targetCals) * 100) : 0;

  const handleLog = (mealId: string, forceLogged?: boolean) => {
    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: forceLogged !== undefined ? forceLogged : !m.isLogged, 
      photoUri: tempPhoto || m.photoUri 
    } : m));
    setShowLogModal(null);
    setTempPhoto(null);
  };

  const openAlternative = async (meal: Meal) => {
    setSelectedMealForAlt(meal);
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setAlternatives(alts);
    setLoadingAlts(false);
  };

  const openRecipe = async (meal: Meal) => {
    setSelectedMealForRecipe(meal);
    setLoadingRecipe(true);
    const recipe = await generateRecipe(meal.name, profile);
    setRecipeData(recipe);
    setLoadingRecipe(false);
  };

  const handlePhotoCapture = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setTempPhoto(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-[#F9FBFC] dark:bg-slate-900 overflow-hidden relative transition-colors duration-500">
      {/* Refined Header matching screenshot style */}
      <div className="p-6 pt-2 bg-white dark:bg-slate-800 border-b border-slate-50 dark:border-slate-700 flex justify-between items-center z-10 transition-colors">
        <div className="flex items-center gap-3">
          <BackButton onClick={onExit} className="-ml-2 dark:text-slate-100" />
          <div className="flex flex-col">
            <h2 className="text-xl font-black text-slate-900 dark:text-white tracking-tight leading-none mb-0.5">NutriForge</h2>
            <div className="flex items-center gap-2">
              <span className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-wider">{plan.name}</span>
              <div className="w-1 h-1 bg-slate-200 dark:bg-slate-700 rounded-full"></div>
              <div className="flex items-center gap-1 text-orange-500 font-bold text-[10px] tracking-tight">
                <span>🔥</span> {gamification.streak} Day Streak
              </div>
            </div>
          </div>
        </div>
        <div className="flex flex-col items-end">
          <span className="text-[10px] text-[#A5B3C1] font-black uppercase tracking-widest leading-none mb-1">Forge Points</span>
          <span className="text-xl font-black text-slate-900 dark:text-white leading-none tracking-tight">{gamification.points}</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pb-32 no-scrollbar">
        {/* Calendar Strip */}
        <div className="px-6 py-4 flex gap-4 overflow-x-auto no-scrollbar bg-white dark:bg-slate-800 border-b border-slate-50 dark:border-slate-700 transition-colors">
          {weekDays.map((day, i) => (
            <div key={i} className={`flex-shrink-0 w-12 h-16 rounded-[20px] flex flex-col items-center justify-center gap-1.5 transition-all ${day.isToday ? 'bg-[#39C101] text-white shadow-lg shadow-[#39C101]/25' : 'text-[#A5B3C1] hover:text-slate-500'}`}>
              <span className="text-[11px] font-black uppercase tracking-tight">{day.label}</span>
              <span className="text-base font-black tracking-tighter">{day.date}</span>
            </div>
          ))}
        </div>

        {/* Wearable Sync Card */}
        {activity && (
          <div className="px-6 py-6">
            <Card className="bg-white dark:bg-slate-800 border-slate-100 shadow-sm py-5 px-6 rounded-[32px]">
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-slate-800 dark:bg-slate-100 rounded-full flex items-center justify-center text-white dark:text-slate-900 shadow-inner">
                    <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z"></path></svg>
                  </div>
                  <div className="space-y-0.5">
                    <h4 className="text-[11px] font-black text-slate-900 dark:text-white uppercase tracking-widest">Wearable Synced</h4>
                    <p className="text-[10px] text-[#A5B3C1] font-bold">{activity.lastSynced}</p>
                  </div>
                </div>
                <div className="text-right">
                  <span className="text-lg font-black text-slate-900 dark:text-white leading-none">+{activity.caloriesBurned} kcal</span>
                  <p className="text-[10px] text-[#A5B3C1] font-black uppercase tracking-widest mt-0.5">{activity.steps} STEPS</p>
                </div>
              </div>
            </Card>
          </div>
        )}

        {/* Daily Energy Section */}
        <div className="px-6 pb-6">
          <Card 
            onClick={onViewInsights}
            className="bg-white dark:bg-slate-800 border-slate-100 shadow-sm relative overflow-hidden p-8 rounded-[32px] group cursor-pointer"
          >
            <div className="flex justify-between items-start mb-8">
              <div className="space-y-1">
                <div className="flex items-center gap-1 group-hover:translate-x-0.5 transition-transform">
                  <span className="text-[11px] text-[#A5B3C1] font-black uppercase tracking-[0.15em]">Daily Energy</span>
                  <svg className="w-3.5 h-3.5 text-[#A5B3C1]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7"></path></svg>
                </div>
                <div className="flex items-baseline gap-2">
                  <span className="text-5xl font-black text-slate-900 dark:text-white tracking-tighter leading-none">{totalConsumed}</span>
                  <span className="text-base text-[#A5B3C1] font-bold">/ {targetCals || '---'} kcal</span>
                </div>
              </div>
              <div className="w-16 h-16 rounded-full border-[5px] border-slate-100 dark:border-slate-700 flex items-center justify-center relative shadow-inner">
                <svg className="w-full h-full absolute inset-0 -rotate-90">
                  <circle cx="32" cy="32" r="27.5" fill="transparent" stroke="currentColor" strokeWidth="5" className="text-slate-50 dark:text-slate-700/50"/>
                  <circle 
                    cx="32" cy="32" r="27.5" fill="transparent" stroke="currentColor" strokeWidth="5" 
                    className="text-[#39C101]" 
                    strokeDasharray="172.7" 
                    strokeDashoffset={172.7 - (172.7 * (progressPercent / 100))} 
                    strokeLinecap="round"
                    style={{ transition: 'stroke-dashoffset 1s ease-in-out' }}
                  />
                </svg>
                <span className="text-xs font-black text-slate-900 dark:text-white">{progressPercent}%</span>
              </div>
            </div>

            <div className="w-full h-4 bg-slate-50 dark:bg-slate-900/50 rounded-full overflow-hidden relative shadow-inner">
               <div className="h-full bg-slate-900 dark:bg-white rounded-full transition-all duration-1000 ease-out" style={{ width: `${Math.min(progressPercent, 100)}%` }} />
            </div>
            <p className="text-[10px] text-[#A5B3C1] mt-5 font-black uppercase tracking-widest italic opacity-80 text-center">*Tap to view detailed macro forge</p>
          </Card>
        </div>

        {/* Explore Button Section */}
        <div className="px-6 mb-8">
          <button 
            onClick={onExplore}
            className="w-full bg-[#39C101] hover:bg-[#32aa01] text-white p-7 rounded-[32px] flex items-center justify-between shadow-2xl shadow-[#39C101]/20 active:scale-[0.98] transition-all group relative overflow-hidden"
          >
            <div className="text-left relative z-10">
              <span className="block text-[11px] font-black uppercase tracking-[0.2em] opacity-80 mb-1.5">Discover New</span>
              <span className="block font-black text-3xl leading-none tracking-tight">Explore Now</span>
            </div>
            <div className="w-14 h-14 bg-white/20 rounded-full flex items-center justify-center group-hover:translate-x-1.5 transition-transform relative z-10">
              <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3.5" d="M9 5l7 7-7 7" /></svg>
            </div>
            <div className="absolute top-0 right-0 w-40 h-40 bg-white/10 rounded-full -mr-16 -mt-16 group-hover:scale-110 transition-transform"></div>
          </button>
        </div>

        {/* Meal List Section - Zero Hardcoded Data */}
        <div className="px-6 space-y-6">
          <h3 className="text-[12px] font-black text-[#A5B3C1] uppercase tracking-[0.2em] mb-4 pl-1">Today's Meals</h3>

          {meals.length === 0 && (
            <div className="py-20 text-center bg-white dark:bg-slate-800 rounded-[32px] border-2 border-dashed border-slate-100 dark:border-slate-700 shadow-sm">
               <div className="w-12 h-12 border-4 border-[#39C101] border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
               <p className="text-[#A5B3C1] text-[10px] font-black uppercase tracking-[0.2em]">Forging Culinary Intelligence...</p>
            </div>
          )}

