 * Returns null instead of throwing to prevent UI crashes.
 */
export const fetchApiMealPlans = async (params: FetchMealPlanParams = {}): Promise<MealPlanApiResponse | null> => {
  try {
    const queryParams = new URLSearchParams();

    if (params.limit) queryParams.append("limit", params.limit.toString());
    if (params.offset) queryParams.append("offset", params.offset.toString());
    if (params.health_goal) queryParams.append("health_goal", params.health_goal);
    if (params.status) queryParams.append("status", params.status);
    if (params.country) queryParams.append("country", params.country);
    if (params.tags) queryParams.append("tags", params.tags);

    const response = await fetch(`${API_ENDPOINT}?${queryParams.toString()}`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        'x-client-id': CLIENT_ID,
        'x-secret-id': CLIENT_SECRET,
        'Accept': 'application/json'
      }
    });

    if (!response.ok) {
      console.error(`Meal Plan API Error: ${response.status} ${response.statusText}`);
      return null;
    }

    const json = await response.json();
    return json as MealPlanApiResponse;
  } catch (error) {
    console.error("Global API Error [MealPlans]:", error);
    return null;
  }
};

/**
