import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

/**
 * GOQii NutriForge API Mock & Proxy Layer
 * Intercepts relative fetch calls to /api.
 * 
 * Includes a proxy for /api/external/meal-plans that forwards to the real 
 * NutriForge backend at nutriforge.goqii.com.
 */
const originalFetch = window.fetch.bind(window);

const mockFetch = async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
  const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;

  // Real API Proxy for External Meal Plans
  if (url.includes('/api/external/meal-plans')) {
    try {
      // Extract original query parameters
      const urlObj = new URL(url, window.location.origin);
      const queryString = urlObj.search;

      const targetUrl = `https://nutriforge.goqii.com/meal-plans${queryString}`;

      // Forward the request to the real external API
      const response = await originalFetch(targetUrl, {
        method: init?.method || 'GET',
        headers: init?.headers || {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        body: init?.body
      });

      // Clone the response so we can return it as-is
      return response;
    } catch (err) {
      console.error("Proxy Forwarding Error:", err);
      return new Response(JSON.stringify({ 
        error: "Proxy connection failed", 
        message: "Unable to reach NutriForge API" 
      }), {
        status: 502,
        headers: { 'Content-Type': 'application/json' }
      });
    }
  }

  // Fallback Mock for standard /api/meal-plans (if still used elsewhere)
  if (url.includes('/api/meal-plans')) {
    const mockMealPlans = [
      {
        id: "plan1",
        title: "Fat Loss Reset – 7 Days",
        name: "Fat Loss Reset – 7 Days",
        goal: "Weight Loss",
        health_goal: "Weight Loss",
        calories: 1300,
        daily_calories: 1300,
        days: 7,
        duration_days: 7,
        image: "https://images.unsplash.com/photo-1490645935967-10de6ba17061",
        image_url: "https://images.unsplash.com/photo-1490645935967-10de6ba17061",
        description: "A precision metabolic reset designed for efficient fat oxidation and metabolic flexibility.",
        status: "published"
      },
      {
        id: "plan2",
        title: "Heart Smart – 7 Days",
        name: "Heart Smart – 7 Days",
        goal: "Heart Health",
        health_goal: "Heart Health",
        calories: 1400,
        daily_calories: 1400,
        days: 7,
        duration_days: 7,
        image: "https://images.unsplash.com/photo-1546069901-ba9599a7e63c",
        image_url: "https://images.unsplash.com/photo-1546069901-ba9599a7e63c",
        description: "Cardio-protective nutritional blueprint focused on heart health and optimized micronutrients.",
        status: "published"
      },
      {
        id: "plan3",
        title: "Muscle Builder – 7 Days",
        name: "Muscle Builder – 7 Days",
        goal: "Muscle Gain",
        health_goal: "Muscle Gain",
        calories: 2000,
        daily_calories: 2000,
        days: 7,
        duration_days: 7,
        image: "https://images.unsplash.com/photo-1504674900247-0877df9cc836",
        image_url: "https://images.unsplash.com/photo-1504674900247-0877df9cc836",
        description: "Anabolic-focused plan designed to maximize muscle protein synthesis and strength performance.",
        status: "published"
      }
    ];

    const urlBase = window.location.origin;
    const urlObj = new URL(url, urlBase);
    const id = urlObj.searchParams.get('id');

    let responseBody;
    if (id) {
      const plan = mockMealPlans.find(p => p.id === id);
      responseBody = { data: plan ? [plan] : [] };
    } else {
      responseBody = {
        data: mockMealPlans,
        pagination: { total: mockMealPlans.length, limit: 20, offset: 0, hasMore: false }
      };
    }

    return new Response(JSON.stringify(responseBody), {
      status: 200,
      headers: { 'Content-Type': 'application/json' }
    });
  }

  // Intercept Recipes API
  if (url.includes('/api/recipes')) {
    return new Response(JSON.stringify({
      data: [],
      pagination: { total: 0, limit: 15, offset: 0, hasMore: false }
    }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' }
    });
  }

  // Intercept other stubs to prevent "Failed to fetch" errors
  if (url.includes('/api/workouts') || url.includes('/api/programs')) {
    return new Response(JSON.stringify({ data: [] }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' }
    });
  }

  return originalFetch(input, init);
};

/**
 * Perform the override using Object.defineProperty to handle environments
 * where window.fetch is read-only or defined via a getter.
 */
try {
  Object.defineProperty(window, 'fetch', {
    value: mockFetch,
    configurable: true,
    writable: true,
    enumerable: true
  });
} catch (e) {
  console.warn("NutriForge: Standard fetch override failed, trying fallback assignment...", e);
  try {
    // @ts-ignore - Bypass read-only check for fallback
    window.fetch = mockFetch;
  } catch (e2) {
    console.error("NutriForge: Failed to override fetch. API calls may fail if no backend is present.", e2);
  }
}

