interface PlanSelectionProps {
  onSelect: (plan: MealPlan | null) => void;
  onBack: () => void;
  profile: UserProfile | null;
}

const PlanSelection: React.FC<PlanSelectionProps> = ({ onSelect, onBack, profile }) => {
  const [plans, setPlans] = useState<MealPlan[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const mapGoalToApi = (goal: HealthGoal): string => {
    switch (goal) {
      case HealthGoal.WeightLoss: return 'weight_loss';
      case HealthGoal.MuscleGain: return 'muscle_gain';
      case HealthGoal.HeartHealth: return 'heart_health';
      case HealthGoal.Energy: return 'muscle_gain'; // Fallback mapping
      case HealthGoal.BalancedLifestyle: return 'heart_health'; // Fallback mapping
      default: return 'weight_loss';
    }
  };

  const loadPlans = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const apiGoal = profile ? mapGoalToApi(profile.healthGoal) : undefined;

      const result = await fetchApiMealPlans({
        limit: 20,
        health_goal: apiGoal,
        status: 'published'
      });

      if (result) {
        // Handle both standard response object with .data and direct arrays
        const rawData = result.data || (Array.isArray(result) ? result : null);

        if (rawData && Array.isArray(rawData)) {
          const mappedPlans: MealPlan[] = rawData.map((p: any) => ({
            id: p.id || p.plan_id || String(Math.random()),
