/**
 * GOQii NutriForge - Transparent CORS Bridge
 * This interceptor handles "Failed to fetch" errors caused by browser CORS restrictions
 * when calling the external NutriForge API. It preserves the original fetch signature
 * so the service layer remains clean and calls the real absolute URLs.
 */
const originalFetch = window.fetch.bind(window);

const corsWrappedFetch = async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
  const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;

  // Detect NutriForge absolute URL calls
  if (url.startsWith('https://nutriforge.goqii.com')) {
    try {
      // Use a standard CORS proxy to bridge the request in environments where direct access is blocked
      const proxyUrl = `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`;
      const response = await originalFetch(proxyUrl, init);

      // If the proxy fails or is blocked, try original fetch as fallback
      if (!response.ok && response.status !== 404) {
        return originalFetch(input, init);
      }

      return response;
    } catch (err) {
      // Fallback to original fetch if proxy logic fails
      return originalFetch(input, init);
    }
  }

  return originalFetch(input, init);
};

// Safely override window.fetch using Object.defineProperty to bypass potential getter-only restrictions
try {
  Object.defineProperty(window, 'fetch', {
    value: corsWrappedFetch,
    configurable: true,
    writable: true,
    enumerable: true
  });
} catch (e) {
  // Fallback assignment for non-restricted environments
  (window as any).fetch = corsWrappedFetch;
}

