import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

/**
 * GOQii NutriForge - Enhanced Transparent CORS Bridge
 * Replaced allorigins with corsproxy.io for improved reliability.
 * This interceptor allows the app to call the NutriForge production API 
 * while bypassing browser-level CORS restrictions in the sandbox.
 */
const originalFetch = window.fetch.bind(window);

const corsWrappedFetch = async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
  const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;

  // Intercept NutriForge domain calls to apply CORS bridge
  if (url.includes('nutriforge.goqii.com')) {
    try {
      // Using corsproxy.io which is generally more stable for direct JSON forwarding
      const proxyUrl = `https://corsproxy.io/?${encodeURIComponent(url)}`;

      const response = await originalFetch(proxyUrl, {
        ...init,
        // Ensure credentials/mode are safe for the proxy
        mode: 'cors',
        cache: 'no-cache'
      });

      return response;
    } catch (err) {
      console.error("CORS Bridge Error:", err);
      // Fallback to original fetch if the proxy fails to resolve
      return originalFetch(input, init);
    }
  }

  return originalFetch(input, init);
};

// Apply the fetch override globally
try {
  Object.defineProperty(window, 'fetch', {
    value: corsWrappedFetch,
    configurable: true,
    writable: true,
    enumerable: true
  });
} catch (e) {
  (window as any).fetch = corsWrappedFetch;
}

