import { MealPlanApiResponse, ApiMealPlan } from "../types";

/**
 * Interface for meal plan fetching parameters.
 */
export interface FetchMealPlanParams {
  limit?: number;
  offset?: number;
  status?: string;
  country?: string;
}

/**
 * Fetches all meal plans directly from the real NutriForge API.
 * The absolute URL is used; the index.tsx interceptor handles proxying.
 * Fix: Added optional params argument to support filtering and pagination in API calls.
 */
export const fetchApiMealPlans = async (params: FetchMealPlanParams = {}): Promise<any> => {
  try {
    const queryParams = new URLSearchParams();
    if (params.limit) queryParams.append("limit", params.limit.toString());
    if (params.offset) queryParams.append("offset", params.offset.toString());
    if (params.status) queryParams.append("status", params.status);
    if (params.country) queryParams.append("country", params.country);

    const queryString = queryParams.toString();
    const url = `https://nutriforge.goqii.com/meal-plans${queryString ? '?' + queryString : ''}`;

    console.debug(`NutriForge: Requesting meal plans from ${url}`);

    // We omit complex headers that often trigger CORS preflight (OPTIONS)
    // which many free proxies don't support well.
    const response = await fetch(url, { method: "GET" });

    if (!response.ok) {
      console.error(`Meal Plan API Error: ${response.status}`);
      return null;
    }

    const json = await response.json();

    // Support both standardized {data: []} and direct array responses
    if (json && json.data && Array.isArray(json.data)) return json.data;
    if (json && Array.isArray(json)) return json;

    return null;
  } catch (error) {
    console.error("Global API Error [MealPlans]:", error instanceof Error ? error.message : String(error));
    // We return null so the UI can show the retry state rather than crashing
    return null;
  }
};

/**
 * Fetches a specific meal plan by ID directly from the NutriForge API.
 */
export const fetchApiMealPlanById = async (id: string): Promise<any> => {
  try {
    const url = `https://nutriforge.goqii.com/meal-plans?id=${id}`;
    const response = await fetch(url, { method: "GET" });

    if (!response.ok) return null;

    const json = await response.json();
    const data = json.data || json;
    return Array.isArray(data) ? data[0] : data;
  } catch (error) {
    console.error("Global API Error [MealPlanById]:", error);
    return null;
  }
};

