import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

/**
 * GOQii NutriForge - Resilient CORS Interceptor
 * Transparently wraps fetch calls to NutriForge domains using public CORS bridges.
 * This is necessary to allow the browser to communicate with the production API
 * in environments that enforce strict CORS policies.
 */
const originalFetch = window.fetch.bind(window);

// List of available public CORS proxies to try sequentially if one fails
const PROXY_GENERATORS = [
  (url: string) => `https://corsproxy.io/?${encodeURIComponent(url)}`,
  (url: string) => `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`,
];

const corsWrappedFetch = async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
  const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;

  // Intercept NutriForge API calls
  if (url.includes('nutriforge.goqii.com')) {
    let lastError: any = null;

    for (const generateProxyUrl of PROXY_GENERATORS) {
      try {
        const proxyUrl = generateProxyUrl(url);

        // When using a proxy, we simplify the request to ensure maximum compatibility
        const response = await originalFetch(proxyUrl, {
          method: init?.method || 'GET',
          headers: { 'Accept': 'application/json' },
          cache: 'no-cache',
          mode: 'cors'
        });

        if (response.ok) {
          // Check if the proxy returned an HTML landing page instead of actual content
          const contentType = response.headers.get("content-type");
          if (contentType && contentType.includes("text/html")) {
             console.debug(`Proxy ${proxyUrl} returned HTML instead of data. Trying next proxy...`);
             continue; 
          }
          return response;
        }
        console.debug(`Proxy attempt failed with status: ${response.status}`);
      } catch (err) {
        lastError = err;
        console.debug('Proxy attempt failed with error:', err);
      }
    }

    // Last resort: try direct fetch
    try {
      return await originalFetch(input, init);
    } catch (finalErr) {
      console.error("NutriForge API Access Failed via all methods:", finalErr || lastError);
      throw finalErr || lastError;
    }
  }

  return originalFetch(input, init);
};

// Override global fetch safely
try {
  Object.defineProperty(window, 'fetch', {
    value: corsWrappedFetch,
    configurable: true,
    writable: true,
    enumerable: true
  });
} catch (e) {
  (window as any).fetch = corsWrappedFetch;
}

const rootElement = document.getElementById('root');
if (rootElement) {
  const root = ReactDOM.createRoot(rootElement);
  root.render(
    <React.StrictMode>
      <App />
    </React.StrictMode>
  );
}

