              { id: '2', name: 'Zesty Lemon Salmon', cals: 450, time: '25 min', img: 'https://images.unsplash.com/photo-1467003909585-2f8a72700288?auto=format&fit=crop&q=80&w=400' },
              { id: '3', name: 'Spiced Chickpea Bowl', cals: 380, time: '15 min', img: 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&q=80&w=400' },
            ].map((recipe) => (
              <div key={recipe.id} className="flex-shrink-0 w-64 bg-white dark:bg-slate-800 rounded-[32px] overflow-hidden border border-slate-50 dark:border-slate-700 shadow-sm hover:shadow-xl transition-all duration-300 group cursor-pointer">
