                    <span className="flex items-center gap-1"><span className="text-[#39C101]">🔥</span> {recipe.cals} kcal</span>
                    <span className="flex items-center gap-1"><svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg> {recipe.time}</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Grocery List Section */}
        <div className="px-6 mt-12">
          <h3 className="text-[12px] font-black text-[#A5B3C1] uppercase tracking-[0.2em] mb-6 pl-1">Your Grocery List</h3>
