            <div className="flex items-center gap-6 mb-8">
              <div className="w-16 h-16 bg-[#39C101]/10 rounded-3xl flex items-center justify-center text-[#39C101] shadow-inner">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
              </div>
              <div className="space-y-1">
                <h4 className="text-lg font-black text-slate-900 dark:text-white leading-tight">Smart Cart</h4>
