              </div>
            </div>
            <Button onClick={onViewGrocery} className="w-full h-14 rounded-2xl bg-slate-900 hover:bg-black text-white text-[11px] font-black uppercase tracking-widest transition-all shadow-xl shadow-slate-900/10">
              View Grocery List
            </Button>
          </Card>
        </div>

        {/* Tips & Blog Section */}
        <div className="px-6 mt-12 pb-12">
          <h3 className="text-[12px] font-black text-[#A5B3C1] uppercase tracking-[0.2em] mb-6 pl-1">Smart Health Tips</h3>
          <div className="space-y-4">
            {[
              { title: 'The Power of Leafy Greens', tag: 'Micro-nutrients', img: 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&q=80&w=400' },
              { title: 'Hydration & Metabolism', tag: 'Bio-hacking', img: 'https://images.unsplash.com/photo-1548919973-5dea585f3968?auto=format&fit=crop&q=80&w=400' },
            ].map((tip, i) => (
              <div key={i} className="flex gap-5 items-center bg-white dark:bg-slate-800 p-4 rounded-[32px] shadow-sm border border-slate-50 dark:border-slate-700 hover:bg-slate-50 transition-all cursor-pointer group">
