              <div className="absolute -bottom-10 -left-10 w-40 h-40 bg-[#39C101]/20 rounded-full blur-3xl opacity-0 group-hover:opacity-100 transition-opacity"></div>
            </button>
          </div>
        </div>
      </div>

      {/* Modals */}
      {showPlanDetails && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[130] flex flex-col justify-end">
          <div className="bg-white dark:bg-slate-900 rounded-t-[48px] p-10 max-h-[85%] overflow-y-auto animate-in slide-in-from-bottom duration-500 no-scrollbar">
            <div className="flex justify-between items-start mb-8">
              <div>
                <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight leading-none mb-2">Plan Details</h3>
                <p className="text-[10px] text-[#A5B3C1] font-black uppercase tracking-[0.2em]">Scientific Logic Breakdown</p>
              </div>
              <button onClick={() => setShowPlanDetails(false)} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>

            {loadingReasoning ? (
              <div className="py-20 text-center space-y-4">
                <div className="w-10 h-10 border-4 border-[#39C101] border-t-transparent rounded-full animate-spin mx-auto"></div>
                <p className="text-[10px] font-black text-[#A5B3C1] uppercase tracking-widest">Decoding Metabolic Pattern...</p>
              </div>
            ) : (
              <div className="space-y-8 pb-10">
                <div className="grid grid-cols-2 gap-4">
                  <DetailItem label="Goal" value={profile.healthGoal} />
                  <DetailItem label="Daily Target" value={`${plan.calories} kcal`} />
                  <DetailItem label="Cuisine" value={profile.cuisine} />
                  <DetailItem label="Diet" value={profile.dietPreference} />
                </div>

                <LogicCard title="Metabolic Strategy" content={planReasoning?.nutrientTiming || ""} />
                <LogicCard title="Micronutrient Focus" content={planReasoning?.micronutrientFocus || ""} />
                <LogicCard title="Food Synergy Tips" content={planReasoning?.foodSynergyTips || ""} />

                <div className="p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border border-slate-100 dark:border-slate-700">
                  <h4 className="text-[10px] font-black text-[#A5B3C1] uppercase tracking-[0.2em] mb-4">Restrictions & Allergies</h4>
                  <div className="flex flex-wrap gap-2">
                    {profile.allergies.length > 0 ? profile.allergies.map(a => (
                      <span key={a} className="px-3 py-1.5 bg-red-50 dark:bg-red-950/20 text-red-500 text-[10px] font-black uppercase tracking-widest rounded-full">{a}</span>
                    )) : <span className="text-[10px] font-bold text-slate-400">None identified</span>}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {showRegenerate && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[130] flex flex-col justify-end">
          <div className="bg-white dark:bg-slate-900 rounded-t-[48px] p-10 max-h-[90%] overflow-y-auto animate-in slide-in-from-bottom duration-500 no-scrollbar shadow-2xl">
            <div className="flex justify-between items-center mb-10">
              <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight leading-none">Modify Forge</h3>
              <button onClick={() => setShowRegenerate(false)} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>

            <div className="space-y-8 pb-10">
              <div className="space-y-4">
                <label className="text-[10px] font-black text-[#A5B3C1] uppercase tracking-widest pl-1">Health Goal</label>
                <div className="flex gap-2 overflow-x-auto no-scrollbar">
                  {Object.values(HealthGoal).map(goal => (
                    <button 
                      key={goal} 
                      onClick={() => setEditProfile({...editProfile, healthGoal: goal})}
                      className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shrink-0 ${editProfile.healthGoal === goal ? 'bg-[#39C101] text-white shadow-lg' : 'bg-slate-50 dark:bg-slate-800 text-slate-500'}`}
                    >
                      {goal}
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-4">
                <label className="text-[10px] font-black text-[#A5B3C1] uppercase tracking-widest pl-1">Cuisine Style</label>
                <div className="flex gap-2 overflow-x-auto no-scrollbar">
                  {Object.values(Cuisine).map(c => (
                    <button 
                      key={c} 
                      onClick={() => setEditProfile({...editProfile, cuisine: c})}
                      className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shrink-0 ${editProfile.cuisine === c ? 'bg-[#39C101] text-white shadow-lg' : 'bg-slate-50 dark:bg-slate-800 text-slate-500'}`}
                    >
                      {c}
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-4">
                <label className="text-[10px] font-black text-[#A5B3C1] uppercase tracking-widest pl-1">Diet Preference</label>
                <div className="flex gap-2 overflow-x-auto no-scrollbar">
                  {Object.values(DietPreference).map(d => (
                    <button 
                      key={d} 
                      onClick={() => setEditProfile({...editProfile, dietPreference: d})}
                      className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shrink-0 ${editProfile.dietPreference === d ? 'bg-[#39C101] text-white shadow-lg' : 'bg-slate-50 dark:bg-slate-800 text-slate-500'}`}
                    >
                      {d}
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-4">
                <label className="text-[10px] font-black text-[#A5B3C1] uppercase tracking-widest pl-1">Meals Per Day</label>
                <div className="flex gap-2 overflow-x-auto no-scrollbar">
                  {Object.values(MealFrequency).map(m => (
                    <button 
                      key={m} 
                      onClick={() => setEditProfile({...editProfile, mealFrequency: m})}
                      className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shrink-0 ${editProfile.mealFrequency === m ? 'bg-[#39C101] text-white shadow-lg' : 'bg-slate-50 dark:bg-slate-800 text-slate-500'}`}
                    >
                      {m.split(' ')[0]}
                    </button>
                  ))}
                </div>
              </div>

              <Button onClick={handleRebuild} className="w-full h-20 rounded-[32px] text-lg font-black bg-[#39C101] text-white shadow-2xl shadow-[#39C101]/30">
