            <div className="flex justify-between items-start mb-8">
              <div className="pr-12">
                <h3 className="text-2xl font-black text-slate-900 dark:text-white leading-tight tracking-tight mb-1">{selectedMealForRecipe.name}</h3>
                <p className="text-[10px] text-[#A5B3C1] font-black uppercase tracking-[0.2em]">Metabolic Prep Guide</p>
              </div>
              <button onClick={() => { setSelectedMealForRecipe(null); setRecipeData(null); }} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full hover:bg-slate-200 transition-colors">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            {loadingRecipe ? (
              <div className="py-24 text-center">
                <div className="w-14 h-14 border-[5px] border-[#39C101] border-t-transparent rounded-full animate-spin mx-auto mb-6"></div>
                <p className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-[0.25em]">Forging culinary blueprint...</p>
              </div>
            ) : recipeData ? (
              <div className="space-y-10 pb-12">
                <div className="grid grid-cols-2 gap-6">
                  <div className="p-5 bg-slate-50 dark:bg-slate-800 rounded-3xl border border-slate-100 dark:border-slate-700/50"><span className="text-[10px] font-black text-[#A5B3C1] uppercase tracking-widest block mb-2">Prep Time</span><span className="text-lg font-black text-slate-800 dark:text-white">{recipeData.prepTime}</span></div>
                  <div className="p-5 bg-slate-50 dark:bg-slate-800 rounded-3xl border border-slate-100 dark:border-slate-700/50"><span className="text-[10px] font-black text-[#A5B3C1] uppercase tracking-widest block mb-2">Cook Time</span><span className="text-lg font-black text-slate-800 dark:text-white">{recipeData.cookTime}</span></div>
                </div>

                {selectedMealForRecipe.apiRecipeDetail?.description ? (
                  <div className="space-y-4">
                    <h4 className="text-[12px] font-black text-slate-900 dark:text-white uppercase tracking-widest border-l-[6px] border-[#39C101] pl-4">Chef's Details</h4>
                    <div 
                      className="prose prose-sm dark:prose-invert text-[14px] text-slate-600 dark:text-slate-400 font-bold leading-relaxed"
                      dangerouslySetInnerHTML={{ __html: selectedMealForRecipe.apiRecipeDetail.description }} 
                    />
                  </div>
                ) : (
                  <>
                    <div className="space-y-4">
                      <h4 className="text-[12px] font-black text-slate-900 dark:text-white uppercase tracking-widest border-l-[6px] border-[#39C101] pl-4">Metabolic Components</h4>
                      <ul className="grid grid-cols-1 gap-3">
                        {recipeData.ingredients.map((ing, i) => (
                          <li key={i} className="text-[13px] text-slate-600 dark:text-slate-400 font-bold bg-slate-50/50 dark:bg-slate-800/40 p-3 rounded-2xl flex items-center gap-3">
                            <div className="w-1.5 h-1.5 bg-[#39C101] rounded-full"></div>{ing}
                          </li>
                        ))}
                      </ul>
                    </div>
                    <div className="space-y-6">
                      <h4 className="text-[12px] font-black text-slate-900 dark:text-white uppercase tracking-widest border-l-[6px] border-[#39C101] pl-4">Preparation Guide</h4>
                      <div className="space-y-6">
                        {recipeData.instructions.map((step, i) => (
                          <div key={i} className="flex gap-5">
                            <span className="flex-shrink-0 w-8 h-8 bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-white rounded-[14px] flex items-center justify-center text-[12px] font-black shadow-sm">{i + 1}</span>
                            <p className="text-[14px] text-slate-600 dark:text-slate-400 font-bold leading-relaxed">{step}</p>
                          </div>
                        ))}
                      </div>
                    </div>
                  </>
                )}

                <Button className="w-full h-16 rounded-[24px] text-white shadow-2xl shadow-[#39C101]/30" onClick={() => { setShowLogModal(selectedMealForRecipe); setSelectedMealForRecipe(null); }}>Commit to Meal Plan</Button>
              </div>
            ) : null}
          </div>
        </div>
      )}

      {showLogModal && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-[120] flex flex-col justify-end">
          <div className="bg-white dark:bg-slate-900 rounded-t-[48px] p-10 max-h-[90%] overflow-y-auto animate-in slide-in-from-bottom duration-500 no-scrollbar shadow-2xl">
             <div className="flex justify-between items-center mb-10">
              <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight leading-none">Log {showLogModal.type}</h3>
              <button onClick={() => { setShowLogModal(null); setTempPhoto(null); }} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full hover:bg-slate-200 transition-colors">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            <div className="mb-8 flex flex-col items-center">
               <div className="w-full aspect-square max-w-[280px] bg-slate-50 dark:bg-slate-800 rounded-[48px] border-4 border-dashed border-slate-100 dark:border-slate-700 relative overflow-hidden flex items-center justify-center cursor-pointer group hover:border-[#39C101]/50 transition-all" onClick={() => fileInputRef.current?.click()}>
                 {tempPhoto ? <img src={tempPhoto} className="w-full h-full object-cover" /> : <div className="text-center space-y-4 text-[#A5B3C1] group-hover:scale-110 transition-transform duration-500"><svg className="w-16 h-16 mx-auto opacity-50" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" strokeWidth="1.5"/><path d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" strokeWidth="1.5"/></svg><span className="text-[11px] font-black uppercase tracking-[0.3em] block px-4 opacity-80 leading-relaxed">Forge Visual Proof</span></div>}
                 <input type="file" ref={fileInputRef} className="hidden" accept="image/*" capture="environment" onChange={handlePhotoCapture}/>
               </div>
            </div>
            <div className="mb-10 text-center space-y-1">
               <h4 className="text-lg font-black text-slate-800 dark:text-white leading-tight">{showLogModal.name}</h4>
               <p className="text-[12px] text-[#A5B3C1] font-bold tracking-tight">{showLogModal.calories} kcal Blueprint Target</p>
            </div>
            <Button className="w-full h-20 rounded-[32px] text-lg font-black text-white shadow-2xl shadow-[#39C101]/40 mb-6 bg-[#39C101] hover:bg-[#32aa01]" onClick={() => handleLog(showLogModal.id, true)}>
              {showLogModal.isLogged ? 'Update Log' : 'Confirm Entry'}
            </Button>
            {showLogModal.isLogged && <button className="w-full py-4 text-red-500 text-[11px] font-black uppercase tracking-[0.3em] opacity-80 hover:opacity-100 transition-opacity" onClick={() => handleLog(showLogModal.id, false)}>Clear Metabolic Entry</button>}
          </div>
        </div>
      )}
    </div>
  );
};

const DetailItem: React.FC<{ label: string; value: string }> = ({ label, value }) => (
  <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-slate-700">
    <span className="text-[8px] font-black text-[#A5B3C1] uppercase tracking-widest block mb-1">{label}</span>
    <span className="text-[12px] font-black text-slate-800 dark:text-slate-100">{value}</span>
  </div>
);

const LogicCard: React.FC<{ title: string; content: string }> = ({ title, content }) => (
  <div className="space-y-3">
    <h4 className="text-[11px] font-black text-slate-900 dark:text-white uppercase tracking-widest border-l-[4px] border-[#39C101] pl-3">{title}</h4>
    <p className="text-xs text-slate-500 dark:text-slate-400 font-bold leading-relaxed bg-white dark:bg-slate-900/50">
