import React, { useState, useEffect } from 'react';
import { UserProfile, HealthGoal, Cuisine, MealFrequency, DietPreference, MealPlan, Meal, ApiMealPlan } from './types';
import Onboarding from './views/Onboarding';
import PlanSelection from './views/PlanSelection';
import Dashboard from './views/Dashboard';
import FreeMode from './views/FreeMode';
import Insights from './views/Insights';
import Settings from './views/Settings';
import ExploreHub from './views/ExploreHub';
import GroceryList from './views/GroceryList';
import PlanDetails from './views/PlanDetails';
import EditPlan from './views/EditPlan';
import { generateDailyMeals } from './services/geminiService';
import { fetchApiMealPlanById } from './services/mealPlanService';

type View = 'onboarding' | 'plan-selection' | 'dashboard' | 'free-mode' | 'insights' | 'settings' | 'explore-hub' | 'grocery-list' | 'plan-details' | 'edit-plan';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('onboarding');
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [selectedPlan, setSelectedPlan] = useState<MealPlan | null>(null);
  const [meals, setMeals] = useState<Meal[]>([]);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isForging, setIsForging] = useState(false);
  const [time, setTime] = useState(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));

  useEffect(() => {
    const timer = setInterval(() => {
      setTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    }, 10000);
    return () => clearInterval(timer);
  }, []);

  const handleOnboardingComplete = (data: UserProfile) => {
    setProfile(data);
    setCurrentView('plan-selection');
  };

  const mapMealType = (type: string): Meal['type'] => {
    const t = type.toLowerCase();
    if (t.includes('breakfast')) return 'Breakfast';
    if (t.includes('lunch')) return 'Lunch';
    if (t.includes('dinner')) return 'Dinner';
    return 'Snack';
  };

  const handleUpdateProfile = async (newProfile: UserProfile) => {
    setProfile(newProfile);
    if (selectedPlan) {
      setIsForging(true);
      try {
        const finalMeals = await generateDailyMeals(selectedPlan, newProfile);
        setMeals(finalMeals);
        setCurrentView('dashboard');
      } catch (err) {
        console.error("Error rebuilding plan:", err);
      } finally {
        setIsForging(false);
      }
    }
  };

  const handlePlanSelect = async (plan: MealPlan | null) => {
    if (plan && profile) {
      setIsForging(true);

      try {
        const apiPlanResponse = await fetchApiMealPlanById(plan.id);
        const apiPlanDetail = apiPlanResponse?.data || apiPlanResponse;

        const enrichedPlan: MealPlan = apiPlanDetail ? {
          id: apiPlanDetail.id || apiPlanDetail.plan_id || plan.id,
          name: apiPlanDetail.name || apiPlanDetail.plan_name || apiPlanDetail.title || plan.name,
          duration: `${apiPlanDetail.duration_days || apiPlanDetail.days || 7} Days`,
          calories: Number(apiPlanDetail.daily_calories || apiPlanDetail.calories_per_day || apiPlanDetail.calories || plan.calories),
          description: apiPlanDetail.description || plan.description,
          image_url: apiPlanDetail.image_url || apiPlanDetail.image || plan.image_url
        } : plan;

        setSelectedPlan(enrichedPlan);

        let finalMeals: Meal[] = [];

        if (apiPlanDetail?.days && apiPlanDetail.days["1"]) {
          finalMeals = apiPlanDetail.days["1"].map((item: any, idx: number) => ({
            id: item.recipe?.id || `api-meal-${idx}-${Date.now()}`,
            type: mapMealType(item.meal_type),
            name: item.recipe?.title || 'Unknown Meal',
            calories: item.recipe?.calories || 0,
            protein: item.recipe?.protein || 0,
            carbs: item.recipe?.carbs || 0,
            fat: item.recipe?.fats || 0,
            isLogged: false,
            apiRecipeDetail: {
              description: item.recipe?.description,
              instructions: item.recipe?.instructions,
              prepTime: item.recipe?.prep_time,
              cookTime: item.recipe?.cook_time,
              image_url: item.recipe?.image_url
            }
          }));
        } else {
          finalMeals = await generateDailyMeals(enrichedPlan, profile);
        }

        setMeals(finalMeals);
      } catch (err) {
        console.error("Critical error fetching or forging meal plan:", err);
        setSelectedPlan(plan);
        setMeals([]);
      } finally {
        setIsForging(false);
        setCurrentView('dashboard');
      }
    } else {
      setCurrentView('free-mode');
    }
  };

  const isMainApp = ['dashboard', 'free-mode', 'insights', 'settings', 'explore-hub', 'grocery-list', 'plan-details', 'edit-plan'].includes(currentView);

  return (
    <div className={`min-h-screen ${isDarkMode ? 'bg-slate-950' : 'bg-slate-200'} flex items-center justify-center p-0 sm:p-4 transition-colors duration-500`}>
      <div className={`${isDarkMode ? 'dark' : ''} w-full max-w-md h-[100vh] sm:h-[844px] relative overflow-hidden flex flex-col sm:rounded-[48px] sm:shadow-2xl border-[8px] border-slate-900 shadow-inner shadow-black/20`}>
        <div className="w-full h-full bg-[#F9FBFC] dark:bg-slate-950 flex flex-col transition-colors duration-500">

          <div className="h-10 flex justify-between items-center px-8 shrink-0 z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-sm">
            <span className="text-xs font-bold text-slate-800 dark:text-slate-100">{time}</span>
            <div className="flex gap-1.5 items-center">
              <svg className="w-4 h-4 text-slate-800 dark:text-slate-100" fill="currentColor" viewBox="0 0 20 20"><path d="M2 11a1 1 0 011-1h2a1 1 0 011 1v5a1 1 0 01-1 1H3a1 1 0 01-1-1v-5zm6-4a1 1 0 011-1h2a1 1 0 011 1v9a1 1 0 01-1 1H9a1 1 0 01-1-1V7zm6-4a1 1 0 011-1h2a1 1 0 011 1v13a1 1 0 01-1 1h-2a1 1 0 01-1-1V3z"></path></svg>
              <div className="w-5 h-2.5 border border-slate-800 dark:border-slate-100 rounded-sm relative">
                <div className="absolute left-0.5 top-0.5 bottom-0.5 right-1 bg-slate-800 dark:bg-slate-100 rounded-px"></div>
              </div>
            </div>
          </div>

          <div className="flex-1 flex flex-col overflow-hidden relative">
            {isForging && (
              <div className="absolute inset-0 bg-white/95 dark:bg-slate-900/95 z-[100] flex flex-col items-center justify-center p-12 text-center animate-in fade-in duration-500">
                <div className="relative w-32 h-32 mb-8">
                  <div className="absolute inset-0 border-4 border-slate-100 dark:border-slate-800 rounded-full"></div>
                  <div className="absolute inset-0 border-4 border-[#39C101] rounded-full border-t-transparent animate-spin"></div>
                  <div className="absolute inset-4 bg-[#39C101]/5 rounded-full flex items-center justify-center animate-pulse">
                    <svg className="w-10 h-10 text-[#39C101]" fill="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z"/></svg>
                  </div>
                </div>
                <h2 className="text-2xl font-black text-slate-900 dark:text-white mb-2 tracking-tight uppercase">Forging Daily Blueprint</h2>
                <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest max-w-xs leading-relaxed italic">
                  Syncing with Global Nutrition Database...
                </p>
              </div>
            )}

            {currentView === 'onboarding' && (
              <Onboarding onComplete={handleOnboardingComplete} />
            )}
            {currentView === 'plan-selection' && (
              <PlanSelection 
                onSelect={handlePlanSelect} 
                onBack={() => setCurrentView('onboarding')} 
                profile={profile}
              />
            )}
            {currentView === 'dashboard' && profile && selectedPlan && (
              <Dashboard 
                profile={profile} 
                plan={selectedPlan} 
                meals={meals}
                setMeals={setMeals}
                onExit={() => setCurrentView('plan-selection')}
                onViewInsights={() => setCurrentView('insights')}
                onExplore={() => setCurrentView('explore-hub')}
                onViewGrocery={() => setCurrentView('grocery-list')}
                onViewPlanDetails={() => setCurrentView('plan-details')}
                onEditPlan={() => setCurrentView('edit-plan')}
              />
            )}
            {currentView === 'plan-details' && profile && selectedPlan && (
              <PlanDetails 
                profile={profile}
                plan={selectedPlan}
                onBack={() => setCurrentView('dashboard')}
              />
            )}
            {currentView === 'edit-plan' && profile && (
              <EditPlan 
                profile={profile}
                onBack={() => setCurrentView('dashboard')}
                onRebuild={handleUpdateProfile}
              />
            )}
            {currentView === 'explore-hub' && profile && selectedPlan && (
              <ExploreHub 
                profile={profile}
                plan={selectedPlan}
                meals={meals}
                onBack={() => setCurrentView('dashboard')}
                onSelectPlan={() => setCurrentView('plan-selection')}
              />
            )}
            {currentView === 'grocery-list' && (
              <GroceryList onBack={() => setCurrentView('dashboard')} />
            )}
            {currentView === 'free-mode' && (
              <FreeMode 
                onBack={() => setCurrentView('plan-selection')} 
                meals={meals}
                plan={selectedPlan}
                onExplore={() => setCurrentView('explore-hub')}
                onViewGrocery={() => setCurrentView('grocery-list')}
              />
            )}
            {currentView === 'insights' && profile && (
              <Insights 
                onBack={() => setCurrentView('dashboard')} 
                meals={meals}
                targetCalories={selectedPlan?.calories || 2000}
              />
            )}
            {currentView === 'settings' && (
              <Settings 
                onBack={() => setCurrentView('dashboard')}
                isDarkMode={isDarkMode}
                onToggleDarkMode={() => setIsDarkMode(!isDarkMode)}
              />
            )}
          </div>

          {isMainApp && (
            <div className="absolute bottom-0 left-0 right-0 h-20 bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl border-t border-slate-100 dark:border-slate-800 flex items-center justify-around px-4 pb-2 z-50">
              <button onClick={() => setCurrentView('dashboard')} className={`flex flex-col items-center gap-1 transition-all ${['dashboard', 'explore-hub', 'grocery-list', 'plan-details', 'edit-plan'].includes(currentView) ? 'text-[#39C101]' : 'text-slate-400 dark:text-slate-500'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"></path></svg>
                <span className="text-[10px] font-black uppercase tracking-tighter">Home</span>
              </button>
              <button onClick={() => setCurrentView('free-mode')} className={`flex flex-col items-center gap-1 transition-all ${currentView === 'free-mode' ? 'text-[#39C101]' : 'text-slate-400 dark:text-slate-500'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
                <span className="text-[10px] font-black uppercase tracking-tighter">Forge</span>
              </button>
              <button onClick={() => setCurrentView('insights')} className={`flex flex-col items-center gap-1 transition-all ${currentView === 'insights' ? 'text-[#39C101]' : 'text-slate-400 dark:text-slate-500'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"></path></svg>
                <span className="text-[10px] font-black uppercase tracking-tighter">Insights</span>
              </button>
              <button onClick={() => setCurrentView('settings')} className={`flex flex-col items-center gap-1 transition-all ${currentView === 'settings' ? 'text-[#39C101]' : 'text-slate-400 dark:text-slate-500'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                <span className="text-[10px] font-black uppercase tracking-tighter">Profile</span>
              </button>
            </div>
          )}

          <div className="absolute top-0 left-1/2 -translate-x-1/2 w-32 h-6 bg-slate-900 rounded-b-2xl z-[60] hidden sm:block"></div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { UserProfile, MealPlan, Meal, MealAlternative, GamificationState, Recipe } from '../types';
import { Card, Button, BackButton } from '../components/UI';
import { generateMealAlternatives, generateRecipe } from '../services/geminiService';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  meals: Meal[];
  setMeals: React.Dispatch<React.SetStateAction<Meal[]>>;
  onExit: () => void;
  onViewInsights: () => void;
  onExplore: () => void;
  onViewGrocery: () => void;
  onViewPlanDetails: () => void;
  onEditPlan: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, meals, setMeals, onExit, onViewInsights, onExplore, onViewGrocery, onViewPlanDetails, onEditPlan }) => {
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [selectedMealForRecipe, setSelectedMealForRecipe] = useState<Meal | null>(null);
  const [recipeData, setRecipeData] = useState<Recipe | null>(null);
  const [loadingRecipe, setLoadingRecipe] = useState(false);
  const [alternatives, setAlternatives] = useState<MealAlternative[]>([]);
  const [loadingAlts, setLoadingAlts] = useState(false);
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [gamification] = useState<GamificationState>({
    points: 1240,
    streak: 4,
    badges: [{ id: 'sync', name: 'Sync King', icon: '⌚', description: 'Connected a wearable device' }]
  });

  const weekDays = useMemo(() => {
    const today = new Date();
    const days = [];
    const start = new Date(today);
    start.setDate(today.getDate() - 3);

    for (let i = 0; i < 7; i++) {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      days.push({
        label: d.toLocaleDateString('en-US', { weekday: 'narrow' }),
        date: d.getDate(),
        isToday: d.toDateString() === today.toDateString(),
      });
    }
    return days;
  }, []);

  const totalConsumed = meals.reduce((sum, m) => m.isLogged ? sum + m.calories : sum, 0);
  const targetCals = plan.calories;
  const progressPercent = targetCals > 0 ? Math.round((totalConsumed / targetCals) * 100) : 0;

  const handleLog = (mealId: string, forceLogged?: boolean) => {
    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: forceLogged !== undefined ? forceLogged : !m.isLogged, 
      photoUri: tempPhoto || m.photoUri 
    } : m));
    setShowLogModal(null);
    setTempPhoto(null);
  };

  const openAlternative = async (meal: Meal) => {
    setSelectedMealForAlt(meal);
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setAlternatives(alts);
    setLoadingAlts(false);
  };

  const openRecipe = async (meal: Meal) => {
    setSelectedMealForRecipe(meal);

    if (meal.apiRecipeDetail && (meal.apiRecipeDetail.description || (meal.apiRecipeDetail.instructions && meal.apiRecipeDetail.instructions.length > 0))) {
      setRecipeData({
        ingredients: [],
        instructions: meal.apiRecipeDetail.instructions || [],
        prepTime: meal.apiRecipeDetail.prepTime ? `${meal.apiRecipeDetail.prepTime}m` : '15m',
        cookTime: meal.apiRecipeDetail.cookTime ? `${meal.apiRecipeDetail.cookTime}m` : '15m'
      });
      return;
    }

    setLoadingRecipe(true);
    const recipe = await generateRecipe(meal.name, profile);
    setRecipeData(recipe);
    setLoadingRecipe(false);
  };

  const handlePhotoCapture = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setTempPhoto(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-[#F9FBFC] dark:bg-slate-900 overflow-hidden relative transition-colors duration-500">
      {/* Header */}
      <div className="p-6 pt-2 bg-white dark:bg-slate-800 border-b border-slate-50 dark:border-slate-700 flex justify-between items-center z-10 transition-colors">
        <div className="flex items-center gap-3">
          <BackButton onClick={onExit} className="-ml-2 dark:text-slate-100" />
          <div className="flex flex-col">
            <h2 className="text-xl font-black text-slate-900 dark:text-white tracking-tight leading-none mb-0.5">NutriForge</h2>
            <div className="flex items-center gap-2">
              <span className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-wider">{plan.name}</span>
              <div className="w-1 h-1 bg-slate-200 dark:bg-slate-700 rounded-full"></div>
              <div className="flex items-center gap-1 text-orange-500 font-bold text-[10px] tracking-tight">
                <span>🔥</span> {gamification.streak} Day Streak
              </div>
            </div>
          </div>
        </div>
        <div className="flex flex-col items-end">
          <span className="text-[10px] text-[#A5B3C1] font-black uppercase tracking-widest leading-none mb-1">Forge Points</span>
          <span className="text-xl font-black text-slate-900 dark:text-white leading-none tracking-tight">{gamification.points}</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pb-32 no-scrollbar">
        {/* Calendar Strip */}
        <div className="px-6 py-4 flex gap-4 overflow-x-auto no-scrollbar bg-white dark:bg-slate-800 border-b border-slate-50 dark:border-slate-700 transition-colors">
          {weekDays.map((day, i) => (
            <div key={i} className={`flex-shrink-0 w-12 h-16 rounded-[20px] flex flex-col items-center justify-center gap-1.5 transition-all ${day.isToday ? 'bg-[#39C101] text-white shadow-lg shadow-[#39C101]/25' : 'text-[#A5B3C1] hover:text-slate-500'}`}>
              <span className="text-[11px] font-black uppercase tracking-tight">{day.label}</span>
              <span className="text-base font-black tracking-tighter">{day.date}</span>
            </div>
          ))}
        </div>

        {/* Daily Energy Section */}
        <div className="px-6 py-6">
          <Card 
            onClick={onViewInsights}
            className="bg-white dark:bg-slate-800 border-slate-100 shadow-sm relative overflow-hidden p-8 rounded-[32px] group cursor-pointer"
          >
            <div className="flex justify-between items-start mb-8">
              <div className="space-y-1">
                <div className="flex items-center gap-1 group-hover:translate-x-0.5 transition-transform">
                  <span className="text-[11px] text-[#A5B3C1] font-black uppercase tracking-[0.15em]">Daily Energy</span>
                  <svg className="w-3.5 h-3.5 text-[#A5B3C1]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7"></path></svg>
                </div>
                <div className="flex items-baseline gap-2">
                  <span className="text-5xl font-black text-slate-900 dark:text-white tracking-tighter leading-none">{totalConsumed}</span>
                  <span className="text-base text-[#A5B3C1] font-bold">/ {targetCals || '---'} kcal</span>
                </div>
              </div>
              <div className="w-16 h-16 rounded-full border-[5px] border-slate-100 dark:border-slate-700 flex items-center justify-center relative shadow-inner">
                <svg className="w-full h-full absolute inset-0 -rotate-90">
                  <circle cx="32" cy="32" r="27.5" fill="transparent" stroke="currentColor" strokeWidth="5" className="text-slate-50 dark:text-slate-700/50"/>
                  <circle 
                    cx="32" cy="32" r="27.5" fill="transparent" stroke="currentColor" strokeWidth="5" 
                    className="text-[#39C101]" 
                    strokeDasharray="172.7" 
                    strokeDashoffset={172.7 - (172.7 * (progressPercent / 100))} 
                    strokeLinecap="round"
                    style={{ transition: 'stroke-dashoffset 1s ease-in-out' }}
                  />
                </svg>
                <span className="text-xs font-black text-slate-900 dark:text-white">{progressPercent}%</span>
              </div>
            </div>

            <div className="w-full h-4 bg-slate-50 dark:bg-slate-900/50 rounded-full overflow-hidden relative shadow-inner">
               <div className="h-full bg-slate-900 dark:bg-white rounded-full transition-all duration-1000 ease-out" style={{ width: `${Math.min(progressPercent, 100)}%` }} />
            </div>
            <p className="text-[10px] text-[#A5B3C1] mt-5 font-black uppercase tracking-widest italic opacity-80 text-center">*Tap to view detailed macro forge</p>
          </Card>

          {/* New Horizontal Plan Buttons */}
          <div className="flex justify-center gap-8 mt-4 px-2">
            <button onClick={onViewPlanDetails} className="text-[11px] font-black text-[#39C101] uppercase tracking-widest hover:opacity-80 transition-opacity">View Plan Details</button>
            <button onClick={onEditPlan} className="text-[11px] font-black text-[#39C101] uppercase tracking-widest hover:opacity-80 transition-opacity">Change Plan</button>
          </div>
        </div>

        {/* Meal List Section */}
        <div className="px-6 space-y-6">
          <h3 className="text-[12px] font-black text-[#A5B3C1] uppercase tracking-[0.2em] mb-4 pl-1">Today's Meals</h3>

          {meals.length === 0 && (
            <div className="py-20 text-center bg-white dark:bg-slate-800 rounded-[32px] border-2 border-dashed border-slate-100 dark:border-slate-700 shadow-sm">
               <div className="w-12 h-12 border-4 border-[#39C101] border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
               <p className="text-[#A5B3C1] text-[10px] font-black uppercase tracking-[0.2em]">Forging Culinary Intelligence...</p>
