import React, { useState } from 'react';
import { UserProfile, HealthGoal, Cuisine, DietPreference, MealFrequency } from '../types';
import { BackButton, Card, Button } from '../components/UI';

interface EditPlanProps {
  profile: UserProfile;
  onBack: () => void;
  onRebuild: (p: UserProfile) => void;
}

const EditPlan: React.FC<EditPlanProps> = ({ profile, onBack, onRebuild }) => {
  const [editProfile, setEditProfile] = useState<UserProfile>({ ...profile });

  const toggleAllergy = (allergy: string) => {
    let newList: string[];
    if (allergy === 'None') {
      newList = ['None'];
    } else {
      newList = editProfile.allergies.filter(i => i !== 'None');
      newList = newList.includes(allergy) 
        ? newList.filter(i => i !== allergy) 
        : [...newList, allergy];
    }
    setEditProfile(prev => ({ ...prev, allergies: newList }));
  };

  return (
    <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 transition-colors no-scrollbar overflow-y-auto pb-32">
      <div className="p-6 pt-2 flex items-center gap-4 border-b border-slate-50 dark:border-slate-800 sticky top-0 bg-white/90 dark:bg-slate-900/90 backdrop-blur-md z-20 transition-colors">
        <BackButton onClick={onBack} className="-ml-2 dark:text-slate-300" />
        <h1 className="text-xl font-bold text-slate-800 dark:text-white tracking-tight">Edit Nutrition Plan</h1>
      </div>

      <div className="p-6 space-y-10">
        <section className="space-y-4">
          <label className="text-[10px] font-black text-[#A5B3C1] uppercase tracking-[0.2em] pl-1">Health Goal</label>
          <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
            {Object.values(HealthGoal).map(goal => (
              <button 
                key={goal} 
                onClick={() => setEditProfile({...editProfile, healthGoal: goal})}
                className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shrink-0 border-2 ${editProfile.healthGoal === goal ? 'bg-[#39C101] border-[#39C101] text-white shadow-lg' : 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700 text-slate-500'}`}
              >
