              <div className="p-6 flex flex-col gap-2">
                <div className="flex justify-between items-start">
                  <h3 className="text-lg font-black text-slate-800 dark:text-white tracking-tight leading-tight group-hover:text-green-600 transition-colors">
                    {plan.name}
                  </h3>
                  <div className="flex items-center gap-1.5 shrink-0 ml-4">
                    <span className="w-1 h-1 bg-slate-300 dark:bg-slate-600 rounded-full"></span>
                    <span className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">
                      {plan.duration}
                    </span>
                  </div>
                </div>

                <p className="text-xs text-slate-500 dark:text-slate-400 leading-relaxed mt-1 mb-4 line-clamp-2 italic font-medium">
                  {plan.description}
                </p>

                <Button 
                  onClick={() => onSelect(plan)} 
                  className="w-full h-12 rounded-2xl text-[11px] font-black uppercase tracking-widest shadow-lg shadow-green-500/10 hover:shadow-green-500/20 transition-all active:scale-95"
                >
                  Start This Journey
                </Button>

                {/* New horizontal container with text buttons */}
                <div className="flex justify-center gap-6 mt-3 px-2">
                  <button 
                    onClick={() => onViewDetails(plan)} 
                    className="text-[10px] font-black text-[#39C101] uppercase tracking-widest hover:opacity-80 transition-opacity"
                  >
                    View Plan Details
                  </button>
                  <button 
                    onClick={onEditPlan} 
                    className="text-[10px] font-black text-[#39C101] uppercase tracking-widest hover:opacity-80 transition-opacity"
                  >
                    Change Plan
                  </button>
                </div>
              </div>
            </div>
          ))
        ) : (
          <div className="text-center py-16 px-6 bg-slate-100/50 dark:bg-slate-800/50 rounded-[40px] border-2 border-dashed border-slate-200 dark:border-slate-700">
            <div className="text-4xl mb-4">🥗</div>
            <p className="text-slate-500 dark:text-slate-400 font-bold text-sm">No meal plans available at the moment.</p>
            <p className="text-slate-400 dark:text-slate-500 text-xs mt-1">Try checking back later.</p>
          </div>
        )}
      </div>

      <div className="mt-auto space-y-4 text-center pb-8">
        <Button variant="ghost" onClick={() => onSelect(null)} className="w-full text-slate-500 dark:text-slate-400 uppercase font-black text-[10px] tracking-widest">Skip for now</Button>
        <p className="text-slate-400 dark:text-slate-500 text-[9px] px-4 italic leading-relaxed">
          Unlock premium metabolic blueprints and AI-guided recipes anytime from your master dashboard.
        </p>
      </div>
    </div>
  );
};

