interface PlanDetailsProps {
  profile: UserProfile;
  plan: MealPlan;
  onBack: () => void;
  onSelect?: (plan: MealPlan) => void;
}

const PlanDetails: React.FC<PlanDetailsProps> = ({ profile, plan, onBack, onSelect }) => {
  const [reasoning, setReasoning] = useState<PlanReasoning | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchReasoning = async () => {
      setLoading(true);
      const res = await generatePlanReasoning(plan, profile);
      setReasoning(res);
      setLoading(false);
    };
    fetchReasoning();
  }, [plan, profile]);

  return (
    <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 transition-colors no-scrollbar overflow-y-auto pb-48">
      <div className="p-6 pt-2 flex items-center gap-4 border-b border-slate-50 dark:border-slate-800 sticky top-0 bg-white/90 dark:bg-slate-900/90 backdrop-blur-md z-20 transition-colors">
        <BackButton onClick={onBack} className="-ml-2 dark:text-slate-300" />
        <h1 className="text-xl font-bold text-slate-800 dark:text-white tracking-tight">Plan Details</h1>
      </div>

      <div className="p-6 space-y-8">
        <section className="space-y-4">
          <h2 className="text-2xl font-black text-slate-900 dark:text-white leading-tight tracking-tight">{plan.name}</h2>
          <div className="grid grid-cols-2 gap-4">
            <DetailCard label="Goal" value={profile.healthGoal} />
            <DetailCard label="Daily Target" value={`${plan.calories} kcal`} />
            <DetailCard label="Cuisine" value={profile.cuisine} />
            <DetailCard label="Diet" value={profile.dietPreference} />
          </div>
        </section>

        {loading ? (
          <div className="py-12 text-center space-y-4">
            <div className="w-10 h-10 border-4 border-[#39C101] border-t-transparent rounded-full animate-spin mx-auto"></div>
            <p className="text-[10px] font-black text-[#A5B3C1] uppercase tracking-widest">Decoding Metabolic Logic...</p>
          </div>
        ) : (
          <div className="space-y-8">
            <LogicSection title="Nutrient Timing" content={reasoning?.nutrientTiming || ""} />
            <LogicSection title="Micronutrient Focus" content={reasoning?.micronutrientFocus || ""} />
            <LogicSection title="Food Synergy" content={reasoning?.foodSynergyTips || ""} />

            <div className="p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border border-slate-100 dark:border-slate-700">
              <h4 className="text-[10px] font-black text-[#A5B3C1] uppercase tracking-[0.2em] mb-4">Restrictions & Allergies</h4>
              <div className="flex flex-wrap gap-2">
                {profile.allergies.length > 0 ? profile.allergies.filter(a => a !== 'None').map(a => (
                  <span key={a} className="px-3 py-1.5 bg-red-50 dark:bg-red-950/20 text-red-500 text-[10px] font-black uppercase tracking-widest rounded-full">{a}</span>
                )) : <span className="text-[10px] font-bold text-slate-400">No restrictions identified</span>}
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Action Buttons */}
      <div className="fixed bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-white via-white dark:from-slate-900 dark:via-slate-900 to-transparent z-30 flex flex-col gap-3">
        <Button 
          onClick={() => onSelect?.(plan)} 
          className="w-full h-16 rounded-[24px] text-[12px] font-black uppercase tracking-widest shadow-2xl shadow-green-500/20"
        >
          Start Meal Plan
        </Button>
        <button 
          onClick={onBack}
          className="w-full py-2 text-[11px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest hover:text-slate-600 dark:hover:text-slate-300 transition-colors"
        >
          Skip & Go Back
        </button>
      </div>
    </div>
  );
};

