                    <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path d="M9 2a1 1 0 000 2h2a1 1 0 100-2H9z" /><path fillRule="evenodd" d="M4 5a2 2 0 012-2 3 3 0 003 3h2a3 3 0 003-3 2 2 0 012 2v11a2 2 0 01-2 2H6a2 2 0 01-2-2V5zm3 4a1 1 0 000 2h.01a1 1 0 100-2H7zm3 0a1 1 0 000 2h3a1 1 0 100-2h-3zm-3 4a1 1 0 100 2h.01a1 1 0 100-2H7zm3 0a1 1 0 100 2h3a1 1 0 100-2h-3z" clipRule="evenodd" /></svg>
                  </div>
                  <div className="text-left">
                    <span className="block font-black text-slate-900 dark:text-white uppercase text-sm">Select from My Plan</span>
                    <span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest">Follow your metabolic blueprint</span>
                  </div>
                </div>
                <svg className="w-5 h-5 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7"/></svg>
              </button>

              <button 
                onClick={() => fileInputRef.current?.click()}
                className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 transition-all"
              >
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-[#39C101]/10 rounded-2xl flex items-center justify-center text-[#39C101]">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                  </div>
                  <div className="text-left">
                    <span className="block font-black text-slate-900 dark:text-white uppercase text-sm">Upload Food Photo</span>
                    <span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest">Instant AI Food Recognition</span>
                  </div>
                </div>
                <svg className="w-5 h-5 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7"/></svg>
              </button>

              <button 
                onClick={() => galleryInputRef.current?.click()}
                className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 transition-all"
              >
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-[#39C101]/10 rounded-2xl flex items-center justify-center text-[#39C101]">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h14a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                  </div>
                  <div className="text-left">
                    <span className="block font-black text-slate-900 dark:text-white uppercase text-sm">Choose from Gallery</span>
                    <span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest">Analyze past culinary captures</span>
                  </div>
                </div>
                <svg className="w-5 h-5 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7"/></svg>
              </button>
            </div>

            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" capture="environment" onChange={e => handleImageInput(e, showLoggingOptions)}/>
            <input type="file" ref={galleryInputRef} className="hidden" accept="image/*" onChange={e => handleImageInput(e, showLoggingOptions)}/>
          </div>
        </div>
      )}

      {/* Analyzing Loader Overlay */}
      {isAnalyzingFood && (
        <div className="fixed inset-0 bg-white/95 dark:bg-slate-950/95 z-[150] flex flex-col items-center justify-center p-12 text-center">
          <div className="relative w-32 h-32 mb-8">
            <div className="absolute inset-0 border-4 border-slate-100 dark:border-slate-800 rounded-full"></div>
            <div className="absolute inset-0 border-4 border-[#39C101] rounded-full border-t-transparent animate-spin"></div>
            <div className="absolute inset-4 bg-[#39C101]/5 rounded-full flex items-center justify-center animate-pulse">
              <svg className="w-10 h-10 text-[#39C101]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            </div>
          </div>
          <h2 className="text-2xl font-black text-slate-900 dark:text-white mb-2 tracking-tight uppercase">AI Vision Forge</h2>
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.25em] max-w-xs leading-relaxed italic animate-pulse">
            Deconstructing ingredients & nutritional density...
          </p>
        </div>
      )}

      {/* Detection Preview Modal */}
      {showDetectionPreview && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-[130] flex flex-col items-center justify-center p-6">
          <div className="bg-white dark:bg-slate-900 rounded-[48px] w-full max-w-md overflow-hidden flex flex-col shadow-2xl h-[85%]">
            <div className="h-64 relative shrink-0">
              {tempPhoto && <img src={tempPhoto} className="w-full h-full object-cover" />}
              <div className="absolute inset-0 bg-gradient-to-t from-slate-900/80 via-transparent to-transparent"></div>
              <button onClick={() => { setShowDetectionPreview(null); setTempPhoto(null); }} className="absolute top-6 right-6 p-3 bg-white/20 backdrop-blur-md rounded-full text-white">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
              <div className="absolute bottom-6 left-6 right-6">
                <span className="text-[10px] font-black text-green-400 uppercase tracking-widest block mb-1">Detected Profile</span>
                <h4 className="text-xl font-black text-white uppercase tracking-tight leading-none">AI Insight Preview</h4>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-8 no-scrollbar">
              <div className="space-y-4">
                <div className="flex justify-between items-center px-1">
                  <h5 className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Detected Foods</h5>
                  <button onClick={() => setDetectedItems([...detectedItems, { name: 'New Item', calories: 100, protein: 10, carbs: 10, fat: 5 }])} className="text-[10px] font-black text-[#39C101] uppercase tracking-widest">+ Add Item</button>
                </div>

                <div className="space-y-3">
                  {detectedItems.length === 0 ? (
                    <p className="text-center py-8 text-slate-400 text-[11px] font-bold uppercase italic tracking-widest">No items detected. Try manually adding.</p>
                  ) : detectedItems.map((item, idx) => (
                    <div key={idx} className="bg-slate-50 dark:bg-slate-800 p-5 rounded-[28px] border border-slate-100 dark:border-slate-700 space-y-4">
                      <div className="flex justify-between items-start gap-4">
                        <input 
                          value={item.name} 
                          onChange={e => updateDetectedItem(idx, 'name', e.target.value)}
                          className="flex-1 bg-transparent border-none p-0 text-sm font-black text-slate-900 dark:text-white focus:ring-0 uppercase tracking-tight"
                        />
                        <button onClick={() => removeDetectedItem(idx)} className="text-red-400">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                      </div>
                      <div className="grid grid-cols-4 gap-2">
                        <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase">Kcal</span><input type="number" value={item.calories} onChange={e => updateDetectedItem(idx, 'calories', e.target.value)} className="text-[11px] font-black bg-transparent border-none p-0 focus:ring-0 text-slate-800 dark:text-white" /></div>
                        <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase">Pro</span><input type="number" value={item.protein} onChange={e => updateDetectedItem(idx, 'protein', e.target.value)} className="text-[11px] font-black bg-transparent border-none p-0 focus:ring-0 text-slate-800 dark:text-white" /></div>
                        <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase">Carb</span><input type="number" value={item.carbs} onChange={e => updateDetectedItem(idx, 'carbs', e.target.value)} className="text-[11px] font-black bg-transparent border-none p-0 focus:ring-0 text-slate-800 dark:text-white" /></div>
                        <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase">Fat</span><input type="number" value={item.fat} onChange={e => updateDetectedItem(idx, 'fat', e.target.value)} className="text-[11px] font-black bg-transparent border-none p-0 focus:ring-0 text-slate-800 dark:text-white" /></div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="p-8 bg-[#39C101]/5 rounded-[32px] border-2 border-dashed border-[#39C101]/20 text-center">
                 <span className="text-[10px] font-black text-[#39C101] uppercase tracking-[0.3em] block mb-2">Total Energy Forge</span>
                 <span className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">{detectedItems.reduce((s, i) => s + i.calories, 0)} kcal</span>
              </div>
            </div>

            <div className="p-8 pt-0">
               <Button 
                onClick={() => handleLogManual(showDetectionPreview.id, detectedItems)}
                className="w-full h-16 rounded-[24px] text-white shadow-2xl shadow-[#39C101]/30 text-[12px] font-black uppercase tracking-widest"
               >
                 Log This Meal
               </Button>
            </div>
          </div>
        </div>
      )}

      {/* Existing Recipe Modal */}
      {selectedMealForRecipe && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[110] flex flex-col justify-end">
          {/* ... (Existing recipe modal code) */}
        </div>
      )}

      {/* Existing Log Modal removed - replaced by new flow */}
    </div>
  );
};

