                  className={`flex-1 py-4 px-4 rounded-[20px] text-[12px] font-black uppercase tracking-widest transition-all active:scale-95 shadow-xl ${meal.isLogged ? 'bg-slate-200 text-slate-500 shadow-none' : 'bg-[#39C101] text-white shadow-[#39C101]/25 hover:bg-[#32aa01]'}`}
