            </div>
          ))}
        </div>
      </div>

      {/* Enhanced Logging Options Bottom Sheet */}
      {showLoggingOptions && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[110] flex flex-col justify-end" onClick={() => setShowLoggingOptions(null)}>
