            <div className="h-64 relative shrink-0">
              {tempPhoto && <img src={tempPhoto} className="w-full h-full object-cover" />}
              <div className="absolute inset-0 bg-gradient-to-t from-slate-900/80 via-transparent to-transparent"></div>
              <button onClick={() => { setShowDetectionPreview(null); setTempPhoto(null); }} className="absolute top-6 right-6 p-3 bg-white/20 backdrop-blur-md rounded-full text-white">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
              <div className="absolute bottom-6 left-8 right-8">
                <span className="text-[10px] font-black text-green-400 uppercase tracking-widest block mb-1">Detected Profile</span>
                <h4 className="text-xl font-black text-white uppercase tracking-tight leading-none">{showDetectionPreview.isManual ? 'Edit Metabolic Log' : 'AI Insight Preview'}</h4>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-8 no-scrollbar">
              <div className="space-y-4">
                <div className="flex justify-between items-center px-1">
                  <h5 className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Logged Time</h5>
                  <input 
                    type="time" 
                    value={logTime} 
                    onChange={e => setLogTime(e.target.value)}
                    className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl text-xs font-black text-[#39C101] uppercase p-2 focus:ring-2 focus:ring-[#39C101]"
                  />
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex justify-between items-center px-1">
                  <h5 className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Food Items & Portions</h5>
                  <button onClick={() => setDetectedItems([...detectedItems, { name: 'New Item', calories: 100, protein: 10, carbs: 10, fat: 5 }])} className="text-[10px] font-black text-[#39C101] uppercase tracking-widest">+ Add Item</button>
                </div>

                <div className="space-y-3">
                  {detectedItems.map((item, idx) => (
                    <div key={idx} className="bg-slate-50 dark:bg-slate-800 p-5 rounded-[28px] border border-slate-100 dark:border-slate-700 space-y-4">
                      <div className="flex justify-between items-start gap-4">
                        <input 
                          value={item.name} 
                          onChange={e => updateDetectedItem(idx, 'name', e.target.value)}
                          className="flex-1 bg-transparent border-none p-0 text-sm font-black text-slate-900 dark:text-white focus:ring-0 uppercase tracking-tight"
                          placeholder="Food Name"
                        />
                        <button onClick={() => removeDetectedItem(idx)} className="text-red-400 p-1">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                      </div>
                      <div className="grid grid-cols-4 gap-2">
                        <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">Kcal</span><input type="number" value={item.calories} onChange={e => updateDetectedItem(idx, 'calories', e.target.value)} className="text-[11px] font-black bg-transparent border-none p-0 focus:ring-0 text-slate-800 dark:text-white" /></div>
                        <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">Pro</span><input type="number" value={item.protein} onChange={e => updateDetectedItem(idx, 'protein', e.target.value)} className="text-[11px] font-black bg-transparent border-none p-0 focus:ring-0 text-slate-800 dark:text-white" /></div>
                        <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">Carb</span><input type="number" value={item.carbs} onChange={e => updateDetectedItem(idx, 'carbs', e.target.value)} className="text-[11px] font-black bg-transparent border-none p-0 focus:ring-0 text-slate-800 dark:text-white" /></div>
                        <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">Fat</span><input type="number" value={item.fat} onChange={e => updateDetectedItem(idx, 'fat', e.target.value)} className="text-[11px] font-black bg-transparent border-none p-0 focus:ring-0 text-slate-800 dark:text-white" /></div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="p-8 bg-[#39C101]/5 rounded-[32px] border-2 border-dashed border-[#39C101]/20 text-center">
                 <span className="text-[10px] font-black text-[#39C101] uppercase tracking-[0.3em] block mb-2">Total Energy Forge</span>
                 <span className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">{detectedItems.reduce((s, i) => s + i.calories, 0)} kcal</span>
              </div>
            </div>

            <div className="p-8 pt-0">
               <Button 
                onClick={() => handleLogManual(showDetectionPreview.id, detectedItems)}
                className="w-full h-16 rounded-[24px] text-white shadow-2xl shadow-[#39C101]/30 text-[12px] font-black uppercase tracking-widest"
               >
                 {showDetectionPreview.isManual ? 'Update Log' : 'Log This Meal'}
               </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useEffect, useState, useRef } from 'react';
import { Card, Button } from '../components/UI';
import { Meal, MealPlan, ApiRecipe, DetectedFoodItem } from '../types';
import { fetchApiRecipes } from '../services/recipeService';
import { analyzeFoodImage } from '../services/geminiService';

interface FreeModeProps {
  onBack: () => void;
  meals?: Meal[];
  setMeals?: React.Dispatch<React.SetStateAction<Meal[]>>;
  plan?: MealPlan | null;
  onExplore: () => void;
  onViewGrocery: () => void;
}

const FreeMode: React.FC<FreeModeProps> = ({ onBack, meals = [], setMeals, plan, onExplore, onViewGrocery }) => {
  const [trendingRecipes, setTrendingRecipes] = useState<ApiRecipe[]>([]);
  const [loadingRecipes, setLoadingRecipes] = useState(false);

  // Logging flow states
  const [showLoggingOptions, setShowLoggingOptions] = useState<Meal | null>(null);
  const [isAnalyzingFood, setIsAnalyzingFood] = useState(false);
  const [detectedItems, setDetectedItems] = useState<DetectedFoodItem[]>([]);
  const [logTime, setLogTime] = useState<string>(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
  const [showDetectionPreview, setShowDetectionPreview] = useState<Meal | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const loadRecipes = async () => {
      setLoadingRecipes(true);
      const result = await fetchApiRecipes({ limit: 6 });
      if (result && result.data) {
        setTrendingRecipes(result.data);
      }
      setLoadingRecipes(false);
    };
    loadRecipes();
  }, []);

  const handleLogFromPlan = (mealId: string) => {
    if (!setMeals) return;
    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: true,
      isManual: false,
      loggedAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
      manualItems: undefined
    } : m));
    setShowLoggingOptions(null);
  };

  const handleLogManual = (mealId: string, finalItems: DetectedFoodItem[]) => {
    if (!setMeals) return;
    const totalCals = finalItems.reduce((s, i) => s + i.calories, 0);
    const totalPro = finalItems.reduce((s, i) => s + i.protein, 0);
    const totalCarb = finalItems.reduce((s, i) => s + i.carbs, 0);
    const totalFat = finalItems.reduce((s, i) => s + i.fat, 0);

    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: true, 
      isManual: true,
      calories: totalCals,
      protein: totalPro,
      carbs: totalCarb,
      fat: totalFat,
      photoUri: tempPhoto || m.photoUri,
      loggedAt: logTime,
      manualItems: finalItems,
      name: finalItems.length > 0 ? finalItems.map(i => i.name).join(", ") : m.name
    } : m));

    setShowDetectionPreview(null);
    setShowLoggingOptions(null);
    setTempPhoto(null);
    setDetectedItems([]);
  };

  const handleEditManual = (meal: Meal) => {
    const itemsToEdit = meal.manualItems && meal.manualItems.length > 0 
      ? [...meal.manualItems] 
      : [{ name: meal.name, calories: meal.calories, protein: meal.protein, carbs: meal.carbs, fat: meal.fat }];

    setDetectedItems(itemsToEdit);
    setTempPhoto(meal.photoUri || null);
    setLogTime(meal.loggedAt || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
    setShowDetectionPreview(meal);
    setShowLoggingOptions(null);
  };

  const handleImageInput = async (e: React.ChangeEvent<HTMLInputElement>, meal: Meal) => {
    const file = e.target.files?.[0];
    if (file) {
      setShowLoggingOptions(null);
      setIsAnalyzingFood(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setTempPhoto(base64);
        try {
          const items = await analyzeFoodImage(base64);
          setDetectedItems(items);
          setLogTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
        } catch (err) {
          console.error("Analysis error:", err);
        } finally {
          setIsAnalyzingFood(false);
          setShowDetectionPreview(meal);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const updateDetectedItem = (index: number, field: keyof DetectedFoodItem, value: any) => {
    setDetectedItems(prev => {
      const copy = [...prev];
      copy[index] = { ...copy[index], [field]: field === 'name' ? value : Number(value) };
      return copy;
    });
  };

  const removeDetectedItem = (index: number) => {
    setDetectedItems(prev => prev.filter((_, i) => i !== index));
  };

  return (
    <div className="flex-1 flex flex-col bg-[#F9FBFC] dark:bg-slate-950 overflow-hidden relative transition-colors duration-500">
      <div className="p-6 pt-2 flex items-center gap-4 bg-white dark:bg-slate-900 border-b border-slate-50 dark:border-slate-800 z-10 transition-colors">
        <button onClick={onBack} className="p-2.5 bg-slate-50 dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-slate-700 transition-colors">
           <svg className="w-5 h-5 text-slate-600 dark:text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7"></path></svg>
        </button>
        <h1 className="text-xl font-black text-slate-800 dark:text-white tracking-tight leading-none">NutriForge Labs</h1>
      </div>

      <div className="flex-1 overflow-y-auto pb-32 no-scrollbar">
        <div className="px-6 py-8">
          <div className="bg-[#39C101] rounded-[40px] p-8 text-white relative overflow-hidden shadow-2xl shadow-[#39C101]/30 group active:scale-[0.98] transition-all cursor-pointer">
            <div className="relative z-10">
              <span className="block text-[10px] font-black uppercase tracking-[0.3em] opacity-80 mb-2">Experimental Forge</span>
              <h3 className="text-2xl font-black leading-none tracking-tight mb-2">AI Recipe Labs</h3>
              <p className="text-[12px] text-green-50 mb-6 font-bold leading-relaxed opacity-90 max-w-[200px]">Craft unique meals & analyze metabolic impact instantly.</p>
              <Button variant="secondary" className="w-full bg-white text-[#39C101] hover:bg-green-50 border-none h-14 py-0 text-[11px] font-black uppercase tracking-widest shadow-xl">Open Labs</Button>
            </div>
            <div className="absolute top-0 right-0 w-48 h-48 bg-white/10 rounded-full -mr-24 -mt-24 group-hover:scale-110 transition-transform duration-700"></div>
          </div>
        </div>

        {meals && meals.length > 0 && (
          <div className="px-6 space-y-6 mb-12">
            <h3 className="text-[12px] font-black text-[#A5B3C1] uppercase tracking-[0.2em] mb-4 pl-1">Today's Active Forge</h3>
            {meals.map(meal => (
              <div key={meal.id} className="bg-white dark:bg-slate-800 rounded-[40px] p-7 shadow-sm border border-slate-50 dark:border-slate-700 relative group overflow-hidden transition-all hover:shadow-xl hover:shadow-slate-200/50">
                <button 
                  onClick={() => {
                    if (meal.isLogged && meal.isManual) {
                      handleEditManual(meal);
                    } else if (!meal.isLogged) {
                      setShowLoggingOptions(meal);
                    }
                  }}
                  className={`absolute top-7 right-7 w-12 h-12 rounded-full border-2 flex items-center justify-center transition-all ${meal.isLogged ? 'bg-[#39C101] border-[#39C101] shadow-xl shadow-[#39C101]/30' : 'bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 shadow-sm'}`}
                >
                  {meal.isLogged ? (
                    <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>
                  ) : (
                    <svg className="w-6 h-6 text-[#39C101]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"></path></svg>
                  )}
                </button>
                <div className="flex flex-col gap-1.5 pr-16">
                  <div className="flex items-center gap-2">
                    <span className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-[0.2em]">{meal.type}</span>
                    {meal.isLogged && meal.isManual && (
                      <span className="text-[9px] font-black text-white bg-[#39C101] px-2 py-0.5 rounded-full uppercase tracking-widest shadow-sm shadow-[#39C101]/30">Logged manually</span>
                    )}
                    {meal.loggedAt && (
                      <span className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest ml-1">{meal.loggedAt}</span>
                    )}
                  </div>
                  <h4 className="text-xl font-black text-slate-900 dark:text-white leading-tight tracking-tight">{meal.name}</h4>
                  <span className="text-xs font-bold text-[#A5B3C1]">{meal.calories} kcal</span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {showLoggingOptions && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[110] flex flex-col justify-end" onClick={() => setShowLoggingOptions(null)}>
          <div className="bg-white dark:bg-slate-900 rounded-t-[48px] p-10 animate-in slide-in-from-bottom duration-500 shadow-2xl" onClick={e => e.stopPropagation()}>
            <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mx-auto mb-8"></div>
            <div className="flex justify-between items-center mb-10">
              <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight leading-none uppercase">Log {showLoggingOptions.type}</h3>
              <button onClick={() => setShowLoggingOptions(null)} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full hover:bg-slate-200 transition-colors">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            <div className="space-y-4">
              <button onClick={() => handleLogFromPlan(showLoggingOptions.id)} className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 transition-all active:scale-95">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-[#39C101]/10 rounded-2xl flex items-center justify-center text-[#39C101]"><svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path d="M9 2a1 1 0 000 2h2a1 1 0 100-2H9z" /><path fillRule="evenodd" d="M4 5a2 2 0 012-2 3 3 0 003 3h2a3 3 0 003-3 2 2 0 012 2v11a2 2 0 01-2 2H6a2 2 0 01-2-2V5zm3 4a1 1 0 000 2h.01a1 1 0 100-2H7zm3 0a1 1 0 000 2h3a1 1 0 100-2h-3zm-3 4a1 1 0 100 2h.01a1 1 0 100-2H7zm3 0a1 1 0 100 2h3a1 1 0 100-2h-3z" clipRule="evenodd" /></svg></div>
                  <div className="text-left"><span className="block font-black text-slate-900 dark:text-white uppercase text-sm tracking-tight">Select from My Plan</span><span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest leading-none">Standard metabolic entry</span></div>
                </div>
              </button>
              <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 transition-all active:scale-95">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-[#39C101]/10 rounded-2xl flex items-center justify-center text-[#39C101]"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg></div>
                  <div className="text-left"><span className="block font-black text-slate-900 dark:text-white uppercase text-sm tracking-tight">Upload Food Photo</span><span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest leading-none">Instant AI Vision Forge</span></div>
                </div>
              </button>
              <button onClick={() => galleryInputRef.current?.click()} className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 transition-all active:scale-95">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-[#39C101]/10 rounded-2xl flex items-center justify-center text-[#39C101]"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h14a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></div>
                  <div className="text-left"><span className="block font-black text-slate-900 dark:text-white uppercase text-sm tracking-tight">Choose from Gallery</span><span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest leading-none">Analyze past capture</span></div>
                </div>
              </button>
            </div>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" capture="environment" onChange={e => handleImageInput(e, showLoggingOptions!)}/>
            <input type="file" ref={galleryInputRef} className="hidden" accept="image/*" onChange={e => handleImageInput(e, showLoggingOptions!)}/>
          </div>
        </div>
      )}

      {isAnalyzingFood && (
        <div className="fixed inset-0 bg-white/95 dark:bg-slate-950/95 z-[150] flex flex-col items-center justify-center p-12 text-center animate-in fade-in duration-500">
          <div className="w-16 h-16 border-4 border-[#39C101] border-t-transparent rounded-full animate-spin mb-6"></div>
          <h2 className="text-xl font-black text-slate-900 dark:text-white uppercase tracking-tight">AI Analysis</h2>
        </div>
      )}

      {showDetectionPreview && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-[130] flex flex-col items-center justify-center p-6">
          <div className="bg-white dark:bg-slate-900 rounded-[48px] w-full max-w-md overflow-hidden flex flex-col shadow-2xl h-[85%] animate-in zoom-in-95 duration-300">
            <div className="h-48 relative shrink-0">
              {tempPhoto && <img src={tempPhoto} className="w-full h-full object-cover" />}
              <button onClick={() => { setShowDetectionPreview(null); setTempPhoto(null); }} className="absolute top-6 right-6 p-2 bg-black/20 rounded-full text-white"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg></button>
            </div>
            <div className="flex-1 overflow-y-auto p-8 space-y-6 no-scrollbar">
               <div className="flex justify-between items-center px-1 mb-4">
                  <h5 className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Logged Time</h5>
                  <input type="time" value={logTime} onChange={e => setLogTime(e.target.value)} className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl text-xs font-black text-[#39C101] uppercase p-2 focus:ring-2 focus:ring-[#39C101]" />
               </div>
               <h4 className="text-xl font-black text-slate-900 dark:text-white uppercase">{showDetectionPreview.isManual ? 'Edit Detected Foods' : 'Detected Foods'}</h4>
               <div className="space-y-3">
                  {detectedItems.map((item, idx) => (
                    <div key={idx} className="bg-slate-50 dark:bg-slate-800 p-4 rounded-3xl border border-slate-100 dark:border-slate-700">
                      <input value={item.name} onChange={e => updateDetectedItem(idx, 'name', e.target.value)} className="w-full bg-transparent border-none p-0 text-sm font-black uppercase mb-2 focus:ring-0" />
                      <div className="grid grid-cols-4 gap-2 text-[10px] font-bold uppercase text-slate-400">
                        <div>Kcal<input type="number" value={item.calories} onChange={e => updateDetectedItem(idx, 'calories', e.target.value)} className="w-full bg-transparent border-none p-0 text-xs font-black text-slate-800 dark:text-white focus:ring-0" /></div>
                        <div>Pro<input type="number" value={item.protein} onChange={e => updateDetectedItem(idx, 'protein', e.target.value)} className="w-full bg-transparent border-none p-0 text-xs font-black text-slate-800 dark:text-white focus:ring-0" /></div>
                        <div>Carb<input type="number" value={item.carbs} onChange={e => updateDetectedItem(idx, 'carbs', e.target.value)} className="w-full bg-transparent border-none p-0 text-xs font-black text-slate-800 dark:text-white focus:ring-0" /></div>
                        <div>Fat<input type="number" value={item.fat} onChange={e => updateDetectedItem(idx, 'fat', e.target.value)} className="w-full bg-transparent border-none p-0 text-xs font-black text-slate-800 dark:text-white focus:ring-0" /></div>
                      </div>
                    </div>
                  ))}
               </div>
            </div>
            <div className="p-8"><Button onClick={() => handleLogManual(showDetectionPreview.id, detectedItems)} className="w-full h-16 rounded-[24px] uppercase font-black text-sm tracking-widest">{showDetectionPreview.isManual ? 'Update Log' : 'Log This Meal'}</Button></div>
          </div>
        </div>
      )}
    </div>
  );
};

export default FreeMode;

import React, { useState, useMemo, useRef } from 'react';
import { UserProfile, MealPlan, Meal, MealAlternative, GamificationState, Recipe, DetectedFoodItem } from '../types';
import { Card, Button, BackButton } from '../components/UI';
import { generateMealAlternatives, generateRecipe, analyzeFoodImage } from '../services/geminiService';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  meals: Meal[];
  setMeals: React.Dispatch<React.SetStateAction<Meal[]>>;
  onExit: () => void;
  onViewInsights: () => void;
  onExplore: () => void;
  onViewGrocery: () => void;
  onViewPlanDetails: () => void;
  onEditPlan: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, meals, setMeals, onExit, onViewInsights, onExplore, onViewGrocery, onViewPlanDetails, onEditPlan }) => {
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [selectedMealForRecipe, setSelectedMealForRecipe] = useState<Meal | null>(null);
  const [recipeData, setRecipeData] = useState<Recipe | null>(null);
  const [loadingRecipe, setLoadingRecipe] = useState(false);
  const [loadingAlts, setLoadingAlts] = useState(false);

  // Logging flow states
  const [showLoggingOptions, setShowLoggingOptions] = useState<Meal | null>(null);
  const [isAnalyzingFood, setIsAnalyzingFood] = useState(false);
  const [detectedItems, setDetectedItems] = useState<DetectedFoodItem[]>([]);
  const [logTime, setLogTime] = useState<string>(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
  const [showDetectionPreview, setShowDetectionPreview] = useState<Meal | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);

  const [gamification] = useState<GamificationState>({
    points: 1240,
    streak: 4,
    badges: [{ id: 'sync', name: 'Sync King', icon: '⌚', description: 'Connected a wearable device' }]
  });

  const weekDays = useMemo(() => {
    const today = new Date();
    const days = [];
    const start = new Date(today);
    start.setDate(today.getDate() - 3);

    for (let i = 0; i < 7; i++) {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      days.push({
        label: d.toLocaleDateString('en-US', { weekday: 'narrow' }),
        date: d.getDate(),
        isToday: d.toDateString() === today.toDateString(),
      });
    }
    return days;
  }, []);

  const totalConsumed = meals.reduce((sum, m) => m.isLogged ? sum + m.calories : sum, 0);
  const targetCals = plan.calories;
  const progressPercent = targetCals > 0 ? Math.round((totalConsumed / targetCals) * 100) : 0;

  const handleLogFromPlan = (mealId: string) => {
    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: true,
      isManual: false,
      loggedAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
      manualItems: undefined
    } : m));
    setShowLoggingOptions(null);
  };

  const handleLogManual = (mealId: string, finalItems: DetectedFoodItem[]) => {
    const totalCals = finalItems.reduce((s, i) => s + i.calories, 0);
    const totalPro = finalItems.reduce((s, i) => s + i.protein, 0);
    const totalCarb = finalItems.reduce((s, i) => s + i.carbs, 0);
    const totalFat = finalItems.reduce((s, i) => s + i.fat, 0);

    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: true, 
      isManual: true,
      calories: totalCals,
      protein: totalPro,
      carbs: totalCarb,
      fat: totalFat,
      photoUri: tempPhoto || m.photoUri,
      loggedAt: logTime,
      manualItems: finalItems,
      name: finalItems.length > 0 ? finalItems.map(i => i.name).join(", ") : m.name
    } : m));

    setShowDetectionPreview(null);
    setShowLoggingOptions(null);
    setTempPhoto(null);
    setDetectedItems([]);
  };

  const handleEditManual = (meal: Meal) => {
    const itemsToEdit = meal.manualItems && meal.manualItems.length > 0 
      ? [...meal.manualItems] 
      : [{ name: meal.name, calories: meal.calories, protein: meal.protein, carbs: meal.carbs, fat: meal.fat }];

    setDetectedItems(itemsToEdit);
    setTempPhoto(meal.photoUri || null);
    setLogTime(meal.loggedAt || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
    setShowDetectionPreview(meal);
    setShowLoggingOptions(null);
  };

  const handleImageInput = async (e: React.ChangeEvent<HTMLInputElement>, meal: Meal) => {
    const file = e.target.files?.[0];
    if (file) {
      setShowLoggingOptions(null);
      setIsAnalyzingFood(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setTempPhoto(base64);

        try {
          const items = await analyzeFoodImage(base64);
          setDetectedItems(items);
          setLogTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
        } catch (err) {
          console.error("Analysis error:", err);
        } finally {
          setIsAnalyzingFood(false);
          setShowDetectionPreview(meal);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const updateDetectedItem = (index: number, field: keyof DetectedFoodItem, value: any) => {
    setDetectedItems(prev => {
      const copy = [...prev];
      copy[index] = { ...copy[index], [field]: field === 'name' ? value : Number(value) };
      return copy;
    });
  };

  const removeDetectedItem = (index: number) => {
    setDetectedItems(prev => prev.filter((_, i) => i !== index));
  };

  const openAlternative = async (meal: Meal) => {
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setLoadingAlts(false);
  };

  const openRecipe = async (meal: Meal) => {
    setSelectedMealForRecipe(meal);
    if (meal.apiRecipeDetail && (meal.apiRecipeDetail.description || (meal.apiRecipeDetail.instructions && meal.apiRecipeDetail.instructions.length > 0))) {
      setRecipeData({
        ingredients: [],
        instructions: meal.apiRecipeDetail.instructions || [],
        prepTime: meal.apiRecipeDetail.prepTime ? `${meal.apiRecipeDetail.prepTime}m` : '15m',
        cookTime: meal.apiRecipeDetail.cookTime ? `${meal.apiRecipeDetail.cookTime}m` : '15m'
      });
      return;
    }
    setLoadingRecipe(true);
    const recipe = await generateRecipe(meal.name, profile);
    setRecipeData(recipe);
    setLoadingRecipe(false);
  };

  return (
    <div className="flex-1 flex flex-col bg-[#F9FBFC] dark:bg-slate-900 overflow-hidden relative transition-colors duration-500">
      <div className="p-6 pt-2 bg-white dark:bg-slate-800 border-b border-slate-50 dark:border-slate-700 flex justify-between items-center z-10 transition-colors">
        <div className="flex items-center gap-3">
          <BackButton onClick={onExit} className="-ml-2 dark:text-slate-100" />
          <div className="flex flex-col">
            <h2 className="text-xl font-black text-slate-900 dark:text-white tracking-tight leading-none mb-0.5">NutriForge</h2>
            <div className="flex items-center gap-2">
              <span className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-wider">{plan.name}</span>
              <div className="w-1 h-1 bg-slate-200 dark:bg-slate-700 rounded-full"></div>
              <div className="flex items-center gap-1 text-orange-500 font-bold text-[10px] tracking-tight">
                <span>🔥</span> {gamification.streak} Day Streak
              </div>
            </div>
          </div>
        </div>
        <div className="flex flex-col items-end">
          {/* Forge Points count removed as per user request */}
          <span className="text-[10px] text-[#A5B3C1] font-black uppercase tracking-widest leading-none mb-1">Target Energy</span>
          <span className="text-xl font-black text-slate-900 dark:text-white leading-none tracking-tight">{targetCals} kcal</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pb-32 no-scrollbar">
        <div className="px-6 py-4 flex gap-4 overflow-x-auto no-scrollbar bg-white dark:bg-slate-800 border-b border-slate-50 dark:border-slate-700 transition-colors">
          {weekDays.map((day, i) => (
            <div key={i} className={`flex-shrink-0 w-12 h-16 rounded-[20px] flex flex-col items-center justify-center gap-1.5 transition-all ${day.isToday ? 'bg-[#39C101] text-white shadow-lg shadow-[#39C101]/25' : 'text-[#A5B3C1] hover:text-slate-500'}`}>
              <span className="text-[11px] font-black uppercase tracking-tight">{day.label}</span>
              <span className="text-base font-black tracking-tighter">{day.date}</span>
            </div>
          ))}
        </div>

        <div className="px-6 py-6">
          <Card onClick={onViewInsights} className="bg-white dark:bg-slate-800 border-slate-100 shadow-sm relative overflow-hidden p-8 rounded-[32px] group cursor-pointer">
            <div className="flex justify-between items-start mb-8">
              <div className="space-y-1">
                <div className="flex items-center gap-1 group-hover:translate-x-0.5 transition-transform">
                  <span className="text-[11px] text-[#A5B3C1] font-black uppercase tracking-[0.15em]">Daily Energy</span>
                  <svg className="w-3.5 h-3.5 text-[#A5B3C1]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7"></path></svg>
                </div>
                <div className="flex items-baseline gap-2">
                  <span className="text-5xl font-black text-slate-900 dark:text-white tracking-tighter leading-none">{totalConsumed}</span>
                  <span className="text-base text-[#A5B3C1] font-bold">/ {targetCals || '---'} kcal</span>
                </div>
              </div>
              <div className="w-16 h-16 rounded-full border-[5px] border-slate-100 dark:border-slate-700 flex items-center justify-center relative shadow-inner">
                <svg className="w-full h-full absolute inset-0 -rotate-90">
                  <circle cx="32" cy="32" r="27.5" fill="transparent" stroke="currentColor" strokeWidth="5" className="text-slate-50 dark:text-slate-700/50"/>
                  <circle cx="32" cy="32" r="27.5" fill="transparent" stroke="currentColor" strokeWidth="5" className="text-[#39C101]" strokeDasharray="172.7" strokeDashoffset={172.7 - (172.7 * (progressPercent / 100))} strokeLinecap="round" style={{ transition: 'stroke-dashoffset 1s ease-in-out' }} />
                </svg>
                <span className="text-xs font-black text-slate-900 dark:text-white">{progressPercent}%</span>
              </div>
            </div>
            <div className="w-full h-4 bg-slate-50 dark:bg-slate-900/50 rounded-full overflow-hidden relative shadow-inner">
               <div className="h-full bg-slate-900 dark:bg-white rounded-full transition-all duration-1000 ease-out" style={{ width: `${Math.min(progressPercent, 100)}%` }} />
            </div>
            <p className="text-[10px] text-[#A5B3C1] mt-5 font-black uppercase tracking-widest italic opacity-80 text-center">*Tap to view detailed macro forge</p>
          </Card>
          <div className="flex justify-center gap-8 mt-4 px-2">
            <button onClick={onViewPlanDetails} className="text-[11px] font-black text-[#39C101] uppercase tracking-widest hover:opacity-80 transition-opacity">View Plan Details</button>
            <button onClick={onEditPlan} className="text-[11px] font-black text-[#39C101] uppercase tracking-widest hover:opacity-80 transition-opacity">Change Plan</button>
          </div>
        </div>

        <div className="px-6 space-y-6">
          <h3 className="text-[12px] font-black text-[#A5B3C1] uppercase tracking-[0.2em] mb-4 pl-1">Today's Meals</h3>
          {meals.map(meal => (
            <div key={meal.id} className="bg-white dark:bg-slate-800 rounded-[40px] p-7 shadow-sm border border-slate-50 dark:border-slate-700 relative group overflow-hidden transition-all hover:shadow-xl hover:shadow-slate-200/50">
              <button 
                onClick={() => {
                  if (meal.isLogged && meal.isManual) {
                    handleEditManual(meal);
                  } else if (!meal.isLogged) {
                    setShowLoggingOptions(meal);
                  }
                }}
                className={`absolute top-7 right-7 w-12 h-12 rounded-full border-2 flex items-center justify-center transition-all ${meal.isLogged ? 'bg-[#39C101] border-[#39C101] shadow-xl shadow-[#39C101]/30' : 'bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 shadow-sm'}`}
              >
                {meal.isLogged ? (
                  <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>
                ) : (
                  <svg className="w-6 h-6 text-[#39C101]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"></path></svg>
                )}
              </button>

              <div className="flex flex-col gap-1.5 mb-8 pr-16">
                <div className="flex items-center gap-2">
                  <span className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-[0.2em]">{meal.type}</span>
                  {meal.isLogged && meal.isManual && (
                    <span className="text-[9px] font-black text-white bg-[#39C101] px-2 py-0.5 rounded-full uppercase tracking-widest shadow-sm shadow-[#39C101]/30">Logged manually</span>
                  )}
                  {meal.loggedAt && (
                    <span className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest ml-1">{meal.loggedAt}</span>
                  )}
                </div>
                <h4 className="text-xl font-black text-slate-900 dark:text-white leading-tight tracking-tight">{meal.name}</h4>
                <span className="text-xs font-bold text-[#A5B3C1]">{meal.calories} kcal</span>
              </div>

              <div className="flex gap-4">
                <button onClick={() => openRecipe(meal)} className="flex-1 py-4 px-4 rounded-[20px] border-2 border-[#E9EEF2] dark:border-slate-700 text-[12px] font-black text-[#39C101] uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-all active:scale-95 shadow-sm bg-white dark:bg-slate-800">Recipe</button>
                <button onClick={() => openAlternative(meal)} className="flex-1 py-4 px-4 rounded-[20px] border-2 border-[#E9EEF2] dark:border-slate-700 text-[12px] font-black text-[#39C101] uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-all active:scale-95 shadow-sm bg-white dark:bg-slate-800">Swap</button>
                <button 
                  onClick={() => {
                    if (meal.isLogged && meal.isManual) {
                      handleEditManual(meal);
                    } else if (!meal.isLogged) {
                      setShowLoggingOptions(meal);
                    }
                  }}
                  className={`flex-1 py-4 px-4 rounded-[20px] text-[12px] font-black uppercase tracking-widest transition-all active:scale-95 shadow-xl ${meal.isLogged && !meal.isManual ? 'bg-slate-200 text-slate-500 shadow-none cursor-not-allowed' : 'bg-[#39C101] text-white shadow-[#39C101]/25 hover:bg-[#32aa01]'}`}
                >
                  {meal.isLogged ? (meal.isManual ? 'Edit Log' : 'Logged') : 'Log'}
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {showLoggingOptions && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[110] flex flex-col justify-end" onClick={() => setShowLoggingOptions(null)}>
          <div className="bg-white dark:bg-slate-900 rounded-t-[48px] p-10 animate-in slide-in-from-bottom duration-500 shadow-2xl" onClick={e => e.stopPropagation()}>
            <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mx-auto mb-8"></div>
            <div className="flex justify-between items-center mb-10">
              <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight leading-none uppercase">Log {showLoggingOptions.type}</h3>
              <button onClick={() => setShowLoggingOptions(null)} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full hover:bg-slate-200 transition-colors">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            <div className="space-y-4">
              <button onClick={() => handleLogFromPlan(showLoggingOptions.id)} className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 transition-all active:scale-95">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-[#39C101]/10 rounded-2xl flex items-center justify-center text-[#39C101]"><svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path d="M9 2a1 1 0 000 2h2a1 1 0 100-2H9z" /><path fillRule="evenodd" d="M4 5a2 2 0 012-2 3 3 0 003 3h2a3 3 0 003-3 2 2 0 012 2v11a2 2 0 01-2 2H6a2 2 0 01-2-2V5zm3 4a1 1 0 000 2h.01a1 1 0 100-2H7zm3 0a1 1 0 000 2h3a1 1 0 100-2h-3zm-3 4a1 1 0 100 2h.01a1 1 0 100-2H7zm3 0a1 1 0 100 2h3a1 1 0 100-2h-3z" clipRule="evenodd" /></svg></div>
                  <div className="text-left">
                    <span className="block font-black text-slate-900 dark:text-white uppercase text-sm tracking-tight">Select from My Plan</span>
                    <span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest leading-none">Standard metabolic entry</span>
                  </div>
                </div>
              </button>
              <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 transition-all active:scale-95">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-[#39C101]/10 rounded-2xl flex items-center justify-center text-[#39C101]"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg></div>
                  <div className="text-left">
                    <span className="block font-black text-slate-900 dark:text-white uppercase text-sm tracking-tight">Upload Food Photo</span>
                    <span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest leading-none">Instant AI Vision Forge</span>
                  </div>
                </div>
              </button>
              <button onClick={() => galleryInputRef.current?.click()} className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 transition-all active:scale-95">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-[#39C101]/10 rounded-2xl flex items-center justify-center text-[#39C101]"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h14a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></div>
                  <div className="text-left">
                    <span className="block font-black text-slate-900 dark:text-white uppercase text-sm tracking-tight">Choose from Gallery</span>
                    <span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest leading-none">Analyze past capture</span>
                  </div>
                </div>
              </button>
            </div>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" capture="environment" onChange={e => handleImageInput(e, showLoggingOptions!)}/>
            <input type="file" ref={galleryInputRef} className="hidden" accept="image/*" onChange={e => handleImageInput(e, showLoggingOptions!)}/>
          </div>
        </div>
      )}

      {isAnalyzingFood && (
        <div className="fixed inset-0 bg-white/95 dark:bg-slate-950/95 z-[150] flex flex-col items-center justify-center p-12 text-center animate-in fade-in duration-500">
          <div className="w-16 h-16 border-4 border-[#39C101] border-t-transparent rounded-full animate-spin mb-6"></div>
          <h2 className="text-2xl font-black text-slate-900 dark:text-white mb-2 tracking-tight uppercase">AI Vision Forge</h2>
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.25em] max-w-xs leading-relaxed italic animate-pulse">Deconstructing metabolic density...</p>
        </div>
      )}

      {showDetectionPreview && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-[130] flex flex-col items-center justify-center p-6">
          <div className="bg-white dark:bg-slate-900 rounded-[48px] w-full max-w-md overflow-hidden flex flex-col shadow-2xl h-[85%] animate-in zoom-in-95 duration-300">
            <div className="h-64 relative shrink-0">
              {tempPhoto && <img src={tempPhoto} className="w-full h-full object-cover" />}
              <div className="absolute inset-0 bg-gradient-to-t from-slate-900/80 via-transparent to-transparent"></div>
              <button onClick={() => { setShowDetectionPreview(null); setTempPhoto(null); }} className="absolute top-6 right-6 p-3 bg-white/20 backdrop-blur-md rounded-full text-white">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
              <div className="absolute bottom-6 left-8 right-8">
                <span className="text-[10px] font-black text-green-400 uppercase tracking-widest block mb-1">Detected Profile</span>
                <h4 className="text-xl font-black text-white uppercase tracking-tight leading-none">{showDetectionPreview.isManual ? 'Edit Metabolic Log' : 'AI Insight Preview'}</h4>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-8 no-scrollbar">
              <div className="space-y-4">
                <div className="flex justify-between items-center px-1">
                  <h5 className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Logged Time</h5>
                  <input 
                    type="time" 
                    value={logTime} 
                    onChange={e => setLogTime(e.target.value)}
                    className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl text-xs font-black text-[#39C101] uppercase p-2 focus:ring-2 focus:ring-[#39C101]"
                  />
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex justify-between items-center px-1">
                  <h5 className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Food Items & Portions</h5>
                  <button onClick={() => setDetectedItems([...detectedItems, { name: 'New Item', calories: 100, protein: 10, carbs: 10, fat: 5 }])} className="text-[10px] font-black text-[#39C101] uppercase tracking-widest">+ Add Item</button>
                </div>

                <div className="space-y-3">
                  {detectedItems.map((item, idx) => (
                    <div key={idx} className="bg-slate-50 dark:bg-slate-800 p-5 rounded-[28px] border border-slate-100 dark:border-slate-700 space-y-4">
                      <div className="flex justify-between items-start gap-4">
                        <input 
                          value={item.name} 
                          onChange={e => updateDetectedItem(idx, 'name', e.target.value)}
                          className="flex-1 bg-transparent border-none p-0 text-sm font-black text-slate-900 dark:text-white focus:ring-0 uppercase tracking-tight"
                          placeholder="Food Name"
                        />
                        <button onClick={() => removeDetectedItem(idx)} className="text-red-400 p-1">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                      </div>
                      <div className="grid grid-cols-4 gap-2">
                        <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">Kcal</span><input type="number" value={item.calories} onChange={e => updateDetectedItem(idx, 'calories', e.target.value)} className="text-[11px] font-black bg-transparent border-none p-0 focus:ring-0 text-slate-800 dark:text-white" /></div>
                        <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">Pro</span><input type="number" value={item.protein} onChange={e => updateDetectedItem(idx, 'protein', e.target.value)} className="text-[11px] font-black bg-transparent border-none p-0 focus:ring-0 text-slate-800 dark:text-white" /></div>
                        <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">Carb</span><input type="number" value={item.carbs} onChange={e => updateDetectedItem(idx, 'carbs', e.target.value)} className="text-[11px] font-black bg-transparent border-none p-0 focus:ring-0 text-slate-800 dark:text-white" /></div>
                        <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">Fat</span><input type="number" value={item.fat} onChange={e => updateDetectedItem(idx, 'fat', e.target.value)} className="text-[11px] font-black bg-transparent border-none p-0 focus:ring-0 text-slate-800 dark:text-white" /></div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="p-8 bg-[#39C101]/5 rounded-[32px] border-2 border-dashed border-[#39C101]/20 text-center">
                 <span className="text-[10px] font-black text-[#39C101] uppercase tracking-[0.3em] block mb-2">Total Energy Forge</span>
                 <span className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">{detectedItems.reduce((s, i) => s + i.calories, 0)} kcal</span>
              </div>
            </div>

            <div className="p-8 pt-0">
               <Button 
                onClick={() => handleLogManual(showDetectionPreview.id, detectedItems)}
                className="w-full h-16 rounded-[24px] text-white shadow-2xl shadow-[#39C101]/30 text-[12px] font-black uppercase tracking-widest"
               >
                 {showDetectionPreview.isManual ? 'Update Log' : 'Log This Meal'}
               </Button>
            </div>
          </div>
        </div>
      )}

      {selectedMealForRecipe && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[110] flex flex-col justify-end" onClick={() => setSelectedMealForRecipe(null)}>
           <div className="bg-white dark:bg-slate-900 rounded-t-[48px] p-8 max-h-[85%] overflow-y-auto shadow-2xl animate-in slide-in-from-bottom duration-500 no-scrollbar" onClick={e => e.stopPropagation()}>
            <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mx-auto mb-8"></div>
            <div className="flex justify-between items-start mb-8">
              <div className="space-y-1">
                <span className="text-[10px] font-black text-[#39C101] uppercase tracking-[0.2em]">Culinary Blueprint</span>
                <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight leading-tight">{selectedMealForRecipe.name}</h3>
              </div>
              <button onClick={() => setSelectedMealForRecipe(null)} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            {loadingRecipe ? (
              <div className="py-20 text-center">
                <div className="w-12 h-12 border-4 border-[#39C101] border-t-transparent rounded-full animate-spin mx-auto mb-6"></div>
                <p className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-[0.2em]">Decrypting Recipe Intel...</p>
              </div>
            ) : recipeData ? (
              <div className="space-y-8">
                <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl flex flex-col items-center justify-center text-center">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Prep Time</span>
                    <span className="text-sm font-black text-slate-800 dark:text-white">{recipeData.prepTime}</span>
                  </div>
                  <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl flex flex-col items-center justify-center text-center">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Cook Time</span>
                    <span className="text-sm font-black text-slate-800 dark:text-white">{recipeData.cookTime}</span>
                  </div>
                </div>
                <div className="space-y-6">
                  <h4 className="text-sm font-black text-slate-900 dark:text-white uppercase tracking-widest border-l-4 border-[#39C101] pl-3">Instructions</h4>
                  <div className="space-y-6">
                    {recipeData.instructions.map((step, i) => (
                      <div key={i} className="flex gap-4">
                        <span className="flex-shrink-0 w-8 h-8 bg-[#39C101] text-white rounded-xl flex items-center justify-center text-xs font-black">{i + 1}</span>
                        <p className="text-sm text-slate-600 dark:text-slate-300 leading-relaxed font-medium">{step}</p>
                      </div>
                    ))}
                  </div>
                </div>
                <Button onClick={() => setSelectedMealForRecipe(null)} className="w-full h-16 rounded-[24px]">Done</Button>
              </div>
            ) : null}
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useRef } from 'react';
import { UserProfile, MealPlan, Meal, MealAlternative, GamificationState, Recipe, DetectedFoodItem } from '../types';
import { Card, Button, BackButton } from '../components/UI';
import { generateMealAlternatives, generateRecipe, analyzeFoodImage } from '../services/geminiService';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  meals: Meal[];
  setMeals: React.Dispatch<React.SetStateAction<Meal[]>>;
  onExit: () => void;
  onViewInsights: () => void;
  onExplore: () => void;
  onViewGrocery: () => void;
  onViewPlanDetails: () => void;
  onEditPlan: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, meals, setMeals, onExit, onViewInsights, onExplore, onViewGrocery, onViewPlanDetails, onEditPlan }) => {
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [selectedMealForRecipe, setSelectedMealForRecipe] = useState<Meal | null>(null);
  const [recipeData, setRecipeData] = useState<Recipe | null>(null);
  const [loadingRecipe, setLoadingRecipe] = useState(false);
  const [loadingAlts, setLoadingAlts] = useState(false);

  // Logging flow states
  const [showLoggingOptions, setShowLoggingOptions] = useState<Meal | null>(null);
  const [isAnalyzingFood, setIsAnalyzingFood] = useState(false);
  const [detectedItems, setDetectedItems] = useState<DetectedFoodItem[]>([]);
  const [logTime, setLogTime] = useState<string>(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);

  const [gamification] = useState<GamificationState>({
    points: 1240,
    streak: 4,
    badges: [{ id: 'sync', name: 'Sync King', icon: '⌚', description: 'Connected a wearable device' }]
  });

  const weekDays = useMemo(() => {
    const today = new Date();
    const days = [];
    const start = new Date(today);
    start.setDate(today.getDate() - 3);

    for (let i = 0; i < 7; i++) {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      days.push({
        label: d.toLocaleDateString('en-US', { weekday: 'narrow' }),
        date: d.getDate(),
        isToday: d.toDateString() === today.toDateString(),
      });
    }
    return days;
  }, []);

  const totalConsumed = meals.reduce((sum, m) => m.isLogged ? sum + m.calories : sum, 0);
  const targetCals = plan.calories;
  const progressPercent = targetCals > 0 ? Math.round((totalConsumed / targetCals) * 100) : 0;

  const handleQuickLog = (mealId: string) => {
    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: true,
      isManual: false,
      loggedAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false })
    } : m));
    setShowLoggingOptions(null);
  };

  const handleSaveLog = (mealId: string, finalItems: DetectedFoodItem[]) => {
    const totalCals = finalItems.reduce((s, i) => s + i.calories, 0);
    const totalPro = finalItems.reduce((s, i) => s + i.protein, 0);
    const totalCarb = finalItems.reduce((s, i) => s + i.carbs, 0);
    const totalFat = finalItems.reduce((s, i) => s + i.fat, 0);

    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: true, 
      calories: totalCals,
      protein: totalPro,
      carbs: totalCarb,
      fat: totalFat,
      photoUri: tempPhoto || m.photoUri,
      loggedAt: logTime,
      manualItems: finalItems,
      // Only change name if it's a manual log
      name: (m.isManual || !m.isLogged) && finalItems.length > 0 && showLogModal?.isManual ? finalItems.map(i => i.name).join(", ") : m.name
    } : m));

    setShowLogModal(null);
    setShowLoggingOptions(null);
    setTempPhoto(null);
    setDetectedItems([]);
  };

  const handleEditLog = (meal: Meal) => {
    const itemsToEdit = meal.manualItems && meal.manualItems.length > 0 
      ? [...meal.manualItems] 
      : [{ name: meal.name, calories: meal.calories, protein: meal.protein, carbs: meal.carbs, fat: meal.fat }];

    setDetectedItems(itemsToEdit);
    setTempPhoto(meal.photoUri || null);
    setLogTime(meal.loggedAt || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
    setShowLogModal(meal);
    setShowLoggingOptions(null);
  };

  const handleImageInput = async (e: React.ChangeEvent<HTMLInputElement>, meal: Meal) => {
    const file = e.target.files?.[0];
    if (file) {
      setShowLoggingOptions(null);
      setIsAnalyzingFood(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setTempPhoto(base64);
        try {
          const items = await analyzeFoodImage(base64);
          setDetectedItems(items);
          setLogTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
        } catch (err) {
          console.error("Analysis error:", err);
        } finally {
          setIsAnalyzingFood(false);
          // Set as manual since it's an AI capture
          setShowLogModal({ ...meal, isManual: true });
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const updateDetectedItem = (index: number, field: keyof DetectedFoodItem, value: any) => {
    setDetectedItems(prev => {
      const copy = [...prev];
      copy[index] = { ...copy[index], [field]: field === 'name' ? value : Number(value) };
      return copy;
    });
  };

  const removeDetectedItem = (index: number) => {
    setDetectedItems(prev => prev.filter((_, i) => i !== index));
  };

  const openAlternative = async (meal: Meal) => {
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setLoadingAlts(false);
  };

  const openRecipe = async (meal: Meal) => {
    setSelectedMealForRecipe(meal);
    if (meal.apiRecipeDetail && (meal.apiRecipeDetail.description || (meal.apiRecipeDetail.instructions && meal.apiRecipeDetail.instructions.length > 0))) {
      setRecipeData({
        ingredients: [],
        instructions: meal.apiRecipeDetail.instructions || [],
        prepTime: meal.apiRecipeDetail.prepTime ? `${meal.apiRecipeDetail.prepTime}m` : '15m',
        cookTime: meal.apiRecipeDetail.cookTime ? `${meal.apiRecipeDetail.cookTime}m` : '15m'
      });
      return;
    }
    setLoadingRecipe(true);
    const recipe = await generateRecipe(meal.name, profile);
    setRecipeData(recipe);
    setLoadingRecipe(false);
  };

  return (
    <div className="flex-1 flex flex-col bg-[#F9FBFC] dark:bg-slate-900 overflow-hidden relative transition-colors duration-500">
      <div className="p-6 pt-2 bg-white dark:bg-slate-800 border-b border-slate-50 dark:border-slate-700 flex justify-between items-center z-10 transition-colors">
        <div className="flex items-center gap-3">
          <BackButton onClick={onExit} className="-ml-2 dark:text-slate-100" />
          <div className="flex flex-col">
            <h2 className="text-xl font-black text-slate-900 dark:text-white tracking-tight leading-none mb-0.5">NutriForge</h2>
            <div className="flex items-center gap-2">
              <span className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-wider">{plan.name}</span>
              <div className="w-1 h-1 bg-slate-200 dark:bg-slate-700 rounded-full"></div>
              <div className="flex items-center gap-1 text-orange-500 font-bold text-[10px] tracking-tight">
                <span>🔥</span> {gamification.streak} Day Streak
              </div>
            </div>
          </div>
        </div>
        <div className="flex flex-col items-end">
          <span className="text-[10px] text-[#A5B3C1] font-black uppercase tracking-widest leading-none mb-1">Target Energy</span>
          <span className="text-xl font-black text-slate-900 dark:text-white leading-none tracking-tight">{targetCals} kcal</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pb-32 no-scrollbar">
        <div className="px-6 py-4 flex gap-4 overflow-x-auto no-scrollbar bg-white dark:bg-slate-800 border-b border-slate-50 dark:border-slate-700 transition-colors">
          {weekDays.map((day, i) => (
            <div key={i} className={`flex-shrink-0 w-12 h-16 rounded-[20px] flex flex-col items-center justify-center gap-1.5 transition-all ${day.isToday ? 'bg-[#39C101] text-white shadow-lg shadow-[#39C101]/25' : 'text-[#A5B3C1] hover:text-slate-500'}`}>
              <span className="text-[11px] font-black uppercase tracking-tight">{day.label}</span>
              <span className="text-base font-black tracking-tighter">{day.date}</span>
            </div>
          ))}
        </div>

        <div className="px-6 py-6">
          <Card onClick={onViewInsights} className="bg-white dark:bg-slate-800 border-slate-100 shadow-sm relative overflow-hidden p-8 rounded-[32px] group cursor-pointer">
            <div className="flex justify-between items-start mb-8">
              <div className="space-y-1">
                <div className="flex items-center gap-1 group-hover:translate-x-0.5 transition-transform">
                  <span className="text-[11px] text-[#A5B3C1] font-black uppercase tracking-[0.15em]">Daily Energy</span>
                  <svg className="w-3.5 h-3.5 text-[#A5B3C1]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7"></path></svg>
                </div>
                <div className="flex items-baseline gap-2">
                  <span className="text-5xl font-black text-slate-900 dark:text-white tracking-tighter leading-none">{totalConsumed}</span>
                  <span className="text-base text-[#A5B3C1] font-bold">/ {targetCals || '---'} kcal</span>
                </div>
              </div>
              <div className="w-16 h-16 rounded-full border-[5px] border-slate-100 dark:border-slate-700 flex items-center justify-center relative shadow-inner">
                <svg className="w-full h-full absolute inset-0 -rotate-90">
                  <circle cx="32" cy="32" r="27.5" fill="transparent" stroke="currentColor" strokeWidth="5" className="text-slate-50 dark:text-slate-700/50"/>
                  <circle cx="32" cy="32" r="27.5" fill="transparent" stroke="currentColor" strokeWidth="5" className="text-[#39C101]" strokeDasharray="172.7" strokeDashoffset={172.7 - (172.7 * (progressPercent / 100))} strokeLinecap="round" style={{ transition: 'stroke-dashoffset 1s ease-in-out' }} />
                </svg>
                <span className="text-xs font-black text-slate-900 dark:text-white">{progressPercent}%</span>
              </div>
            </div>
            <div className="w-full h-4 bg-slate-50 dark:bg-slate-900/50 rounded-full overflow-hidden relative shadow-inner">
               <div className="h-full bg-slate-900 dark:bg-white rounded-full transition-all duration-1000 ease-out" style={{ width: `${Math.min(progressPercent, 100)}%` }} />
            </div>
          </Card>
          <div className="flex justify-center gap-8 mt-4 px-2">
            <button onClick={onViewPlanDetails} className="text-[11px] font-black text-[#39C101] uppercase tracking-widest hover:opacity-80 transition-opacity">View Plan Details</button>
            <button onClick={onEditPlan} className="text-[11px] font-black text-[#39C101] uppercase tracking-widest hover:opacity-80 transition-opacity">Change Plan</button>
          </div>
        </div>

        <div className="px-6 space-y-6">
          <h3 className="text-[12px] font-black text-[#A5B3C1] uppercase tracking-[0.2em] mb-4 pl-1">Today's Meals</h3>
          {meals.map(meal => (
            <div key={meal.id} className="bg-white dark:bg-slate-800 rounded-[40px] p-7 shadow-sm border border-slate-50 dark:border-slate-700 relative group overflow-hidden transition-all hover:shadow-xl hover:shadow-slate-200/50">
              <button 
                onClick={() => {
                  if (meal.isLogged) {
                    handleEditLog(meal);
                  } else {
                    handleQuickLog(meal.id);
                  }
                }}
                className={`absolute top-7 right-7 w-12 h-12 rounded-full border-2 flex items-center justify-center transition-all ${meal.isLogged ? 'bg-[#39C101] border-[#39C101] shadow-xl shadow-[#39C101]/30' : 'bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 shadow-sm'}`}
              >
                {meal.isLogged ? (
                  <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>
                ) : (
                  <svg className="w-6 h-6 text-[#39C101]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"></path></svg>
                )}
              </button>

              <div className="flex flex-col gap-1.5 mb-8 pr-16">
                <div className="flex items-center gap-2">
                  <span className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-[0.2em]">{meal.type}</span>
                  {meal.isLogged && meal.isManual && (
                    <span className="text-[9px] font-black text-white bg-[#39C101] px-2 py-0.5 rounded-full uppercase tracking-widest shadow-sm shadow-[#39C101]/30">Logged manually</span>
                  )}
                  {meal.loggedAt && (
                    <span className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest ml-1">{meal.loggedAt}</span>
                  )}
                </div>
                <h4 className="text-xl font-black text-slate-900 dark:text-white leading-tight tracking-tight">{meal.name}</h4>
                <span className="text-xs font-bold text-[#A5B3C1]">{meal.calories} kcal</span>
              </div>

              <div className="flex gap-4">
                <button onClick={() => openRecipe(meal)} className="flex-1 py-4 px-4 rounded-[20px] border-2 border-[#E9EEF2] dark:border-slate-700 text-[12px] font-black text-[#39C101] uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-all active:scale-95 shadow-sm bg-white dark:bg-slate-800">Recipe</button>
                <button onClick={() => openAlternative(meal)} className="flex-1 py-4 px-4 rounded-[20px] border-2 border-[#E9EEF2] dark:border-slate-700 text-[12px] font-black text-[#39C101] uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-all active:scale-95 shadow-sm bg-white dark:bg-slate-800">Swap</button>
                <button 
                  onClick={() => {
                    if (meal.isLogged) {
                      handleEditLog(meal);
                    } else {
                      setShowLoggingOptions(meal);
                    }
                  }}
                  className={`flex-1 py-4 px-4 rounded-[20px] text-[12px] font-black uppercase tracking-widest transition-all active:scale-95 shadow-xl ${meal.isLogged ? 'bg-[#39C101] text-white shadow-[#39C101]/25 hover:bg-[#32aa01]' : 'bg-green-500 text-white shadow-green-500/20'}`}
                >
                  {meal.isLogged ? 'Edit Log' : 'Log'}
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {showLoggingOptions && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[110] flex flex-col justify-end" onClick={() => setShowLoggingOptions(null)}>
          <div className="bg-white dark:bg-slate-900 rounded-t-[48px] p-10 animate-in slide-in-from-bottom duration-500 shadow-2xl" onClick={e => e.stopPropagation()}>
            <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mx-auto mb-8"></div>
            <div className="flex justify-between items-center mb-10">
              <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight leading-none uppercase">Log {showLoggingOptions.type}</h3>
              <button onClick={() => setShowLoggingOptions(null)} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full hover:bg-slate-200 transition-colors">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            <div className="space-y-4">
              <button onClick={() => handleQuickLog(showLoggingOptions.id)} className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 transition-all active:scale-95">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-[#39C101]/10 rounded-2xl flex items-center justify-center text-[#39C101]"><svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path d="M9 2a1 1 0 000 2h2a1 1 0 100-2H9z" /><path fillRule="evenodd" d="M4 5a2 2 0 012-2 3 3 0 003 3h2a3 3 0 003-3 2 2 0 012 2v11a2 2 0 01-2 2H6a2 2 0 01-2-2V5zm3 4a1 1 0 000 2h.01a1 1 0 100-2H7zm3 0a1 1 0 000 2h3a1 1 0 100-2h-3zm-3 4a1 1 0 100 2h.01a1 1 0 100-2H7zm3 0a1 1 0 100 2h3a1 1 0 100-2h-3z" clipRule="evenodd" /></svg></div>
                  <div className="text-left">
                    <span className="block font-black text-slate-900 dark:text-white uppercase text-sm tracking-tight">Select from My Plan</span>
                    <span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest leading-none">Standard metabolic entry</span>
                  </div>
                </div>
              </button>
              <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 transition-all active:scale-95">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-[#39C101]/10 rounded-2xl flex items-center justify-center text-[#39C101]"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg></div>
                  <div className="text-left">
                    <span className="block font-black text-slate-900 dark:text-white uppercase text-sm tracking-tight">Upload Food Photo</span>
                    <span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest leading-none">Instant AI Vision Forge</span>
                  </div>
                </div>
              </button>
              <button onClick={() => galleryInputRef.current?.click()} className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 transition-all active:scale-95">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-[#39C101]/10 rounded-2xl flex items-center justify-center text-[#39C101]"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h14a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></div>
                  <div className="text-left">
                    <span className="block font-black text-slate-900 dark:text-white uppercase text-sm tracking-tight">Choose from Gallery</span>
                    <span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest leading-none">Analyze past capture</span>
                  </div>
                </div>
              </button>
            </div>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" capture="environment" onChange={e => handleImageInput(e, showLoggingOptions!)}/>
            <input type="file" ref={galleryInputRef} className="hidden" accept="image/*" onChange={e => handleImageInput(e, showLoggingOptions!)}/>
          </div>
        </div>
      )}

      {isAnalyzingFood && (
        <div className="fixed inset-0 bg-white/95 dark:bg-slate-950/95 z-[150] flex flex-col items-center justify-center p-12 text-center animate-in fade-in duration-500">
          <div className="w-16 h-16 border-4 border-[#39C101] border-t-transparent rounded-full animate-spin mb-6"></div>
          <h2 className="text-2xl font-black text-slate-900 dark:text-white mb-2 tracking-tight uppercase">AI Vision Forge</h2>
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.25em] max-w-xs leading-relaxed italic animate-pulse">Deconstructing metabolic density...</p>
        </div>
      )}

      {showLogModal && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-[130] flex flex-col items-center justify-center p-6">
          <div className="bg-white dark:bg-slate-900 rounded-[48px] w-full max-w-md overflow-hidden flex flex-col shadow-2xl h-[85%] animate-in zoom-in-95 duration-300">
            <div className="h-48 relative shrink-0">
              {tempPhoto && <img src={tempPhoto} className="w-full h-full object-cover" />}
              <div className="absolute inset-0 bg-gradient-to-t from-slate-900/80 via-transparent to-transparent"></div>
              <button onClick={() => { setShowLogModal(null); setTempPhoto(null); }} className="absolute top-6 right-6 p-3 bg-white/20 backdrop-blur-md rounded-full text-white">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
              <div className="absolute bottom-6 left-8 right-8">
                <span className="text-[10px] font-black text-green-400 uppercase tracking-widest block mb-1">Metabolic Log</span>
                <h4 className="text-xl font-black text-white uppercase tracking-tight leading-none">{showLogModal.isManual ? 'Edit Manual Log' : 'Edit Plan Log'}</h4>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-8 no-scrollbar">
              <div className="space-y-4">
                <div className="flex justify-between items-center px-1">
                  <h5 className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Logged Time</h5>
                  <input 
                    type="time" 
                    value={logTime} 
                    onChange={e => setLogTime(e.target.value)}
                    className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl text-xs font-black text-[#39C101] uppercase p-2 focus:ring-2 focus:ring-[#39C101]"
                  />
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex justify-between items-center px-1">
                  <h5 className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Food Breakdown</h5>
                  {showLogModal.isManual && (
                    <button onClick={() => setDetectedItems([...detectedItems, { name: 'New Item', calories: 100, protein: 10, carbs: 10, fat: 5 }])} className="text-[10px] font-black text-[#39C101] uppercase tracking-widest">+ Add Item</button>
                  )}
                </div>

                <div className="space-y-3">
                  {detectedItems.map((item, idx) => (
                    <div key={idx} className="bg-slate-50 dark:bg-slate-800 p-5 rounded-[28px] border border-slate-100 dark:border-slate-700 space-y-4">
                      <div className="flex justify-between items-start gap-4">
                        <input 
                          value={item.name} 
                          onChange={e => updateDetectedItem(idx, 'name', e.target.value)}
                          // If it's a plan meal, name is read-only as requested
                          disabled={!showLogModal.isManual}
                          className={`flex-1 bg-transparent border-none p-0 text-sm font-black text-slate-900 dark:text-white focus:ring-0 uppercase tracking-tight ${!showLogModal.isManual ? 'opacity-50' : ''}`}
                          placeholder="Food Name"
                        />
                        {showLogModal.isManual && (
                          <button onClick={() => removeDetectedItem(idx)} className="text-red-400 p-1">
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                          </button>
                        )}
                      </div>
                      <div className="grid grid-cols-4 gap-2">
                        <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">Kcal</span><input type="number" value={item.calories} onChange={e => updateDetectedItem(idx, 'calories', e.target.value)} className="text-[11px] font-black bg-transparent border-none p-0 focus:ring-0 text-slate-800 dark:text-white" /></div>
                        <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">Pro</span><input type="number" value={item.protein} onChange={e => updateDetectedItem(idx, 'protein', e.target.value)} className="text-[11px] font-black bg-transparent border-none p-0 focus:ring-0 text-slate-800 dark:text-white" /></div>
                        <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">Carb</span><input type="number" value={item.carbs} onChange={e => updateDetectedItem(idx, 'carbs', e.target.value)} className="text-[11px] font-black bg-transparent border-none p-0 focus:ring-0 text-slate-800 dark:text-white" /></div>
                        <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">Fat</span><input type="number" value={item.fat} onChange={e => updateDetectedItem(idx, 'fat', e.target.value)} className="text-[11px] font-black bg-transparent border-none p-0 focus:ring-0 text-slate-800 dark:text-white" /></div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="p-8 bg-[#39C101]/5 rounded-[32px] border-2 border-dashed border-[#39C101]/20 text-center">
                 <span className="text-[10px] font-black text-[#39C101] uppercase tracking-[0.3em] block mb-2">Total Energy Forge</span>
                 <span className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">{detectedItems.reduce((s, i) => s + i.calories, 0)} kcal</span>
              </div>
            </div>

            <div className="p-8 pt-0">
               <Button 
                onClick={() => handleSaveLog(showLogModal.id, detectedItems)}
                className="w-full h-16 rounded-[24px] text-white shadow-2xl shadow-[#39C101]/30 text-[12px] font-black uppercase tracking-widest"
               >
                 Save & Update Log
               </Button>
            </div>
          </div>
        </div>
      )}

      {selectedMealForRecipe && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[110] flex flex-col justify-end" onClick={() => setSelectedMealForRecipe(null)}>
           <div className="bg-white dark:bg-slate-900 rounded-t-[48px] p-8 max-h-[85%] overflow-y-auto shadow-2xl animate-in slide-in-from-bottom duration-500 no-scrollbar" onClick={e => e.stopPropagation()}>
            <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mx-auto mb-8"></div>
            <div className="flex justify-between items-start mb-8">
              <div className="space-y-1">
                <span className="text-[10px] font-black text-[#39C101] uppercase tracking-[0.2em]">Culinary Blueprint</span>
                <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight leading-tight">{selectedMealForRecipe.name}</h3>
              </div>
              <button onClick={() => setSelectedMealForRecipe(null)} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            {loadingRecipe ? (
              <div className="py-20 text-center">
                <div className="w-12 h-12 border-4 border-[#39C101] border-t-transparent rounded-full animate-spin mx-auto mb-6"></div>
                <p className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-[0.2em]">Decrypting Recipe Intel...</p>
              </div>
            ) : recipeData ? (
              <div className="space-y-8">
                <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl flex flex-col items-center justify-center text-center">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Prep Time</span>
                    <span className="text-sm font-black text-slate-800 dark:text-white">{recipeData.prepTime}</span>
                  </div>
                  <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl flex flex-col items-center justify-center text-center">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Cook Time</span>
                    <span className="text-sm font-black text-slate-800 dark:text-white">{recipeData.cookTime}</span>
                  </div>
                </div>
                <div className="space-y-6">
                  <h4 className="text-sm font-black text-slate-900 dark:text-white uppercase tracking-widest border-l-4 border-[#39C101] pl-3">Instructions</h4>
                  <div className="space-y-6">
                    {recipeData.instructions.map((step, i) => (
                      <div key={i} className="flex gap-4">
                        <span className="flex-shrink-0 w-8 h-8 bg-[#39C101] text-white rounded-xl flex items-center justify-center text-xs font-black">{i + 1}</span>
                        <p className="text-sm text-slate-600 dark:text-slate-300 leading-relaxed font-medium">{step}</p>
                      </div>
                    ))}
                  </div>
                </div>
                <Button onClick={() => setSelectedMealForRecipe(null)} className="w-full h-16 rounded-[24px]">Done</Button>
              </div>
            ) : null}
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useEffect, useState, useRef } from 'react';
import { Card, Button } from '../components/UI';
import { Meal, MealPlan, ApiRecipe, DetectedFoodItem } from '../types';
import { fetchApiRecipes } from '../services/recipeService';
import { analyzeFoodImage } from '../services/geminiService';

interface FreeModeProps {
  onBack: () => void;
  meals?: Meal[];
  setMeals?: React.Dispatch<React.SetStateAction<Meal[]>>;
  plan?: MealPlan | null;
  onExplore: () => void;
  onViewGrocery: () => void;
}

const FreeMode: React.FC<FreeModeProps> = ({ onBack, meals = [], setMeals, plan, onExplore, onViewGrocery }) => {
  const [trendingRecipes, setTrendingRecipes] = useState<ApiRecipe[]>([]);
  const [loadingRecipes, setLoadingRecipes] = useState(false);

  // Logging flow states
  const [showLoggingOptions, setShowLoggingOptions] = useState<Meal | null>(null);
  const [isAnalyzingFood, setIsAnalyzingFood] = useState(false);
  const [detectedItems, setDetectedItems] = useState<DetectedFoodItem[]>([]);
  const [logTime, setLogTime] = useState<string>(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const loadRecipes = async () => {
      setLoadingRecipes(true);
      const result = await fetchApiRecipes({ limit: 6 });
      if (result && result.data) {
        setTrendingRecipes(result.data);
      }
      setLoadingRecipes(false);
    };
    loadRecipes();
  }, []);

  const handleQuickLog = (mealId: string) => {
    if (!setMeals) return;
    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: true,
      isManual: false,
      loggedAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false })
    } : m));
    setShowLoggingOptions(null);
  };

  const handleSaveLog = (mealId: string, finalItems: DetectedFoodItem[]) => {
    if (!setMeals) return;
    const totalCals = finalItems.reduce((s, i) => s + i.calories, 0);
    const totalPro = finalItems.reduce((s, i) => s + i.protein, 0);
    const totalCarb = finalItems.reduce((s, i) => s + i.carbs, 0);
    const totalFat = finalItems.reduce((s, i) => s + i.fat, 0);

    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: true, 
      calories: totalCals,
      protein: totalPro,
      carbs: totalCarb,
      fat: totalFat,
      photoUri: tempPhoto || m.photoUri,
      loggedAt: logTime,
      manualItems: finalItems,
      // Name is fixed for plan-based meals
      name: (m.isManual || !m.isLogged) && finalItems.length > 0 && showLogModal?.isManual ? finalItems.map(i => i.name).join(", ") : m.name
    } : m));

    setShowLogModal(null);
    setShowLoggingOptions(null);
    setTempPhoto(null);
    setDetectedItems([]);
  };

  const handleEditLog = (meal: Meal) => {
    const itemsToEdit = meal.manualItems && meal.manualItems.length > 0 
      ? [...meal.manualItems] 
      : [{ name: meal.name, calories: meal.calories, protein: meal.protein, carbs: meal.carbs, fat: meal.fat }];

    setDetectedItems(itemsToEdit);
    setTempPhoto(meal.photoUri || null);
    setLogTime(meal.loggedAt || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
    setShowLogModal(meal);
    setShowLoggingOptions(null);
  };

  const handleImageInput = async (e: React.ChangeEvent<HTMLInputElement>, meal: Meal) => {
    const file = e.target.files?.[0];
    if (file) {
      setShowLoggingOptions(null);
      setIsAnalyzingFood(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setTempPhoto(base64);
        try {
          const items = await analyzeFoodImage(base64);
          setDetectedItems(items);
          setLogTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
        } catch (err) {
          console.error("Analysis error:", err);
        } finally {
          setIsAnalyzingFood(false);
          setShowLogModal({ ...meal, isManual: true });
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const updateDetectedItem = (index: number, field: keyof DetectedFoodItem, value: any) => {
    setDetectedItems(prev => {
      const copy = [...prev];
      copy[index] = { ...copy[index], [field]: field === 'name' ? value : Number(value) };
      return copy;
    });
  };

  const removeDetectedItem = (index: number) => {
    setDetectedItems(prev => prev.filter((_, i) => i !== index));
  };

  return (
    <div className="flex-1 flex flex-col bg-[#F9FBFC] dark:bg-slate-950 overflow-hidden relative transition-colors duration-500">
      <div className="p-6 pt-2 flex items-center gap-4 bg-white dark:bg-slate-900 border-b border-slate-50 dark:border-slate-800 z-10 transition-colors">
        <button onClick={onBack} className="p-2.5 bg-slate-50 dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-slate-700 transition-colors">
           <svg className="w-5 h-5 text-slate-600 dark:text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7"></path></svg>
        </button>
        <h1 className="text-xl font-black text-slate-800 dark:text-white tracking-tight leading-none">NutriForge Labs</h1>
      </div>

      <div className="flex-1 overflow-y-auto pb-32 no-scrollbar">
        <div className="px-6 py-8">
          <div className="bg-[#39C101] rounded-[40px] p-8 text-white relative overflow-hidden shadow-2xl shadow-[#39C101]/30 group active:scale-[0.98] transition-all cursor-pointer">
            <div className="relative z-10">
              <span className="block text-[10px] font-black uppercase tracking-[0.3em] opacity-80 mb-2">Experimental Forge</span>
              <h3 className="text-2xl font-black leading-none tracking-tight mb-2">AI Recipe Labs</h3>
              <p className="text-[12px] text-green-50 mb-6 font-bold leading-relaxed opacity-90 max-w-[200px]">Craft unique meals & analyze metabolic impact instantly.</p>
              <Button variant="secondary" className="w-full bg-white text-[#39C101] hover:bg-green-50 border-none h-14 py-0 text-[11px] font-black uppercase tracking-widest shadow-xl">Open Labs</Button>
            </div>
            <div className="absolute top-0 right-0 w-48 h-48 bg-white/10 rounded-full -mr-24 -mt-24 group-hover:scale-110 transition-transform duration-700"></div>
          </div>
        </div>

        {meals && meals.length > 0 && (
          <div className="px-6 space-y-6 mb-12">
            <h3 className="text-[12px] font-black text-[#A5B3C1] uppercase tracking-[0.2em] mb-4 pl-1">Today's Active Forge</h3>
            {meals.map(meal => (
              <div key={meal.id} className="bg-white dark:bg-slate-800 rounded-[40px] p-7 shadow-sm border border-slate-50 dark:border-slate-700 relative group overflow-hidden transition-all hover:shadow-xl hover:shadow-slate-200/50">
                <button 
                  onClick={() => {
                    if (meal.isLogged) {
                      handleEditLog(meal);
                    } else {
                      handleQuickLog(meal.id);
                    }
                  }}
                  className={`absolute top-7 right-7 w-12 h-12 rounded-full border-2 flex items-center justify-center transition-all ${meal.isLogged ? 'bg-[#39C101] border-[#39C101] shadow-xl shadow-[#39C101]/30' : 'bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 shadow-sm'}`}
                >
                  {meal.isLogged ? (
                    <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>
                  ) : (
                    <svg className="w-6 h-6 text-[#39C101]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"></path></svg>
                  )}
                </button>
                <div className="flex flex-col gap-1.5 pr-16">
                  <div className="flex items-center gap-2">
                    <span className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-[0.2em]">{meal.type}</span>
                    {meal.isLogged && meal.isManual && (
                      <span className="text-[9px] font-black text-white bg-[#39C101] px-2 py-0.5 rounded-full uppercase tracking-widest shadow-sm shadow-[#39C101]/30">Logged manually</span>
                    )}
                    {meal.loggedAt && (
                      <span className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest ml-1">{meal.loggedAt}</span>
                    )}
                  </div>
                  <h4 className="text-xl font-black text-slate-900 dark:text-white leading-tight tracking-tight">{meal.name}</h4>
                  <span className="text-xs font-bold text-[#A5B3C1]">{meal.calories} kcal</span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {showLoggingOptions && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[110] flex flex-col justify-end" onClick={() => setShowLoggingOptions(null)}>
          <div className="bg-white dark:bg-slate-900 rounded-t-[48px] p-10 animate-in slide-in-from-bottom duration-500 shadow-2xl" onClick={e => e.stopPropagation()}>
            <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mx-auto mb-8"></div>
            <div className="flex justify-between items-center mb-10">
              <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight leading-none uppercase">Log {showLoggingOptions.type}</h3>
              <button onClick={() => setShowLoggingOptions(null)} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full hover:bg-slate-200 transition-colors">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            <div className="space-y-4">
              <button onClick={() => handleQuickLog(showLoggingOptions.id)} className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 transition-all active:scale-95">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-[#39C101]/10 rounded-2xl flex items-center justify-center text-[#39C101]"><svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path d="M9 2a1 1 0 000 2h2a1 1 0 100-2H9z" /><path fillRule="evenodd" d="M4 5a2 2 0 012-2 3 3 0 003 3h2a3 3 0 003-3 2 2 0 012 2v11a2 2 0 01-2 2H6a2 2 0 01-2-2V5zm3 4a1 1 0 000 2h.01a1 1 0 100-2H7zm3 0a1 1 0 000 2h3a1 1 0 100-2h-3zm-3 4a1 1 0 100 2h.01a1 1 0 100-2H7zm3 0a1 1 0 100 2h3a1 1 0 100-2h-3z" clipRule="evenodd" /></svg></div>
                  <div className="text-left"><span className="block font-black text-slate-900 dark:text-white uppercase text-sm tracking-tight">Select from My Plan</span><span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest leading-none">Standard metabolic entry</span></div>
                </div>
              </button>
              <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 transition-all active:scale-95">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-[#39C101]/10 rounded-2xl flex items-center justify-center text-[#39C101]"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg></div>
                  <div className="text-left"><span className="block font-black text-slate-900 dark:text-white uppercase text-sm tracking-tight">Upload Food Photo</span><span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest leading-none">Instant AI Vision Forge</span></div>
                </div>
              </button>
              <button onClick={() => galleryInputRef.current?.click()} className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 transition-all active:scale-95">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-[#39C101]/10 rounded-2xl flex items-center justify-center text-[#39C101]"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h14a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></div>
                  <div className="text-left"><span className="block font-black text-slate-900 dark:text-white uppercase text-sm tracking-tight">Choose from Gallery</span><span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest leading-none">Analyze past capture</span></div>
                </div>
              </button>
            </div>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" capture="environment" onChange={e => handleImageInput(e, showLoggingOptions!)}/>
            <input type="file" ref={galleryInputRef} className="hidden" accept="image/*" onChange={e => handleImageInput(e, showLoggingOptions!)}/>
          </div>
        </div>
      )}

      {isAnalyzingFood && (
        <div className="fixed inset-0 bg-white/95 dark:bg-slate-950/95 z-[150] flex flex-col items-center justify-center p-12 text-center">
          <div className="w-16 h-16 border-4 border-[#39C101] border-t-transparent rounded-full animate-spin mb-6"></div>
          <h2 className="text-xl font-black text-slate-900 dark:text-white uppercase tracking-tight">AI Analysis</h2>
        </div>
      )}

      {showLogModal && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-[130] flex flex-col items-center justify-center p-6">
          <div className="bg-white dark:bg-slate-900 rounded-[48px] w-full max-w-md overflow-hidden flex flex-col shadow-2xl h-[85%]">
            <div className="h-48 relative shrink-0">
              {tempPhoto && <img src={tempPhoto} className="w-full h-full object-cover" />}
              <button onClick={() => { setShowLogModal(null); setTempPhoto(null); }} className="absolute top-6 right-6 p-2 bg-black/20 rounded-full text-white"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg></button>
            </div>
            <div className="flex-1 overflow-y-auto p-8 space-y-6 no-scrollbar">
               <div className="flex justify-between items-center px-1 mb-4">
                  <h5 className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Logged Time</h5>
                  <input type="time" value={logTime} onChange={e => setLogTime(e.target.value)} className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl text-xs font-black text-[#39C101] uppercase p-2 focus:ring-2 focus:ring-[#39C101]" />
               </div>
               <h4 className="text-xl font-black text-slate-900 dark:text-white uppercase">{showLogModal.isManual ? 'Edit Manual Log' : 'Edit Plan Log'}</h4>
               <div className="space-y-3">
                  {detectedItems.map((item, idx) => (
                    <div key={idx} className="bg-slate-50 dark:bg-slate-800 p-4 rounded-3xl border border-slate-100 dark:border-slate-700">
                      <input 
                        value={item.name} 
                        onChange={e => updateDetectedItem(idx, 'name', e.target.value)} 
                        disabled={!showLogModal.isManual}
                        className={`w-full bg-transparent border-none p-0 text-sm font-black uppercase mb-2 focus:ring-0 ${!showLogModal.isManual ? 'opacity-50' : ''}`} 
                      />
                      <div className="grid grid-cols-4 gap-2 text-[10px] font-bold uppercase text-slate-400">
                        <div>Kcal<input type="number" value={item.calories} onChange={e => updateDetectedItem(idx, 'calories', e.target.value)} className="w-full bg-transparent border-none p-0 text-xs font-black text-slate-800 dark:text-white focus:ring-0" /></div>
                        <div>Pro<input type="number" value={item.protein} onChange={e => updateDetectedItem(idx, 'protein', e.target.value)} className="w-full bg-transparent border-none p-0 text-xs font-black text-slate-800 dark:text-white focus:ring-0" /></div>
                        <div>Carb<input type="number" value={item.carbs} onChange={e => updateDetectedItem(idx, 'carbs', e.target.value)} className="w-full bg-transparent border-none p-0 text-xs font-black text-slate-800 dark:text-white focus:ring-0" /></div>
                        <div>Fat<input type="number" value={item.fat} onChange={e => updateDetectedItem(idx, 'fat', e.target.value)} className="w-full bg-transparent border-none p-0 text-xs font-black text-slate-800 dark:text-white focus:ring-0" /></div>
                      </div>
                    </div>
                  ))}
               </div>
            </div>
            <div className="p-8"><Button onClick={() => handleSaveLog(showLogModal.id, detectedItems)} className="w-full h-16 rounded-[24px] uppercase font-black text-sm tracking-widest">Update Log</Button></div>
          </div>
        </div>
      )}
    </div>
  );
};

export default FreeMode;

import React, { useState, useMemo, useRef } from 'react';
import { UserProfile, MealPlan, Meal, MealAlternative, GamificationState, Recipe, DetectedFoodItem } from '../types';
import { Card, Button, BackButton } from '../components/UI';
import { generateMealAlternatives, generateRecipe, analyzeFoodImage } from '../services/geminiService';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  meals: Meal[];
  setMeals: React.Dispatch<React.SetStateAction<Meal[]>>;
  onExit: () => void;
  onViewInsights: () => void;
  onExplore: () => void;
  onViewGrocery: () => void;
  onViewPlanDetails: () => void;
  onEditPlan: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, meals, setMeals, onExit, onViewInsights, onExplore, onViewGrocery, onViewPlanDetails, onEditPlan }) => {
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [selectedMealForRecipe, setSelectedMealForRecipe] = useState<Meal | null>(null);
  const [recipeData, setRecipeData] = useState<Recipe | null>(null);
  const [loadingRecipe, setLoadingRecipe] = useState(false);
  const [loadingAlts, setLoadingAlts] = useState(false);

  // Logging flow states
  const [showLoggingOptions, setShowLoggingOptions] = useState<Meal | null>(null);
  const [isAnalyzingFood, setIsAnalyzingFood] = useState(false);
  const [detectedItems, setDetectedItems] = useState<DetectedFoodItem[]>([]);
  const [logTime, setLogTime] = useState<string>(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);
  const editFileInputRef = useRef<HTMLInputElement>(null);

  const [gamification] = useState<GamificationState>({
    points: 1240,
    streak: 4,
    badges: [{ id: 'sync', name: 'Sync King', icon: '⌚', description: 'Connected a wearable device' }]
  });

  const weekDays = useMemo(() => {
    const today = new Date();
    const days = [];
    const start = new Date(today);
    start.setDate(today.getDate() - 3);

    for (let i = 0; i < 7; i++) {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      days.push({
        label: d.toLocaleDateString('en-US', { weekday: 'narrow' }),
        date: d.getDate(),
        isToday: d.toDateString() === today.toDateString(),
      });
    }
    return days;
  }, []);

  const totalConsumed = meals.reduce((sum, m) => m.isLogged ? sum + m.calories : sum, 0);
  const targetCals = plan.calories;
  const progressPercent = targetCals > 0 ? Math.round((totalConsumed / targetCals) * 100) : 0;

  const handleQuickLog = (mealId: string) => {
    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: true,
      isManual: false,
      loggedAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false })
    } : m));
    setShowLoggingOptions(null);
  };

  const handleSaveLog = (mealId: string, finalItems: DetectedFoodItem[]) => {
    const totalCals = finalItems.reduce((s, i) => s + i.calories, 0);
    const totalPro = finalItems.reduce((s, i) => s + i.protein, 0);
    const totalCarb = finalItems.reduce((s, i) => s + i.carbs, 0);
    const totalFat = finalItems.reduce((s, i) => s + i.fat, 0);

    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: true, 
      calories: totalCals,
      protein: totalPro,
      carbs: totalCarb,
      fat: totalFat,
      photoUri: tempPhoto || m.photoUri,
      loggedAt: logTime,
      manualItems: finalItems,
      // Only change name if it's a manual log or brand new AI log
      name: (m.isManual || (!m.isLogged && showLogModal?.isManual)) && finalItems.length > 0 ? finalItems.map(i => i.name).join(", ") : m.name
    } : m));

    setShowLogModal(null);
    setShowLoggingOptions(null);
    setTempPhoto(null);
    setDetectedItems([]);
  };

  const handleEditLog = (meal: Meal) => {
    const itemsToEdit = meal.manualItems && meal.manualItems.length > 0 
      ? [...meal.manualItems] 
      : [{ name: meal.name, calories: meal.calories, protein: meal.protein, carbs: meal.carbs, fat: meal.fat }];

    setDetectedItems(itemsToEdit);
    setTempPhoto(meal.photoUri || null);
    setLogTime(meal.loggedAt || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
    setShowLogModal(meal);
    setShowLoggingOptions(null);
  };

  const handleImageInput = async (e: React.ChangeEvent<HTMLInputElement>, meal: Meal | null, replaceOnly: boolean = false) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!replaceOnly) {
        setShowLoggingOptions(null);
        setIsAnalyzingFood(true);
      }

      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setTempPhoto(base64);

        if (!replaceOnly && meal) {
          try {
            const items = await analyzeFoodImage(base64);
            setDetectedItems(items);
            setLogTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
          } catch (err) {
            console.error("Analysis error:", err);
          } finally {
            setIsAnalyzingFood(false);
            setShowLogModal({ ...meal, isManual: true });
          }
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const updateDetectedItem = (index: number, field: keyof DetectedFoodItem, value: any) => {
    setDetectedItems(prev => {
      const copy = [...prev];
      copy[index] = { ...copy[index], [field]: field === 'name' ? value : Number(value) };
      return copy;
    });
  };

  const removeDetectedItem = (index: number) => {
    setDetectedItems(prev => prev.filter((_, i) => i !== index));
  };

  const openAlternative = async (meal: Meal) => {
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setLoadingAlts(false);
  };

  const openRecipe = async (meal: Meal) => {
    setSelectedMealForRecipe(meal);
    if (meal.apiRecipeDetail && (meal.apiRecipeDetail.description || (meal.apiRecipeDetail.instructions && meal.apiRecipeDetail.instructions.length > 0))) {
      setRecipeData({
        ingredients: [],
        instructions: meal.apiRecipeDetail.instructions || [],
        prepTime: meal.apiRecipeDetail.prepTime ? `${meal.apiRecipeDetail.prepTime}m` : '15m',
        cookTime: meal.apiRecipeDetail.cookTime ? `${meal.apiRecipeDetail.cookTime}m` : '15m'
      });
      return;
    }
    setLoadingRecipe(true);
    const recipe = await generateRecipe(meal.name, profile);
    setRecipeData(recipe);
    setLoadingRecipe(false);
  };

  return (
    <div className="flex-1 flex flex-col bg-[#F9FBFC] dark:bg-slate-900 overflow-hidden relative transition-colors duration-500">
      <div className="p-6 pt-2 bg-white dark:bg-slate-800 border-b border-slate-50 dark:border-slate-700 flex justify-between items-center z-10 transition-colors">
        <div className="flex items-center gap-3">
          <BackButton onClick={onExit} className="-ml-2 dark:text-slate-100" />
          <div className="flex flex-col">
            <h2 className="text-xl font-black text-slate-900 dark:text-white tracking-tight leading-none mb-0.5">NutriForge</h2>
            <div className="flex items-center gap-2">
              <span className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-wider">{plan.name}</span>
              <div className="w-1 h-1 bg-slate-200 dark:bg-slate-700 rounded-full"></div>
              <div className="flex items-center gap-1 text-orange-500 font-bold text-[10px] tracking-tight">
                <span>🔥</span> {gamification.streak} Day Streak
              </div>
            </div>
          </div>
        </div>
        <div className="flex flex-col items-end">
          <span className="text-[10px] text-[#A5B3C1] font-black uppercase tracking-widest leading-none mb-1">Target Energy</span>
          <span className="text-xl font-black text-slate-900 dark:text-white leading-none tracking-tight">{targetCals} kcal</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pb-32 no-scrollbar">
        <div className="px-6 py-4 flex gap-4 overflow-x-auto no-scrollbar bg-white dark:bg-slate-800 border-b border-slate-50 dark:border-slate-700 transition-colors">
          {weekDays.map((day, i) => (
            <div key={i} className={`flex-shrink-0 w-12 h-16 rounded-[20px] flex flex-col items-center justify-center gap-1.5 transition-all ${day.isToday ? 'bg-[#39C101] text-white shadow-lg shadow-[#39C101]/25' : 'text-[#A5B3C1] hover:text-slate-500'}`}>
              <span className="text-[11px] font-black uppercase tracking-tight">{day.label}</span>
              <span className="text-base font-black tracking-tighter">{day.date}</span>
            </div>
          ))}
        </div>

        <div className="px-6 py-6">
          <Card onClick={onViewInsights} className="bg-white dark:bg-slate-800 border-slate-100 shadow-sm relative overflow-hidden p-8 rounded-[32px] group cursor-pointer">
            <div className="flex justify-between items-start mb-8">
              <div className="space-y-1">
                <div className="flex items-center gap-1 group-hover:translate-x-0.5 transition-transform">
                  <span className="text-[11px] text-[#A5B3C1] font-black uppercase tracking-[0.15em]">Daily Energy</span>
                  <svg className="w-3.5 h-3.5 text-[#A5B3C1]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7"></path></svg>
                </div>
                <div className="flex items-baseline gap-2">
                  <span className="text-5xl font-black text-slate-900 dark:text-white tracking-tighter leading-none">{totalConsumed}</span>
                  <span className="text-base text-[#A5B3C1] font-bold">/ {targetCals || '---'} kcal</span>
                </div>
              </div>
              <div className="w-16 h-16 rounded-full border-[5px] border-slate-100 dark:border-slate-700 flex items-center justify-center relative shadow-inner">
                <svg className="w-full h-full absolute inset-0 -rotate-90">
                  <circle cx="32" cy="32" r="27.5" fill="transparent" stroke="currentColor" strokeWidth="5" className="text-slate-50 dark:text-slate-700/50"/>
                  <circle cx="32" cy="32" r="27.5" fill="transparent" stroke="currentColor" strokeWidth="5" className="text-[#39C101]" strokeDasharray="172.7" strokeDashoffset={172.7 - (172.7 * (progressPercent / 100))} strokeLinecap="round" style={{ transition: 'stroke-dashoffset 1s ease-in-out' }} />
                </svg>
                <span className="text-xs font-black text-slate-900 dark:text-white">{progressPercent}%</span>
              </div>
            </div>
            <div className="w-full h-4 bg-slate-50 dark:bg-slate-900/50 rounded-full overflow-hidden relative shadow-inner">
               <div className="h-full bg-slate-900 dark:bg-white rounded-full transition-all duration-1000 ease-out" style={{ width: `${Math.min(progressPercent, 100)}%` }} />
            </div>
          </Card>
          <div className="flex justify-center gap-8 mt-4 px-2">
            <button onClick={onViewPlanDetails} className="text-[11px] font-black text-[#39C101] uppercase tracking-widest hover:opacity-80 transition-opacity">View Plan Details</button>
            <button onClick={onEditPlan} className="text-[11px] font-black text-[#39C101] uppercase tracking-widest hover:opacity-80 transition-opacity">Change Plan</button>
          </div>
        </div>

        <div className="px-6 space-y-6">
          <h3 className="text-[12px] font-black text-[#A5B3C1] uppercase tracking-[0.2em] mb-4 pl-1">Today's Meals</h3>
          {meals.map(meal => (
            <div key={meal.id} className="bg-white dark:bg-slate-800 rounded-[40px] p-7 shadow-sm border border-slate-50 dark:border-slate-700 relative group overflow-hidden transition-all hover:shadow-xl hover:shadow-slate-200/50">
              <button 
                onClick={() => {
                  if (meal.isLogged) {
                    handleEditLog(meal);
                  } else {
                    handleQuickLog(meal.id);
                  }
                }}
                className={`absolute top-7 right-7 w-12 h-12 rounded-full border-2 flex items-center justify-center transition-all ${meal.isLogged ? 'bg-[#39C101] border-[#39C101] shadow-xl shadow-[#39C101]/30' : 'bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 shadow-sm'}`}
              >
                {meal.isLogged ? (
                  <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>
                ) : (
                  <svg className="w-6 h-6 text-[#39C101]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"></path></svg>
                )}
              </button>

              <div className="flex flex-col gap-1.5 mb-8 pr-16">
                <div className="flex items-center gap-2">
                  <span className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-[0.2em]">{meal.type}</span>
                  {meal.isLogged && meal.isManual && (
                    <span className="text-[9px] font-black text-white bg-[#39C101] px-2 py-0.5 rounded-full uppercase tracking-widest shadow-sm shadow-[#39C101]/30">Logged manually</span>
                  )}
                  {meal.loggedAt && (
                    <span className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest ml-1">{meal.loggedAt}</span>
                  )}
                </div>
                <div className="flex items-center gap-3">
                  {meal.photoUri && (
                    <div className="w-10 h-10 rounded-xl overflow-hidden shrink-0 border border-slate-100 dark:border-slate-700">
                      <img src={meal.photoUri} className="w-full h-full object-cover" alt="" />
                    </div>
                  )}
                  <h4 className="text-xl font-black text-slate-900 dark:text-white leading-tight tracking-tight">{meal.name}</h4>
                </div>
                <span className="text-xs font-bold text-[#A5B3C1]">{meal.calories} kcal</span>
              </div>

              <div className="flex gap-4">
                <button onClick={() => openRecipe(meal)} className="flex-1 py-4 px-4 rounded-[20px] border-2 border-[#E9EEF2] dark:border-slate-700 text-[12px] font-black text-[#39C101] uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-all active:scale-95 shadow-sm bg-white dark:bg-slate-800">Recipe</button>
                <button onClick={() => openAlternative(meal)} className="flex-1 py-4 px-4 rounded-[20px] border-2 border-[#E9EEF2] dark:border-slate-700 text-[12px] font-black text-[#39C101] uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-all active:scale-95 shadow-sm bg-white dark:bg-slate-800">Swap</button>
                <button 
                  onClick={() => {
                    if (meal.isLogged) {
                      handleEditLog(meal);
                    } else {
                      setShowLoggingOptions(meal);
                    }
                  }}
                  className={`flex-1 py-4 px-4 rounded-[20px] text-[12px] font-black uppercase tracking-widest transition-all active:scale-95 shadow-xl ${meal.isLogged ? 'bg-[#39C101] text-white shadow-[#39C101]/25 hover:bg-[#32aa01]' : 'bg-green-500 text-white shadow-green-500/20'}`}
                >
                  {meal.isLogged ? 'Edit Log' : 'Log'}
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {showLoggingOptions && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[110] flex flex-col justify-end" onClick={() => setShowLoggingOptions(null)}>
