              </button>
              <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 transition-all active:scale-95">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-[#39C101]/10 rounded-2xl flex items-center justify-center text-[#39C101]"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg></div>
                  <div className="text-left"><span className="block font-black text-slate-900 dark:text-white uppercase text-sm tracking-tight">Upload Food Photo</span><span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest leading-none">Instant AI Vision Forge</span></div>
                </div>
              </button>
              <button onClick={() => galleryInputRef.current?.click()} className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 transition-all active:scale-95">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-[#39C101]/10 rounded-2xl flex items-center justify-center text-[#39C101]"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h14a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></div>
                  <div className="text-left"><span className="block font-black text-slate-900 dark:text-white uppercase text-sm tracking-tight">Choose from Gallery</span><span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest leading-none">Analyze past capture</span></div>
                </div>
              </button>
            </div>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" capture="environment" onChange={e => handleImageInput(e, showLoggingOptions!)}/>
            <input type="file" ref={galleryInputRef} className="hidden" accept="image/*" onChange={e => handleImageInput(e, showLoggingOptions!)}/>
          </div>
        </div>
      )}

      {isAnalyzingFood && (
        <div className="fixed inset-0 bg-white/95 dark:bg-slate-950/95 z-[150] flex flex-col items-center justify-center p-12 text-center animate-in fade-in duration-500">
          <div className="w-16 h-16 border-4 border-[#39C101] border-t-transparent rounded-full animate-spin mb-6"></div>
          <h2 className="text-xl font-black text-slate-900 dark:text-white uppercase tracking-tight">AI Analysis</h2>
        </div>
      )}

      {showLogModal && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-[130] flex flex-col items-center justify-center p-6">
          <div className="bg-white dark:bg-slate-900 rounded-[48px] w-full max-w-md overflow-hidden flex flex-col shadow-2xl h-[85%] animate-in zoom-in-95 duration-300">
            <div className="h-48 relative shrink-0">
              {tempPhoto ? (
                <img src={tempPhoto} className="w-full h-full object-cover" />
              ) : showLogModal.photoUri ? (
                <img src={showLogModal.photoUri} className="w-full h-full object-cover" />
              ) : (
                <div className="w-full h-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-slate-300">
                  <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h14a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                </div>
              )}
              <div className="absolute inset-0 bg-gradient-to-t from-slate-900/80 via-transparent to-transparent"></div>

              <button 
                onClick={() => editFileInputRef.current?.click()}
                className="absolute bottom-4 right-4 p-2.5 bg-white/20 backdrop-blur-md rounded-xl text-white border border-white/30 hover:bg-white/30 transition-all flex items-center gap-2"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /></svg>
                <span className="text-[10px] font-black uppercase tracking-widest">Change Photo</span>
              </button>
              <input type="file" ref={editFileInputRef} className="hidden" accept="image/*" onChange={e => handleImageInput(e, null, true)}/>

              <button onClick={() => { setShowLogModal(null); setTempPhoto(null); }} className="absolute top-6 right-6 p-2 bg-black/20 rounded-full text-white"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg></button>
            </div>
            <div className="flex-1 overflow-y-auto p-8 space-y-6 no-scrollbar">
               <div className="flex justify-between items-center px-1 mb-4">
                  <h5 className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Logged Time</h5>
                  <input type="time" value={logTime} onChange={e => setLogTime(e.target.value)} className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl text-xs font-black text-[#39C101] uppercase p-2 focus:ring-2 focus:ring-[#39C101]" />
               </div>
               <h4 className="text-xl font-black text-slate-900 dark:text-white uppercase">
                 {showLogModal.isManual || (!showLogModal.isLogged && showLogModal.isManual) ? 'Edit Manual Log' : 'Edit Plan Log'}
               </h4>
               <div className="space-y-3">
                  {detectedItems.map((item, idx) => (
                    <div key={idx} className="bg-slate-50 dark:bg-slate-800 p-4 rounded-3xl border border-slate-100 dark:border-slate-700">
                      <input 
                        value={item.name} 
                        onChange={e => updateDetectedItem(idx, 'name', e.target.value)} 
                        disabled={!(showLogModal.isManual || (!showLogModal.isLogged && showLogModal.isManual))}
                        className={`w-full bg-transparent border-none p-0 text-sm font-black uppercase mb-2 focus:ring-0 ${!(showLogModal.isManual || (!showLogModal.isLogged && showLogModal.isManual)) ? 'opacity-50' : ''}`} 
                      />
                      <div className="grid grid-cols-4 gap-2 text-[10px] font-bold uppercase text-slate-400">
                        <div>Kcal<input type="number" value={item.calories} onChange={e => updateDetectedItem(idx, 'calories', e.target.value)} className="w-full bg-transparent border-none p-0 text-xs font-black text-slate-800 dark:text-white focus:ring-0" /></div>
                        <div>Pro<input type="number" value={item.protein} onChange={e => updateDetectedItem(idx, 'protein', e.target.value)} className="w-full bg-transparent border-none p-0 text-xs font-black text-slate-800 dark:text-white focus:ring-0" /></div>
                        <div>Carb<input type="number" value={item.carbs} onChange={e => updateDetectedItem(idx, 'carbs', e.target.value)} className="w-full bg-transparent border-none p-0 text-xs font-black text-slate-800 dark:text-white focus:ring-0" /></div>
                        <div>Fat<input type="number" value={item.fat} onChange={e => updateDetectedItem(idx, 'fat', e.target.value)} className="w-full bg-transparent border-none p-0 text-xs font-black text-slate-800 dark:text-white focus:ring-0" /></div>
                      </div>
                    </div>
                  ))}
               </div>
            </div>
            <div className="p-8"><Button onClick={() => handleSaveLog(showLogModal.id, detectedItems)} className="w-full h-16 rounded-[24px] uppercase font-black text-sm tracking-widest">Update Log</Button></div>
          </div>
        </div>
      )}
    </div>
  );
};

export default FreeMode;

import React, { useState, useMemo, useRef } from 'react';
import { UserProfile, MealPlan, Meal, MealAlternative, GamificationState, Recipe, DetectedFoodItem } from '../types';
import { Card, Button, BackButton } from '../components/UI';
import { generateMealAlternatives, generateRecipe, analyzeFoodImage } from '../services/geminiService';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  meals: Meal[];
  setMeals: React.Dispatch<React.SetStateAction<Meal[]>>;
  onExit: () => void;
  onViewInsights: () => void;
  onExplore: () => void;
  onViewGrocery: () => void;
  onViewPlanDetails: () => void;
  onEditPlan: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, meals, setMeals, onExit, onViewInsights, onExplore, onViewGrocery, onViewPlanDetails, onEditPlan }) => {
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [alternativeMeals, setAlternativeMeals] = useState<MealAlternative[]>([]);
  const [selectedMealForRecipe, setSelectedMealForRecipe] = useState<Meal | null>(null);
  const [recipeData, setRecipeData] = useState<Recipe | null>(null);
  const [loadingRecipe, setLoadingRecipe] = useState(false);
  const [loadingAlts, setLoadingAlts] = useState(false);

  // Logging flow states
  const [showLoggingOptions, setShowLoggingOptions] = useState<Meal | null>(null);
  const [isAnalyzingFood, setIsAnalyzingFood] = useState(false);
  const [detectedItems, setDetectedItems] = useState<DetectedFoodItem[]>([]);
  const [logTime, setLogTime] = useState<string>(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);
  const editFileInputRef = useRef<HTMLInputElement>(null);

  const [gamification] = useState<GamificationState>({
    points: 0,
    streak: 4,
    badges: [{ id: 'sync', name: 'Sync King', icon: '⌚', description: 'Connected a wearable device' }]
  });

  const weekDays = useMemo(() => {
    const today = new Date();
    const days = [];
    const start = new Date(today);
    start.setDate(today.getDate() - 3);

    for (let i = 0; i < 7; i++) {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      days.push({
        label: d.toLocaleDateString('en-US', { weekday: 'narrow' }),
        date: d.getDate(),
        isToday: d.toDateString() === today.toDateString(),
      });
    }
    return days;
  }, []);

  const totalConsumed = meals.reduce((sum, m) => m.isLogged ? sum + m.calories : sum, 0);
  const targetCals = plan.calories;
  const progressPercent = targetCals > 0 ? Math.round((totalConsumed / targetCals) * 100) : 0;

  const handleQuickLog = (mealId: string) => {
    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: true,
      isManual: false,
      loggedAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false })
    } : m));
    setShowLoggingOptions(null);
  };

  const handleSaveLog = (mealId: string, finalItems: DetectedFoodItem[]) => {
    const totalCals = finalItems.reduce((s, i) => s + i.calories, 0);
    const totalPro = finalItems.reduce((s, i) => s + i.protein, 0);
    const totalCarb = finalItems.reduce((s, i) => s + i.carbs, 0);
    const totalFat = finalItems.reduce((s, i) => s + i.fat, 0);

    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: true, 
      calories: totalCals,
      protein: totalPro,
      carbs: totalCarb,
      fat: totalFat,
      photoUri: tempPhoto || m.photoUri,
      loggedAt: logTime,
      manualItems: finalItems,
      name: (m.isManual || (!m.isLogged && showLogModal?.isManual)) && finalItems.length > 0 ? finalItems.map(i => i.name).join(", ") : m.name
    } : m));

    setShowLogModal(null);
    setShowLoggingOptions(null);
    setTempPhoto(null);
    setDetectedItems([]);
  };

  const handleEditLog = (meal: Meal) => {
    const itemsToEdit = meal.manualItems && meal.manualItems.length > 0 
      ? [...meal.manualItems] 
      : [{ name: meal.name, calories: meal.calories, protein: meal.protein, carbs: meal.carbs, fat: meal.fat }];

    setDetectedItems(itemsToEdit);
    setTempPhoto(meal.photoUri || null);
    setLogTime(meal.loggedAt || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
    setShowLogModal(meal);
    setShowLoggingOptions(null);
  };

  const handleImageInput = async (e: React.ChangeEvent<HTMLInputElement>, meal: Meal | null, replaceOnly: boolean = false) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!replaceOnly) {
        setShowLoggingOptions(null);
        setIsAnalyzingFood(true);
      }

      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setTempPhoto(base64);

        if (!replaceOnly && meal) {
          try {
            const items = await analyzeFoodImage(base64);
            setDetectedItems(items);
            setLogTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
          } catch (err) {
            console.error("Analysis error:", err);
          } finally {
            setIsAnalyzingFood(false);
            setShowLogModal({ ...meal, isManual: true });
          }
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const updateDetectedItem = (index: number, field: keyof DetectedFoodItem, value: any) => {
    setDetectedItems(prev => {
      const copy = [...prev];
      copy[index] = { ...copy[index], [field]: field === 'name' ? value : Number(value) };
      return copy;
    });
  };

  const removeDetectedItem = (index: number) => {
    setDetectedItems(prev => prev.filter((_, i) => i !== index));
  };

  const openAlternative = async (meal: Meal) => {
    setSelectedMealForAlt(meal);
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setAlternativeMeals(alts);
    setLoadingAlts(false);
  };

  const handleSwapMeal = (alt: MealAlternative) => {
    if (!selectedMealForAlt) return;
    setMeals(prev => prev.map(m => m.id === selectedMealForAlt.id ? {
      ...m,
      name: alt.name,
      calories: alt.calories,
      protein: alt.protein,
      carbs: alt.carbs,
      fat: alt.fat,
      isLogged: false, // Reset log state if swapped
      manualItems: [{ name: alt.name, calories: alt.calories, protein: alt.protein, carbs: alt.carbs, fat: alt.fat }]
    } : m));
    setSelectedMealForAlt(null);
    setAlternativeMeals([]);
  };

  const openRecipe = async (meal: Meal) => {
    setSelectedMealForRecipe(meal);
    if (meal.apiRecipeDetail && (meal.apiRecipeDetail.description || (meal.apiRecipeDetail.instructions && meal.apiRecipeDetail.instructions.length > 0))) {
      setRecipeData({
        ingredients: [],
        instructions: meal.apiRecipeDetail.instructions || [],
        prepTime: meal.apiRecipeDetail.prepTime ? `${meal.apiRecipeDetail.prepTime}m` : '15m',
        cookTime: meal.apiRecipeDetail.cookTime ? `${meal.apiRecipeDetail.cookTime}m` : '15m'
      });
      return;
    }
    setLoadingRecipe(true);
    const recipe = await generateRecipe(meal.name, profile);
    setRecipeData(recipe);
    setLoadingRecipe(false);
  };

  return (
    <div className="flex-1 flex flex-col bg-[#F9FBFC] dark:bg-slate-900 overflow-hidden relative transition-colors duration-500">
      <div className="p-6 pt-2 bg-white dark:bg-slate-800 border-b border-slate-50 dark:border-slate-700 flex justify-between items-center z-10 transition-colors">
        <div className="flex items-center gap-3">
