import React, { useState, useEffect } from 'react';
import { UserProfile, HealthGoal, Cuisine, MealFrequency, DietPreference, MealPlan, Meal, ApiMealPlan } from './types';
import Onboarding from './views/Onboarding';
import PlanSelection from './views/PlanSelection';
import Dashboard from './views/Dashboard';
import FreeMode from './views/FreeMode';
import Insights from './views/Insights';
import Settings from './views/Settings';
import ExploreHub from './views/ExploreHub';
import GroceryList from './views/GroceryList';
import PlanDetails from './views/PlanDetails';
import EditPlan from './views/EditPlan';
import { generateDailyMeals } from './services/geminiService';
import { fetchApiMealPlanById } from './services/mealPlanService';

type View = 'onboarding' | 'plan-selection' | 'dashboard' | 'free-mode' | 'insights' | 'settings' | 'explore-hub' | 'grocery-list' | 'plan-details' | 'edit-plan';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('onboarding');
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [selectedPlan, setSelectedPlan] = useState<MealPlan | null>(null);
  const [previewPlan, setPreviewPlan] = useState<MealPlan | null>(null);
  const [meals, setMeals] = useState<Meal[]>([]);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isForging, setIsForging] = useState(false);
  const [time, setTime] = useState(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));

  useEffect(() => {
    const timer = setInterval(() => {
      setTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    }, 10000);
    return () => clearInterval(timer);
  }, []);

  const handleOnboardingComplete = (data: UserProfile) => {
    setProfile(data);
    setCurrentView('plan-selection');
  };

  const mapMealType = (type: string): Meal['type'] => {
    const t = type.toLowerCase();
    if (t.includes('breakfast')) return 'Breakfast';
    if (t.includes('lunch')) return 'Lunch';
    if (t.includes('dinner')) return 'Dinner';
    return 'Snack';
  };

  const handleUpdateProfile = async (newProfile: UserProfile) => {
    setProfile(newProfile);
    if (selectedPlan) {
      setIsForging(true);
      try {
        const finalMeals = await generateDailyMeals(selectedPlan, newProfile);
        setMeals(finalMeals);
        setCurrentView('dashboard');
      } catch (err) {
        console.error("Error rebuilding plan:", err);
      } finally {
        setIsForging(false);
      }
    } else {
      setCurrentView('plan-selection');
    }
  };

  const handlePlanSelect = async (plan: MealPlan | null) => {
    if (plan && profile) {
      setIsForging(true);

      try {
        const apiPlanResponse = await fetchApiMealPlanById(plan.id);
        const apiPlanDetail = apiPlanResponse?.data || apiPlanResponse;

        const enrichedPlan: MealPlan = apiPlanDetail ? {
          id: apiPlanDetail.id || apiPlanDetail.plan_id || plan.id,
          name: apiPlanDetail.name || apiPlanDetail.plan_name || apiPlanDetail.title || plan.name,
          duration: `${apiPlanDetail.duration_days || apiPlanDetail.days || 7} Days`,
          calories: Number(apiPlanDetail.daily_calories || apiPlanDetail.calories_per_day || apiPlanDetail.calories || plan.calories),
          description: apiPlanDetail.description || plan.description,
          image_url: apiPlanDetail.image_url || apiPlanDetail.image || plan.image_url
        } : plan;

        setSelectedPlan(enrichedPlan);

        let finalMeals: Meal[] = [];

        if (apiPlanDetail?.days && apiPlanDetail.days["1"]) {
          finalMeals = apiPlanDetail.days["1"].map((item: any, idx: number) => ({
            id: item.recipe?.id || `api-meal-${idx}-${Date.now()}`,
            type: mapMealType(item.meal_type),
            name: item.recipe?.title || 'Unknown Meal',
            calories: item.recipe?.calories || 0,
            protein: item.recipe?.protein || 0,
            carbs: item.recipe?.carbs || 0,
            fat: item.recipe?.fats || 0,
            isLogged: false,
            apiRecipeDetail: {
              description: item.recipe?.description,
              instructions: item.recipe?.instructions,
              prepTime: item.recipe?.prep_time,
              cookTime: item.recipe?.cook_time,
              image_url: item.recipe?.image_url
            }
          }));
        } else {
          finalMeals = await generateDailyMeals(enrichedPlan, profile);
        }

        setMeals(finalMeals);
      } catch (err) {
        console.error("Critical error fetching or forging meal plan:", err);
        setSelectedPlan(plan);
        setMeals([]);
      } finally {
        setIsForging(false);
        setPreviewPlan(null);
        setCurrentView('dashboard');
      }
    } else {
      setCurrentView('free-mode');
    }
  };

  const handleViewPlanDetails = (plan: MealPlan) => {
    setPreviewPlan(plan);
    setCurrentView('plan-details');
  };

  const handleDetailsBack = () => {
    if (selectedPlan && currentView === 'plan-details' && !previewPlan) {
      setCurrentView('dashboard');
    } else {
      setPreviewPlan(null);
      setCurrentView('plan-selection');
    }
  };

  const isMainApp = ['dashboard', 'free-mode', 'insights', 'settings', 'explore-hub', 'grocery-list', 'plan-details', 'edit-plan'].includes(currentView);

  return (
    <div className={`min-h-screen ${isDarkMode ? 'bg-slate-950' : 'bg-slate-200'} flex items-center justify-center p-0 sm:p-4 transition-colors duration-500`}>
      <div className={`${isDarkMode ? 'dark' : ''} w-full max-w-md h-[100vh] sm:h-[844px] relative overflow-hidden flex flex-col sm:rounded-[48px] sm:shadow-2xl border-[8px] border-slate-900 shadow-inner shadow-black/20`}>
        <div className="w-full h-full bg-[#F9FBFC] dark:bg-slate-950 flex flex-col transition-colors duration-500">

          <div className="h-10 flex justify-between items-center px-8 shrink-0 z-50 bg-white/80 dark:bg-slate-900/80 backdrop-blur-sm">
            <span className="text-xs font-bold text-slate-800 dark:text-slate-100">{time}</span>
            <div className="flex gap-1.5 items-center">
              <svg className="w-4 h-4 text-slate-800 dark:text-slate-100" fill="currentColor" viewBox="0 0 20 20"><path d="M2 11a1 1 0 011-1h2a1 1 0 011 1v5a1 1 0 01-1 1H3a1 1 0 01-1-1v-5zm6-4a1 1 0 011-1h2a1 1 0 011 1v9a1 1 0 01-1 1H9a1 1 0 01-1-1V7zm6-4a1 1 0 011-1h2a1 1 0 011 1v13a1 1 0 01-1 1h-2a1 1 0 01-1-1V3z"></path></svg>
              <div className="w-5 h-2.5 border border-slate-800 dark:border-slate-100 rounded-sm relative">
                <div className="absolute left-0.5 top-0.5 bottom-0.5 right-1 bg-slate-800 dark:bg-slate-100 rounded-px"></div>
              </div>
            </div>
          </div>

          <div className="flex-1 flex flex-col overflow-hidden relative">
            {isForging && (
              <div className="absolute inset-0 bg-white/95 dark:bg-slate-900/95 z-[100] flex flex-col items-center justify-center p-12 text-center animate-in fade-in duration-500">
                <div className="relative w-32 h-32 mb-8">
                  <div className="absolute inset-0 border-4 border-slate-100 dark:border-slate-800 rounded-full"></div>
                  <div className="absolute inset-0 border-4 border-[#39C101] rounded-full border-t-transparent animate-spin"></div>
                  <div className="absolute inset-4 bg-[#39C101]/5 rounded-full flex items-center justify-center animate-pulse">
                    <svg className="w-10 h-10 text-[#39C101]" fill="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z"/></svg>
                  </div>
                </div>
                <h2 className="text-2xl font-black text-slate-900 dark:text-white mb-2 tracking-tight uppercase">Forging Daily Blueprint</h2>
                <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest max-w-xs leading-relaxed italic">
                  Syncing with Global Nutrition Database...
                </p>
              </div>
            )}

            {currentView === 'onboarding' && (
              <Onboarding onComplete={handleOnboardingComplete} />
            )}
            {currentView === 'plan-selection' && (
              <PlanSelection 
                onSelect={handlePlanSelect} 
                onBack={() => setCurrentView('onboarding')} 
                onViewDetails={handleViewPlanDetails}
                onEditPlan={() => setCurrentView('edit-plan')}
                profile={profile}
              />
            )}
            {currentView === 'dashboard' && profile && selectedPlan && (
              <Dashboard 
                profile={profile} 
                plan={selectedPlan} 
                meals={meals}
                setMeals={setMeals}
                onExit={() => setCurrentView('plan-selection')}
                onViewInsights={() => setCurrentView('insights')}
                onExplore={() => setCurrentView('explore-hub')}
                onViewGrocery={() => setCurrentView('grocery-list')}
                onViewPlanDetails={() => { setPreviewPlan(null); setCurrentView('plan-details'); }}
                onEditPlan={() => setCurrentView('edit-plan')}
              />
            )}
            {currentView === 'plan-details' && profile && (selectedPlan || previewPlan) && (
              <PlanDetails 
                profile={profile}
                plan={previewPlan || selectedPlan!}
                onBack={handleDetailsBack}
                onSelect={handlePlanSelect}
              />
            )}
            {currentView === 'edit-plan' && profile && (
              <EditPlan 
                profile={profile}
                onBack={() => {
                  if (selectedPlan) setCurrentView('dashboard');
                  else setCurrentView('plan-selection');
                }}
                onRebuild={handleUpdateProfile}
              />
            )}
            {currentView === 'explore-hub' && profile && selectedPlan && (
              <ExploreHub 
                profile={profile}
                plan={selectedPlan}
                meals={meals}
                onBack={() => setCurrentView('dashboard')}
                onSelectPlan={() => setCurrentView('plan-selection')}
              />
            )}
            {currentView === 'grocery-list' && (
              <GroceryList onBack={() => setCurrentView('dashboard')} />
            )}
            {currentView === 'free-mode' && (
              <FreeMode 
                onBack={() => setCurrentView('plan-selection')} 
                meals={meals}
                setMeals={setMeals}
                plan={selectedPlan}
                profile={profile || undefined}
                onExplore={() => setCurrentView('explore-hub')}
                onViewGrocery={() => setCurrentView('grocery-list')}
              />
            )}
            {currentView === 'insights' && profile && (
              <Insights 
                onBack={() => setCurrentView('dashboard')} 
                meals={meals}
                targetCalories={selectedPlan?.calories || 2000}
              />
            )}
            {currentView === 'settings' && (
              <Settings 
                onBack={() => setCurrentView('dashboard')}
                isDarkMode={isDarkMode}
                onToggleDarkMode={() => setIsDarkMode(!isDarkMode)}
              />
            )}
          </div>

          {isMainApp && (
            <div className="absolute bottom-0 left-0 right-0 h-20 bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl border-t border-slate-100 dark:border-slate-800 flex items-center justify-around px-4 pb-2 z-50">
              <button onClick={() => setCurrentView('dashboard')} className={`flex flex-col items-center gap-1 transition-all ${['dashboard', 'explore-hub', 'grocery-list', 'plan-details', 'edit-plan'].includes(currentView) ? 'text-[#39C101]' : 'text-slate-400 dark:text-slate-500'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"></path></svg>
                <span className="text-[10px] font-black uppercase tracking-tighter">Home</span>
              </button>
              <button onClick={() => setCurrentView('free-mode')} className={`flex flex-col items-center gap-1 transition-all ${currentView === 'free-mode' ? 'text-[#39C101]' : 'text-slate-400 dark:text-slate-500'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
                <span className="text-[10px] font-black uppercase tracking-tighter">Forge</span>
              </button>
              <button onClick={() => setCurrentView('insights')} className={`flex flex-col items-center gap-1 transition-all ${currentView === 'insights' ? 'text-[#39C101]' : 'text-slate-400 dark:text-slate-500'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"></path></svg>
                <span className="text-[10px] font-black uppercase tracking-tighter">Insights</span>
              </button>
              <button onClick={() => setCurrentView('settings')} className={`flex flex-col items-center gap-1 transition-all ${currentView === 'settings' ? 'text-[#39C101]' : 'text-slate-400 dark:text-slate-500'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                <span className="text-[10px] font-black uppercase tracking-tighter">Profile</span>
              </button>
            </div>
          )}

          <div className="absolute top-0 left-1/2 -translate-x-1/2 w-32 h-6 bg-slate-900 rounded-b-2xl z-[60] hidden sm:block"></div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useState, useCallback } from 'react';
import { MealPlan, UserProfile } from '../types';
import { Button, BackButton } from '../components/UI';
import { fetchApiMealPlans } from '../services/mealPlanService';

interface PlanSelectionProps {
  onSelect: (plan: MealPlan | null) => void;
  onBack: () => void;
  onViewDetails: (plan: MealPlan) => void;
  onEditPlan: () => void;
  profile: UserProfile | null;
}

const PlanSelection: React.FC<PlanSelectionProps> = ({ onSelect, onBack, onViewDetails, onEditPlan, profile }) => {
  const [plans, setPlans] = useState<MealPlan[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadPlans = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      // Fetch meal plans with a limit of 5 for a more curated selection
      const apiPlans = await fetchApiMealPlans({ limit: 5 });

      if (apiPlans && Array.isArray(apiPlans)) {
        const mappedPlans: MealPlan[] = apiPlans.map((p: any) => ({
          id: p.id || p.plan_id || String(Math.random()),
          name: p.name || p.plan_name || p.title || 'Untitled Plan',
          calories: Number(p.daily_calories || p.calories_per_day || p.calories || 0),
          duration: `${p.duration_days || p.days || 7} Days`,
          image_url: p.image_url || p.image || `https://images.unsplash.com/photo-1490645935967-10de6ba17061?auto=format&fit=crop&q=80&w=600`,
          description: p.description || ""
        })).slice(0, 5); // Ensure exactly 5 plans are shown if the API returns more

        setPlans(mappedPlans);

        if (mappedPlans.length === 0) {
          setError("No meal plans found in the system. Please try again later.");
        }
      } else {
        setError("Unable to load meal plans. Please try again.");
      }
    } catch (err) {
      console.error("Plan Selection Component Error:", err);
      setError("Unable to load meal plans. Please try again.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadPlans();
  }, [loadPlans]);

  return (
    <div className="flex-1 flex flex-col p-6 overflow-y-auto bg-slate-50 dark:bg-slate-900 transition-colors no-scrollbar">
      <div className="flex items-center gap-2 mb-6 mt-2">
        <BackButton onClick={onBack} className="-ml-2 dark:text-slate-300" />
        <h1 className="text-2xl font-black text-slate-800 dark:text-white tracking-tight">Meal Plans</h1>
      </div>

      <div className="space-y-6 mb-8">
        {loading ? (
          [1, 2, 3].map(i => (
            <div key={i} className="bg-white dark:bg-slate-800 rounded-[32px] overflow-hidden animate-pulse border border-slate-100 dark:border-slate-700">
              <div className="h-44 bg-slate-200 dark:bg-slate-700"></div>
              <div className="p-6 space-y-3">
                <div className="h-4 bg-slate-200 dark:bg-slate-700 rounded w-3/4"></div>
                <div className="h-3 bg-slate-200 dark:bg-slate-700 rounded w-1/2"></div>
                <div className="h-10 bg-slate-200 dark:bg-slate-700 rounded-2xl w-full mt-4"></div>
              </div>
            </div>
          ))
        ) : error ? (
           <div className="text-center py-12 px-4 space-y-4">
            <div className="w-16 h-16 bg-red-50 text-red-400 rounded-full flex items-center justify-center mx-auto mb-4">
              <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
            </div>
            <p className="text-slate-600 dark:text-slate-400 font-medium">{error}</p>
            <Button onClick={loadPlans} variant="outline" className="mx-auto">Retry Sync</Button>
          </div>
        ) : plans.length > 0 ? (
          plans.map((plan, index) => (
            <div 
              key={plan.id} 
              className="bg-white dark:bg-slate-800 rounded-[32px] overflow-hidden shadow-sm border border-slate-100 dark:border-slate-700 flex flex-col group transition-all hover:shadow-xl hover:shadow-green-500/5"
            >
              <div className="h-44 relative overflow-hidden">
                <img 
                  src={plan.image_url || `https://images.unsplash.com/photo-1490645935967-10de6ba17061?auto=format&fit=crop&q=80&w=600`} 
                  alt={plan.name} 
                  className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" 
                />

                {index === 0 && (
                  <div className="absolute top-4 left-4 bg-indigo-600 text-white px-3 py-1 rounded-full text-[9px] font-black uppercase shadow-lg shadow-indigo-500/30 backdrop-blur-md flex items-center gap-1.5 z-10">
                    <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20">
                      <path d="M13 10V3L4 14h7v7l9-11h-7z" />
                    </svg>
                    AI Recommended
                  </div>
                )}

                <div className="absolute inset-0 bg-gradient-to-t from-black/40 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>

                <div className="absolute top-4 right-4 bg-green-500 text-white px-3 py-1 rounded-full text-[10px] font-black uppercase shadow-lg shadow-green-500/20 backdrop-blur-sm z-10">
                  {plan.calories} kcal
                </div>
              </div>

              <div className="p-6 flex flex-col gap-2">
                <div className="flex justify-between items-start">
                  <h3 className="text-lg font-black text-slate-800 dark:text-white tracking-tight leading-tight group-hover:text-green-600 transition-colors">
                    {plan.name}
                  </h3>
                  <div className="flex items-center gap-1.5 shrink-0 ml-4">
                    <span className="w-1 h-1 bg-slate-300 dark:bg-slate-600 rounded-full"></span>
                    <span className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">
                      {plan.duration}
                    </span>
                  </div>
                </div>

                <p className="text-xs text-slate-500 dark:text-slate-400 leading-relaxed mt-1 mb-4 line-clamp-2 italic font-medium">
                  {plan.description}
                </p>

                <Button 
                  onClick={() => onSelect(plan)} 
                  className="w-full h-12 rounded-2xl text-[11px] font-black uppercase tracking-widest shadow-lg shadow-green-500/10 hover:shadow-green-500/20 transition-all active:scale-95"
                >
                  Start this Meal
                </Button>

                <div className="flex justify-center gap-6 mt-3 px-2">
                  <button 
                    onClick={() => onViewDetails(plan)} 
                    className="text-[10px] font-black text-[#39C101] uppercase tracking-widest hover:opacity-80 transition-opacity"
                  >
                    View Plan Details
                  </button>
                  <button 
                    onClick={onEditPlan} 
                    className="text-[10px] font-black text-[#39C101] uppercase tracking-widest hover:opacity-80 transition-opacity"
                  >
                    Change Plan
                  </button>
                </div>
              </div>
            </div>
          ))
        ) : (
          <div className="text-center py-16 px-6 bg-slate-100/50 dark:bg-slate-800/50 rounded-[40px] border-2 border-dashed border-slate-200 dark:border-slate-700">
            <div className="text-4xl mb-4">🥗</div>
            <p className="text-slate-500 dark:text-slate-400 font-bold text-sm">No meal plans available at the moment.</p>
            <p className="text-slate-400 dark:text-slate-500 text-xs mt-1">Try checking back later.</p>
          </div>
        )}
      </div>

      <div className="mt-auto space-y-4 text-center pb-8">
        <Button variant="ghost" onClick={() => onSelect(null)} className="w-full text-slate-500 dark:text-slate-400 uppercase font-black text-[10px] tracking-widest">Skip for now</Button>
        <p className="text-slate-400 dark:text-slate-500 text-[9px] px-4 italic leading-relaxed">
          Unlock premium metabolic blueprints and AI-guided recipes anytime from your master dashboard.
        </p>
      </div>
    </div>
  );
};

export default PlanSelection;

import React, { useState, useMemo, useRef } from 'react';
import { UserProfile, MealPlan, Meal, MealAlternative, GamificationState, Recipe, DetectedFoodItem } from '../types';
import { Card, Button, BackButton } from '../components/UI';
import { generateMealAlternatives, generateRecipe, analyzeFoodImage } from '../services/geminiService';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  meals: Meal[];
  setMeals: React.Dispatch<React.SetStateAction<Meal[]>>;
  onExit: () => void;
  onViewInsights: () => void;
  onExplore: () => void;
  onViewGrocery: () => void;
  onViewPlanDetails: () => void;
  onEditPlan: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, meals, setMeals, onExit, onViewInsights, onExplore, onViewGrocery, onViewPlanDetails, onEditPlan }) => {
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [alternativeMeals, setAlternativeMeals] = useState<MealAlternative[]>([]);
  const [selectedMealForRecipe, setSelectedMealForRecipe] = useState<Meal | null>(null);
  const [recipeData, setRecipeData] = useState<Recipe | null>(null);
  const [loadingRecipe, setLoadingRecipe] = useState(false);
  const [loadingAlts, setLoadingAlts] = useState(false);

  // Logging flow states
  const [showLoggingOptions, setShowLoggingOptions] = useState<Meal | null>(null);
  const [isAnalyzingFood, setIsAnalyzingFood] = useState(false);
  const [detectedItems, setDetectedItems] = useState<DetectedFoodItem[]>([]);
  const [logTime, setLogTime] = useState<string>(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);
  const editFileInputRef = useRef<HTMLInputElement>(null);

  const [gamification] = useState<GamificationState>({
    points: 0,
    streak: 4,
    badges: [{ id: 'sync', name: 'Sync King', icon: '⌚', description: 'Connected a wearable device' }]
  });

  const weekDays = useMemo(() => {
    const today = new Date();
    const days = [];
    const start = new Date(today);
    start.setDate(today.getDate() - 3);

    for (let i = 0; i < 7; i++) {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      days.push({
        label: d.toLocaleDateString('en-US', { weekday: 'narrow' }),
        date: d.getDate(),
        isToday: d.toDateString() === today.toDateString(),
      });
    }
    return days;
  }, []);

  const totalConsumed = meals.reduce((sum, m) => m.isLogged ? sum + m.calories : sum, 0);
  const targetCals = plan.calories;
  const progressPercent = targetCals > 0 ? Math.round((totalConsumed / targetCals) * 100) : 0;

  const handleQuickLog = (mealId: string) => {
    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: true,
      isManual: false,
      loggedAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false })
    } : m));
    setShowLoggingOptions(null);
  };

  const handleSaveLog = (mealId: string, finalItems: DetectedFoodItem[]) => {
    const totalCals = finalItems.reduce((s, i) => s + i.calories, 0);
    const totalPro = finalItems.reduce((s, i) => s + i.protein, 0);
    const totalCarb = finalItems.reduce((s, i) => s + i.carbs, 0);
    const totalFat = finalItems.reduce((s, i) => s + i.fat, 0);

    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: true, 
      calories: totalCals,
      protein: totalPro,
      carbs: totalCarb,
      fat: totalFat,
      photoUri: tempPhoto || m.photoUri,
      loggedAt: logTime,
      manualItems: finalItems,
      // Only update name if it was a manual entry (camera/gallery)
      name: (m.isManual || (!m.isLogged && showLogModal?.isManual)) && finalItems.length > 0 ? finalItems.map(i => i.name).join(", ") : m.name
    } : m));

    setShowLogModal(null);
    setShowLoggingOptions(null);
    setTempPhoto(null);
    setDetectedItems([]);
  };

  const handleEditLog = (meal: Meal) => {
    const itemsToEdit = meal.manualItems && meal.manualItems.length > 0 
      ? [...meal.manualItems] 
      : [{ name: meal.name, calories: meal.calories, protein: meal.protein, carbs: meal.carbs, fat: meal.fat }];

    setDetectedItems(itemsToEdit);
    setTempPhoto(meal.photoUri || null);
    setLogTime(meal.loggedAt || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
    setShowLogModal(meal);
    setShowLoggingOptions(null);
  };

  const handleImageInput = async (e: React.ChangeEvent<HTMLInputElement>, meal: Meal | null, replaceOnly: boolean = false) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!replaceOnly) {
        setShowLoggingOptions(null);
        setIsAnalyzingFood(true);
      }

      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setTempPhoto(base64);

        if (!replaceOnly && meal) {
          try {
            const items = await analyzeFoodImage(base64);
            setDetectedItems(items);
            setLogTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
          } catch (err) {
            console.error("Analysis error:", err);
          } finally {
            setIsAnalyzingFood(false);
            setShowLogModal({ ...meal, isManual: true });
          }
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const updateDetectedItem = (index: number, field: keyof DetectedFoodItem, value: any) => {
    setDetectedItems(prev => {
      const copy = [...prev];
      copy[index] = { ...copy[index], [field]: field === 'name' ? value : Number(value) };
      return copy;
    });
  };

  const removeDetectedItem = (index: number) => {
    setDetectedItems(prev => prev.filter((_, i) => i !== index));
  };

  const openAlternative = async (meal: Meal) => {
    setSelectedMealForAlt(meal);
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setAlternativeMeals(alts);
    setLoadingAlts(false);
  };

  const handleSwapMeal = (alt: MealAlternative) => {
    if (!selectedMealForAlt) return;
    setMeals(prev => prev.map(m => m.id === selectedMealForAlt.id ? {
      ...m,
      name: alt.name,
      calories: alt.calories,
      protein: alt.protein,
      carbs: alt.carbs,
      fat: alt.fat,
      isLogged: false,
      manualItems: [{ name: alt.name, calories: alt.calories, protein: alt.protein, carbs: alt.carbs, fat: alt.fat }]
    } : m));
    setSelectedMealForAlt(null);
    setAlternativeMeals([]);
  };

  const openRecipe = async (meal: Meal) => {
    setSelectedMealForRecipe(meal);
    if (meal.apiRecipeDetail && (meal.apiRecipeDetail.description || (meal.apiRecipeDetail.instructions && meal.apiRecipeDetail.instructions.length > 0))) {
      setRecipeData({
        ingredients: [],
        instructions: meal.apiRecipeDetail.instructions || [],
        prepTime: meal.apiRecipeDetail.prepTime ? `${meal.apiRecipeDetail.prepTime}m` : '15m',
        cookTime: meal.apiRecipeDetail.cookTime ? `${meal.apiRecipeDetail.cookTime}m` : '15m'
      });
      return;
    }
    setLoadingRecipe(true);
    const recipe = await generateRecipe(meal.name, profile);
    setRecipeData(recipe);
    setLoadingRecipe(false);
  };

  return (
    <div className="flex-1 flex flex-col bg-[#F9FBFC] dark:bg-slate-900 overflow-hidden relative transition-colors duration-500">
      <div className="p-6 pt-2 bg-white dark:bg-slate-800 border-b border-slate-50 dark:border-slate-700 flex justify-between items-center z-10 transition-colors">
        <div className="flex items-center gap-3">
          <BackButton onClick={onExit} className="-ml-2 dark:text-slate-100" />
          <div className="flex flex-col">
            <h2 className="text-xl font-black text-slate-900 dark:text-white tracking-tight leading-none mb-0.5">NutriForge</h2>
            <div className="flex items-center gap-2">
              <span className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-wider">{plan.name}</span>
              <div className="w-1 h-1 bg-slate-200 dark:bg-slate-700 rounded-full"></div>
              <div className="flex items-center gap-1 text-orange-500 font-bold text-[10px] tracking-tight">
                <span>🔥</span> {gamification.streak} Day Streak
              </div>
            </div>
          </div>
        </div>
        <div className="flex flex-col items-end">
          <span className="text-[10px] text-[#A5B3C1] font-black uppercase tracking-widest leading-none mb-1">Target Energy</span>
          <span className="text-xl font-black text-slate-900 dark:text-white leading-none tracking-tight">{targetCals} kcal</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pb-32 no-scrollbar">
        <div className="px-6 py-4 flex gap-4 overflow-x-auto no-scrollbar bg-white dark:bg-slate-800 border-b border-slate-50 dark:border-slate-700 transition-colors">
          {weekDays.map((day, i) => (
            <div key={i} className={`flex-shrink-0 w-12 h-16 rounded-[20px] flex flex-col items-center justify-center gap-1.5 transition-all ${day.isToday ? 'bg-[#39C101] text-white shadow-lg shadow-[#39C101]/25' : 'text-[#A5B3C1] hover:text-slate-500'}`}>
              <span className="text-[11px] font-black uppercase tracking-tight">{day.label}</span>
              <span className="text-base font-black tracking-tighter">{day.date}</span>
            </div>
          ))}
        </div>

        <div className="px-6 py-6">
          <Card onClick={onViewInsights} className="bg-white dark:bg-slate-800 border-slate-100 shadow-sm relative overflow-hidden p-8 rounded-[32px] group cursor-pointer">
            <div className="flex justify-between items-start mb-8">
              <div className="space-y-1">
                <div className="flex items-center gap-1 group-hover:translate-x-0.5 transition-transform">
                  <span className="text-[11px] text-[#A5B3C1] font-black uppercase tracking-[0.15em]">Daily Energy</span>
                  <svg className="w-3.5 h-3.5 text-[#A5B3C1]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7"></path></svg>
                </div>
                <div className="flex items-baseline gap-2">
                  <span className="text-5xl font-black text-slate-900 dark:text-white tracking-tighter leading-none">{totalConsumed}</span>
                  <span className="text-base text-[#A5B3C1] font-bold">/ {targetCals || '---'} kcal</span>
                </div>
              </div>
              <div className="w-16 h-16 rounded-full border-[5px] border-slate-100 dark:border-slate-700 flex items-center justify-center relative shadow-inner">
                <svg className="w-full h-full absolute inset-0 -rotate-90">
                  <circle cx="32" cy="32" r="27.5" fill="transparent" stroke="currentColor" strokeWidth="5" className="text-slate-50 dark:text-slate-700/50"/>
                  <circle cx="32" cy="32" r="27.5" fill="transparent" stroke="currentColor" strokeWidth="5" className="text-[#39C101]" strokeDasharray="172.7" strokeDashoffset={172.7 - (172.7 * (progressPercent / 100))} strokeLinecap="round" style={{ transition: 'stroke-dashoffset 1s ease-in-out' }} />
                </svg>
                <span className="text-xs font-black text-slate-900 dark:text-white">{progressPercent}%</span>
              </div>
            </div>
            <div className="w-full h-4 bg-slate-50 dark:bg-slate-900/50 rounded-full overflow-hidden relative shadow-inner">
               <div className="h-full bg-slate-900 dark:bg-white rounded-full transition-all duration-1000 ease-out" style={{ width: `${Math.min(progressPercent, 100)}%` }} />
            </div>
          </Card>
          <div className="flex justify-center gap-8 mt-4 px-2">
            <button onClick={onViewPlanDetails} className="text-[11px] font-black text-[#39C101] uppercase tracking-widest hover:opacity-80 transition-opacity">View Plan Details</button>
            <button onClick={onEditPlan} className="text-[11px] font-black text-[#39C101] uppercase tracking-widest hover:opacity-80 transition-opacity">Change Plan</button>
          </div>
        </div>

        <div className="px-6 space-y-6">
          <h3 className="text-[12px] font-black text-[#A5B3C1] uppercase tracking-[0.2em] mb-4 pl-1">Today's Meals</h3>
          {meals.map(meal => (
            <div key={meal.id} className="bg-white dark:bg-slate-800 rounded-[40px] p-7 shadow-sm border border-slate-50 dark:border-slate-700 relative group overflow-hidden transition-all hover:shadow-xl hover:shadow-slate-200/50">
              <button 
                onClick={() => {
                  if (meal.isLogged) {
                    handleEditLog(meal);
                  } else {
                    setShowLoggingOptions(meal);
                  }
                }}
                className={`absolute top-7 right-7 w-12 h-12 rounded-full border-2 flex items-center justify-center transition-all ${meal.isLogged ? 'bg-[#39C101] border-[#39C101] shadow-xl shadow-[#39C101]/30' : 'bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 shadow-sm'}`}
              >
                {meal.isLogged ? (
                  <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>
                ) : (
                  <svg className="w-6 h-6 text-[#39C101]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"></path></svg>
                )}
              </button>

              <div className="flex flex-col gap-1.5 mb-8 pr-16">
                <div className="flex items-center gap-2">
                  <span className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-[0.2em]">{meal.type}</span>
                  {meal.isLogged && meal.isManual && (
                    <span className="text-[9px] font-black text-white bg-[#39C101] px-2 py-0.5 rounded-full uppercase tracking-widest shadow-sm shadow-[#39C101]/30">Logged manually</span>
                  )}
                  {meal.loggedAt && (
                    <span className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest ml-1">{meal.loggedAt}</span>
                  )}
                </div>
                <div className="flex items-center gap-3">
                  {meal.photoUri && (
                    <div className="w-10 h-10 rounded-xl overflow-hidden shrink-0 border border-slate-100 dark:border-slate-700 shadow-sm">
                      <img src={meal.photoUri} className="w-full h-full object-cover" alt="" />
                    </div>
                  )}
                  <h4 className="text-xl font-black text-slate-900 dark:text-white leading-tight tracking-tight">{meal.name}</h4>
                </div>
                <span className="text-xs font-bold text-[#A5B3C1]">{meal.calories} kcal</span>
              </div>

              <div className="flex gap-4">
                <button onClick={() => openRecipe(meal)} className="flex-1 py-4 px-4 rounded-[20px] border-2 border-[#E9EEF2] dark:border-slate-700 text-[12px] font-black text-[#39C101] uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-all active:scale-95 shadow-sm bg-white dark:bg-slate-800">Recipe</button>
                <button onClick={() => openAlternative(meal)} className="flex-1 py-4 px-4 rounded-[20px] border-2 border-[#E9EEF2] dark:border-slate-700 text-[12px] font-black text-[#39C101] uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-all active:scale-95 shadow-sm bg-white dark:bg-slate-800">Swap</button>
                <button 
                  onClick={() => {
                    if (meal.isLogged) {
                      handleEditLog(meal);
                    } else {
                      setShowLoggingOptions(meal);
                    }
                  }}
                  className={`flex-1 py-4 px-4 rounded-[20px] text-[12px] font-black uppercase tracking-widest transition-all active:scale-95 shadow-xl ${meal.isLogged ? 'bg-[#39C101] text-white shadow-[#39C101]/25 hover:bg-[#32aa01]' : 'bg-green-500 text-white shadow-green-500/20'}`}
                >
                  {meal.isLogged ? 'Edit Log' : 'Log'}
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {showLoggingOptions && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[110] flex flex-col justify-end" onClick={() => setShowLoggingOptions(null)}>
          <div className="bg-white dark:bg-slate-900 rounded-t-[48px] p-10 animate-in slide-in-from-bottom duration-500 shadow-2xl" onClick={e => e.stopPropagation()}>
            <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mx-auto mb-8"></div>
            <div className="flex justify-between items-center mb-10">
              <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight leading-none uppercase">Log {showLoggingOptions.type}</h3>
              <button onClick={() => setShowLoggingOptions(null)} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full hover:bg-slate-200 transition-colors">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            <div className="space-y-4">
              <button onClick={() => handleQuickLog(showLoggingOptions.id)} className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 transition-all active:scale-95">
                <div className="flex items-center gap-5">
                  <div className="w-12 h-12 bg-[#39C101]/10 rounded-2xl flex items-center justify-center text-[#39C101]"><svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path d="M9 2a1 1 0 000 2h2a1 1 0 100-2H9z" /><path fillRule="evenodd" d="M4 5a2 2 0 012-2 3 3 0 003 3h2a3 3 0 003-3 2 2 0 012 2v11a2 2 0 01-2 2H6a2 2 0 01-2-2V5zm3 4a1 1 0 000 2h.01a1 1 0 100-2H7zm3 0a1 1 0 000 2h3a1 1 0 100-2h-3zm-3 4a1 1 0 100 2h.01a1 1 0 100-2H7zm3 0a1 1 0 100 2h3a1 1 0 100-2h-3z" clipRule="evenodd" /></svg></div>
                  <div className="text-left">
                    <span className="block font-black text-slate-900 dark:text-white uppercase text-sm tracking-tight">Select from My Plan</span>
                    <span className="text-[10px] text-[#A5B3C1] font-bold uppercase tracking-widest leading-none">Standard metabolic entry</span>
                  </div>
                </div>
