                ))}
              </div>
            ) : null}
            <Button onClick={() => {setSelectedMealForAlt(null); setAlternativeMeals([]);}} className="w-full h-16 rounded-[24px]" variant="ghost">Cancel Swap</Button>
          </div>
        </div>
      )}

      {selectedMealForRecipe && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[110] flex flex-col justify-end" onClick={() => setSelectedMealForRecipe(null)}>
           <div className="bg-white dark:bg-slate-900 rounded-t-[48px] p-8 max-h-[85%] overflow-y-auto shadow-2xl animate-in slide-in-from-bottom duration-500 no-scrollbar" onClick={e => e.stopPropagation()}>
            <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mx-auto mb-8"></div>
            <div className="flex justify-between items-start mb-8">
              <div className="space-y-1">
                <span className="text-[10px] font-black text-[#39C101] uppercase tracking-[0.2em]">Culinary Blueprint</span>
                <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight leading-tight">{selectedMealForRecipe.name}</h3>
              </div>
              <button onClick={() => setSelectedMealForRecipe(null)} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            {loadingRecipe ? (
              <div className="py-20 text-center">
                <div className="w-12 h-12 border-4 border-[#39C101] border-t-transparent rounded-full animate-spin mx-auto mb-6"></div>
                <p className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-[0.2em]">Decrypting Recipe Intel...</p>
              </div>
            ) : recipeData ? (
              <div className="space-y-8">
                <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl flex flex-col items-center justify-center text-center">
