        <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl border border-slate-100 dark:border-slate-800 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h3 className="font-bold text-slate-800 dark:text-white">Macronutrient Budget</h3>
              <p className={`text-[10px] font-bold uppercase tracking-wider ${totalMacro === 100 ? 'text-slate-400' : 'text-red-500'}`}>
                Total Macronutrient Budget = {totalMacro}%
              </p>
            </div>
          </div>

          <div className="space-y-6">
            <BudgetRow 
              icon="🍞" 
              label="Carbs" 
              value={`${calcGrams(macros.carbs, 4)} g`} 
              percentage={macros.carbs} 
              onUpdate={(d) => handleUpdateMacro('carbs', d)} 
            />
            <BudgetRow 
              icon="🍗" 
              label="Protein" 
              value={`${calcGrams(macros.protein, 4)} g`} 
              percentage={macros.protein} 
              onUpdate={(d) => handleUpdateMacro('protein', d)} 
            />
            <BudgetRow 
              icon="🧀" 
              label="Fat" 
              value={`${calcGrams(macros.fat, 9)} g`} 
              percentage={macros.fat} 
              onUpdate={(d) => handleUpdateMacro('fat', d)} 
            />
          </div>

          <div className="mt-6 pt-4 border-t border-slate-50 dark:border-slate-800 flex justify-between items-center">
            <span className="text-[10px] font-bold text-slate-400 uppercase">Recommended % = 40:30:30</span>
            <span className="text-[10px] font-bold text-green-500 uppercase cursor-pointer">Learn More</span>
          </div>
        </div>

        {/* Meal Split Budget Section */}
        <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl border border-slate-100 dark:border-slate-800 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h3 className="font-bold text-slate-800 dark:text-white">Meal Split Budget</h3>
              <p className={`text-[10px] font-bold uppercase tracking-wider ${totalSplit === 100 ? 'text-slate-400' : 'text-red-500'}`}>
                Total Meal Split Budget = {totalSplit}%
              </p>
            </div>
          </div>

          <div className="space-y-6">
            <BudgetRow 
              icon="☕" 
              label="Breakfast" 
              value={`${calcCals(splits.breakfast)} cal`} 
              percentage={splits.breakfast} 
              onUpdate={(d) => handleUpdateSplit('breakfast', d)} 
            />
            <BudgetRow 
              icon="🍲" 
              label="Lunch" 
              value={`${calcCals(splits.lunch)} cal`} 
              percentage={splits.lunch} 
              onUpdate={(d) => handleUpdateSplit('lunch', d)} 
            />
            <BudgetRow 
              icon="🍽️" 
              label="Dinner" 
              value={`${calcCals(splits.dinner)} cal`} 
              percentage={splits.dinner} 
              onUpdate={(d) => handleUpdateSplit('dinner', d)} 
            />
            <BudgetRow 
              icon="🍎" 
              label="Snacks" 
              value={`${calcCals(splits.snack)} cal`} 
              percentage={splits.snack} 
              onUpdate={(d) => handleUpdateSplit('snack', d)} 
            />
          </div>

          <div className="mt-6 pt-4 border-t border-slate-50 dark:border-slate-800 flex justify-between items-center">
            <span className="text-[10px] font-bold text-slate-400 uppercase">Recommended % = 25:35:20:20</span>
            <span className="text-[10px] font-bold text-green-500 uppercase cursor-pointer">Learn More</span>
          </div>
        </div>
      </div>

      {/* Footer Save Button */}
      <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-t border-slate-100 dark:border-slate-800 z-40">
        <Button 
          disabled={totalMacro !== 100 || totalSplit !== 100}
          onClick={() => onSelect?.({...plan, calories: budget})} 
          className="w-full h-14 rounded-full bg-[#39C101] text-white font-black uppercase text-sm tracking-widest shadow-xl shadow-green-500/20"
        >
          Save & Start Plan
        </Button>
      </div>
    </div>
  );
};

const BudgetRow: React.FC<{ 
  icon: string; 
  label: string; 
  value: string; 
  percentage: number; 
  onUpdate: (d: number) => void;
}> = ({ icon, label, value, percentage, onUpdate }) => (
  <div className="flex items-center justify-between">
    <div className="flex items-center gap-4">
      <div className="w-12 h-12 rounded-full border border-slate-100 dark:border-slate-800 flex items-center justify-center text-xl bg-slate-50 dark:bg-slate-800/50">
        {icon}
