}

export interface PlanReasoning {
  nutrientTiming: string;
  micronutrientFocus: string;
  foodSynergyTips: string;
}

export interface GamificationState {
  points: number;
  streak: number;
  badges: Badge[];
}

export interface Badge {
  id: string;
  name: string;
  icon: string;
  description: string;
  dateEarned?: string;
}

