      {selectedMealForRecipe && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-[110] flex flex-col justify-end" onClick={() => setSelectedMealForRecipe(null)}>
           <div className="bg-white dark:bg-slate-900 rounded-t-[48px] p-8 max-h-[85%] overflow-y-auto shadow-2xl animate-in slide-in-from-bottom duration-500 no-scrollbar" onClick={e => e.stopPropagation()}>
            <div className="w-12 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mx-auto mb-8"></div>
            <div className="flex justify-between items-start mb-8">
              <div className="space-y-1">
                <span className="text-[10px] font-black text-[#39C101] uppercase tracking-[0.2em]">Culinary Blueprint</span>
                <h3 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight leading-tight">{selectedMealForRecipe.name}</h3>
              </div>
              <button onClick={() => setSelectedMealForRecipe(null)} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full">
                <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"></path></svg>
              </button>
            </div>
            {loadingRecipe ? (
              <div className="py-20 text-center">
                <div className="w-12 h-12 border-4 border-[#39C101] border-t-transparent rounded-full animate-spin mx-auto mb-6"></div>
                <p className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-[0.2em]">Decrypting Recipe Intel...</p>
              </div>
            ) : recipeData ? (
              <div className="space-y-8">
                <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl flex flex-col items-center justify-center text-center">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Prep Time</span>
                    <span className="text-sm font-black text-slate-800 dark:text-white">{recipeData.prepTime}</span>
                  </div>
                  <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl flex flex-col items-center justify-center text-center">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Cook Time</span>
                    <span className="text-sm font-black text-slate-800 dark:text-white">{recipeData.cookTime}</span>
                  </div>
                </div>
                <div className="space-y-6">
                  <h4 className="text-sm font-black text-slate-900 dark:text-white uppercase tracking-widest border-l-4 border-[#39C101] pl-3">Instructions</h4>
                  <div className="space-y-6">
                    {recipeData.instructions.map((step, i) => (
                      <div key={i} className="flex gap-4">
                        <span className="flex-shrink-0 w-8 h-8 bg-[#39C101] text-white rounded-xl flex items-center justify-center text-xs font-black">{i + 1}</span>
                        <p className="text-sm text-slate-600 dark:text-slate-300 leading-relaxed font-medium">{step}</p>
                      </div>
                    ))}
                  </div>
                </div>
                <Button onClick={() => setSelectedMealForRecipe(null)} className="w-full h-16 rounded-[24px]">Done</Button>
              </div>
            ) : null}
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React from 'react';
import { BackButton, ProgressBar, Card } from '../components/UI';
import { Meal } from '../types';

interface InsightsProps {
  onBack: () => void;
  meals: Meal[];
  targetCalories: number;
}

const Insights: React.FC<InsightsProps> = ({ onBack, meals, targetCalories }) => {
  // Exclude skipped meals from the intake calculation
  const loggedMeals = meals.filter(m => m.isLogged && !m.isSkipped);

  const totalMacros = loggedMeals.reduce((acc, meal) => ({
    calories: acc.calories + meal.calories,
    protein: acc.protein + meal.protein,
    carbs: acc.carbs + meal.carbs,
    fat: acc.fat + meal.fat,
  }), { calories: 0, protein: 0, carbs: 0, fat: 0 });

  const totalGrams = totalMacros.protein + totalMacros.carbs + totalMacros.fat || 1;
  const pPct = Math.round((totalMacros.protein / totalGrams) * 100);
  const cPct = Math.round((totalMacros.carbs / totalGrams) * 100);
  const fPct = 100 - pPct - cPct;

  // Mock targets based on the image
  const targets = {
    calories: targetCalories,
    carbs: 313,
    fat: 319,
    protein: 313,
    fiber: 30,
  };

  return (
    <div className="flex-1 flex flex-col bg-white overflow-y-auto pb-24">
      <div className="p-6 pt-2 flex items-center gap-4 border-b border-slate-50 sticky top-0 bg-white/90 backdrop-blur-md z-20">
        <BackButton onClick={onBack} className="-ml-2" />
        <h1 className="text-xl font-bold text-slate-800 tracking-tight">Daily Insights</h1>
      </div>

      <div className="p-6 space-y-8">
        {/* Pie Chart Simulation */}
        <div className="flex flex-col items-center">
          <div className="relative w-48 h-48 rounded-full border-[12px] border-white shadow-xl overflow-hidden flex items-center justify-center bg-slate-50">
             <div 
               className="absolute inset-0"
               style={{
                 background: `conic-gradient(
                   #8c71d6 0% ${pPct}%, 
                   #f5b61a ${pPct}% ${pPct + fPct}%, 
                   #26b1b5 ${pPct + fPct}% 100%
                 )`
               }}
             />
             <div className="absolute inset-0 flex items-center justify-center">
               <div className="w-32 h-32 bg-white rounded-full flex flex-col items-center justify-center shadow-inner">
                 <span className="text-xs font-black text-slate-400 uppercase">Macros</span>
                 <span className="text-xl font-black text-slate-800">{totalMacros.calories}</span>
               </div>
             </div>

             {/* Labels Overlay */}
             <div className="absolute top-6 right-6 text-[10px] font-black text-white drop-shadow-sm text-center">
               Protein<br/>{pPct}%
             </div>
             <div className="absolute bottom-10 right-10 text-[10px] font-black text-white drop-shadow-sm text-center">
               Fats<br/>{fPct}%
             </div>
             <div className="absolute top-1/2 left-8 -translate-y-1/2 text-[10px] font-black text-white drop-shadow-sm text-center">
               Carbs<br/>{cPct}%
             </div>
          </div>
        </div>

        {/* Nutrition Targets Section */}
        <section className="space-y-6">
          <h3 className="text-sm font-bold text-slate-500 border-b border-slate-100 pb-2">Nutrition Targets</h3>

          <div className="grid grid-cols-3 text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">
            <span>Nutrition</span>
            <span className="text-center">Today's Intake</span>
            <span className="text-right">Targets</span>
          </div>

          <div className="space-y-5">
            <NutrientRow label="Calories" current={totalMacros.calories} target={targets.calories} unit="" color="bg-orange-500" />
            <NutrientRow label="Carbs" current={totalMacros.carbs} target={targets.carbs} unit="g" color="bg-[#26b1b5]" />
            <NutrientRow label="Fat" current={totalMacros.fat} target={targets.fat} unit="g" color="bg-[#f5b61a]" />
            <NutrientRow label="Protein" current={totalMacros.protein} target={targets.protein} unit="g" color="bg-[#8c71d6]" />
            <NutrientRow label="Fiber" current={18} target={targets.fiber} unit="g" color="bg-cyan-400" />
          </div>
        </section>

        {/* List Breakdown */}
        <section className="space-y-3 pt-4">
          <DetailRow label="Net Carbs" value="213g" />
          <DetailRow label="Sodium" value="864mg" />
          <DetailRow label="Potassium" value="3957mg" />
          <div className="border-t border-slate-100 border-dashed my-2"></div>
          <DetailRow label="Cholesterol" value="162mg" />
        </section>

        {/* Sugar Section */}
        <section className="space-y-4 pt-4">
          <div className="flex justify-between items-center text-xs font-bold text-slate-500 border-b border-slate-100 pb-2">
            <span>Sugar</span>
            <span>%DV</span>
          </div>
          <DetailRow label="Sugar" value="103g" />
          <DetailRow label="Sucrose" value="11.3g" />
          <DetailRow label="Glucose" value="46.2g" />
        </section>
      </div>
    </div>
  );
};

