          </div>
        </div>
        <div className="flex flex-col items-end">
          <span className="text-[10px] text-[#A5B3C1] font-black uppercase tracking-widest leading-none mb-1">Target Energy</span>
          <span className="text-xl font-black text-slate-900 dark:text-white leading-none tracking-tight">{targetCals} kcal</span>
        </div>
