                    className={`flex-1 min-w-[100px] py-4 px-4 rounded-[20px] text-[12px] font-black uppercase tracking-widest transition-all active:scale-95 shadow-xl ${meal.isLogged ? 'bg-[#39C101] text-white shadow-[#39C101]/25 hover:bg-[#32aa01]' : 'bg-green-500 text-white shadow-green-500/20'}`}
                  >
                    {meal.isLogged ? 'Edit Log' : 'Log'}
                  </button>
