                    className={`absolute top-7 right-7 w-12 h-12 rounded-full border-2 flex items-center justify-center transition-all ${meal.isLogged ? 'bg-[#39C101] border-[#39C101] shadow-xl shadow-[#39C101]/30' : 'bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 shadow-sm'}`}
                  >
                    {meal.isLogged ? (
                      <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>
                    ) : (
                      <svg className="w-6 h-6 text-[#39C101]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"></path></svg>
                    )}
                  </button>
                )}
                <div className="flex flex-col gap-1.5 pr-16 mb-6">
                  <div className="flex items-center gap-2">
                    <span className="text-[11px] font-black text-[#A5B3C1] uppercase tracking-[0.2em]">{meal.type}</span>
                    {meal.isSkipped && (
                      <span className="text-[9px] font-black text-white bg-slate-500 dark:bg-slate-600 px-3 py-1 rounded-full uppercase tracking-widest shadow-sm">Skipped</span>
                    )}
                  </div>
                  <div className="flex items-center gap-3">
                    {meal.photoUri && (
                      <div className="w-10 h-10 rounded-xl overflow-hidden shrink-0 border border-slate-100 dark:border-slate-700">
                        <img src={meal.photoUri} className="w-full h-full object-cover" alt="" />
                      </div>
                    )}
                    <h4 className={`text-xl font-black transition-colors ${meal.isSkipped ? 'text-slate-400 dark:text-slate-500' : 'text-slate-900 dark:text-white'} leading-tight tracking-tight`}>{meal.name}</h4>
                  </div>
                  <span className="text-xs font-bold text-[#A5B3C1]">{meal.isSkipped ? 0 : meal.calories} kcal</span>
                </div>
                {meal.isSkipped ? (
                  <div className="w-full flex justify-center py-2 animate-in fade-in zoom-in-95 duration-500">
                    <div className="text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-[0.4em] bg-white dark:bg-slate-800 px-14 py-4 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm">
                      Skipped
                    </div>
                  </div>
                ) : (
                  <div className="flex gap-4">
                    <button onClick={() => openAlternative(meal)} className="flex-1 py-4 px-4 rounded-[20px] border-2 border-[#E9EEF2] dark:border-slate-700 text-[12px] font-black text-[#39C101] uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-all active:scale-95 shadow-sm bg-white dark:bg-slate-800">Swap</button>
                    <button onClick={() => handleSkipMeal(meal.id)} className="flex-1 py-4 px-4 rounded-[20px] border-2 border-[#E9EEF2] dark:border-slate-700 text-[12px] font-black text-red-500 uppercase tracking-widest hover:bg-red-50 dark:hover:bg-red-900/10 transition-all active:scale-95 shadow-sm bg-white dark:bg-slate-800">Skip</button>
                    <button 
                      onClick={() => {
                        if (meal.isLogged) {
                          handleEditLog(meal);
                        } else {
                          setShowLoggingOptions(meal);
                        }
                      }}
                      className={`flex-1 py-4 px-4 rounded-[20px] text-[12px] font-black uppercase tracking-widest transition-all active:scale-95 shadow-xl ${meal.isLogged ? 'bg-[#39C101] text-white shadow-[#39C101]/25 hover:bg-[#32aa01]' : 'bg-green-500 text-white shadow-green-500/20'}`}
