                    <span className="text-[9px] font-black text-white bg-slate-500 dark:bg-slate-600 px-3 py-1 rounded-full uppercase tracking-widest shadow-sm">Skipped</span>
                  )}
                  {meal.isLogged && !meal.isSkipped && meal.isManual && (
                    <span className="text-[9px] font-black text-white bg-[#39C101] px-2 py-0.5 rounded-full uppercase tracking-widest shadow-sm shadow-[#39C101]/30">Logged manually</span>
                  )}
                  {meal.loggedAt && !meal.isSkipped && (
                    <span className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest ml-1">{meal.loggedAt}</span>
