                  <button onClick={() => openAlternative(meal)} className={`flex-1 min-w-[80px] py-4 px-4 ${Layout.innerRadius} border-2 border-[#E9EEF2] dark:border-slate-700 text-[12px] font-black text-[#39C101] uppercase tracking-widest hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-all active:scale-95 shadow-sm bg-white dark:bg-slate-800`}>Swap</button>
                  <button onClick={() => handleSkipMeal(meal.id)} className={`flex-1 min-w-[80px] py-4 px-4 ${Layout.innerRadius} border-2 border-[#E9EEF2] dark:border-slate-700 text-[12px] font-black text-red-500 uppercase tracking-widest hover:bg-red-50 dark:hover:bg-red-900/10 transition-all active:scale-95 shadow-sm bg-white dark:bg-slate-800`}>Skip</button>
