              <button onClick={() => galleryInputRef.current?.click()} className={`w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-slate-800 rounded-[32px] border-2 border-[#F1F5F9] dark:border-slate-700 hover:border-[#39C101]/50 transition-all active:scale-95`}>
