}> = ({ children, className = '', onClick }) => (
  <div 
    onClick={onClick}
    className={`${GlobalStyles.card} ${onClick ? 'cursor-pointer hover:shadow-xl hover:shadow-slate-200/50 active:scale-[0.99]' : ''} ${className}`}
