import React, { useState, useEffect } from 'react';
import { UserProfile, HealthGoal, Cuisine, MealFrequency, DietPreference } from '../types';
import { Button, ProgressBar, BackButton } from '../components/UI';
import { Colors, Typography, Layout } from '../theme/goqiiDesignSystem';

interface OnboardingProps {
  onComplete: (data: UserProfile) => void;
}

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(0);
  const [formData, setFormData] = useState<UserProfile>({
    language: 'English',
    healthGoal: HealthGoal.WeightLoss,
    cuisine: Cuisine.Indian,
    mealFrequency: MealFrequency.ThreePlusSnacks,
    dietPreference: DietPreference.Vegetarian,
    allergies: [],
    challenges: [],
  });

  const totalSteps = 8;

  useEffect(() => {
    if (step === 7) {
      const timer = setTimeout(() => {
        onComplete(formData);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [step, formData, onComplete]);

  const next = () => {
    if (step < totalSteps - 1) {
      setStep(s => s + 1);
    }
  };

  const back = () => {
    if (step > 0) {
      setStep(s => s - 1);
    }
  };

  const toggleItem = (list: string[], item: string, key: keyof UserProfile) => {
    let newList: string[];
    if (item === 'None') {
      newList = ['None'];
    } else {
      newList = list.filter(i => i !== 'None');
      newList = newList.includes(item) 
        ? newList.filter(i => i !== item) 
        : [...newList, item];
    }
    setFormData(prev => ({ ...prev, [key]: newList }));
  };

  const renderStep = () => {
    switch (step) {
      case 0:
        return (
          <div className="absolute inset-0 flex flex-col justify-end overflow-hidden">
            <div className="absolute inset-0 z-0">
              <img 
                src="https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&q=80&w=1000" 
                alt="Healthy Food" 
                className="w-full h-full object-cover scale-105 animate-pulse-slow"
                style={{ animationDuration: '8s' }}
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent"></div>
            </div>
            <div className="relative z-10 p-8 pb-16 text-center space-y-6 animate-in slide-in-from-bottom-8 duration-1000">
              <div className="space-y-3">
                <h1 className={`${Typography.h1} ${Typography.Black} text-white leading-[1.1]`}>
                  Nutrition That Understands Your Body
                </h1>
                <p className={`text-slate-200 ${Typography.bodyBold} px-4 opacity-90`}>
                  Powered by food science, genetics & lifestyle data
                </p>
              </div>
              <div className="pt-4">
                <button 
                  onClick={next} 
                  className={`w-full bg-[#39C101] hover:bg-[#32aa01] text-white font-bold py-5 px-8 ${Layout.fullRadius} shadow-none transition-all active:scale-95 text-lg flex items-center justify-center gap-2`}
                >
                  Personalise My Nutrition
                </button>
              </div>
            </div>
          </div>
        );

      case 1:
        const goalIcons: Record<string, string> = {
          [HealthGoal.WeightLoss]: '⚖️',
          [HealthGoal.MuscleGain]: '💪',
          [HealthGoal.HeartHealth]: '❤️',
          [HealthGoal.Energy]: '⚡',
          [HealthGoal.BalancedLifestyle]: '🧘',
        };
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2" />
            <h2 className={`${Typography.h2} ${Typography.Black} text-[#0F172A] dark:text-white mb-6`}>What's your primary health goal?</h2>
            <div className="space-y-3">
              {Object.values(HealthGoal).map(goal => (
                <div 
                  key={goal} 
                  onClick={() => { setFormData({...formData, healthGoal: goal}); next(); }}
                  className={`transition-all border-2 ${Layout.radius} p-4 cursor-pointer flex items-center gap-4 ${formData.healthGoal === goal ? 'border-[#39C101] bg-green-50 dark:bg-green-950/20' : 'border-[#F1F5F9] dark:border-slate-800 bg-white'}`}
                >
                  <div className={`w-12 h-12 ${Layout.radius} flex items-center justify-center text-2xl ${formData.healthGoal === goal ? 'bg-green-100 dark:bg-green-900/40' : 'bg-slate-100 dark:bg-slate-800'}`}>
                    {goalIcons[goal]}
                  </div>
                  <div className="flex-1">
                    <span className={`${Typography.bodyBold} text-[#0F172A] dark:text-white block`}>{goal}</span>
                  </div>
                  {formData.healthGoal === goal && (
                    <div className="w-6 h-6 bg-[#39C101] rounded-full flex items-center justify-center">
                      <svg className="w-4 h-4 text-white" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        );

      case 2:
        const cuisineIcons: Record<string, string> = {
          [Cuisine.Indian]: '🍛',
          [Cuisine.Mediterranean]: '🥗',
          [Cuisine.Asian]: '🥢',
          [Cuisine.MiddleEastern]: '🥙',
          [Cuisine.Western]: '🍔',
          [Cuisine.Mixed]: '🍱',
        };
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2" />
            <h2 className={`${Typography.h2} ${Typography.Black} text-[#0F172A] dark:text-white mb-6`}>Cuisine Preference</h2>
            <div className="grid grid-cols-2 gap-3">
              {Object.values(Cuisine).map(c => (
                <div 
                  key={c} 
                  onClick={() => { setFormData({...formData, cuisine: c}); next(); }}
                  className={`transition-all border-2 ${Layout.radius} p-6 text-center flex flex-col items-center gap-3 cursor-pointer ${formData.cuisine === c ? 'border-[#39C101] bg-green-50 dark:bg-green-950/20' : 'border-[#F1F5F9] dark:border-slate-800 bg-white'}`}
                >
                  <span className="text-3xl">{cuisineIcons[c]}</span>
                  <span className={`${Typography.bodyBold} text-[#0F172A] dark:text-white text-sm`}>{c}</span>
                </div>
              ))}
            </div>
          </div>
        );

      case 3:
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2" />
            <h2 className={`${Typography.h2} ${Typography.Black} text-[#0F172A] dark:text-white mb-6`}>Meals Per Day</h2>
            <div className="space-y-3">
              {Object.values(MealFrequency).map(f => (
                <div 
                  key={f} 
                  onClick={() => { setFormData({...formData, mealFrequency: f}); next(); }}
                  className={`transition-all border-2 ${Layout.radius} p-4 cursor-pointer ${formData.mealFrequency === f ? 'border-[#39C101] bg-green-50 dark:bg-green-950/20' : 'border-[#F1F5F9] dark:border-slate-800 bg-white'}`}
                >
                  <span className={`${Typography.bodyBold} text-[#0F172A] dark:text-white`}>{f}</span>
                </div>
              ))}
            </div>
          </div>
        );

      case 4:
        const dietIcons: Record<string, string> = {
          [DietPreference.Vegetarian]: '🥦',
          [DietPreference.Vegan]: '🌿',
          [DietPreference.Eggetarian]: '🥚',
          [DietPreference.NonVegetarian]: '🍗',
          [DietPreference.OpenToAll]: '🥘',
          [DietPreference.Keto]: '🥓',
          [DietPreference.Balanced]: '⚖️',
        };
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2" />
            <h2 className={`${Typography.h2} ${Typography.Black} text-[#0F172A] dark:text-white mb-6`}>Dietary Preference</h2>
            <div className="space-y-3">
              {Object.values(DietPreference).map((type) => (
                <div 
                  key={type} 
                  onClick={() => { setFormData({...formData, dietPreference: type}); next(); }}
                  className={`transition-all border-2 ${Layout.radius} p-4 cursor-pointer flex items-center gap-4 ${formData.dietPreference === type ? 'border-[#39C101] bg-green-50 dark:bg-green-950/20' : 'border-[#F1F5F9] dark:border-slate-800 bg-white'}`}
                >
                  <span className="text-2xl">{dietIcons[type]}</span>
                  <span className={`${Typography.bodyBold} text-[#0F172A] dark:text-white flex-1`}>{type}</span>
                  {formData.dietPreference === type && <div className="w-2 h-2 rounded-full bg-[#39C101]"></div>}
                </div>
              ))}
            </div>
          </div>
        );

      case 5:
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2" />
            <h2 className={`${Typography.h2} ${Typography.Black} text-[#0F172A] dark:text-white mb-2`}>Any Allergies?</h2>
            <p className={`${Typography.body} text-[#64748B] mb-4`}>We'll exclude these from your recipes.</p>
            <div className="grid grid-cols-2 gap-3">
              {['Nuts', 'Dairy', 'Gluten', 'Seafood', 'Eggs', 'None'].map((opt) => (
                <div 
                  key={opt} 
                  onClick={() => toggleItem(formData.allergies, opt, 'allergies')}
                  className={`transition-all border-2 ${Layout.radius} p-4 text-center cursor-pointer ${formData.allergies.includes(opt) ? 'border-[#39C101] bg-green-50 dark:bg-green-950/20' : 'border-[#F1F5F9] dark:border-slate-800 bg-white'}`}
                >
                  <span className={`${Typography.bodyBold} text-[#0F172A] dark:text-white text-sm`}>{opt}</span>
                </div>
              ))}
            </div>
            <div className="pt-4">
              <Button 
                disabled={formData.allergies.length === 0}
                onClick={next}
                className="w-full h-14"
              >
                Continue
              </Button>
            </div>
          </div>
        );

      case 6:
        return (
          <div className="space-y-4 pt-4">
            <BackButton onClick={back} className="mb-2 -ml-2" />
            <h2 className={`${Typography.h2} ${Typography.Black} text-[#0F172A] dark:text-white mb-2`}>Challenging Foods?</h2>
            <p className={`${Typography.body} text-[#64748B] mb-4`}>Areas where you struggle most.</p>
            <div className="space-y-3">
              {['Sugar', 'Fried Foods', 'Late-night Snacking', 'Portions', 'Emotional Eating'].map(c => (
                <div 
                  key={c} 
                  onClick={() => toggleItem(formData.challenges, c, 'challenges')}
                  className={`transition-all border-2 ${Layout.radius} p-4 cursor-pointer ${formData.challenges.includes(c) ? 'border-[#39C101] bg-green-50 dark:bg-green-950/20' : 'border-[#F1F5F9] dark:border-slate-800 bg-white'}`}
                >
                  <span className={`${Typography.bodyBold} text-[#0F172A] dark:text-white`}>{c}</span>
                </div>
              ))}
            </div>
            <Button onClick={next} className="w-full mt-6 h-14">Build My Plan</Button>
          </div>
        );

      case 7:
        return (
          <div className="flex flex-col items-center justify-center space-y-8 py-20 px-8 text-center h-full">
            <div className="relative w-32 h-32">
              <div className={`absolute inset-0 border-4 border-[#F1F5F9] dark:border-slate-800 rounded-full`}></div>
              <div className={`absolute inset-0 border-4 border-[#39C101] rounded-full border-t-transparent animate-spin`}></div>
            </div>
            <div className="space-y-3">
              <h2 className={`${Typography.h2} ${Typography.Black} text-[#0F172A] dark:text-white animate-pulse`}>NutriForge is Thinking...</h2>
              <p className={`${Typography.body} text-[#64748B]`}>Synthesizing metabolic data and crafting your metabolic blueprint...</p>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className={`flex-1 flex flex-col relative overflow-hidden bg-[#F5F6F8] dark:bg-[#020617] transition-colors duration-500`}>
      {step > 0 && step < totalSteps - 1 && (
        <div className="px-6 pt-6 z-20">
          <ProgressBar progress={(step / (totalSteps - 2)) * 100} height="h-1.5" />
        </div>
      )}
      <div className="flex-1 flex flex-col px-6 overflow-y-auto z-10 no-scrollbar">
        {renderStep()}
      </div>
    </div>
  );
};

export default Onboarding;

import React, { useEffect, useState, useRef } from 'react';
import { Card, Button } from '../components/UI';
import { Meal, MealPlan, ApiRecipe, DetectedFoodItem, MealAlternative, UserProfile } from '../types';
import { fetchApiRecipes } from '../services/recipeService';
import { analyzeFoodImage, generateMealAlternatives } from '../services/geminiService';
import { Colors, Typography, Layout } from '../theme/goqiiDesignSystem';

interface FreeModeProps {
  onBack: () => void;
  meals?: Meal[];
  setMeals?: React.Dispatch<React.SetStateAction<Meal[]>>;
  plan?: MealPlan | null;
  onExplore: () => void;
  onViewGrocery: () => void;
  profile?: UserProfile;
}

const FreeMode: React.FC<FreeModeProps> = ({ onBack, meals = [], setMeals, plan, onExplore, onViewGrocery, profile }) => {
  const [trendingRecipes, setTrendingRecipes] = useState<ApiRecipe[]>([]);
  const [loadingRecipes, setLoadingRecipes] = useState(false);

  // Logging flow states
  const [showLoggingOptions, setShowLoggingOptions] = useState<Meal | null>(null);
  const [isAnalyzingFood, setIsAnalyzingFood] = useState(false);
  const [detectedItems, setDetectedItems] = useState<DetectedFoodItem[]>([]);
  const [logTime, setLogTime] = useState<string>(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
  const [showLogModal, setShowLogModal] = useState<Meal | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);

  // Swap states
  const [selectedMealForAlt, setSelectedMealForAlt] = useState<Meal | null>(null);
  const [alternativeMeals, setAlternativeMeals] = useState<MealAlternative[]>([]);
  const [loadingAlts, setLoadingAlts] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);
  const editFileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const loadRecipes = async () => {
      setLoadingRecipes(true);
      const result = await fetchApiRecipes({ limit: 6 });
      if (result && result.data) {
        setTrendingRecipes(result.data);
      }
      setLoadingRecipes(false);
    };
    loadRecipes();
  }, []);

  const handleQuickLog = (mealId: string) => {
    if (!setMeals) return;
    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: true,
      isManual: false,
      isSkipped: false,
      loggedAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false })
    } : m));
    setShowLoggingOptions(null);
  };

  const handleSkipMeal = (mealId: string) => {
    if (!setMeals) return;
    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: true,
      isSkipped: true,
      loggedAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false })
    } : m));
  };

  const handleSaveLog = (mealId: string, finalItems: DetectedFoodItem[]) => {
    if (!setMeals) return;
    const totalCals = finalItems.reduce((s, i) => s + i.calories, 0);
    const totalPro = finalItems.reduce((s, i) => s + i.protein, 0);
    const totalCarb = finalItems.reduce((s, i) => s + i.carbs, 0);
    const totalFat = finalItems.reduce((s, i) => s + i.fat, 0);

    setMeals(prev => prev.map(m => m.id === mealId ? { 
      ...m, 
      isLogged: true, 
      isSkipped: false,
      calories: totalCals,
      protein: totalPro,
      carbs: totalCarb,
      fat: totalFat,
      photoUri: tempPhoto || m.photoUri,
      loggedAt: logTime,
      manualItems: finalItems,
      name: (m.isManual || (!m.isLogged && showLogModal?.isManual)) && finalItems.length > 0 ? finalItems.map(i => i.name).join(", ") : m.name
    } : m));

    setShowLogModal(null);
    setShowLoggingOptions(null);
    setTempPhoto(null);
    setDetectedItems([]);
  };

  const handleEditLog = (meal: Meal) => {
    const itemsToEdit = meal.manualItems && meal.manualItems.length > 0 
      ? [...meal.manualItems] 
      : [{ name: meal.name, calories: meal.calories, protein: meal.protein, carbs: meal.carbs, fat: meal.fat }];

    setDetectedItems(itemsToEdit);
    setTempPhoto(meal.photoUri || null);
    setLogTime(meal.loggedAt || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
    setShowLogModal(meal);
    setShowLoggingOptions(null);
  };

  const handleImageInput = async (e: React.ChangeEvent<HTMLInputElement>, meal: Meal | null, replaceOnly: boolean = false) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!replaceOnly) {
        setShowLoggingOptions(null);
        setIsAnalyzingFood(true);
      }

      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setTempPhoto(base64);

        if (!replaceOnly && meal) {
          try {
            const items = await analyzeFoodImage(base64);
            setDetectedItems(items);
            setLogTime(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
          } catch (err) {
            console.error("Analysis error:", err);
          } finally {
            setIsAnalyzingFood(false);
            setShowLogModal({ ...meal, isManual: true });
          }
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const updateDetectedItem = (index: number, field: keyof DetectedFoodItem, value: any) => {
    setDetectedItems(prev => {
      const copy = [...prev];
      copy[index] = { ...copy[index], [field]: field === 'name' ? value : Number(value) };
      return copy;
    });
  };

  const removeDetectedItem = (index: number) => {
    setDetectedItems(prev => prev.filter((_, i) => i !== index));
  };

  const openAlternative = async (meal: Meal) => {
    if (!profile) return;
    setSelectedMealForAlt(meal);
    setLoadingAlts(true);
    const alts = await generateMealAlternatives(meal, profile);
    setAlternativeMeals(alts);
    setLoadingAlts(false);
  };

  const handleSwapMeal = (alt: MealAlternative) => {
    if (!selectedMealForAlt || !setMeals) return;
    setMeals(prev => prev.map(m => m.id === selectedMealForAlt.id ? {
      ...m,
      name: alt.name,
      calories: alt.calories,
      protein: alt.protein,
      carbs: alt.carbs,
      fat: alt.fat,
      isLogged: false,
      isSkipped: false,
      manualItems: [{ name: alt.name, calories: alt.calories, protein: alt.protein, carbs: alt.carbs, fat: alt.fat }]
    } : m));
    setSelectedMealForAlt(null);
    setAlternativeMeals([]);
  };

  return (
    <div className="flex-1 flex flex-col bg-[#F5F6F8] dark:bg-slate-950 overflow-hidden relative transition-colors duration-500">
      <div className="p-6 pt-2 flex items-center gap-4 bg-white dark:bg-slate-900 border-b border-slate-50 dark:border-slate-800 z-10 transition-colors">
        <button onClick={onBack} className={`p-2.5 bg-slate-50 dark:bg-slate-800 ${Layout.radius10} border border-slate-100 dark:border-slate-700 transition-colors shadow-none`}>
           <svg className="w-5 h-5 text-slate-600 dark:text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7"></path></svg>
        </button>
        <h1 className="text-xl font-black text-slate-800 dark:text-white tracking-tight leading-none">NutriForge Labs</h1>
      </div>

      <div className="flex-1 overflow-y-auto pb-32 no-scrollbar">
        <div className="px-6 py-8">
          <div className={`bg-[#39C101] rounded-[40px] p-8 text-white relative overflow-hidden shadow-none group active:scale-[0.98] transition-all cursor-pointer`}>
            <div className="relative z-10">
              <span className="block text-[10px] font-black uppercase tracking-[0.3em] opacity-80 mb-2">Experimental Forge</span>
              <h3 className="text-2xl font-black leading-none tracking-tight mb-2">AI Recipe Labs</h3>
              <p className="text-[12px] text-green-50 mb-6 font-bold leading-relaxed opacity-90 max-w-[200px]">Craft unique meals & analyze metabolic impact instantly.</p>
              <Button variant="secondary" className="w-full bg-white text-[#39C101] hover:bg-green-50 border-none h-14 py-0 text-[11px] font-black uppercase tracking-widest shadow-none">Open Labs</Button>
            </div>
            <div className="absolute top-0 right-0 w-48 h-48 bg-white/10 rounded-full -mr-24 -mt-24 group-hover:scale-110 transition-transform duration-700"></div>
          </div>
        </div>

        {meals && meals.length > 0 && (
          <div className="px-6 space-y-6 mb-12">
            <h3 className="text-[12px] font-black text-[#A5B3C1] uppercase tracking-[0.2em] mb-4 pl-1">Today's Active Forge</h3>
            {meals.map(meal => (
              <div key={meal.id} className={`bg-white dark:bg-slate-800 rounded-[40px] p-7 shadow-sm border border-slate-50 dark:border-slate-700 relative group overflow-hidden transition-all duration-300 ${meal.isSkipped ? 'opacity-50 grayscale bg-slate-50 dark:bg-slate-900' : 'hover:shadow-xl hover:shadow-slate-200/50'}`}>
                {!meal.isSkipped && (
                  <button 
                    onClick={() => {
                      if (meal.isLogged) {
                        handleEditLog(meal);
                      } else {
                        setShowLoggingOptions(meal);
                      }
                    }}
                    className={`absolute top-7 right-7 w-12 h-12 rounded-full border-2 flex items-center justify-center transition-all ${meal.isLogged ? 'bg-[#39C101] border-[#39C101] shadow-none' : 'bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-700 hover:border-[#39C101]/50 shadow-none'}`}
                  >
                    {meal.isLogged ? (
                      <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>
                    ) : (
                      <svg className="w-6 h-6 text-[#39C101]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"></path></svg>
                    )}
