import React, { useState, useMemo } from 'react';
import { View, Text, ScrollView, StyleSheet, Image, Pressable } from 'react-native';
import { UserProfile, MealPlan, Meal } from '../types';
import { Card, Button, BackButton, ProgressBar } from '../components/UI';
import { GlobalStyles, Typography, Colors, Layout } from '../theme/goqiiDesignSystem';

interface DashboardProps {
  profile: UserProfile;
  plan: MealPlan;
  meals: Meal[];
  setMeals: React.Dispatch<React.SetStateAction<Meal[]>>;
  onExit: () => void;
  onViewInsights: () => void;
  onViewPlanDetails: () => void;
  onEditPlan: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ profile, plan, meals, setMeals, onExit, onViewInsights, onViewPlanDetails, onEditPlan }) => {
  const totalConsumed = useMemo(() => 
    meals.reduce((sum, m) => (m.isLogged && !m.isSkipped) ? sum + m.calories : sum, 0),
    [meals]
  );

  const targetCals = plan.calories;
  const progressPercent = targetCals > 0 ? Math.round((totalConsumed / targetCals) * 100) : 0;

  return (
    <View style={GlobalStyles.screen}>
      <View style={GlobalStyles.header}>
        <View style={{ flexDirection: 'row', alignItems: 'center' }}>
          <BackButton onPress={onExit} />
          <View style={{ marginLeft: 12 }}>
            <Text style={[Typography.h3, { color: Colors.primary }]}>NutriForge</Text>
            <Text style={[Typography.label, { color: Colors.textMuted }]}>{plan.name}</Text>
          </View>
        </View>
        <View style={{ alignItems: 'flex-end' }}>
          <Text style={Typography.caption}>Target</Text>
          <Text style={Typography.h4}>{targetCals} kcal</Text>
        </View>
      </View>

      <ScrollView contentContainerStyle={{ paddingBottom: 100 }}>
        <View style={styles.statsContainer}>
          <Card onPress={onViewInsights} style={styles.mainCard}>
            <View style={styles.energyRow}>
              <View>
                <Text style={Typography.caption}>Daily Energy</Text>
                <View style={{ flexDirection: 'row', alignItems: 'baseline' }}>
                  <Text style={Typography.energy}>{totalConsumed}</Text>
                  <Text style={[Typography.h4, { color: Colors.textLight }]}> / {targetCals}</Text>
                </View>
              </View>
              <View style={styles.percentageCircle}>
                <Text style={Typography.h6}>{progressPercent}%</Text>
              </View>
            </View>
            <ProgressBar progress={progressPercent} />
          </Card>

          <View style={styles.planActions}>
            <Pressable onPress={onViewPlanDetails}><Text style={styles.actionText}>View Plan Details</Text></Pressable>
            <Pressable onPress={onEditPlan}><Text style={styles.actionText}>Change Plan</Text></Pressable>
          </View>
        </View>

        <View style={styles.mealSection}>
          <Text style={[Typography.label, { marginBottom: 16 }]}>Today's Meals</Text>
          {meals.map(meal => (
            <Card key={meal.id} style={styles.mealCard}>
              <View style={styles.mealHeader}>
                <View style={{ flex: 1 }}>
                  <Text style={Typography.caption}>{meal.type}</Text>
                  <Text style={Typography.h3}>{meal.name}</Text>
                  <Text style={[Typography.body, { color: Colors.textMuted }]}>{meal.calories} kcal</Text>
                </View>
                <Pressable style={[styles.logIcon, meal.isLogged && { backgroundColor: Colors.primary }]}>
                   <Text style={{ color: meal.isLogged ? 'white' : Colors.primary }}>{meal.isLogged ? '✓' : '+'}</Text>
                </Pressable>
              </View>
              <View style={styles.mealActions}>
                <Button variant="outline" style={styles.mealBtn}>Recipe</Button>
                <Button variant="outline" style={styles.mealBtn}>Swap</Button>
                <Button style={styles.mealBtn}>Log</Button>
              </View>
            </Card>
          ))}
        </View>
      </ScrollView>
    </View>
  );
};

const styles = StyleSheet.create({
  statsContainer: { padding: Layout.padding },
  mainCard: { padding: 32 },
  energyRow: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 },
  percentageCircle: { width: 60, height: 60, borderRadius: 30, borderWidth: 4, borderColor: Colors.primary, alignItems: 'center', justifyContent: 'center' },
  planActions: { flexDirection: 'row', justifyContent: 'center', marginTop: 12 },
  actionText: { ...Typography.label, color: Colors.primary, marginHorizontal: 16 },
  mealSection: { paddingHorizontal: Layout.padding },
  mealCard: { marginBottom: 16 },
  mealHeader: { flexDirection: 'row', justifyContent: 'space-between', marginBottom: 20 },
  logIcon: { width: 44, height: 44, borderRadius: 22, borderWidth: 2, borderColor: Colors.primary, alignItems: 'center', justifyContent: 'center' },
  mealActions: { flexDirection: 'row', justifyContent: 'space-between' },
  mealBtn: { flex: 1, marginHorizontal: 4, paddingVertical: 10 },
});

