  const renderView = () => {
    switch (currentView) {
      case 'onboarding':
        return <Onboarding onComplete={(data) => { setProfile(data); setCurrentView('plan-selection'); }} />;
      case 'plan-selection':
        return <PlanSelection onSelect={(plan) => { if(plan) { setSelectedPlan(plan); setCurrentView('dashboard'); } }} onBack={() => setCurrentView('onboarding')} profile={profile} />;
      case 'dashboard':
        return profile && selectedPlan ? (
          <Dashboard 
            profile={profile} 
            plan={selectedPlan} 
            meals={meals} 
            setMeals={setMeals} 
            onExit={() => setCurrentView('plan-selection')}
            onViewInsights={() => {}}
            onViewPlanDetails={() => {}}
            onEditPlan={() => {}}
          />
        ) : null;
      default:
        return null;
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      <View style={GlobalStyles.screen}>
        {renderView()}

        {currentView === 'dashboard' && (
          <View style={GlobalStyles.tabBar}>
