            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
              <span style={{ ...Typography.label, color: Colors.textMuted }}>{plan.name}</span>
            </div>
          </div>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end' }}>
          <span style={{ ...Typography.caption, color: Colors.textLight }}>Target Energy</span>
          <span style={{ ...Typography.h3, ...Typography.Black }}>{targetCals} kcal</span>
        </div>
      </header>

      <div style={{ flex: 1, overflowY: 'auto', paddingBottom: '100px' }}>
        <div style={{ padding: '24px' }}>
          <Card onClick={onViewInsights} style={{ padding: '32px', marginBottom: '24px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'start', marginBottom: '32px' }}>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
                <span style={Typography.caption}>Daily Energy</span>
                <div style={{ display: 'flex', alignItems: 'baseline', gap: '8px' }}>
                  <span style={Typography.energy}>{totalConsumed}</span>
                  <span style={{ fontSize: '16px', color: Colors.textLight, fontWeight: 700 }}>/ {targetCals} kcal</span>
                </div>
              </div>
              <div style={{ width: '64px', height: '64px', borderRadius: '50%', border: `5px solid ${Colors.primary}`, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <span style={{ fontSize: '12px', fontWeight: 900 }}>{progressPercent}%</span>
              </div>
            </div>
            <ProgressBar progress={progressPercent} />
