        </div>

        <div style={{ padding: '0 24px 24px 24px' }}>
          <h3 style={{ ...Typography.label, marginBottom: '16px', paddingLeft: '4px' }}>Today's Meals</h3>

          <div style={GlobalStyles.cardsGrid}>
            {meals.map(meal => (
              <div 
                key={meal.id} 
                style={{
                  ...GlobalStyles.card,
                  flex: '1 1 300px',
                  padding: '28px',
                  display: 'flex',
                  flexDirection: 'column',
                  position: 'relative',
                  opacity: meal.isSkipped ? 0.5 : 1,
                }}
              >
                <div style={{ display: 'flex', flexDirection: 'column', gap: '6px', marginBottom: '32px' }}>
                  <span style={{ ...Typography.label, color: Colors.textLight }}>{meal.type}</span>
                  <h4 style={{ ...Typography.h3, ...Typography.Black, margin: 0 }}>{meal.name}</h4>
                  <span style={{ fontSize: '14px', fontWeight: 700, color: Colors.textLight }}>{meal.calories} kcal</span>
                </div>

                <div style={{ display: 'flex', gap: '12px', marginTop: 'auto' }}>
                  <Button variant="outline" style={{ flex: 1, padding: '12px' }}>Recipe</Button>
                  <Button variant="outline" style={{ flex: 1, padding: '12px' }}>Swap</Button>
                  <Button style={{ flex: 1, padding: '12px' }}>Log</Button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useEffect, useState, useCallback } from 'react';
import { MealPlan, UserProfile } from '../types';
import { Button, BackButton, Card } from '../components/UI';
import { fetchApiMealPlans } from '../services/mealPlanService';
import { Colors, Typography, Layout, GlobalStyles } from '../theme/goqiiDesignSystem';

interface PlanSelectionProps {
  onSelect: (plan: MealPlan | null) => void;
  onBack: () => void;
  onViewDetails: (plan: MealPlan) => void;
  onEditPlan: () => void;
  profile: UserProfile | null;
}

const PlanSelection: React.FC<PlanSelectionProps> = ({ onSelect, onBack, onViewDetails, onEditPlan, profile }) => {
  const [plans, setPlans] = useState<MealPlan[]>([]);
  const [loading, setLoading] = useState(true);

  const loadPlans = useCallback(async () => {
    setLoading(true);
    try {
      const apiPlans = await fetchApiMealPlans({ limit: 12 });
      if (apiPlans && Array.isArray(apiPlans)) {
        const mappedPlans: MealPlan[] = apiPlans.map((p: any) => ({
          id: p.id || String(Math.random()),
          name: p.name || 'Untitled Plan',
          calories: Number(p.daily_calories || 0),
          duration: `${p.duration_days || 7} Days`,
          image_url: p.image_url || `https://images.unsplash.com/photo-1490645935967-10de6ba17061?auto=format&fit=crop&q=80&w=600`,
          description: p.description || ""
        }));
        setPlans(mappedPlans);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { loadPlans(); }, [loadPlans]);

  return (
    <div style={{ ...GlobalStyles.screen, overflowY: 'auto' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '32px', padding: '24px 24px 0 24px' }}>
        <BackButton onClick={onBack} />
        <h1 style={{ ...Typography.h2, ...Typography.Black, color: Colors.textPrimary, margin: 0 }}>Meal Plans</h1>
      </div>

      <div style={{ ...GlobalStyles.cardsGrid, padding: '0 24px' }}>
        {plans.map((plan) => (
          <Card 
            key={plan.id} 
            style={{ flex: '1 1 340px', overflow: 'hidden', display: 'flex', flexDirection: 'column' }}
          >
            <div style={{ height: '176px', position: 'relative' }}>
              <img 
                src={plan.image_url} 
                alt={plan.name} 
                style={{ width: '100%', height: '100%', objectFit: 'cover' }} 
              />
              <div style={{ position: 'absolute', top: '16px', right: '16px', backgroundColor: Colors.primary, color: Colors.white, padding: '4px 12px', borderRadius: '999px', ...Typography.caption }}>
                {plan.calories} kcal
              </div>
            </div>

            <div style={{ padding: '24px', display: 'flex', flexDirection: 'column', flex: 1 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
                <h3 style={{ ...Typography.h4, ...Typography.Black, margin: 0 }}>{plan.name}</h3>
                <span style={{ ...Typography.caption, color: Colors.textLight }}>{plan.duration}</span>
              </div>

              <p style={{ ...Typography.body, color: Colors.textMuted, fontStyle: 'italic', marginBottom: '24px', flex: 1 }}>
                {plan.description}
              </p>

              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                <Button onClick={() => onSelect(plan)}>Start this Meal</Button>
                <div style={{ display: 'flex', justifyContent: 'center', gap: '24px' }}>
                  <button onClick={() => onViewDetails(plan)} style={{ background: 'none', border: 'none', ...Typography.caption, color: Colors.primary, cursor: 'pointer' }}>View Details</button>
                  <button onClick={onEditPlan} style={{ background: 'none', border: 'none', ...Typography.caption, color: Colors.primary, cursor: 'pointer' }}>Change Plan</button>
                </div>
              </div>
            </div>
          </Card>
        ))}
      </div>

      <div style={{ padding: '48px 24px 80px 24px', textAlign: 'center' }}>
        <Button variant="ghost" onClick={() => onSelect(null)} style={{ width: '100%' }}>Skip for now</Button>
      </div>
    </div>
  );
};

export default PlanSelection;

import React, { useState, useEffect } from 'react';
import { UserProfile, MealPlan, Meal } from './types';
import Onboarding from './views/Onboarding';
import PlanSelection from './views/PlanSelection';
import Dashboard from './views/Dashboard';
import FreeMode from './views/FreeMode';
import Insights from './views/Insights';
import Settings from './views/Settings';
import ExploreHub from './views/ExploreHub';
import GroceryList from './views/GroceryList';
import PlanDetails from './views/PlanDetails';
import EditPlan from './views/EditPlan';
import { generateDailyMeals } from './services/geminiService';
import { fetchApiMealPlanById } from './services/mealPlanService';
import { Colors, GlobalStyles, Typography } from './theme/goqiiDesignSystem';

type View = 'onboarding' | 'plan-selection' | 'dashboard' | 'free-mode' | 'insights' | 'settings' | 'explore-hub' | 'grocery-list' | 'plan-details' | 'edit-plan';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('onboarding');
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [selectedPlan, setSelectedPlan] = useState<MealPlan | null>(null);
  const [previewPlan, setPreviewPlan] = useState<MealPlan | null>(null);
  const [meals, setMeals] = useState<Meal[]>([]);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isForging, setIsForging] = useState(false);

  const handleOnboardingComplete = (data: UserProfile) => {
    setProfile(data);
    setCurrentView('plan-selection');
  };

  const handlePlanSelect = async (plan: MealPlan | null) => {
    if (plan && profile) {
      setIsForging(true);
      try {
        const enrichedPlan = await fetchApiMealPlanById(plan.id);
        setSelectedPlan(plan);
        const finalMeals = await generateDailyMeals(plan, profile);
        setMeals(finalMeals);
      } catch (err) {
        setSelectedPlan(plan);
      } finally {
        setIsForging(false);
        setCurrentView('dashboard');
      }
    } else {
      setCurrentView('free-mode');
    }
  };

  const isMainApp = !['onboarding', 'plan-selection'].includes(currentView);

  const NavItem = ({ view, icon, label, activeViews }: { view: View, icon: React.ReactNode, label: string, activeViews: View[] }) => {
    const isActive = activeViews.includes(currentView);
    return (
      <button 
        onClick={() => setCurrentView(view)} 
        style={{ 
          display: 'flex', 
          flexDirection: 'column', 
          alignItems: 'center', 
          gap: '4px', 
          background: 'none', 
          border: 'none', 
          color: isActive ? Colors.primary : Colors.textMuted,
          cursor: 'pointer'
        }}
      >
        {icon}
        <span style={{ ...Typography.caption, fontSize: '8px' }}>{label}</span>
      </button>
    );
  };

  return (
    <div style={{ 
      minHeight: '100vh', 
      backgroundColor: Colors.background, 
      display: 'flex', 
      justifyContent: 'center' 
    }}>
      <div style={{ 
        width: '100%', 
        maxWidth: '440px', 
        backgroundColor: 'transparent', 
        position: 'relative', 
        display: 'flex', 
        flexDirection: 'column',
        boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.25)'
      }}>
        <div style={GlobalStyles.screen}>
          {isForging && (
            <div style={{ position: 'absolute', inset: 0, backgroundColor: 'white', zIndex: 100, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center' }}>
              <div style={{ width: '64px', height: '64px', borderRadius: '50%', border: `4px solid ${Colors.primary}`, borderTopColor: 'transparent', animation: 'spin 1s linear infinite' }}></div>
              <h2 style={{ ...Typography.h3, marginTop: '24px' }}>Forging Blueprint</h2>
            </div>
          )}

          {currentView === 'onboarding' && <Onboarding onComplete={handleOnboardingComplete} />}
          {currentView === 'plan-selection' && <PlanSelection onSelect={handlePlanSelect} onBack={() => setCurrentView('onboarding')} onViewDetails={(p) => { setPreviewPlan(p); setCurrentView('plan-details'); }} onEditPlan={() => setCurrentView('edit-plan')} profile={profile} />}
          {currentView === 'dashboard' && profile && selectedPlan && <Dashboard profile={profile} plan={selectedPlan} meals={meals} setMeals={setMeals} onExit={() => setCurrentView('plan-selection')} onViewInsights={() => setCurrentView('insights')} onExplore={() => setCurrentView('explore-hub')} onViewGrocery={() => setCurrentView('grocery-list')} onViewPlanDetails={() => setCurrentView('plan-details')} onEditPlan={() => setCurrentView('edit-plan')} />}
          {currentView === 'plan-details' && profile && (selectedPlan || previewPlan) && <PlanDetails profile={profile} plan={previewPlan || selectedPlan!} onBack={() => setCurrentView(selectedPlan ? 'dashboard' : 'plan-selection')} onSelect={handlePlanSelect} />}
        </div>

        {isMainApp && (
          <nav style={GlobalStyles.tabBar}>
            <NavItem view="dashboard" label="Home" activeViews={['dashboard']} icon={<svg style={{width:'24px',height:'24px'}} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"/></svg>} />
            <NavItem view="free-mode" label="Forge" activeViews={['free-mode']} icon={<svg style={{width:'24px',height:'24px'}} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>} />
            <NavItem view="insights" label="Insights" activeViews={['insights']} icon={<svg style={{width:'24px',height:'24px'}} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"/></svg>} />
            <NavItem view="settings" label="Profile" activeViews={['settings']} icon={<svg style={{width:'24px',height:'24px'}} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"/></svg>} />
          </nav>
        )}
      </div>
    </div>
  );
};

export default App;
